INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95085, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95085, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "殖民地是被别的国家抢来管着的地方。", "primary_collocate": null, "pronunciation": "zhí mín dì", "ipa": "ʈʂɻ̩˧˥ min˧˥ ti˥˩", "syllable_count": 3, "sentences": [{"text": "这个岛以前是别国的殖民地。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多国家都曾经是殖民地。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "殖民地的人想要自己的国家。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个国家有很多殖民地。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里过去是英国的殖民地。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "殖民地的人不能自己做主。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们从殖民地拿走了很多东西。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市当过一百年的殖民地。", "target_word": "殖民地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那块殖民地后来变成了新国家。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争以后，这块殖民地独立了。", "target_word": "殖民地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "半殖民地", "label": "复合"}], "register": "书面", "sense_fingerprint": "被别的国家抢来管着的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21944ec0-25a1-4e3d-9f77-8f4f59681f20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95085, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "殖民地", "is_correct": true, "explanation": "正确。“殖民地”指被别国统治的地方，与“别国的”搭配相合。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：岛屿不能是人，“别国的朋友”与句意不符。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：岛屿不是歌曲，“这个岛是别国的歌曲”句意不通。"}, {"text": "语言", "is_correct": false, "explanation": "搭配：“别国的”后面接的是可以被占有或管辖的地方，“语言”不能这样搭配。"}], "explanations": {"殖民地": "正确。“殖民地”指被别国统治的地方，与“别国的”搭配相合。", "朋友": "语义：岛屿不能是人，“别国的朋友”与句意不符。", "歌曲": "语义：岛屿不是歌曲，“这个岛是别国的歌曲”句意不通。", "语言": "搭配：“别国的”后面接的是可以被占有或管辖的地方，“语言”不能这样搭配。"}, "sentence_index": 0, "correct_answer": "殖民地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个国家有一条殖民地。", "explanation": "这里应该用〈块〉。殖民地是一片地区，“条”用于细长的东西，不能用来计量殖民地。"}, {"text": "这些殖民地是外国人。", "explanation": "这里应该用〈殖民者〉。殖民地指被统治的地区，不能指人；占领和统治的人要说殖民者。"}, {"text": "殖民地给我们做了一顿饭。", "explanation": "这里应该用〈妈妈〉。殖民地是地区，不能做饭；做饭的是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95085, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "殖民地", "is_correct": true, "explanation": "正确。“从殖民地拿走东西”说的是地方，与“从”的搭配相合。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不能被理解为可以拿走东西的地方，句意不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：“眼睛”是身体器官，不能作为他们拿走东西的来源，句意不通。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：梦想是人心里的愿望，不能作为拿走东西的来源。"}], "explanations": {"殖民地": "正确。“从殖民地拿走东西”说的是地方，与“从”的搭配相合。", "太阳": "语义：太阳不能被理解为可以拿走东西的地方，句意不通。", "眼睛": "语义：“眼睛”是身体器官，不能作为他们拿走东西的来源，句意不通。", "梦想": "语义：梦想是人心里的愿望，不能作为拿走东西的来源。"}, "sentence_index": 6, "correct_answer": "殖民地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里的殖民地都很勤劳。", "explanation": "这里应该用〈居民〉。殖民地是地区，不能形容为勤劳；形容人要说居民。"}, {"text": "殖民地都很努力地学习。", "explanation": "这里应该用〈学生〉。殖民地是地区，不能学习；学习的是学生。"}, {"text": "殖民地写了一本书。", "explanation": "这里应该用〈作家〉。殖民地不能写书，写书的人是作家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95085, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条殖民地很快就独立了。", "corrected_sentence": "那块殖民地很快就独立了。", "error_description": "“殖民地”的量词应用“块”，不能用“条”；“条”用于细长的东西，地区要用“块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95085, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多人殖民地出生。", "corrected_sentence": "很多人在殖民地出生。", "error_description": "“出生”前面的地点“殖民地”要用介词“在”引出，应说“在殖民地出生”，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
