INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95086, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "被外国占领并统治、掠夺的地区。", "primary_collocate": null, "pronunciation": "zhí mín dì", "ipa": "ʈʂɻ̩˧˥ min˧˥ ti˥˩", "syllable_count": 3, "sentences": [{"text": "他们占领小岛，把它变成殖民地。", "target_word": "殖民地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把殖民地的矿都运走了。", "target_word": "殖民地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "殖民地的农民生活很苦。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国王派军队去管理殖民地。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书讲殖民地的历史。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "殖民地的人要给外国交很多税。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一百年前，这里是殖民地。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "殖民者在殖民地建了很多港口。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "殖民地人民开始反对外国统治。", "target_word": "殖民地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争结束后，殖民地变成了独立国家。", "target_word": "殖民地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "半殖民地", "label": "复合"}], "register": "书面", "sense_fingerprint": "被外国占领统治掠夺的地区", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21944ec0-25a1-4e3d-9f77-8f4f59681f20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95086, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "殖民地", "is_correct": true, "explanation": "正确。“变成殖民地”指小岛被外国占领统治，与句意相合。"}, {"text": "老师", "is_correct": false, "explanation": "语义：小岛不能变成人，“把它变成老师”句意不通。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“变成”后要接由小岛转化而来的事物，“乐器”不能这样搭配。"}, {"text": "饭", "is_correct": false, "explanation": "语义：小岛不能变成饭，句意不通。"}], "explanations": {"殖民地": "正确。“变成殖民地”指小岛被外国占领统治，与句意相合。", "老师": "语义：小岛不能变成人，“把它变成老师”句意不通。", "乐器": "搭配：“变成”后要接由小岛转化而来的事物，“乐器”不能这样搭配。", "饭": "语义：小岛不能变成饭，句意不通。"}, "sentence_index": 0, "correct_answer": "殖民地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国王派军队去管理一条殖民地。", "explanation": "这里应该用〈块〉。殖民地是一片地区，“条”用于细长的东西，不能用来计量殖民地。"}, {"text": "殖民地在田里工作。", "explanation": "这里应该用〈农民〉。殖民地是地区，不能做“工作”这样的动作；做工的人要说农民。"}, {"text": "殖民地保卫这座城市。", "explanation": "这里应该用〈士兵〉。殖民地是地区，不能保卫城市；保卫城市的是士兵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "殖民地", "is_correct": true, "explanation": "正确。“一百年前，这里是殖民地”指这里曾被外国统治，与句意相合。"}, {"text": "学生", "is_correct": false, "explanation": "语义：这里是地方，不能是人，“这里是学生”句意不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：这里不能是一部手机，句意不通。"}, {"text": "大衣", "is_correct": false, "explanation": "搭配：“这里是”后面接的应是地点或场所类名词，“大衣”不能这样搭配。"}], "explanations": {"殖民地": "正确。“一百年前，这里是殖民地”指这里曾被外国统治，与句意相合。", "学生": "语义：这里是地方，不能是人，“这里是学生”句意不通。", "手机": "语义：这里不能是一部手机，句意不通。", "大衣": "搭配：“这里是”后面接的应是地点或场所类名词，“大衣”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "殖民地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "殖民地很认真地读书。", "explanation": "这里应该用〈学生〉。殖民地是地区，不能读书；读书的是学生。"}, {"text": "殖民地在公园里散步。", "explanation": "这里应该用〈老人〉。殖民地是地区，不能散步；散步的是人，应说老人。"}, {"text": "殖民地写了一本好书。", "explanation": "这里应该用〈作家〉。殖民地不能写书，写书的人是作家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们殖民地运走了粮食。", "corrected_sentence": "他们从殖民地运走了粮食。", "error_description": "“殖民地”作动作的起点时，前面要加介词“从”，应说“从殖民地运走”，不能省略“从”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条殖民地很大。", "corrected_sentence": "那片殖民地很大。", "error_description": "“殖民地”的量词应用“片”，不能用“条”；“条”用于细长的东西，地区要用“片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95087, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95087, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95087, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个地方的社会安全和秩序。", "primary_collocate": null, "pronunciation": "zhì ān", "ipa": "ʈʂɻ̩˥˩ an˥", "syllable_count": 2, "sentences": [{"text": "这个小区的治安很好，晚上可以放心散步。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那个城市的治安不太好，我们要小心。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为治安好，所以很多人愿意住在这里。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街治安很差，晚上最好别一个人走。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以前，我先打听了那里的治安。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在治安好的地方，父母才放心。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的治安越来越好，小偷也少了。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国游客说，这个城市的治安让他很安心。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想租房子，所以先看看附近的治安怎么样。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "治安不好的地方，孩子不能自己出门。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "治安管理", "label": "复合"}, {"form": "治安问题", "label": "复合"}], "register": "中性", "sense_fingerprint": "某个小区、街道或城市是否安全、有没有坏人乱来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61745b1a-f27b-4aaf-b958-4b5b5e37ece2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95087, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "噪音", "is_correct": false, "explanation": "搭配：「噪音」说大小，不说「好」，也不能支撑「放心散步」。"}, {"text": "治安", "is_correct": true, "explanation": "「治安」指小区的安全与秩序，与「很好」「放心散步」相符。"}, {"text": "房租", "is_correct": false, "explanation": "语义：房租指付的钱，与小区是否安全无关，不能说明可以放心散步。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口说多少，不说好坏，与「放心散步」无关。"}], "explanations": {"噪音": "搭配：「噪音」说大小，不说「好」，也不能支撑「放心散步」。", "治安": "「治安」指小区的安全与秩序，与「很好」「放心散步」相符。", "房租": "语义：房租指付的钱，与小区是否安全无关，不能说明可以放心散步。", "人口": "语义：人口说多少，不说好坏，与「放心散步」无关。"}, "sentence_index": 0, "correct_answer": "治安"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路的治安很好，车不会撞人。", "explanation": "这里应该用〈安全〉。治安指社会秩序和防范犯罪，车祸属于交通安全，不属于治安。"}, {"text": "这次会议的治安很好，大家都按时发言。", "explanation": "这里应该用〈秩序〉。治安指一个地区的社会安全，会议里的次序要用秩序，不用治安。"}, {"text": "这家医院的治安很好，医生看病很认真。", "explanation": "这里应该用〈服务〉。治安指一个地区的社会安全，医生看病认真说的是服务，不是治安。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95087, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物价", "is_correct": false, "explanation": "搭配：「物价」说高低，不说「越来越好」。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：「学费」说多少，不说「好」，与「越来越好」不合。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：「垃圾」指脏的东西，与「越来越好」和「小偷也少了」都不相合。"}, {"text": "治安", "is_correct": true, "explanation": "「治安」指地方的安全与秩序，「越来越好」且「小偷也少了」正说明它变好。"}], "explanations": {"物价": "搭配：「物价」说高低，不说「越来越好」。", "学费": "搭配：「学费」说多少，不说「好」，与「越来越好」不合。", "垃圾": "语义：「垃圾」指脏的东西，与「越来越好」和「小偷也少了」都不相合。", "治安": "「治安」指地方的安全与秩序，「越来越好」且「小偷也少了」正说明它变好。"}, "sentence_index": 6, "correct_answer": "治安"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的治安很多，孩子不能自己出门。", "explanation": "这里应该用〈犯罪〉。治安指社会秩序的好坏，说数量多少应说「犯罪」或「治安问题」。"}, {"text": "这家餐厅的治安很好，菜都很新鲜。", "explanation": "这里应该用〈卫生〉。治安指社会秩序和防范犯罪，餐厅的清洁要用卫生，不用治安。"}, {"text": "这条街的治安很高，我们晚上可以放心散步。", "explanation": "这里应该用〈好〉。〈治安〉用「好」「差」来评价，不用「高」「低」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95087, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个地区的一个治安越来越好，老人也敢出门散步了。", "corrected_sentence": "这个地区的治安越来越好，老人也敢出门散步了。", "error_description": "错误：「治安」前加了量词「一个」。正确：「治安」是不可数名词，前面不加量词，直接说「这个地区的治安」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95087, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一起制造小区治安，让大家都放心。", "corrected_sentence": "我们一起维护小区治安，让大家都放心。", "error_description": "错误：「制造小区治安」。「制造」用于具体事物，治安是需要维护的秩序，应说「维护小区治安」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
