INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95088, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "社会的安全和秩序。", "primary_collocate": null, "pronunciation": "zhì ān", "ipa": "ʈʂɻ̩˥˩ an˥", "syllable_count": 2, "sentences": [{"text": "政府一直努力维护社会治安。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察的工作是保护人民，维持治安。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日人多，警察要加强治安管理。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的治安问题越来越严重。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的治安需要政府和市民一起努力。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长说，今年要重点改善城市治安。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公安局工作，负责治安方面的事。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里有警察巡逻，全城的治安更好了。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，去年全市的治安明显变好。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了社会治安，政府增加了很多警察。", "target_word": "治安", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "治安管理", "label": "复合"}, {"form": "治安问题", "label": "复合"}], "register": "中性", "sense_fingerprint": "政府和警察要维护的社会安全与秩序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61745b1a-f27b-4aaf-b958-4b5b5e37ece2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95088, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垃圾", "is_correct": false, "explanation": "搭配：「维护」的对象应是秩序、安全等，垃圾不能被维护。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是社会事务，不能被「维护」。"}, {"text": "治安", "is_correct": true, "explanation": "「维护社会治安」指维护社会的安全与秩序，符合句意。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口说数量，不是可以被维护的事务。"}], "explanations": {"垃圾": "搭配：「维护」的对象应是秩序、安全等，垃圾不能被维护。", "天气": "语义：天气不是社会事务，不能被「维护」。", "治安": "「维护社会治安」指维护社会的安全与秩序，符合句意。", "人口": "语义：人口说数量，不是可以被维护的事务。"}, "sentence_index": 0, "correct_answer": "治安"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家的治安很干净，街上没有垃圾。", "explanation": "这里应该用〈环境〉。治安指社会秩序和安全，说干净、整洁的是环境。"}, {"text": "这台治安很好，全城的人都很安心。", "explanation": "这里不能用〈台〉。〈台〉用于机器、电器；「治安」是抽象名词，一般不加量词，直接说「这里的治安很好」。"}, {"text": "那位治安很有名，大家都认识他。", "explanation": "这里应该用〈警察〉。治安指社会秩序，不指人，称呼维持秩序的人要用警察。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95088, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "农业", "is_correct": false, "explanation": "语义：公安局不管农业，与「在公安局工作」不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气预报不归公安局管，与「在公安局工作」不符。"}, {"text": "治安", "is_correct": true, "explanation": "「治安方面的事」指维护社会秩序和安全的工作，与公安局的职责相符。"}, {"text": "天文", "is_correct": false, "explanation": "语义：公安局不负责天文研究，与「在公安局工作」不符。"}], "explanations": {"农业": "语义：公安局不管农业，与「在公安局工作」不符。", "天气": "语义：天气预报不归公安局管，与「在公安局工作」不符。", "治安": "「治安方面的事」指维护社会秩序和安全的工作，与公安局的职责相符。", "天文": "语义：公安局不负责天文研究，与「在公安局工作」不符。"}, "sentence_index": 6, "correct_answer": "治安"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂的治安很好，工人都戴好了头盔。", "explanation": "这里应该用〈安全〉。治安指社会秩序，工厂里的人身安全要用安全，不用治安。"}, {"text": "这间教室的治安很好，地上没有纸屑。", "explanation": "这里应该用〈卫生〉。治安指社会秩序和防范犯罪，教室的清洁要用卫生，不用治安。"}, {"text": "这个国家的治安很重，所以政府增加了很多警察。", "explanation": "〈治安〉用「好」「差」来评价，「很重」不能用来描述治安状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察每天都在制造社会治安。", "corrected_sentence": "警察每天都在维护社会治安。", "error_description": "错误：「制造社会治安」。正确：「维护社会治安」，治安是需要维护的社会秩序，不能说「制造」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95088, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里街上很安全，全城的那份治安都很稳定。", "corrected_sentence": "夜里街上很安全，全城的治安都很稳定。", "error_description": "错误：「那份治安」。正确：「治安」是抽象名词，前面不用「份」修饰，直接说「全城的治安」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
