INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95091, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海岸是海和陆地连着的地方。", "primary_collocate": null, "pronunciation": "hǎi àn", "ipa": "xaɪ˨˩ an˥˩", "syllable_count": 2, "sentences": [{"text": "海岸离我家不远。", "target_word": "海岸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "海岸边有一家小店。", "target_word": "海岸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们在海岸上跑步。", "target_word": "海岸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "海岸的水很蓝，也很干净。", "target_word": "海岸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台风快到了，海岸边的人都回家了。", "target_word": "海岸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最喜欢坐在海岸边看日出。", "target_word": "海岸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海岸的石头很多，走路要小心。", "target_word": "海岸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海浪一次又一次地拍打着海岸。", "target_word": "海岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在海岸住过十年，所以很会游泳。", "target_word": "海岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片是在海岸拍的，你看，天多蓝！", "target_word": "海岸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海岸线", "label": "复合词"}, {"form": "段", "label": "量词"}], "register": "中性", "sense_fingerprint": "海和陆地连着的地方，日常说的海边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54467bb6-6f7e-4da9-9fdd-38e961a14e4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95091, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海岸", "is_correct": true, "explanation": "海岸是海和陆地连着的地方，可以作为“我家”的位置参照，句子通顺。"}, {"text": "北极", "is_correct": false, "explanation": "语义：北极离我家很远，与“不远”的语意矛盾。"}, {"text": "火星", "is_correct": false, "explanation": "语义：火星离地球很远，与“离我家不远”不相符。"}, {"text": "海风", "is_correct": false, "explanation": "搭配：“海风”没有固定位置，不能与“离……不远”搭配。"}], "explanations": {"海岸": "海岸是海和陆地连着的地方，可以作为“我家”的位置参照，句子通顺。", "北极": "语义：北极离我家很远，与“不远”的语意矛盾。", "火星": "语义：火星离地球很远，与“离我家不远”不相符。", "海风": "搭配：“海风”没有固定位置，不能与“离……不远”搭配。"}, "sentence_index": 0, "correct_answer": "海岸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山的海岸有一千米高，山顶很冷。", "explanation": "这里应该用〈海拔〉。〈海岸〉指海与陆地相接的地带，不表示高度；说山的高度要用〈海拔〉。"}, {"text": "这片海岸很窄，两边都是陆地。", "explanation": "这里应该用〈海峡〉。〈海岸〉是海与陆地相接的地带；两边都是陆地、中间是狭窄水道的要用〈海峡〉。"}, {"text": "这片海岸离海很远，全是平原。", "explanation": "这里应该用〈平原〉。〈海岸〉必须靠着海，离海很远的陆地不叫海岸，应说〈平原〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95091, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海岸", "is_correct": true, "explanation": "海岸是海和陆地连着的地方，海岸的石头多、走路要小心，句子通顺。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以堆放石头的地方，“天空的石头很多”不合逻辑。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵是漂浮的水汽，不会有“石头很多，走路要小心”的情况。"}, {"text": "雨水", "is_correct": false, "explanation": "搭配：“雨水”是液体，不能说“雨水的石头很多”。"}], "explanations": {"海岸": "海岸是海和陆地连着的地方，海岸的石头多、走路要小心，句子通顺。", "天空": "语义：天空不是可以堆放石头的地方，“天空的石头很多”不合逻辑。", "云朵": "语义：云朵是漂浮的水汽，不会有“石头很多，走路要小心”的情况。", "雨水": "搭配：“雨水”是液体，不能说“雨水的石头很多”。"}, "sentence_index": 6, "correct_answer": "海岸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的海岸边有很多芦苇，夏天很美。", "explanation": "这里应该用〈河岸〉。河边的陆地说〈河岸〉；海岸指海与陆地相接的地带，河边不能用。"}, {"text": "这个湖的海岸边有很多游客。", "explanation": "这里应该用〈湖岸〉。湖边的陆地说〈湖岸〉；海岸只指海边，湖边不能用。"}, {"text": "这条江的海岸边停着很多船。", "explanation": "这里应该用〈江岸〉。江边的陆地说〈江岸〉；海岸指海与陆地相接处，江边不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95091, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在海岸里散步，很舒服。", "corrected_sentence": "我们在海岸上散步，很舒服。", "error_description": "方位词错误：“海岸”是陆地上的地带，应说“在海岸上”，不能说“在海岸里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95091, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每天海岸边跑步。", "corrected_sentence": "我们每天在海岸边跑步。", "error_description": "漏掉介词“在”：表示地点要说“在海岸边跑步”，不能直接说“海岸边跑步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
