INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95092, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海洋与陆地相接的地带。", "primary_collocate": null, "pronunciation": "hǎi àn", "ipa": "xaɪ˨˩ an˥˩", "syllable_count": 2, "sentences": [{"text": "我家在海岸旁边。", "target_word": "海岸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里的海岸很长。", "target_word": "海岸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "海岸边有很多白色的沙子。", "target_word": "海岸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天，我们开车去了海岸。", "target_word": "海岸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海岸上的风很大，我们都戴着帽子。", "target_word": "海岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他沿着海岸一直往南走。", "target_word": "海岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海岸附近的城市，冬天也不太冷。", "target_word": "海岸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海岸上有一座白色的灯塔。", "target_word": "海岸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在海岸散步，看到了很多海鸟。", "target_word": "海岸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的海岸很漂亮，每年都有很多人来玩。", "target_word": "海岸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海岸线", "label": "复合词"}, {"form": "段", "label": "量词"}], "register": "中性", "sense_fingerprint": "海洋与陆地相接的地带，指海边的陆地一带", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54467bb6-6f7e-4da9-9fdd-38e961a14e4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95092, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海岸", "is_correct": true, "explanation": "海岸是海与陆地相接的地带，可以作为“我家”的位置参照，句子通顺。"}, {"text": "海鸥", "is_correct": false, "explanation": "语义：海鸥是鸟，不是可以作为位置参照的地方，“我家在海鸥旁边”说不通。"}, {"text": "海风", "is_correct": false, "explanation": "搭配：“海风”没有固定位置，不能与“在……旁边”搭配。"}, {"text": "海盐", "is_correct": false, "explanation": "语义：海盐是调味品，不是地点，“我家在海盐旁边”不合逻辑。"}], "explanations": {"海岸": "海岸是海与陆地相接的地带，可以作为“我家”的位置参照，句子通顺。", "海鸥": "语义：海鸥是鸟，不是可以作为位置参照的地方，“我家在海鸥旁边”说不通。", "海风": "搭配：“海风”没有固定位置，不能与“在……旁边”搭配。", "海盐": "语义：海盐是调味品，不是地点，“我家在海盐旁边”不合逻辑。"}, "sentence_index": 0, "correct_answer": "海岸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片海岸很深，里面有很多鱼。", "explanation": "这里应该用〈海洋〉。〈海岸〉指陆地与海相接的地带，不指海水深处；说海水很深、里面有鱼要用〈海洋〉或〈大海〉。"}, {"text": "这座山的海岸有两千米高，山顶常年有雪。", "explanation": "这里应该用〈海拔〉。〈海岸〉指海与陆地相接的地带，不表示高度；说山的高度要用〈海拔〉。"}, {"text": "我们在海岸里游泳，水很凉。", "explanation": "这里应该用〈海里〉。〈海岸〉是陆地上的地带，不指海水中；在海水里游泳要说〈海里〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95092, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海岸", "is_correct": true, "explanation": "海岸是海与陆地相接的地带，海边城市受海洋调节，冬天不太冷，句子通顺。"}, {"text": "北极", "is_correct": false, "explanation": "语义：北极气候寒冷，与“冬天也不太冷”的语意矛盾。"}, {"text": "南极", "is_correct": false, "explanation": "语义：南极气候极寒且没有城市，与“冬天也不太冷”的语意矛盾。"}, {"text": "海带", "is_correct": false, "explanation": "搭配：“海带”是海藻，不是地点，不能与“附近的城市”搭配。"}], "explanations": {"海岸": "海岸是海与陆地相接的地带，海边城市受海洋调节，冬天不太冷，句子通顺。", "北极": "语义：北极气候寒冷，与“冬天也不太冷”的语意矛盾。", "南极": "语义：南极气候极寒且没有城市，与“冬天也不太冷”的语意矛盾。", "海带": "搭配：“海带”是海藻，不是地点，不能与“附近的城市”搭配。"}, "sentence_index": 6, "correct_answer": "海岸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的海岸很宽，船很多。", "explanation": "这里应该用〈河岸〉。河边的陆地说〈河岸〉；海岸指海与陆地相接的地带，河边不能用。"}, {"text": "这个湖的海岸很长，游客很多。", "explanation": "这里应该用〈湖岸〉。湖边的陆地说〈湖岸〉；海岸只指海边，湖边不能用。"}, {"text": "这条江的海岸很宽，水很急。", "explanation": "这里应该用〈江岸〉。江边的陆地说〈江岸〉；海岸指海与陆地相接处，江边不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95092, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在海岸里吹风，很舒服。", "corrected_sentence": "我们在海岸边吹风，很舒服。", "error_description": "方位词错误：“海岸”是陆地上的地带，应说“海岸边”或“海岸上”，不能说“海岸里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95092, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们海岸上散步，心情很好。", "corrected_sentence": "我们在海岸上散步，心情很好。", "error_description": "漏掉介词“在”：表示地点要说“在海岸上散步”，不能直接说“海岸上散步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
