INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95093, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "无比是特别特别，没有别的能比。", "primary_collocate": null, "pronunciation": "wú bǐ", "ipa": "u˧˥ pi˨˩˦", "syllable_count": 2, "sentences": [{"text": "听到好消息，我无比高兴。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到孩子的笑脸，妈妈心里无比温暖。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛赢了，大家无比激动。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离开家的那天，我无比难过。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得了第一名，心里无比骄傲。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在山顶，我觉得无比轻松。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回到家，闻到饭菜的香味，我无比幸福。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说老师要来，同学们无比开心。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着空空的房子，她无比孤单。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "终于见到了爸爸，小明无比兴奋。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無比", "label": "繁体"}], "register": "书面", "sense_fingerprint": "副词：用在表示心情感受的形容词前，表示程度特别高，如无比高兴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d21fd02-94af-431a-bf66-245fcefabcc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95093, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无比", "is_correct": true, "explanation": "正确：“无比”是程度副词，用在表示心情的形容词前，表示程度极高。"}, {"text": "丝毫", "is_correct": false, "explanation": "搭配：“丝毫”多与“不”“没有”连用，不能直接修饰“高兴”。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示不得已，与“听到好消息”的喜悦语境矛盾。"}, {"text": "一共", "is_correct": false, "explanation": "语义：“一共”表示总计，不能用来修饰心情形容词。"}], "explanations": {"无比": "正确：“无比”是程度副词，用在表示心情的形容词前，表示程度极高。", "丝毫": "搭配：“丝毫”多与“不”“没有”连用，不能直接修饰“高兴”。", "只好": "语义：“只好”表示不得已，与“听到好消息”的喜悦语境矛盾。", "一共": "语义：“一共”表示总计，不能用来修饰心情形容词。"}, "sentence_index": 0, "correct_answer": "无比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑比那台无比便宜。", "explanation": "这里应该用〈更〉。无比表示没有可以相比的，不能用在“比”字句里做比较，比较时要用“更”。"}, {"text": "他比我无比高兴。", "explanation": "这里应该用〈更〉。无比表示没有可以相比的，与“比”连用逻辑矛盾，比较时要用“更”。"}, {"text": "这个问题他无比解决了。", "explanation": "这里应该用〈彻底〉。无比表示程度极高，不能修饰“解决”这类表示结果的动词，应说“彻底解决”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95093, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无比", "is_correct": true, "explanation": "正确：“无比”修饰表示心情的“幸福”，表示程度极高，符合闻到饭菜香味后的感受。"}, {"text": "一共", "is_correct": false, "explanation": "搭配：“一共”表示总计，需要数量，不能修饰“幸福”。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：“顺便”表示顺带做某事，与表达幸福的情感不合。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”表示由本人动手，与“幸福”这种感受无关。"}], "explanations": {"无比": "正确：“无比”修饰表示心情的“幸福”，表示程度极高，符合闻到饭菜香味后的感受。", "一共": "搭配：“一共”表示总计，需要数量，不能修饰“幸福”。", "顺便": "语义：“顺便”表示顺带做某事，与表达幸福的情感不合。", "亲自": "语义：“亲自”表示由本人动手，与“幸福”这种感受无关。"}, "sentence_index": 6, "correct_answer": "无比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我这次考试无比及格了。", "explanation": "这里应该用〈勉强〉。无比表示程度极高，不能修饰“及格”这种只分有没有、没有程度的动作；“勉强及格”说的是刚好够分。"}, {"text": "他昨天无比结婚了。", "explanation": "这里应该用〈已经〉。无比表示程度极高，不能修饰“结婚”这种表示状态的动作，应说“已经结婚”。"}, {"text": "我今天无比迟到了，只好站在门口。", "explanation": "这里应该用〈居然〉。无比表示程度极高，不能直接修饰“迟到”，要说“居然迟到了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95093, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "看到朋友来了，我很无比开心。", "corrected_sentence": "看到朋友来了，我无比开心。", "error_description": "“无比”本身已表示程度极高，前面不能再加“很”，应去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95093, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "终于回家了，我无比轻松极了。", "corrected_sentence": "终于回家了，我无比轻松。", "error_description": "“无比”已表示程度极高，后面不能再加“极了”，应去掉“极了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
