INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95094, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "没有可以相比的，程度极高。", "primary_collocate": null, "pronunciation": "wú bǐ", "ipa": "u˧˥ pi˨˩˦", "syllable_count": 2, "sentences": [{"text": "长城是一座无比伟大的建筑。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山无比高大，很少有人上去过。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片沙漠无比辽阔。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的花园无比美丽。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的力量无比强大。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的大海无比安静。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对工作的要求无比严格。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的风景无比迷人，我们都不想走。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人的经验无比丰富。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳的光无比明亮，我睁不开眼。", "target_word": "无比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無比", "label": "繁体"}], "register": "书面", "sense_fingerprint": "副词：用在描写事物性质的形容词前，表示程度极高、无可相比，如无比强大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d21fd02-94af-431a-bf66-245fcefabcc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95094, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无比", "is_correct": true, "explanation": "正确：“无比”修饰描写事物性质的形容词“伟大”，表示程度极高。"}, {"text": "丝毫", "is_correct": false, "explanation": "搭配：“丝毫”需与否定词连用，不能修饰“伟大”。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”表示本人动手，与修饰建筑的程度无关。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：“顺便”表示附带，不能用来修饰表示程度的“伟大”。"}], "explanations": {"无比": "正确：“无比”修饰描写事物性质的形容词“伟大”，表示程度极高。", "丝毫": "搭配：“丝毫”需与否定词连用，不能修饰“伟大”。", "亲自": "语义：“亲自”表示本人动手，与修饰建筑的程度无关。", "顺便": "语义：“顺便”表示附带，不能用来修饰表示程度的“伟大”。"}, "sentence_index": 0, "correct_answer": "无比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他无比到了北京。", "explanation": "这里应该用〈终于〉。无比表示程度极高，不能修饰“到”这种表示动作结果的动词。"}, {"text": "这座山比那座无比高大。", "explanation": "这里应该用〈更〉。无比表示没有可以相比的，不能用在“比”字句里，比较时要用“更”。"}, {"text": "这个问题他无比解决了。", "explanation": "这里应该用〈彻底〉。无比表示程度极高，不能修饰“解决”这类表示结果的动词，应说“彻底解决”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95094, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无比", "is_correct": true, "explanation": "正确：“无比”修饰描写事物性质的形容词“严格”，表示要求的程度极高。"}, {"text": "一共", "is_correct": false, "explanation": "语义：“一共”表示总计，不能修饰“严格”。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示无可奈何，与描述要求程度不合。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”表示本人动手，与“要求严格”的程度无关，不能修饰形容词。"}], "explanations": {"无比": "正确：“无比”修饰描写事物性质的形容词“严格”，表示要求的程度极高。", "一共": "语义：“一共”表示总计，不能修饰“严格”。", "只好": "语义：“只好”表示无可奈何，与描述要求程度不合。", "亲自": "语义：“亲自”表示本人动手，与“要求严格”的程度无关，不能修饰形容词。"}, "sentence_index": 6, "correct_answer": "无比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她昨晚无比出差了。", "explanation": "这里应该用〈就〉。无比表示程度极高，不能修饰“出差”这种表示行为的动词，应说“昨晚就出差了”。"}, {"text": "这本书我无比读完了。", "explanation": "这里应该用〈已经〉。无比不能修饰“读完”这种表示结果的动词，应说“已经读完”。"}, {"text": "班里只有他一人无比去过长城。", "explanation": "这里应该用〈曾经〉。无比表示程度极高，不能修饰“去过”这种表示经历的动词，应说“曾经去过”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河的水很无比清澈。", "corrected_sentence": "这条河的水无比清澈。", "error_description": "“无比”本身已表示程度极高，前面不能再加“很”，应去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市的夜景无比迷人极了。", "corrected_sentence": "这个城市的夜景无比迷人。", "error_description": "“无比”已表示程度极高，后面不能再加“极了”，应去掉“极了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
