INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95095, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "煮是把东西放在水里用火烧熟。", "primary_collocate": null, "pronunciation": "zhǔ", "ipa": "ʈʂu˨˩˦", "syllable_count": 1, "sentences": [{"text": "你先煮水，我来切菜。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸今天煮了一大锅汤。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把豆子放进锅里煮一会儿。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用小锅煮了一些鸡蛋。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在家里煮红豆汤。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他煮过很多次饭，做得不错。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜要煮三十分钟。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子饿了，快去煮点东西。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煮好的面条放在桌子上。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天我喜欢煮一壶热茶。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "煮了", "label": "体标"}, {"form": "煮着", "label": "体标"}, {"form": "煮过", "label": "体标"}, {"form": "煮煮", "label": "重叠"}, {"form": "煮熟", "label": "复合"}, {"form": "煮饭", "label": "复合"}], "register": "口语", "sense_fingerprint": "把东西放在水里用火烧熟，日常做饭的说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063f3ad-a04f-4ab6-a8e5-9b13477be05e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95095, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "煮", "is_correct": true, "explanation": "正确：煮（zhǔ，第三声）指把东西放在水里用火烧熟。"}, {"text": "猪", "is_correct": false, "explanation": "zhū（第一声）与 zhǔ（第三声）声调不同，意思是猪。"}, {"text": "竹", "is_correct": false, "explanation": "zhú（第二声）与 zhǔ（第三声）声调不同，意思是竹子。"}, {"text": "处", "is_correct": false, "explanation": "chǔ 与 zhǔ 声母不同（ch 与 zh），声调相同，意思是处理、地方。"}, {"text": "祖", "is_correct": false, "explanation": "zǔ 与 zhǔ 声母不同（z 与 zh），声调相同，意思是祖先。"}, {"text": "数", "is_correct": false, "explanation": "shǔ 与 zhǔ 声母不同（sh 与 zh），声调相同，意思是数数。"}, {"text": "柱", "is_correct": false, "explanation": "zhù（第四声）与 zhǔ（第三声）声调不同，意思是柱子。"}], "explanations": {"煮": "正确：煮（zhǔ，第三声）指把东西放在水里用火烧熟。", "猪": "zhū（第一声）与 zhǔ（第三声）声调不同，意思是猪。", "竹": "zhú（第二声）与 zhǔ（第三声）声调不同，意思是竹子。", "处": "chǔ 与 zhǔ 声母不同（ch 与 zh），声调相同，意思是处理、地方。", "祖": "zǔ 与 zhǔ 声母不同（z 与 zh），声调相同，意思是祖先。", "数": "shǔ 与 zhǔ 声母不同（sh 与 zh），声调相同，意思是数数。", "柱": "zhù（第四声）与 zhǔ（第三声）声调不同，意思是柱子。"}, "sentence_index": null, "correct_answer": "煮"}, "level_3": {"options": [{"text": "煮", "is_correct": true, "explanation": "正确：煮水即烧水加热，与句中“先”和“切菜”的顺序相合。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：摘用于花果、菜叶等，不说摘水。"}, {"text": "锁", "is_correct": false, "explanation": "语义：锁是上锁、关闭，不能用来加热水。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：拍是拍打，与“先……再切菜”的烹饪语境不合，句意不通。"}], "explanations": {"煮": "正确：煮水即烧水加热，与句中“先”和“切菜”的顺序相合。", "摘": "搭配：摘用于花果、菜叶等，不说摘水。", "锁": "语义：锁是上锁、关闭，不能用来加热水。", "拍": "搭配：拍是拍打，与“先……再切菜”的烹饪语境不合，句意不通。"}, "sentence_index": 0, "correct_answer": "煮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们用油锅煮了一些鸡蛋。", "explanation": "这里应该用〈煎〉。煮要在水中加热，用油加热鸡蛋要用煎。"}, {"text": "我们用烤箱煮了一些栗子。", "explanation": "这里应该用〈烘烤〉。煮要用水加热，用烤箱这种干热方式加热栗子要说烘烤。"}, {"text": "我们在不加水的平底锅里煮了一块牛排。", "explanation": "这里应该用〈煎〉。煮需要加水，不加水的平底锅加热牛排要用煎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95095, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "煮", "is_correct": true, "explanation": "正确：煮（zhǔ，第三声）指把东西放在水里用火烧熟。"}, {"text": "住", "is_correct": false, "explanation": "zhù（第四声）与 zhǔ（第三声）声调不同，意思是居住。"}, {"text": "处", "is_correct": false, "explanation": "chǔ 与 zhǔ 声母不同（ch 与 zh），声调相同，意思是处理。"}, {"text": "竹", "is_correct": false, "explanation": "zhú（第二声）与 zhǔ（第三声）声调不同，意思是竹子。"}, {"text": "猪", "is_correct": false, "explanation": "zhū（第一声）与 zhǔ（第三声）声调不同，意思是猪。"}, {"text": "薯", "is_correct": false, "explanation": "shǔ 与 zhǔ 声母不同（sh 与 zh），声调相同，意思是薯类，如红薯。"}, {"text": "组", "is_correct": false, "explanation": "zǔ 与 zhǔ 声母不同（z 与 zh），声调相同，意思是小组。"}], "explanations": {"煮": "正确：煮（zhǔ，第三声）指把东西放在水里用火烧熟。", "住": "zhù（第四声）与 zhǔ（第三声）声调不同，意思是居住。", "处": "chǔ 与 zhǔ 声母不同（ch 与 zh），声调相同，意思是处理。", "竹": "zhú（第二声）与 zhǔ（第三声）声调不同，意思是竹子。", "猪": "zhū（第一声）与 zhǔ（第三声）声调不同，意思是猪。", "薯": "shǔ 与 zhǔ 声母不同（sh 与 zh），声调相同，意思是薯类，如红薯。", "组": "zǔ 与 zhǔ 声母不同（z 与 zh），声调相同，意思是小组。"}, "sentence_index": null, "correct_answer": "煮"}, "level_3": {"options": [{"text": "煮", "is_correct": true, "explanation": "正确：煮菜即加水用火加热，需要三十分钟，符合句意。"}, {"text": "修", "is_correct": false, "explanation": "语义：修是修理，不能用来指做菜的加热过程。"}, {"text": "扫", "is_correct": false, "explanation": "搭配：扫用于地面、垃圾等，不说扫菜。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是抹拭、摩擦，不表示加热，与“要……三十分钟”的烹饪过程不符。"}], "explanations": {"煮": "正确：煮菜即加水用火加热，需要三十分钟，符合句意。", "修": "语义：修是修理，不能用来指做菜的加热过程。", "扫": "搭配：扫用于地面、垃圾等，不说扫菜。", "擦": "语义：擦是抹拭、摩擦，不表示加热，与“要……三十分钟”的烹饪过程不符。"}, "sentence_index": 6, "correct_answer": "煮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用烘箱煮了几块点心。", "explanation": "这里应该用〈烤〉。煮需要在水中加热，用烘箱这种干热方式做点心要说烤。"}, {"text": "我用热油煮了一盘花生。", "explanation": "这里应该用〈炸〉。煮要用水，用热油加热花生要用炸。"}, {"text": "妈妈把面团煮成了一张大饼。", "explanation": "这里应该用〈擀〉。擀是用工具把面团压成薄片，煮是加热，不能把面团煮成饼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95095, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈昨天煮了着一锅粥。", "corrected_sentence": "妈妈昨天煮了一锅粥。", "error_description": "体标错误：“了”与“着”不能同用，“煮了着”不成立，应去掉“着”，说“煮了一锅粥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95095, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前煮了过粥。", "corrected_sentence": "我以前煮过粥。", "error_description": "体标叠加错误：“煮过”中的“过”已表示经历，不能再加“了”，应说“煮过粥”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
