INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95096, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把食物放在水中加热至熟。", "primary_collocate": null, "pronunciation": "zhǔ", "ipa": "ʈʂu˨˩˦", "syllable_count": 1, "sentences": [{"text": "妈妈在厨房煮面条。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想煮两个鸡蛋当早饭。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水开了，你可以煮饺子了。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把土豆煮了二十分钟。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶煮着一锅热汤。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没有煮过米饭。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我们煮点粥吧。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些玉米要煮熟才好吃。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她煮的汤很好喝。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煮牛肉要花很长时间。", "target_word": "煮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "煮了", "label": "体标"}, {"form": "煮着", "label": "体标"}, {"form": "煮过", "label": "体标"}, {"form": "煮煮", "label": "重叠"}, {"form": "煮熟", "label": "复合"}, {"form": "煮饭", "label": "复合"}], "register": "中性", "sense_fingerprint": "把食物放进水里加热直到煮熟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063f3ad-a04f-4ab6-a8e5-9b13477be05e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95096, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "煮", "is_correct": true, "explanation": "正确：煮（zhǔ，第三声）指把食物放在水中加热至熟。"}, {"text": "猪", "is_correct": false, "explanation": "zhū（第一声）与 zhǔ（第三声）声调不同，意思是猪。"}, {"text": "住", "is_correct": false, "explanation": "zhù（第四声）与 zhǔ（第三声）声调不同，意思是居住。"}, {"text": "竹", "is_correct": false, "explanation": "zhú（第二声）与 zhǔ（第三声）声调不同，意思是竹子。"}, {"text": "处", "is_correct": false, "explanation": "chǔ 与 zhǔ 声母不同（ch 与 zh），声调相同，意思是处理、地方。"}, {"text": "数", "is_correct": false, "explanation": "shǔ 与 zhǔ 声母不同（sh 与 zh），声调相同，意思是数数。"}, {"text": "祖", "is_correct": false, "explanation": "zǔ 与 zhǔ 声母不同（z 与 zh），声调相同，意思是祖先。"}], "explanations": {"煮": "正确：煮（zhǔ，第三声）指把食物放在水中加热至熟。", "猪": "zhū（第一声）与 zhǔ（第三声）声调不同，意思是猪。", "住": "zhù（第四声）与 zhǔ（第三声）声调不同，意思是居住。", "竹": "zhú（第二声）与 zhǔ（第三声）声调不同，意思是竹子。", "处": "chǔ 与 zhǔ 声母不同（ch 与 zh），声调相同，意思是处理、地方。", "数": "shǔ 与 zhǔ 声母不同（sh 与 zh），声调相同，意思是数数。", "祖": "zǔ 与 zhǔ 声母不同（z 与 zh），声调相同，意思是祖先。"}, "sentence_index": null, "correct_answer": "煮"}, "level_3": {"options": [{"text": "煮", "is_correct": true, "explanation": "正确：煮面条即把面条放入水中加热至熟，与句中“厨房”相合。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：烤用于面包、肉类等，不说烤面条。"}, {"text": "买", "is_correct": false, "explanation": "语义：买是购买，不是在厨房做的动作，与“在厨房”冲突。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：擦用于桌面、地面等，面条不能擦。"}], "explanations": {"煮": "正确：煮面条即把面条放入水中加热至熟，与句中“厨房”相合。", "烤": "搭配：烤用于面包、肉类等，不说烤面条。", "买": "语义：买是购买，不是在厨房做的动作，与“在厨房”冲突。", "擦": "搭配：擦用于桌面、地面等，面条不能擦。"}, "sentence_index": 0, "correct_answer": "煮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用油煮了土豆丝，很快就好了。", "explanation": "这里应该用〈炒〉。煮要在水中加热，用油加热食物要用炒。"}, {"text": "妈妈用烤箱煮了几个红薯。", "explanation": "这里应该用〈烘烤〉。煮要在水中加热，用烤箱这种干热方式加热红薯要说烘烤。"}, {"text": "妈妈用平底锅煮了几张饼。", "explanation": "这里应该用〈烙〉。煮需要加水，在干的平底锅上加热饼要用烙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95096, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "煮", "is_correct": true, "explanation": "正确：煮（zhǔ，第三声）指把食物放在水中加热至熟。"}, {"text": "处", "is_correct": false, "explanation": "chǔ 与 zhǔ 声母不同（ch 与 zh），声调相同，意思是处理。"}, {"text": "柱", "is_correct": false, "explanation": "zhù（第四声）与 zhǔ（第三声）声调不同，意思是柱子。"}, {"text": "猪", "is_correct": false, "explanation": "zhū（第一声）与 zhǔ（第三声）声调不同，意思是猪。"}, {"text": "竹", "is_correct": false, "explanation": "zhú（第二声）与 zhǔ（第三声）声调不同，意思是竹子。"}, {"text": "薯", "is_correct": false, "explanation": "shǔ 与 zhǔ 声母不同（sh 与 zh），声调相同，意思是薯类，如红薯。"}, {"text": "组", "is_correct": false, "explanation": "zǔ 与 zhǔ 声母不同（z 与 zh），声调相同，意思是小组。"}], "explanations": {"煮": "正确：煮（zhǔ，第三声）指把食物放在水中加热至熟。", "处": "chǔ 与 zhǔ 声母不同（ch 与 zh），声调相同，意思是处理。", "柱": "zhù（第四声）与 zhǔ（第三声）声调不同，意思是柱子。", "猪": "zhū（第一声）与 zhǔ（第三声）声调不同，意思是猪。", "竹": "zhú（第二声）与 zhǔ（第三声）声调不同，意思是竹子。", "薯": "shǔ 与 zhǔ 声母不同（sh 与 zh），声调相同，意思是薯类，如红薯。", "组": "zǔ 与 zhǔ 声母不同（z 与 zh），声调相同，意思是小组。"}, "sentence_index": null, "correct_answer": "煮"}, "level_3": {"options": [{"text": "煮", "is_correct": true, "explanation": "正确：煮粥即加水用火加热做粥，与句中“粥”相合。"}, {"text": "扫", "is_correct": false, "explanation": "搭配：扫用于地面、垃圾等，不说扫粥。"}, {"text": "锁", "is_correct": false, "explanation": "语义：锁是关闭、上锁，与做饭无关，句意不通。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：拍是拍打、拍照，不能用于粥。"}], "explanations": {"煮": "正确：煮粥即加水用火加热做粥，与句中“粥”相合。", "扫": "搭配：扫用于地面、垃圾等，不说扫粥。", "锁": "语义：锁是关闭、上锁，与做饭无关，句意不通。", "拍": "搭配：拍是拍打、拍照，不能用于粥。"}, "sentence_index": 6, "correct_answer": "煮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用烘箱煮了一盘饼干。", "explanation": "这里应该用〈烤〉。煮需要在水中加热，用烘箱这种干热方式做饼干要说烤。"}, {"text": "我用热油煮了一盘薯条。", "explanation": "这里应该用〈炸〉。煮要用水，用热油加热薯条要用炸。"}, {"text": "妈妈把面团煮成了一张大饼。", "explanation": "这里应该用〈擀〉。擀是用工具把面团压成薄片，煮是加热，不能把面团煮成饼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把饺子熟煮了。", "corrected_sentence": "我们把饺子煮熟了。", "error_description": "补语位置错误：“煮”后应接结果补语“熟”，说“煮熟”，不说“熟煮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天煮了过汤。", "corrected_sentence": "我昨天煮过汤。", "error_description": "体标叠加错误：“煮过”中的“过”已表示经历，不能再加“了”，应说“煮过汤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
