INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95099, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "书、歌、画等作品的权利归创作者所有，别人不能随便使用。", "primary_collocate": null, "pronunciation": "bǎn quán", "ipa": "pan˨˩ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这首歌有版权，你不能随便用。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我画的画，版权是我的。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，用别人的歌要注意版权。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个视频有版权，别人不能拿去用。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你拍的照片有版权吗？", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的书版权是他自己的。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有版权的音乐，大家都可以用。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张画的版权是谁的？", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很在意自己作品的版权。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的歌也有版权，不能乱用。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "版权所有", "label": "复合"}, {"form": "版权费", "label": "复合"}], "register": "中性", "sense_fingerprint": "书、歌、画等作品归创作者所有，别人不能随便使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063f3ad-a04f-4ab6-a8e5-9b13477be05e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95099, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "版权", "is_correct": true, "explanation": "正确：“这首歌有版权，你不能随便用”，版权指作品的权利。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：歌曲不会有脾气，与“不能随便用”的语境无关。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“有体重”一般只用于人或物体，不能用于歌曲。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“有身高”只用于人，歌曲没有身高。"}], "explanations": {"版权": "正确：“这首歌有版权，你不能随便用”，版权指作品的权利。", "脾气": "语义：歌曲不会有脾气，与“不能随便用”的语境无关。", "体重": "搭配：“有体重”一般只用于人或物体，不能用于歌曲。", "身高": "搭配：“有身高”只用于人，歌曲没有身高。"}, "sentence_index": 0, "correct_answer": "版权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个新机器已经申请了版权。", "explanation": "这里应该用〈专利〉。新机器的技术成果要申请专利，版权保护文学和艺术作品。"}, {"text": "这种饮料的牌子已经注册了版权。", "explanation": "这里应该用〈商标〉。品牌名称要注册商标，版权保护的是文学和艺术作品。"}, {"text": "他卖了一把版权。", "explanation": "这里不能用〈把〉。“把”用于有柄的物件，版权是抽象的权利，应说“卖出版权”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95099, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "版权", "is_correct": true, "explanation": "正确：“没有版权的音乐，大家都可以用”，版权决定了能否随便使用。"}, {"text": "视力", "is_correct": false, "explanation": "语义：音乐没有视力，与句中的语境不符。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：音乐不会有鞋子，这个搭配不合逻辑。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：“饭量”只用于人或动物，不能用于音乐。"}], "explanations": {"版权": "正确：“没有版权的音乐，大家都可以用”，版权决定了能否随便使用。", "视力": "语义：音乐没有视力，与句中的语境不符。", "鞋子": "语义：音乐不会有鞋子，这个搭配不合逻辑。", "饭量": "搭配：“饭量”只用于人或动物，不能用于音乐。"}, "sentence_index": 6, "correct_answer": "版权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书有很多版权，你想买哪一版？", "explanation": "这里应该用〈版本〉。版权指作品的归属与使用权，不是书的不同印刷版本。"}, {"text": "他考到了版权。", "explanation": "这里应该用〈驾照〉。版权是对作品的权利，不是考试可以取得的证件。"}, {"text": "这趟火车的版权已经满了。", "explanation": "这里应该用〈座位〉。版权不是可以坐满的东西，不能用“满了”来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95099, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这幅画的一幅版权是我的。", "corrected_sentence": "这幅画的版权是我的。", "error_description": "量词错误：“幅”用于画作，不能修饰“版权”。正确说法是“这幅画的版权是我的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95099, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前买了过这首歌的版权。", "corrected_sentence": "他以前买过这首歌的版权。", "error_description": "体标错误：“过”表示经历，不能与“了”连用。正确说法是“买过这首歌的版权”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
