INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95100, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "作者对其作品依法享有的专有权利。", "primary_collocate": null, "pronunciation": "bǎn quán", "ipa": "pan˨˩ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这本书的版权属于作者。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买版权要花很多钱。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的版权已经卖给公司了。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司没有这部电影的版权。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用别人的照片，要先取得版权。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家出版社买到了小说的版权。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图有版权，不能随便用。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者把版权卖给了出版社。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护版权对作者很重要。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站侵犯了我们的版权。", "target_word": "版权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "版权所有", "label": "复合"}, {"form": "版权费", "label": "复合"}], "register": "书面", "sense_fingerprint": "作者对作品依法享有的专有权利，法律意义上的版权", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063f3ad-a04f-4ab6-a8e5-9b13477be05e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95100, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "版权", "is_correct": true, "explanation": "正确：“版权”是作者对作品依法享有的权利，可以属于作者。"}, {"text": "页码", "is_correct": false, "explanation": "语义：属于作者的是版权，页码不是作者的权利。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“属于”要接可以被拥有的东西，“价格”不能说“属于作者”。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数不是作者的权利，与“属于作者”的语境不符。"}], "explanations": {"版权": "正确：“版权”是作者对作品依法享有的权利，可以属于作者。", "页码": "语义：属于作者的是版权，页码不是作者的权利。", "价格": "搭配：“属于”要接可以被拥有的东西，“价格”不能说“属于作者”。", "字数": "语义：字数不是作者的权利，与“属于作者”的语境不符。"}, "sentence_index": 0, "correct_answer": "版权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项发明已经申请了版权。", "explanation": "这里应该用〈专利〉。版权保护文学艺术作品，发明创造要申请专利。"}, {"text": "这个牌子已经注册了版权。", "explanation": "这里应该用〈商标〉。商标用于品牌标识，版权保护的是作品。"}, {"text": "他买下了一把版权。", "explanation": "这里不能用〈把〉。“把”用于有柄的物件，版权是抽象的权利，应说“买下版权”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95100, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "版权", "is_correct": true, "explanation": "正确：图片有版权，所以不能随便用。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：图片不会有脾气，与“不能随便用”的语境无关。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“有身高”只用于人，图片没有身高。"}, {"text": "性格", "is_correct": false, "explanation": "语义：图片没有性格，与句中的语境不符。"}], "explanations": {"版权": "正确：图片有版权，所以不能随便用。", "脾气": "语义：图片不会有脾气，与“不能随便用”的语境无关。", "身高": "搭配：“有身高”只用于人，图片没有身高。", "性格": "语义：图片没有性格，与句中的语境不符。"}, "sentence_index": 6, "correct_answer": "版权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她拿到了博士版权。", "explanation": "这里应该用〈学位〉。版权是对作品的权利，不是学业资格。"}, {"text": "他办了北京版权。", "explanation": "这里应该用〈户口〉。版权是对作品的权利，不能用来办理户籍。"}, {"text": "这所学校今年的版权很少。", "explanation": "这里应该用〈名额〉。版权是权利，不是可以按数量计算的名额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95100, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "出版社已经买下了这本书的一把版权。", "corrected_sentence": "出版社已经买下了这本书的版权。", "error_description": "量词错误：“版权”是抽象的权利，前面不能加“一把”这类量词。正确说法是“买下了这本书的版权”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95100, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司以前买了过这部电影的版权。", "corrected_sentence": "我们公司以前买过这部电影的版权。", "error_description": "体标错误：“过”表示经历，不能与“了”连用。正确说法是“买过这部电影的版权”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
