INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95102, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "完成学业并从学校毕业的学生。", "primary_collocate": null, "pronunciation": "bì yè shēng", "ipa": "pi˥˩ ie˥˩ ʂɤŋ˥", "syllable_count": 3, "sentences": [{"text": "她是一名大学毕业生，在银行工作。", "target_word": "毕业生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司今年要招十个毕业生。", "target_word": "毕业生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业生拿着证书，笑得很开心。", "target_word": "毕业生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多毕业生去了别的城市工作。", "target_word": "毕业生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个毕业生写过很多好文章。", "target_word": "毕业生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请毕业生回来讲讲自己的故事。", "target_word": "毕业生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业生找到工作了，家人很高兴。", "target_word": "毕业生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是新毕业生，已经工作五年了。", "target_word": "毕业生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年的毕业生现在都在做什么？", "target_word": "毕业生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毕业生们在学校门口拍了合影。", "target_word": "毕业生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "大学毕业生", "label": "复合"}, {"form": "应届毕业生", "label": "复合"}], "register": "中性", "sense_fingerprint": "完成学业、已从学校毕业的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755a2819-fc8e-4d21-b491-ab1430d215e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95102, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毕业生", "is_correct": true, "explanation": "毕业生指已完成学业的人，“一名大学毕业生”与句意相符。"}, {"text": "司机", "is_correct": false, "explanation": "搭配：“大学司机”不是通用说法，“大学”修饰的应是学历身份，且与“在银行工作”不合。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“大学厨师”不是通用说法，且与“在银行工作”矛盾。"}, {"text": "护士", "is_correct": false, "explanation": "语义：护士的工作地点是医院，与“在银行工作”的句意矛盾。"}], "explanations": {"毕业生": "毕业生指已完成学业的人，“一名大学毕业生”与句意相符。", "司机": "搭配：“大学司机”不是通用说法，“大学”修饰的应是学历身份，且与“在银行工作”不合。", "厨师": "搭配：“大学厨师”不是通用说法，且与“在银行工作”矛盾。", "护士": "语义：护士的工作地点是医院，与“在银行工作”的句意矛盾。"}, "sentence_index": 0, "correct_answer": "毕业生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位毕业生还要再读三年才能毕业。", "explanation": "这里应该用〈在校生〉。毕业生已经完成学业，不需要再读三年才毕业。"}, {"text": "这位毕业生今年刚入学，还不熟悉校园。", "explanation": "这里应该用〈新生〉。毕业生已完成学业并从学校毕业，不会刚入学；刚入学、还不熟悉校园的是新生。"}, {"text": "这位毕业生明天还要到教室交作业。", "explanation": "这里应该用〈在校生〉。毕业生已完成学业并从学校毕业，不会再到教室交作业；需要到教室交作业的是在校生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4a3377f-3e32-4c57-9340-b9253ea5873e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95102, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毕业生", "is_correct": true, "explanation": "毕业生指已完成学业的人，能够“找到工作”，与句意相符。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿还不能工作，不可能“找到工作”。"}, {"text": "新生", "is_correct": false, "explanation": "语义：新生刚入学，还没有毕业，不会“找到工作”。"}, {"text": "小学生", "is_correct": false, "explanation": "搭配：“找到工作”的主语应是成年人，小学生不找工作，与句意不搭。"}], "explanations": {"毕业生": "毕业生指已完成学业的人，能够“找到工作”，与句意相符。", "婴儿": "语义：婴儿还不能工作，不可能“找到工作”。", "新生": "语义：新生刚入学，还没有毕业，不会“找到工作”。", "小学生": "搭配：“找到工作”的主语应是成年人，小学生不找工作，与句意不搭。"}, "sentence_index": 6, "correct_answer": "毕业生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毕业生今年秋天要转入我们班插班学习。", "explanation": "这里应该用〈插班生〉。毕业生已完成学业并从学校毕业，不会转入班级插班学习；插班学习的是插班生。"}, {"text": "这个毕业生明年九月才开始上大学。", "explanation": "这里应该用〈高中生〉。还没开始上大学的人不是大学毕业生；毕业生是已经完成学业的人。"}, {"text": "这位毕业生今年要留级，重新读一年级。", "explanation": "这里应该用〈留级生〉。毕业生已完成学业并从学校毕业，不会留级重读；留级、重新读一年级的是留级生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4a3377f-3e32-4c57-9340-b9253ea5873e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三毕业生都找到了工作。", "corrected_sentence": "三名毕业生都找到了工作。", "error_description": "“三”与“毕业生”之间要有量词，应说“三名毕业生”，错误在漏掉量词“名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4a3377f-3e32-4c57-9340-b9253ea5873e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐是一只大学毕业生。", "corrected_sentence": "我姐姐是一名大学毕业生。", "error_description": "量词错误：“毕业生”是人，量词应用“名”，“只”用于动物，不能用于此。应说“一名大学毕业生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4a3377f-3e32-4c57-9340-b9253ea5873e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95103, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95103, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95103, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "眼中是在眼睛里面，指表情、神色等出现的位置。", "primary_collocate": null, "pronunciation": "yǎn zhōng", "ipa": "jɛn˨˩ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "他的眼中满是泪水。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子眼中带着笑意。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的眼中有一点害怕。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从他眼中看到了希望。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人眼中闪着光。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼中映着烛光。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她眼中闪过一丝惊讶。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她眼中满是倦意。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗眼中全是好奇。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他眼中透出感激之意。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "眼睛里面；表情、神色出现的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ea03b26-13d4-42c6-b4dd-6754678089d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95103, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼中", "is_correct": true, "explanation": "眼中指眼睛里面，与“满是泪水”搭配，表示泪水充满双眼。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“天空”不能说“他的天空”，泪水也不会满在天空里。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是能盛满泪水的部位，“他的汽车满是泪水”说不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不能指人的眼睛，泪水也不会充满厨房。"}], "explanations": {"眼中": "眼中指眼睛里面，与“满是泪水”搭配，表示泪水充满双眼。", "天空": "搭配：“天空”不能说“他的天空”，泪水也不会满在天空里。", "汽车": "语义：汽车不是能盛满泪水的部位，“他的汽车满是泪水”说不通。", "厨房": "语义：厨房是做饭的地方，不能指人的眼睛，泪水也不会充满厨房。"}, "sentence_index": 0, "correct_answer": "眼中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙放进了眼中，找了很久。", "explanation": "这里应该用〈抽屉里〉之类的容器词。“眼中”指眼睛内部，不能表示放东西的地方。"}, {"text": "他每天晚上都在眼中做作业。", "explanation": "这里应该用〈书桌上〉之类的地点。“眼中”指眼睛里面，是表情、神色出现的位置，不能作为做作业的场所。"}, {"text": "一群人站在他的眼中，等着开门。", "explanation": "这里应该用〈人群中〉之类的场所词。“眼中”指眼睛里面，不能作为人站立的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95103, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼中", "is_correct": true, "explanation": "眼中指眼睛里面，与“闪过一丝惊讶”搭配，表示惊讶出现在眼神里。"}, {"text": "手中", "is_correct": false, "explanation": "语义：“手中”指拿在手里的位置，惊讶不会闪过手中。"}, {"text": "脚下", "is_correct": false, "explanation": "语义：“脚下”指脚底下的地面，惊讶不会闪过脚下。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不能指人的表情，惊讶不会闪过厨房。"}], "explanations": {"眼中": "眼中指眼睛里面，与“闪过一丝惊讶”搭配，表示惊讶出现在眼神里。", "手中": "语义：“手中”指拿在手里的位置，惊讶不会闪过手中。", "脚下": "语义：“脚下”指脚底下的地面，惊讶不会闪过脚下。", "厨房": "语义：厨房是做饭的地方，不能指人的表情，惊讶不会闪过厨房。"}, "sentence_index": 6, "correct_answer": "眼中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在老师的眼中吃了一顿饭。", "explanation": "这里应该用〈饭厅里〉之类的场所词。“眼中”指眼睛里面，是表情、神色出现的位置，不能表示吃饭的地方。"}, {"text": "我每天上午都在眼中买菜。", "explanation": "这里应该用〈菜市场里〉之类的场所词。“眼中”指眼睛里面，是表情、神色出现的位置，不能表示买菜的地方。"}, {"text": "他在我的眼中写下了一封信。", "explanation": "这里应该用〈信纸上〉之类的地点。“眼中”指眼睛里面，是表情、神色出现的位置，不能作为写信的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95103, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的眼中里布满了血丝，可能是没睡好。", "corrected_sentence": "他的眼中布满了血丝，可能是没睡好。", "error_description": "错误形式：“眼中”后又加了“里”，形成双重方位。正确形式：“眼中”本身已表示位置，去掉“里”，应说“他的眼中布满了血丝”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95103, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她哭了很久，眼中里还带着泪光。", "corrected_sentence": "她哭了很久，眼中还带着泪光。", "error_description": "错误形式：“眼中”后又加了“里”，形成双重方位。正确形式：去掉“里”，说“眼中还带着泪光”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
