INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95104, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在某人看来；指某人心目中的看法。", "primary_collocate": null, "pronunciation": "yǎn zhōng", "ipa": "jɛn˨˩ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "在孩子眼中，爸爸什么都会。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在朋友眼中，她是个热心人。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件小事在他眼中并不小。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我眼中，这里是最美的地方。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他眼中的世界和我的不一样。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在医生眼中，病人都一样重要。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在老板眼中，时间就是钱。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她眼中的生活很简单。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在球迷眼中，他是最好的球员。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在他眼中，金钱远没有朋友重要。", "target_word": "眼中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "在某人看来；某人心目中的看法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ea03b26-13d4-42c6-b4dd-6754678089d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95104, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼中", "is_correct": true, "explanation": "眼中指在某人看来，与“在孩子”搭配，表示孩子的看法。"}, {"text": "手中", "is_correct": false, "explanation": "语义：“手中”指拿在手里的位置，不能表示孩子的看法。"}, {"text": "口袋里", "is_correct": false, "explanation": "搭配：“在孩子口袋里”后不能接对爸爸的评价，口袋不是看法的位置。"}, {"text": "床上", "is_correct": false, "explanation": "语义：“床上”指睡觉的地方，与孩子对爸爸的看法无关。"}], "explanations": {"眼中": "眼中指在某人看来，与“在孩子”搭配，表示孩子的看法。", "手中": "语义：“手中”指拿在手里的位置，不能表示孩子的看法。", "口袋里": "搭配：“在孩子口袋里”后不能接对爸爸的评价，口袋不是看法的位置。", "床上": "语义：“床上”指睡觉的地方，与孩子对爸爸的看法无关。"}, "sentence_index": 0, "correct_answer": "眼中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我眼中很难过，因为他走了。", "explanation": "这里应该用〈心里〉。“眼中”指眼睛里或在某人看来，不能表示个人内心的感受。"}, {"text": "她每天晚上都在我的眼中写日记。", "explanation": "这里应该用〈书桌前〉之类的地点。“眼中”指眼睛里或在某人看来，不能表示写日记的地方。"}, {"text": "他把饼干藏进了我的眼中。", "explanation": "这里应该用〈柜子里〉之类的容器词。“眼中”指眼睛内部或在某人看来，不能表示藏东西的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95104, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼中", "is_correct": true, "explanation": "眼中指在某人看来，与“在老板”搭配，表示老板的看法。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是建筑部件，不能表示老板的看法，句子不通。"}, {"text": "钱包里", "is_correct": false, "explanation": "搭配：“在老板钱包里”后不能接对时间的评价，钱包不是看法的位置。"}, {"text": "河里", "is_correct": false, "explanation": "语义：“河里”指河流之中的位置，与老板对时间的看法无关。"}], "explanations": {"眼中": "眼中指在某人看来，与“在老板”搭配，表示老板的看法。", "窗户": "语义：“窗户”是建筑部件，不能表示老板的看法，句子不通。", "钱包里": "搭配：“在老板钱包里”后不能接对时间的评价，钱包不是看法的位置。", "河里": "语义：“河里”指河流之中的位置，与老板对时间的看法无关。"}, "sentence_index": 6, "correct_answer": "眼中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的眼中住着一家三口。", "explanation": "这里应该用〈家里〉之类的场所词。“眼中”指眼睛里或在某人看来，不能表示居住的地方。"}, {"text": "我在他的眼中吃了一顿晚饭。", "explanation": "这里应该用〈饭馆里〉之类的场所词。“眼中”指眼睛里或在某人看来，不能表示吃饭的地方。"}, {"text": "他在我的眼中跑了一圈操场。", "explanation": "这里应该用〈操场上〉之类的场所词。“眼中”指眼睛里或在某人看来，不能表示跑步的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在我眼中里，他很可靠。", "corrected_sentence": "在我眼中，他很可靠。", "error_description": "错误形式：“眼中”后又加了“里”，形成双重方位。正确形式：去掉“里”，说“在我眼中”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在大家眼中里，她是个成功的人。", "corrected_sentence": "在大家眼中，她是个成功的人。", "error_description": "错误形式：“眼中”后又加了“里”，形成双重方位。正确形式：去掉“里”，说“在大家眼中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
