INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95105, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "瞬间是特别短的一点点时间。", "primary_collocate": null, "pronunciation": "shùn jiān", "ipa": "ʂwən˥˩ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "瞬间的快乐也很珍贵。", "target_word": "瞬间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水杯落地的瞬间，就碎成了几片。", "target_word": "瞬间", "complexity_tier": "T3", "furigana": "shuǐ bēi luò dì de shùn jiān, jiù suì chéng le jǐ piàn.", "sentence_source": "generated"}, {"text": "看到他的瞬间，我哭了。", "target_word": "瞬间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间过得很快，一年好像只是一瞬间。", "target_word": "瞬间", "complexity_tier": "T3", "furigana": "shí jiān guò de hěn kuài, yì nián hǎo xiàng zhǐ shì yí shùn jiān.", "sentence_source": "generated"}, {"text": "火在瞬间烧到了屋顶。", "target_word": "瞬间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子出生的瞬间，爸爸笑了。", "target_word": "瞬间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片留住了美好的瞬间。", "target_word": "瞬间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "就在那一瞬间，他决定答应了。", "target_word": "瞬间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话铃一响的瞬间，她就醒了。", "target_word": "瞬间", "complexity_tier": "T3", "furigana": "diàn huà líng yì xiǎng de shùn jiān, tā jiù xǐng le.", "sentence_source": "generated"}, {"text": "那一瞬间，我觉得很幸福。", "target_word": "瞬间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "特别短的一点点时间，常指某个动作或情景发生的一刻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ea03b26-13d4-42c6-b4dd-6754678089d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95105, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "瞬间", "is_correct": true, "explanation": "瞬间指特别短的一刻，修饰“快乐”，表示快乐只持续一瞬间，句子通顺。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：“铅笔”是文具，不能与“快乐”构成所属关系，句子不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重的快乐”不搭配，体重不能带来快乐这一含义。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是建筑部件，与“快乐”没有修饰关系，说不通。"}], "explanations": {"瞬间": "瞬间指特别短的一刻，修饰“快乐”，表示快乐只持续一瞬间，句子通顺。", "铅笔": "语义：“铅笔”是文具，不能与“快乐”构成所属关系，句子不通。", "体重": "搭配：“体重的快乐”不搭配，体重不能带来快乐这一含义。", "窗户": "语义：“窗户”是建筑部件，与“快乐”没有修饰关系，说不通。"}, "sentence_index": 0, "correct_answer": "瞬间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在这里生活了一瞬间，已经二十年了。", "explanation": "这里应该用〈一直〉之类的表示长时段的词。“瞬间”表示极短的一点点时间，不能与“二十年”这样的长时段搭配。"}, {"text": "他的工资只有一瞬间。", "explanation": "这里应该用〈一笔钱〉。“瞬间”只指时间，不能表示工资的数量。"}, {"text": "我的瞬间每天都来找我玩。", "explanation": "这里应该用〈朋友〉之类的人物名词。“瞬间”是时间概念，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95105, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瞬间", "is_correct": true, "explanation": "瞬间指一眨眼的工夫，修饰“美好的”，表示照片留住的那一刻。"}, {"text": "数量", "is_correct": false, "explanation": "语义：“数量”指多少，照片留不住数量，“美好的数量”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不能被“美好的”修饰，“美好的身高”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“美好的价格”不是常用搭配，照片也不能留住价格。"}], "explanations": {"瞬间": "瞬间指一眨眼的工夫，修饰“美好的”，表示照片留住的那一刻。", "数量": "语义：“数量”指多少，照片留不住数量，“美好的数量”说不通。", "身高": "搭配：“身高”不能被“美好的”修饰，“美好的身高”说不通。", "价格": "搭配：“美好的价格”不是常用搭配，照片也不能留住价格。"}, "sentence_index": 6, "correct_answer": "瞬间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那一瞬间的学校很大，有三千个学生。", "explanation": "这里应该用〈校园〉之类的场所词。“瞬间”是时间概念，不能指学校这样的场所。"}, {"text": "这一瞬间的书很厚，有五百页。", "explanation": "这里应该用〈篇幅〉之类的词。“瞬间”是时间概念，不能用来形容书的厚度。"}, {"text": "我们一瞬间住了三年。", "explanation": "这里应该用〈长期〉之类的词。“瞬间”表示极短的一点点时间，不能与“住了三年”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95105, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只快乐的瞬间让我难忘。", "corrected_sentence": "那个快乐的瞬间让我难忘。", "error_description": "错误形式：“瞬间”用了量词“只”，“只”多用于动物等。正确形式：“瞬间”应配量词“个”，说“那个快乐的瞬间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95105, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门开的那只瞬间，我看到了她。", "corrected_sentence": "门开的那个瞬间，我看到了她。", "error_description": "错误形式：“瞬间”用了量词“只”，“只”多用于动物等。正确形式：“瞬间”应配量词“个”，说“那个瞬间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
