INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95106, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "极短的时间，一眨眼的工夫。", "primary_collocate": null, "pronunciation": "shùn jiān", "ipa": "ʂwən˥˩ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "那个瞬间，我什么都忘了。", "target_word": "瞬间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯亮的那一瞬间，房间一下子变得很亮。", "target_word": "瞬间", "complexity_tier": "T3", "furigana": "dēng liàng de nà yí shùn jiān, fáng jiān yí xià zi biàn de hěn liàng.", "sentence_source": "generated"}, {"text": "这个瞬间，我永远不会忘记。", "target_word": "瞬间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一瞬间，天就黑了。", "target_word": "瞬间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车在瞬间就不见了。", "target_word": "瞬间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑的瞬间，大家都安静了。", "target_word": "瞬间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抓住了拍照的那个瞬间。", "target_word": "瞬间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "就在那一瞬间，雨下得更大了。", "target_word": "瞬间", "complexity_tier": "T3", "furigana": "jiù zài nà yí shùn jiān, yǔ xià de gèng dà le.", "sentence_source": "generated"}, {"text": "比赛结束的瞬间，球迷都站了起来。", "target_word": "瞬间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是一瞬间的事，别担心。", "target_word": "瞬间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "极短的一段时间，一眨眼的工夫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ea03b26-13d4-42c6-b4dd-6754678089d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95106, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "瞬间", "is_correct": true, "explanation": "瞬间指极短的一刻，与“那个……我什么都忘了”搭配，指当时的那一刻。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不指时间，“那个价格，我什么都忘了”说不通。"}, {"text": "座位", "is_correct": false, "explanation": "语义：“座位”指坐的地方，不表示时间，与“什么都忘了”不相干。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：“牛奶”是饮品，不能与“那个……我什么都忘了”搭配，句子不通。"}], "explanations": {"瞬间": "瞬间指极短的一刻，与“那个……我什么都忘了”搭配，指当时的那一刻。", "价格": "语义：“价格”指钱数，不指时间，“那个价格，我什么都忘了”说不通。", "座位": "语义：“座位”指坐的地方，不表示时间，与“什么都忘了”不相干。", "牛奶": "语义：“牛奶”是饮品，不能与“那个……我什么都忘了”搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "瞬间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们已经有一瞬间没见面了。", "explanation": "这里应该用〈一段时间〉。瞬间指一眨眼的工夫，不能用来说几个月的时间跨度。"}, {"text": "这个暑假的瞬间很长。", "explanation": "“瞬间”指极短的一刻，不能形容暑假这样的长时段，这里应该说“时间”。"}, {"text": "这本书的瞬间有五百页。", "explanation": "这里应该用〈篇幅〉之类的词。“瞬间”是极短的一刻，不能指书的页数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95106, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瞬间", "is_correct": true, "explanation": "瞬间指拍照那一刻，与“抓住了拍照的那个”搭配，表示按下快门的时刻。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”指走路的动作，不能被“抓住”来表示拍照的那一刻。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“抓住”后不能接“价格”，这一搭配不成立。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不是可以被抓住的拍照时刻，这里说不通。"}], "explanations": {"瞬间": "瞬间指拍照那一刻，与“抓住了拍照的那个”搭配，表示按下快门的时刻。", "脚步": "语义：“脚步”指走路的动作，不能被“抓住”来表示拍照的那一刻。", "价格": "搭配：“抓住”后不能接“价格”，这一搭配不成立。", "名字": "语义：“名字”不是可以被抓住的拍照时刻，这里说不通。"}, "sentence_index": 6, "correct_answer": "瞬间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行的一瞬间有三个星期。", "explanation": "“瞬间”指极短的一刻，不能用来计算三个星期，这里应该说“时间”。"}, {"text": "这间屋子的瞬间很大。", "explanation": "这里应该用〈面积〉。“瞬间”是时间概念，不能用来形容房间的大小。"}, {"text": "这个瞬间的河流很长，有几千公里。", "explanation": "这里应该用〈长度〉之类的词。“瞬间”指极短的一刻，不能用来形容河流的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我记住了那只美好的瞬间。", "corrected_sentence": "我记住了那个美好的瞬间。", "error_description": "错误形式：“瞬间”用了量词“只”，“只”多用于动物等。正确形式：“瞬间”应配量词“个”，说“那个美好的瞬间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那只精彩的瞬间拍了下来。", "corrected_sentence": "他把那个精彩的瞬间拍了下来。", "error_description": "错误形式：“瞬间”用了量词“只”，“只”多用于动物等。正确形式：“瞬间”应配量词“个”，说“那个精彩的瞬间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
