INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95107, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "研究中心是很多人一起研究事情的地方。", "primary_collocate": null, "pronunciation": "yán jiū zhōng xīn", "ipa": "jɛn˧˥ tɕjoʊ˥ ʈʂʊŋ˥ ɕin˥", "syllable_count": 4, "sentences": [{"text": "我的朋友在一个研究中心工作。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究中心里有很多老师和学生。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上八点到研究中心。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究中心离我家不远。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究中心的大楼旁边有一个小花园。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家在研究中心一起讨论问题。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校新建了一个研究中心。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她下班后从研究中心走回家。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究中心里很安静，大家都在看书。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在研究中心做了三年实验。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词：很多人一起工作、研究的地方，侧重具体的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d21fd02-94af-431a-bf66-245fcefabcc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95107, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究中心", "is_correct": true, "explanation": "正确。研究中心是很多人一起研究的地方，可以作“工作”的地点。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，不是可以去工作的地方。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，人不能在太阳上工作。"}, {"text": "手机", "is_correct": false, "explanation": "配价：“工作”要求处所或机构作地点，手机不能充当工作地点。"}], "explanations": {"研究中心": "正确。研究中心是很多人一起研究的地方，可以作“工作”的地点。", "小说": "语义：小说是文学作品，不是可以去工作的地方。", "太阳": "语义：太阳是天体，人不能在太阳上工作。", "手机": "配价：“工作”要求处所或机构作地点，手机不能充当工作地点。"}, "sentence_index": 0, "correct_answer": "研究中心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校门口有一只研究中心。", "explanation": "这里应该用〈个〉或〈家〉。〈只〉多用于动物，研究中心是机构，不能用〈只〉计量。"}, {"text": "我们城市新建了一条研究中心。", "explanation": "这里应该用〈个〉或〈家〉。〈条〉用于细长的东西，研究中心不能用〈条〉计量。"}, {"text": "我们学校新建了一位研究中心。", "explanation": "这里应该用〈个〉或〈家〉。〈位〉用于人，研究中心是机构，不能用〈位〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95107, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究中心", "is_correct": true, "explanation": "正确。“新建”的对象可以是机构。"}, {"text": "诗", "is_correct": false, "explanation": "语义：诗是文学作品，不是可以新建的机构或建筑。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然形成的，不能说“新建”。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：“新建”多用于机构、建筑，不能与“手套”搭配。"}], "explanations": {"研究中心": "正确。“新建”的对象可以是机构。", "诗": "语义：诗是文学作品，不是可以新建的机构或建筑。", "河流": "语义：河流是自然形成的，不能说“新建”。", "手套": "搭配：“新建”多用于机构、建筑，不能与“手套”搭配。"}, "sentence_index": 6, "correct_answer": "研究中心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我姐姐毕业以后想当研究中心。", "explanation": "这里应该用〈研究生〉。研究中心指机构，不能指人，所以不能说“想当研究中心”。"}, {"text": "爷爷退休前当了研究中心。", "explanation": "这里应该用〈老师〉。研究中心是机构，不能作为职业身份。"}, {"text": "我的邻居是研究中心。", "explanation": "这里应该用〈医生〉。研究中心指机构，不能用来指一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95107, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在一只研究中心实习。", "corrected_sentence": "他在一个研究中心实习。", "error_description": "量词错误：“研究中心”是机构，应用量词“个”。写成“一只”错误，因为“只”多用于动物。应为“他在一个研究中心实习”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95107, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究中心地老师很友好。", "corrected_sentence": "研究中心的老师很友好。", "error_description": "结构助词错误：名词修饰名词要用“的”，“地”用于修饰动词、形容词，“研究中心地老师”错误，应为“研究中心的老师很友好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
