INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95108, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专门从事某方面研究工作的机构。", "primary_collocate": null, "pronunciation": "yán jiū zhōng xīn", "ipa": "jɛn˧˥ tɕjoʊ˥ ʈʂʊŋ˥ ɕin˥", "syllable_count": 4, "sentences": [{"text": "这家研究中心专门研究气候变化。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家建立了一个海洋研究中心。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究中心的科学家发明了新药。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕业后进了一家医学研究中心。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究中心发布了最新的调查报告。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究中心每年招收二十名研究员。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国有很多研究中心，专门研究太空。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究中心的专家说，空气越来越好了。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学和一家研究中心合作过。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究中心为农民提供种植技术。", "target_word": "研究中心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "家", "label": "量词"}], "register": "正式", "sense_fingerprint": "名词：专门研究某个领域的机构或单位，如海洋研究中心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d21fd02-94af-431a-bf66-245fcefabcc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究中心", "is_correct": true, "explanation": "正确。研究中心是专门做研究的机构，可以“专门研究”某个领域。"}, {"text": "饭店", "is_correct": false, "explanation": "配价：“研究”要求研究的主体是机构或人，饭店不能作研究的主语。"}, {"text": "词典", "is_correct": false, "explanation": "搭配：“词典”不能与“专门研究气候变化”搭配。"}, {"text": "商店", "is_correct": false, "explanation": "语义：商店是卖东西的地方，不做气候研究。"}], "explanations": {"研究中心": "正确。研究中心是专门做研究的机构，可以“专门研究”某个领域。", "饭店": "配价：“研究”要求研究的主体是机构或人，饭店不能作研究的主语。", "词典": "搭配：“词典”不能与“专门研究气候变化”搭配。", "商店": "语义：商店是卖东西的地方，不做气候研究。"}, "sentence_index": 0, "correct_answer": "研究中心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他毕业后进了一张医学研究中心。", "explanation": "这里应该用〈家〉或〈个〉。〈张〉用于平面的东西，研究中心是机构，不能用〈张〉计量。"}, {"text": "我们小区旁边有一只医学研究中心。", "explanation": "这里应该用〈家〉或〈个〉。〈只〉多用于动物，研究中心不能用〈只〉计量。"}, {"text": "我们城市新建了一颗医学研究中心。", "explanation": "这里应该用〈家〉或〈个〉。〈颗〉用于小而圆的东西，研究中心是机构，不能用〈颗〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究中心", "is_correct": true, "explanation": "正确。研究中心是专门研究太空等领域的机构。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是卖货的地方，不做太空研究。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院的任务是治病，不专门研究太空。"}, {"text": "宿舍", "is_correct": false, "explanation": "搭配：“宿舍”不能与“专门研究太空”搭配。"}], "explanations": {"研究中心": "正确。研究中心是专门研究太空等领域的机构。", "超市": "语义：超市是卖货的地方，不做太空研究。", "医院": "语义：医院的任务是治病，不专门研究太空。", "宿舍": "搭配：“宿舍”不能与“专门研究太空”搭配。"}, "sentence_index": 6, "correct_answer": "研究中心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的同学当了研究中心。", "explanation": "这里应该用〈律师〉。研究中心指机构，不能作为职业身份。"}, {"text": "我妈妈在医院当研究中心。", "explanation": "这里应该用〈护士〉。研究中心是机构，不能指从事职业的人。"}, {"text": "爸爸年轻时想当研究中心。", "explanation": "这里应该用〈司机〉。研究中心是机构，不能当作人的职业，所以不能说“想当研究中心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在一位研究中心工作。", "corrected_sentence": "她在一家研究中心工作。", "error_description": "量词错误：“研究中心”是机构，应用量词“家”或“个”。“一位”只用于人，“一位研究中心”错误，应为“她在一家研究中心工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
