INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95109, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "示范是做给别人看，让别人学。", "primary_collocate": null, "pronunciation": "shì fàn", "ipa": "ʂɨ˥˩ fan˥˩", "syllable_count": 2, "sentences": [{"text": "请你示范一下。", "target_word": "示范", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在黑板前示范。", "target_word": "示范", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈示范怎么包饺子。", "target_word": "示范", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "教练先示范了一遍。", "target_word": "示范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师示范怎么写这个字，我们看着。", "target_word": "示范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师给客人示范做蛋糕的方法。", "target_word": "示范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他示范了一下，我就会用这台机器了。", "target_word": "示范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把动作慢慢示范给我们看。", "target_word": "示范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳教练在水边示范过好几次。", "target_word": "示范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师示范完以后，我们都想自己试试。", "target_word": "示范", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "示范了", "label": "完成体"}, {"form": "示范过", "label": "经历体"}, {"form": "示范示范", "label": "重叠"}], "register": "中性", "sense_fingerprint": "把动作或做法做给别人看，让别人学会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54467bb6-6f7e-4da9-9fdd-38e961a14e4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95109, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "示范", "is_correct": true, "explanation": "示范后带“一下”，表示做一次给你看，句子通顺。"}, {"text": "投降", "is_correct": false, "explanation": "语义：“投降”是认输，不能用来请对方做示范。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：“逃跑”与请对方做示范的语境完全不符。"}, {"text": "存在", "is_correct": false, "explanation": "搭配：“存在”不是可以带“一下”的动作，不能说“存在一下”。"}], "explanations": {"示范": "示范后带“一下”，表示做一次给你看，句子通顺。", "投降": "语义：“投降”是认输，不能用来请对方做示范。", "逃跑": "语义：“逃跑”与请对方做示范的语境完全不符。", "存在": "搭配：“存在”不是可以带“一下”的动作，不能说“存在一下”。"}, "sentence_index": 0, "correct_answer": "示范"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人在厂门口示范了两个小时，要求涨工资。", "explanation": "这里应该用〈示威〉。〈示范〉是做给别人照着学，不是在门口集体抗议；表达不满的集体行动要用〈示威〉。"}, {"text": "他在家里示范了很多客人，大家都很开心。", "explanation": "这里应该用〈招待〉。〈示范〉是做给别人看、让人学，不是款待客人；接待客人要用〈招待〉。"}, {"text": "这份报告示范了很多问题，大家都很担心。", "explanation": "这里应该用〈暴露〉。〈示范〉是做给人看、让人学，不是指把问题显露出来；问题显露要用〈暴露〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95109, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "示范", "is_correct": true, "explanation": "示范了一下，表示做一次演示，我就会用了，句子通顺。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡了一下”与“我就会用这台机器”没有逻辑联系。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱了一下”与使用机器没有关系，句子不通。"}, {"text": "存在", "is_correct": false, "explanation": "搭配：“存在”不能带“了一下”这样的动量补语。"}], "explanations": {"示范": "示范了一下，表示做一次演示，我就会用了，句子通顺。", "睡": "语义：“睡了一下”与“我就会用这台机器”没有逻辑联系。", "唱": "语义：“唱了一下”与使用机器没有关系，句子不通。", "存在": "搭配：“存在”不能带“了一下”这样的动量补语。"}, "sentence_index": 6, "correct_answer": "示范"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在台上示范了一首歌，观众都热烈地鼓掌。", "explanation": "这里应该用〈演唱〉。在台上唱给观众欣赏是〈演唱〉；“示范”是做给人照着学，这里是演出场合，不宜用“示范”。"}, {"text": "他在会上示范了一场很长的报告，大家都累了。", "explanation": "这里应该用〈讲演〉。〈示范〉是做给别人照着学，不是指对听众长篇讲话；发表讲话要用〈讲演〉。"}, {"text": "他在广场上示范了一段很激动的话，群众都欢呼起来。", "explanation": "这里应该用〈演说〉。〈示范〉是做给人照着学，不是对群众发表激动人心的话；这种公开讲话要用〈演说〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95109, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师给我们示范了一个遍。", "corrected_sentence": "老师给我们示范了一遍。", "error_description": "量词错误：动作次数应用“遍”，说“示范了一遍”，不能说“示范了一个遍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95109, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她示范着一下，大家就都懂了。", "corrected_sentence": "她示范了一下，大家就都懂了。", "error_description": "体标错误：动作已完成要用完成标记“了”，应说“示范了一下”，不能用进行标记“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
