INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95110, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做出榜样供他人学习。", "primary_collocate": null, "pronunciation": "shì fàn", "ipa": "ʂɨ˥˩ fan˥˩", "syllable_count": 2, "sentences": [{"text": "老师先示范，学生再做。", "target_word": "示范", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你给大家示范一下。", "target_word": "示范", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸总是自己先示范。", "target_word": "示范", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他给新同事示范了怎么做。", "target_word": "示范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我先示范一次，你们看着做。", "target_word": "示范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理给新来的人示范了正确的做法。", "target_word": "示范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好老师不只会说，还会自己示范。", "target_word": "示范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想给孩子们示范什么是礼貌。", "target_word": "示范", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给全班同学示范过怎样把书放好。", "target_word": "示范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了让大家学会，队长亲自给每个人示范。", "target_word": "示范", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "示范了", "label": "完成体"}, {"form": "示范过", "label": "经历体"}, {"form": "示范示范", "label": "重叠"}], "register": "中性", "sense_fingerprint": "自己先做出榜样，让别人照着学", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54467bb6-6f7e-4da9-9fdd-38e961a14e4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95110, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "示范", "is_correct": true, "explanation": "示范是做给学生看、让学生照着学，与“先……，学生再做”的教学过程相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：老师睡觉无法让学生“再做”，与示范的意思不合。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“先……，学生再做”的教学过程矛盾。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：“发烧”是身体状态，不能作为“先……”之后的教学动作。"}], "explanations": {"示范": "示范是做给学生看、让学生照着学，与“先……，学生再做”的教学过程相符。", "睡觉": "语义：老师睡觉无法让学生“再做”，与示范的意思不合。", "放弃": "语义：“放弃”与“先……，学生再做”的教学过程矛盾。", "发烧": "搭配：“发烧”是身体状态，不能作为“先……”之后的教学动作。"}, "sentence_index": 0, "correct_answer": "示范"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在大家面前示范了自己有多厉害，大家都很讨厌。", "explanation": "这里应该用〈炫耀〉。〈示范〉是做给别人照着学，不是为了显示自己；得意地显示自己要用〈炫耀〉。"}, {"text": "学校在走廊里示范了一百幅学生的画，很多人来看。", "explanation": "这里应该用〈展出〉。〈示范〉是做给别人照着学，不是把作品摆出来供人欣赏；摆出来让人看要用〈展出〉。"}, {"text": "老师在班上示范了他一顿，大家都不敢说话。", "explanation": "这里应该用〈训斥〉。〈示范〉是做给人看、让人学，不是批评责骂；责备一个人要用〈训斥〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "示范", "is_correct": true, "explanation": "示范是做给别人看、让人学，与“不只会说，还会自己……”的并列结构相符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”不是可以展示的能力，与“不只会说，还会……”的意思不符。"}, {"text": "咳嗽", "is_correct": false, "explanation": "搭配：“咳嗽”是非自主的生理现象，不能作为“还会自己……”的能力。"}, {"text": "失败", "is_correct": false, "explanation": "语义：“失败”不是老师主动做的事，与“还会自己……”的语境不符。"}], "explanations": {"示范": "示范是做给别人看、让人学，与“不只会说，还会自己……”的并列结构相符。", "忘记": "语义：“忘记”不是可以展示的能力，与“不只会说，还会……”的意思不符。", "咳嗽": "搭配：“咳嗽”是非自主的生理现象，不能作为“还会自己……”的能力。", "失败": "语义：“失败”不是老师主动做的事，与“还会自己……”的语境不符。"}, "sentence_index": 6, "correct_answer": "示范"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位歌手在演唱会上示范了三首歌。", "explanation": "这里应该用〈表演〉。在台上唱给观众听是〈表演〉，“示范”是做给别人照着学的。"}, {"text": "他向我示范让我先坐下。", "explanation": "这里应该用〈示意〉。用动作告诉对方意思是〈示意〉，“示范”是为了让别人学会。"}, {"text": "他在晚会上示范了一首诗，大家都鼓掌。", "explanation": "这里应该用〈朗诵〉。朗诵是念给听众欣赏，“示范”是为了让别人学会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他给大家示范着一遍。", "corrected_sentence": "他给大家示范了一遍。", "error_description": "体标错误：表示已完成的一次动作要用完成体“了”，应说“示范了一遍”，不能用进行体“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他示范很清楚，大家都看懂了。", "corrected_sentence": "他示范得很清楚，大家都看懂了。", "error_description": "补语前缺少“得”：“示范”后带程度补语，应说“示范得很清楚”，不能说“示范很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
