INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95111, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "站起来是从坐着变成站着。", "primary_collocate": null, "pronunciation": "zhàn qǐ lái", "ipa": "ʈʂan˥˩ tɕʰi˨˩˦ lai˧˥", "syllable_count": 3, "sentences": [{"text": "他从椅子上站起来。", "target_word": "站起来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师进来了，大家都站起来。", "target_word": "站起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你站起来回答问题。", "target_word": "站起来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他坐了很久，慢慢站起来了。", "target_word": "站起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人来了，我马上站起来了。", "target_word": "站起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到奶奶进来，他连忙站起来。", "target_word": "站起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子从地毯上站起来，跑出去了。", "target_word": "站起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐在沙发上，听到电话响就站起来了。", "target_word": "站起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "音乐开始了，大家一起站起来唱歌。", "target_word": "站起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐得太久，腿很麻，站起来很慢。", "target_word": "站起来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "站起来了", "label": "体标"}, {"form": "站了起来", "label": "体标"}, {"form": "站不起来", "label": "可能补语"}, {"form": "站得起来", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "站起来：从坐着的姿势变成站着", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee0abe9c-383b-4465-adda-6a9bff074073') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95111, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "站起来", "is_correct": true, "explanation": "正确。站起来：从坐着变成站着。"}, {"text": "粘起来", "is_correct": false, "explanation": "zhān（第一声）与 zhàn（第四声）声调不同，意思是粘在一起。"}, {"text": "看起来", "is_correct": false, "explanation": "kàn 与 zhàn 声母不同（k 与 zh），意思是看上去。"}, {"text": "胀起来", "is_correct": false, "explanation": "zhàng 与 zhàn 韵母不同（ng 与 n），意思是膨胀起来。"}], "explanations": {"站起来": "正确。站起来：从坐着变成站着。", "粘起来": "zhān（第一声）与 zhàn（第四声）声调不同，意思是粘在一起。", "看起来": "kàn 与 zhàn 声母不同（k 与 zh），意思是看上去。", "胀起来": "zhàng 与 zhàn 韵母不同（ng 与 n），意思是膨胀起来。"}, "sentence_index": null, "correct_answer": "站起来"}, "level_3": {"options": [{"text": "飞走", "is_correct": false, "explanation": "语义：「飞走」指飞离，与「从椅子上」的动作不符，人不会这样离开椅子。"}, {"text": "游起来", "is_correct": false, "explanation": "语义：「游起来」指在水中游动，与坐在椅子上的动作无关。"}, {"text": "站起来", "is_correct": true, "explanation": "正确。「站起来」表示从椅子上变成站立，符合句意。"}, {"text": "摔碎", "is_correct": false, "explanation": "搭配：「摔碎」的对象是易碎的器物，不能用来描述人从椅子上起身。"}], "explanations": {"飞走": "语义：「飞走」指飞离，与「从椅子上」的动作不符，人不会这样离开椅子。", "游起来": "语义：「游起来」指在水中游动，与坐在椅子上的动作无关。", "站起来": "正确。「站起来」表示从椅子上变成站立，符合句意。", "摔碎": "搭配：「摔碎」的对象是易碎的器物，不能用来描述人从椅子上起身。"}, "sentence_index": 0, "correct_answer": "站起来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子突然站起来，吓了我一跳。", "explanation": "这里应该用〈动〉。“站起来”只用于人或动物由坐、卧变为站，椅子不能“站起来”，应说“动起来”。"}, {"text": "这盏灯站起来了，把屋子照亮了。", "explanation": "这里应该用〈亮起来〉。「站起来」只用于人或动物由坐、卧变为站，灯不能「站起来」，应说〈亮起来〉。"}, {"text": "这块石头刚放稳，又站起来了。", "explanation": "这里应该用〈立〉。“站起来”指人或动物由坐、卧变为站，石头不能“站起来”，应说“立起来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95111, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "站起来", "is_correct": true, "explanation": "正确。站起来：从坐着变成站着。"}, {"text": "转起来", "is_correct": false, "explanation": "zhuàn 与 zhàn 韵母不同（多一个 u），意思是转动起来。"}, {"text": "粘起来", "is_correct": false, "explanation": "zhān（第一声）与 zhàn（第四声）声调不同，意思是粘在一起。"}, {"text": "长起来", "is_correct": false, "explanation": "zhǎng（第三声）与 zhàn（第四声）声调不同，韵母也不同（ng 与 n），意思是长大、生长起来。"}], "explanations": {"站起来": "正确。站起来：从坐着变成站着。", "转起来": "zhuàn 与 zhàn 韵母不同（多一个 u），意思是转动起来。", "粘起来": "zhān（第一声）与 zhàn（第四声）声调不同，意思是粘在一起。", "长起来": "zhǎng（第三声）与 zhàn（第四声）声调不同，韵母也不同（ng 与 n），意思是长大、生长起来。"}, "sentence_index": null, "correct_answer": "站起来"}, "level_3": {"options": [{"text": "睡着", "is_correct": false, "explanation": "语义：「睡着」是睡觉，与后面「跑出去了」的意思矛盾。"}, {"text": "站起来", "is_correct": true, "explanation": "正确。「站起来」表示从地毯上起身，符合句意。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：「熄灭」用于火、灯等，不能用来描述孩子的动作。"}, {"text": "发霉", "is_correct": false, "explanation": "搭配：「发霉」用于食物、衣物等，不能说孩子「发霉」。"}], "explanations": {"睡着": "语义：「睡着」是睡觉，与后面「跑出去了」的意思矛盾。", "站起来": "正确。「站起来」表示从地毯上起身，符合句意。", "熄灭": "搭配：「熄灭」用于火、灯等，不能用来描述孩子的动作。", "发霉": "搭配：「发霉」用于食物、衣物等，不能说孩子「发霉」。"}, "sentence_index": 6, "correct_answer": "站起来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "柱子慢慢站起来了。", "explanation": "这里应该用〈立〉。「站起来」指人或动物由坐变站，柱子不能「站起来」。"}, {"text": "红日从山后站起来了。", "explanation": "这里应该用〈升起〉。「站起来」只用于由坐变站，太阳不能「站起来」。"}, {"text": "一片云被风吹动，慢慢站起来了。", "explanation": "这里应该用〈飘〉。“站起来”指人或动物由坐、卧变为站，云不能“站起来”，应说“飘起来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从沙发上慢慢被站起来。", "corrected_sentence": "他从沙发上慢慢站起来。", "error_description": "「站起来」是不及物动作，没有被动用法，不能用「被」字结构。应说「慢慢站起来」，不能说「慢慢被站起来」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他听到敲门声，马上把他站起来开门。", "corrected_sentence": "他听到敲门声，马上站起来开门。", "error_description": "「站起来」是不及物的动作，不能用「把」字结构，也不能带「他」作宾语。应说「马上站起来开门」，不能说「把他站起来」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
