INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95112, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "由坐、卧等姿势变为站立。", "primary_collocate": null, "pronunciation": "zhàn qǐ lái", "ipa": "ʈʂan˥˩ tɕʰi˨˩˦ lai˧˥", "syllable_count": 3, "sentences": [{"text": "病人躺了很久，今天可以站起来了。", "target_word": "站起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从床上站起来，走到窗边。", "target_word": "站起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗躺在地上，听到声音就站起来。", "target_word": "站起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子从地上站起来，拍了拍裤子。", "target_word": "站起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他蹲了一会儿，然后站起来。", "target_word": "站起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官说话时，所有人都要站起来。", "target_word": "站起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他摔倒在地上，很快又站起来了。", "target_word": "站起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "躺在沙发上的爸爸站起来去开门。", "target_word": "站起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人坐了半天，扶着桌子站起来。", "target_word": "站起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到有人叫他，他从椅子上站起来。", "target_word": "站起来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "站起来了", "label": "体标"}, {"form": "站了起来", "label": "体标"}, {"form": "站不起来", "label": "可能补语"}, {"form": "站得起来", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "站起来：由坐、躺等姿势变为站立", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee0abe9c-383b-4465-adda-6a9bff074073') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95112, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "站起来", "is_correct": true, "explanation": "正确。站起来：由坐、卧等姿势变为站立。"}, {"text": "粘起来", "is_correct": false, "explanation": "zhān（第一声）与 zhàn（第四声）声调不同，意思是粘在一起。"}, {"text": "看起来", "is_correct": false, "explanation": "kàn 与 zhàn 声母不同（k 与 zh），意思是看上去。"}, {"text": "胀起来", "is_correct": false, "explanation": "zhàng 与 zhàn 韵母不同（ng 与 n），意思是膨胀起来。"}], "explanations": {"站起来": "正确。站起来：由坐、卧等姿势变为站立。", "粘起来": "zhān（第一声）与 zhàn（第四声）声调不同，意思是粘在一起。", "看起来": "kàn 与 zhàn 声母不同（k 与 zh），意思是看上去。", "胀起来": "zhàng 与 zhàn 韵母不同（ng 与 n），意思是膨胀起来。"}, "sentence_index": null, "correct_answer": "站起来"}, "level_3": {"options": [{"text": "飞起来", "is_correct": false, "explanation": "语义：「飞起来」指在空中飞行，与病人躺着、能否活动的语境不合。"}, {"text": "站起来", "is_correct": true, "explanation": "正确。「站起来」表示从躺卧变为站立，符合「可以……了」的语境。"}, {"text": "亮起来", "is_correct": false, "explanation": "语义：「亮起来」指灯光或天色变亮，不能用来描述病人的动作。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：「可以……了」后面接的是恢复后的动作，不能接「发烧」。"}], "explanations": {"飞起来": "语义：「飞起来」指在空中飞行，与病人躺着、能否活动的语境不合。", "站起来": "正确。「站起来」表示从躺卧变为站立，符合「可以……了」的语境。", "亮起来": "语义：「亮起来」指灯光或天色变亮，不能用来描述病人的动作。", "发烧": "搭配：「可以……了」后面接的是恢复后的动作，不能接「发烧」。"}, "sentence_index": 0, "correct_answer": "站起来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "风筝慢慢站起来了，飞上了天。", "explanation": "这里应该用〈飞起来〉。「站起来」只用于人或动物由坐、卧变为站立，风筝不能「站起来」，应说「风筝慢慢飞起来了」。"}, {"text": "他站在台上，突然站起来，向大家鞠躬。", "explanation": "这里应该用〈站直〉。「站起来」指由坐、卧变为站，已经站在台上的人只能说〈站直〉，不能说「站起来」。"}, {"text": "下了几天雨，河里的水慢慢站起来了。", "explanation": "这里应该用〈涨起来〉。「站起来」只用于人或动物由坐、卧变为站立，河水不能「站起来」，应说「河水涨起来了」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95112, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "站起来", "is_correct": true, "explanation": "正确。站起来：由坐、卧等姿势变为站立。"}, {"text": "转起来", "is_correct": false, "explanation": "zhuàn 与 zhàn 韵母不同（多一个 u），意思是转动起来。"}, {"text": "粘起来", "is_correct": false, "explanation": "zhān（第一声）与 zhàn（第四声）声调不同，意思是粘在一起。"}, {"text": "长起来", "is_correct": false, "explanation": "zhǎng（第三声）与 zhàn（第四声）声调不同，韵母也不同（ng 与 n），意思是长大、生长起来。"}], "explanations": {"站起来": "正确。站起来：由坐、卧等姿势变为站立。", "转起来": "zhuàn 与 zhàn 韵母不同（多一个 u），意思是转动起来。", "粘起来": "zhān（第一声）与 zhàn（第四声）声调不同，意思是粘在一起。", "长起来": "zhǎng（第三声）与 zhàn（第四声）声调不同，韵母也不同（ng 与 n），意思是长大、生长起来。"}, "sentence_index": null, "correct_answer": "站起来"}, "level_3": {"options": [{"text": "融化", "is_correct": false, "explanation": "语义：「融化」指固体受热变成液体，不能用来描述人摔倒后的动作。"}, {"text": "站起来", "is_correct": true, "explanation": "正确。「站起来」表示摔倒后重新站立，符合句意。"}, {"text": "发霉", "is_correct": false, "explanation": "搭配：「发霉」用于食物、衣物等，不能用来描述人的动作。"}, {"text": "飞走", "is_correct": false, "explanation": "语义：「飞走」指飞离，与摔倒在地上的情境不合。"}], "explanations": {"融化": "语义：「融化」指固体受热变成液体，不能用来描述人摔倒后的动作。", "站起来": "正确。「站起来」表示摔倒后重新站立，符合句意。", "发霉": "搭配：「发霉」用于食物、衣物等，不能用来描述人的动作。", "飞走": "语义：「飞走」指飞离，与摔倒在地上的情境不合。"}, "sentence_index": 6, "correct_answer": "站起来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这面墙终于站起来了。", "explanation": "这里应该用〈立〉。「站起来」指人或动物由坐、卧变为站立，墙不能「站起来」。"}, {"text": "红日从山后站起来了。", "explanation": "这里应该用〈升起〉。「站起来」只用于由坐、卧变为站立，太阳不能「站起来」。"}, {"text": "气温突然站起来了，一下子高了十度。", "explanation": "这里应该用〈升高〉。「站起来」只用于人或动物由坐、卧变为站，气温只能说〈升高〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他摔伤了腿，现在不能被站起来。", "corrected_sentence": "他摔伤了腿，现在不能站起来。", "error_description": "「站起来」是不及物动作，没有被动用法，不能用「被」字结构。应说「现在不能站起来」，不能说「现在不能被站起来」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人慢慢把站起来了。", "corrected_sentence": "老人慢慢站起来了。", "error_description": "多加了「把」字。「站起来」是不及物的动作，不能用「把」字结构，应说「老人慢慢站起来了」，不能说「把站起来」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
