INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95113, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "闻是用鼻子去知道东西的味道。", "primary_collocate": null, "pronunciation": "wén", "ipa": "wən˧˥", "syllable_count": 1, "sentences": [{"text": "我用鼻子闻了一下，这杯茶很香。", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈闻了闻鱼，说有一股臭味。", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你闻闻这朵花，香不香？", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在地上闻来闻去，找吃的。", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他闻着咖啡的香味醒了。", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从没闻过这么特别的香味。", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子蹲下来，用鼻子闻花香。", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你闻一闻，这瓶牛奶坏了没有？", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她闭上眼睛，闻了闻新书的味道。", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸拿起苹果，放在鼻子前闻了闻。", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "闻了", "label": "体标"}, {"form": "闻着", "label": "体标"}, {"form": "闻过", "label": "体标"}, {"form": "闻闻", "label": "重叠"}, {"form": "闻一闻", "label": "重叠"}, {"form": "闻到", "label": "复合"}], "register": "中性", "sense_fingerprint": "用鼻子闻东西的味道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6217be5-e5ea-4a87-a628-c92f2ff422f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95113, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "闻", "is_correct": true, "explanation": "闻 wén，指用鼻子辨别气味，是本题的正确答案。"}, {"text": "温", "is_correct": false, "explanation": "wēn（第一声）与 wén（第二声）声调不同，温的意思是温暖。"}, {"text": "稳", "is_correct": false, "explanation": "wěn（第三声）与 wén（第二声）声调不同，稳的意思是稳定。"}, {"text": "问", "is_correct": false, "explanation": "wèn（第四声）与 wén（第二声）声调不同，问的意思是询问。"}, {"text": "吻", "is_correct": false, "explanation": "wěn（第三声）与 wén（第二声）声调不同，吻的意思是嘴唇相接。"}], "explanations": {"闻": "闻 wén，指用鼻子辨别气味，是本题的正确答案。", "温": "wēn（第一声）与 wén（第二声）声调不同，温的意思是温暖。", "稳": "wěn（第三声）与 wén（第二声）声调不同，稳的意思是稳定。", "问": "wèn（第四声）与 wén（第二声）声调不同，问的意思是询问。", "吻": "wěn（第三声）与 wén（第二声）声调不同，吻的意思是嘴唇相接。"}, "sentence_index": null, "correct_answer": "闻"}, "level_3": {"options": [{"text": "闻", "is_correct": true, "explanation": "闻：用鼻子辨别气味，与“用鼻子”搭配，也与“很香”相符。"}, {"text": "看", "is_correct": false, "explanation": "语义：“看”用眼睛，不能感知香味，“看了一下，这杯茶很香”说不通。"}, {"text": "摸", "is_correct": false, "explanation": "语义：“摸”指用手触碰，与“用鼻子”相冲突。"}, {"text": "听", "is_correct": false, "explanation": "搭配：“听”用耳朵，不能用鼻子，也不能与“茶很香”搭配。"}], "explanations": {"闻": "闻：用鼻子辨别气味，与“用鼻子”搭配，也与“很香”相符。", "看": "语义：“看”用眼睛，不能感知香味，“看了一下，这杯茶很香”说不通。", "摸": "语义：“摸”指用手触碰，与“用鼻子”相冲突。", "听": "搭配：“听”用耳朵，不能用鼻子，也不能与“茶很香”搭配。"}, "sentence_index": 0, "correct_answer": "闻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我闻了闻他的心跳，很有力。", "explanation": "这里应该用〈听〉。闻是用鼻子辨别气味，心跳要用耳朵听，应说〈听〉。"}, {"text": "他用手闻了闻那块布，觉得很软。", "explanation": "这里应该用〈摸〉。闻是用鼻子辨别气味，用手感受软硬要用〈摸〉。"}, {"text": "妈妈闻了闻远处的山，觉得很美。", "explanation": "这里应该用〈看〉。闻要用鼻子，欣赏风景要用眼睛，应说〈看〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95113, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "闻", "is_correct": true, "explanation": "闻 wén，指用鼻子辨别气味，是本题的正确答案。"}, {"text": "完", "is_correct": false, "explanation": "wán（第二声）与 wén 韵母不同（en 变成 an），完的意思是完成。"}, {"text": "玩", "is_correct": false, "explanation": "wán（第二声）与 wén 韵母不同（en 变成 an），玩的意思是游戏、耍。"}, {"text": "丸", "is_correct": false, "explanation": "wán（第二声）与 wén 韵母不同（en 变成 an），丸的意思是药丸。"}, {"text": "瘟", "is_correct": false, "explanation": "wēn（第一声）与 wén（第二声）声调不同，瘟的意思是瘟疫。"}], "explanations": {"闻": "闻 wén，指用鼻子辨别气味，是本题的正确答案。", "完": "wán（第二声）与 wén 韵母不同（en 变成 an），完的意思是完成。", "玩": "wán（第二声）与 wén 韵母不同（en 变成 an），玩的意思是游戏、耍。", "丸": "wán（第二声）与 wén 韵母不同（en 变成 an），丸的意思是药丸。", "瘟": "wēn（第一声）与 wén（第二声）声调不同，瘟的意思是瘟疫。"}, "sentence_index": null, "correct_answer": "闻"}, "level_3": {"options": [{"text": "闻", "is_correct": true, "explanation": "闻：用鼻子辨别气味，与“用鼻子”搭配，也与“花香”相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指用嘴进食，与“用鼻子”不符。"}, {"text": "看", "is_correct": false, "explanation": "搭配：“看”要用眼睛，不能用鼻子来做。"}, {"text": "碰", "is_correct": false, "explanation": "配价：“碰”需要接触的对象，后面接“花香”这样的气味说不通。"}], "explanations": {"闻": "闻：用鼻子辨别气味，与“用鼻子”搭配，也与“花香”相符。", "吃": "语义：“吃”指用嘴进食，与“用鼻子”不符。", "看": "搭配：“看”要用眼睛，不能用鼻子来做。", "碰": "配价：“碰”需要接触的对象，后面接“花香”这样的气味说不通。"}, "sentence_index": 6, "correct_answer": "闻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生闻了闻他的血压，说正常。", "explanation": "这里应该用〈量〉。闻是用鼻子辨别气味，血压要用仪器量，应说〈量〉。"}, {"text": "他闻了闻饼干，觉得很脆。", "explanation": "这里应该用〈嚼〉。闻是用鼻子辨别气味，判断脆不脆要靠咬嚼，应说〈嚼〉。"}, {"text": "孩子哭了，妈妈闻了闻眼泪，安慰他。", "explanation": "这里应该用〈擦〉。闻是用鼻子辨别气味，擦眼泪要用手，应说〈擦〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95113, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟凑过去闻闻了花。", "corrected_sentence": "弟弟凑过去闻了闻花。", "error_description": "错误形式「闻闻了花」，正确形式「闻了闻花」。动词重叠「闻了闻」中，「了」要放在两个「闻」之间，不能放在重叠动词的后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95113, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我过闻这种香味，很特别。", "corrected_sentence": "我闻过这种香味，很特别。", "error_description": "错误形式「过闻」，正确形式「闻过」。「过」表示经历，要放在动词后面，「闻过」才表示闻过这种香味，「过」不能放在动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
