INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95114, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用鼻子辨别气味。", "primary_collocate": null, "pronunciation": "wén", "ipa": "wən˧˥", "syllable_count": 1, "sentences": [{"text": "我闻到厨房里有一股烧焦味。", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你闻，这是什么味道？", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的鼻子很灵，一下就闻出了酒味。", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里的煤气味太重，我一进门就闻到了。", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感冒了，我什么也闻不出来。", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种臭豆腐的味道，我一闻就想走开。", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警犬闻了闻包，找到了藏起来的东西。", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走进花店，我闻到了好多种花香。", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你闻一下，这里是不是有煤气味？", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗的鼻子很灵，能闻出主人的味道。", "target_word": "闻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "闻了", "label": "体标"}, {"form": "闻着", "label": "体标"}, {"form": "闻过", "label": "体标"}, {"form": "闻闻", "label": "重叠"}, {"form": "闻到", "label": "复合"}, {"form": "闻出", "label": "复合"}], "register": "中性", "sense_fingerprint": "用鼻子辨别、察觉气味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6217be5-e5ea-4a87-a628-c92f2ff422f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95114, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "闻", "is_correct": true, "explanation": "闻 wén，指用鼻子察觉、辨别气味，是本题的正确答案。"}, {"text": "温", "is_correct": false, "explanation": "wēn（第一声）与 wén（第二声）声调不同，温的意思是温暖。"}, {"text": "稳", "is_correct": false, "explanation": "wěn（第三声）与 wén（第二声）声调不同，稳的意思是稳定。"}, {"text": "问", "is_correct": false, "explanation": "wèn（第四声）与 wén（第二声）声调不同，问的意思是询问。"}], "explanations": {"闻": "闻 wén，指用鼻子察觉、辨别气味，是本题的正确答案。", "温": "wēn（第一声）与 wén（第二声）声调不同，温的意思是温暖。", "稳": "wěn（第三声）与 wén（第二声）声调不同，稳的意思是稳定。", "问": "wèn（第四声）与 wén（第二声）声调不同，问的意思是询问。"}, "sentence_index": null, "correct_answer": "闻"}, "level_3": {"options": [{"text": "闻", "is_correct": true, "explanation": "闻：察觉气味，与“到”组成“闻到”，与“烧焦味”相符。"}, {"text": "看", "is_correct": false, "explanation": "语义：“看”用眼睛，不能用来察觉气味，“看到烧焦味”说不通。"}, {"text": "听", "is_correct": false, "explanation": "搭配：“听到”的对象是声音，不能与“烧焦味”搭配。"}, {"text": "摸", "is_correct": false, "explanation": "语义：“摸”指用手触碰，不能用来察觉气味。"}], "explanations": {"闻": "闻：察觉气味，与“到”组成“闻到”，与“烧焦味”相符。", "看": "语义：“看”用眼睛，不能用来察觉气味，“看到烧焦味”说不通。", "听": "搭配：“听到”的对象是声音，不能与“烧焦味”搭配。", "摸": "语义：“摸”指用手触碰，不能用来察觉气味。"}, "sentence_index": 0, "correct_answer": "闻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我闻到了阳光的温度。", "explanation": "这里应该用〈感觉〉。闻是用鼻子察觉气味，温度要靠皮肤感觉，应说〈感觉〉。"}, {"text": "我闻到了天上的彩虹。", "explanation": "这里应该用〈看〉。闻是察觉气味，看彩虹要用眼睛，应说〈看〉。"}, {"text": "我闻到了远处传来的歌声。", "explanation": "这里应该用〈听〉。闻是察觉气味，听声音要用耳朵，应说〈听〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95114, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "闻", "is_correct": true, "explanation": "闻 wén，指用鼻子察觉、辨别气味，是本题的正确答案。"}, {"text": "完", "is_correct": false, "explanation": "wán（第二声）与 wén 韵母不同（en 变成 an），完的意思是完成。"}, {"text": "玩", "is_correct": false, "explanation": "wán（第二声）与 wén 韵母不同（en 变成 an），玩的意思是游戏、耍。"}, {"text": "吻", "is_correct": false, "explanation": "wěn（第三声）与 wén（第二声）声调不同，吻的意思是亲吻。"}], "explanations": {"闻": "闻 wén，指用鼻子察觉、辨别气味，是本题的正确答案。", "完": "wán（第二声）与 wén 韵母不同（en 变成 an），完的意思是完成。", "玩": "wán（第二声）与 wén 韵母不同（en 变成 an），玩的意思是游戏、耍。", "吻": "wěn（第三声）与 wén（第二声）声调不同，吻的意思是亲吻。"}, "sentence_index": null, "correct_answer": "闻"}, "level_3": {"options": [{"text": "闻", "is_correct": true, "explanation": "闻：用鼻子察觉气味，与“警犬”及“找到东西”的语境相符。"}, {"text": "尝", "is_correct": false, "explanation": "语义：“尝”是用嘴辨别滋味，警犬用鼻子找东西，“尝”不符合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与“找到藏起来的东西”的语境不符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”是用水加热，与“找东西”不搭配，句子不通。"}], "explanations": {"闻": "闻：用鼻子察觉气味，与“警犬”及“找到东西”的语境相符。", "尝": "语义：“尝”是用嘴辨别滋味，警犬用鼻子找东西，“尝”不符合。", "吃": "语义：“吃”指进食，与“找到藏起来的东西”的语境不符。", "煮": "搭配：“煮”是用水加热，与“找东西”不搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "闻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人闻了闻水温，说很烫。", "explanation": "这里应该用〈测〉。闻是用鼻子察觉气味，水温要用温度计测，应说〈测〉。"}, {"text": "他闻了几个字，给我看。", "explanation": "这里应该用〈写〉。闻是察觉气味的动作，不能用于写字。"}, {"text": "他闻了一口汤，说太咸了。", "explanation": "这里应该用〈尝〉。闻是用鼻子察觉气味，喝一口、判断咸淡要靠嘴品尝，应说〈尝〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一进厨房就闻了到香味。", "corrected_sentence": "我一进厨房就闻到了香味。", "error_description": "错误在“到”和“了”的位置。“闻到”是复合动词，“了”要放在“到”后面，应说“闻到了香味”，不能说“闻了到香味”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚走到门口，就闻了出饭菜的香味。", "corrected_sentence": "他刚走到门口，就闻出了饭菜的香味。", "error_description": "错误在“出”和“了”的位置。“闻出”是复合动词，“了”要放在“出”后面，应说“闻出了饭菜的香味”，不能说“闻了出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
