INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95120, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "与自己有血缘或婚姻关系的人。", "primary_collocate": null, "pronunciation": "qīn qi", "ipa": "tɕʰin⁵⁵ tɕʰi", "syllable_count": 2, "sentences": [{"text": "他是我母亲那边的亲戚。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远房亲戚很少来往。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚以后,他多了很多亲戚。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不是朋友,是亲戚。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和我是亲戚,但不太熟。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在亲戚的公司工作。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲戚之间应该互相帮助。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人是我爸爸的亲戚。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过节时,亲戚们聚在一起吃饭。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这个城市没有亲戚。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "门", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "亲戚朋友", "label": "复合"}, {"form": "親戚", "label": "繁体"}], "register": "口语", "sense_fingerprint": "与自己有血缘或婚姻关系的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e60e0e-e792-48a1-bca2-90faf2e2bfb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亲戚", "is_correct": true, "explanation": "“亲戚”指有血缘关系的人，与“母亲那边的亲戚”的说法相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是物品，不能是母亲那边的亲属。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是建筑部件，不能是母亲那边的亲属。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“母亲那边的”修饰人，不能修饰“石头”。"}], "explanations": {"亲戚": "“亲戚”指有血缘关系的人，与“母亲那边的亲戚”的说法相符。", "手机": "语义：“手机”是物品，不能是母亲那边的亲属。", "窗户": "语义：“窗户”是建筑部件，不能是母亲那边的亲属。", "石头": "搭配：“母亲那边的”修饰人，不能修饰“石头”。"}, "sentence_index": 0, "correct_answer": "亲戚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和他都是北京人，他是我的亲戚，但我们之间没有任何血缘或婚姻关系。", "explanation": "这里应该用〈老乡〉。亲戚必须有血缘或婚姻关系，这句说没有任何关系，只是同乡，应说“老乡”。"}, {"text": "我在地铁上碰到一个亲戚，他跟我没有任何血缘或婚姻关系。", "explanation": "这里应该用〈陌生人〉。亲戚必须有血缘或婚姻关系，这句说没有关系，应说“陌生人”。"}, {"text": "我和他在同一家公司工作，他是我的亲戚，我们只是工作上认识的关系。", "explanation": "这里应该用〈同事〉。亲戚需要血缘或婚姻关系，这句说只是工作上的关系，应说“同事”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲戚", "is_correct": true, "explanation": "“亲戚”指有亲属关系的人，与“亲戚之间应该互相帮助”的语境相符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”之间不会互相帮助。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”没有帮助别人的行为。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“帮助”的主体应是人或组织，“书包之间”不成立。"}], "explanations": {"亲戚": "“亲戚”指有亲属关系的人，与“亲戚之间应该互相帮助”的语境相符。", "汽车": "语义：“汽车”之间不会互相帮助。", "桌子": "语义：“桌子”没有帮助别人的行为。", "书包": "搭配：“帮助”的主体应是人或组织，“书包之间”不成立。"}, "sentence_index": 6, "correct_answer": "亲戚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在辩论赛上，他是我的亲戚，但我们之间没有任何血缘或婚姻关系。", "explanation": "这里应该用〈对手〉。亲戚必须有血缘或婚姻关系，这句说没有关系，应说赛场上的对手。"}, {"text": "我和邻居从小就是亲戚，但我们之间没有任何血缘或婚姻关系，只是要好的交情。", "explanation": "这里应该用〈朋友〉。亲戚必须有血缘或婚姻关系，这句说只是交情，应说“朋友”。"}, {"text": "我们是同班的亲戚，但我们之间没有任何血缘或婚姻关系。", "explanation": "这里应该用〈同学〉。亲戚必须有血缘或婚姻关系，这句说没有关系，同班只是同学关系，应说“同学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我父亲的一棵亲戚。", "corrected_sentence": "他是我父亲的一位亲戚。", "error_description": "“棵”用于树木，不能修饰人。修饰“亲戚”应用“位”或“个”，说“一位亲戚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他家来了一位亲戚们。", "corrected_sentence": "他家来了一位亲戚。", "error_description": "错误形式：“一位亲戚们”；正确形式：“一位亲戚”。“们”表示复数，不能与数量词“一位”一起使用，数量短语后应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
