INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95121, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "评是说一说东西好不好。", "primary_collocate": null, "pronunciation": "píng", "ipa": "pʰiŋ˧˥", "syllable_count": 1, "sentences": [{"text": "这幅画画得怎么样？请你评一评。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都尝了蛋糕，你来评评好不好吃。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我做的这道菜，你们评一评吧。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱评别人的衣服。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完这部电影，朋友们坐下来评了半天。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别急着评，先听完他唱的歌。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让同学们评一评这首诗写得好不好。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个蛋糕哪个好吃，请大家来评评。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他唱得好不好，你们自己评吧。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们边吃饭边评，看哪道菜最好吃。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "评评", "label": "重叠"}, {"form": "评一评", "label": "重叠"}, {"form": "评了", "label": "体标"}, {"form": "评过", "label": "体标"}, {"form": "評", "label": "繁体"}], "register": "中性", "sense_fingerprint": "随口说说一样东西好不好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d21fd02-94af-431a-bf66-245fcefabcc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95121, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "评", "is_correct": true, "explanation": "正确。“评”表示随口说说东西好不好，与“画得怎么样”的评价相符。"}, {"text": "买", "is_correct": false, "explanation": "语义：买是购买，与“请你说说画得怎么样”的意思不符。"}, {"text": "卖", "is_correct": false, "explanation": "语义：卖是出售，不能用来对画表示看法。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不与“画怎么样”搭配。"}], "explanations": {"评": "正确。“评”表示随口说说东西好不好，与“画得怎么样”的评价相符。", "买": "语义：买是购买，与“请你说说画得怎么样”的意思不符。", "卖": "语义：卖是出售，不能用来对画表示看法。", "洗": "搭配：“洗”不与“画怎么样”搭配。"}, "sentence_index": 0, "correct_answer": "评"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师评了他一顿，说他上课说话太大声。", "explanation": "这里应该用〈批评〉。评表示判断好坏，不表示指责，“评了一顿”不能这样说。"}, {"text": "法官评了他有罪。", "explanation": "这里应该用〈判〉。评只用于判断东西好不好、高低，不用于法庭上判定有罪或无罪。"}, {"text": "爸爸评了我一顿，说我不该乱花钱。", "explanation": "这里应该用〈训〉。评没有责备的意思，不能说“评了一顿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95121, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "评", "is_correct": true, "explanation": "正确。“评”可以用来对诗的好坏随口说说。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是进食，不能对诗作判断。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是烹饪，与诗无关。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是丢掉东西，不能用来判断诗写得好不好。"}], "explanations": {"评": "正确。“评”可以用来对诗的好坏随口说说。", "吃": "语义：吃是进食，不能对诗作判断。", "煮": "语义：煮是烹饪，与诗无关。", "扔": "语义：扔是丢掉东西，不能用来判断诗写得好不好。"}, "sentence_index": 6, "correct_answer": "评"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸评了弟弟一顿，说他又不写作业。", "explanation": "这里应该用〈骂〉。评没有斥责的意思，不能说“评了一顿”。"}, {"text": "他评了一下这本书的页数。", "explanation": "这里应该用〈数〉。评只用于判断好坏高低，不能用来计算页数。"}, {"text": "医生评了我的病。", "explanation": "这里应该用〈看〉或〈诊断〉。评只用于判断好坏高低，不表示诊断病情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95121, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前评了过这部电影。", "corrected_sentence": "我以前评过这部电影。", "error_description": "体标错误：表示经历的“过”前面不能再加“了”，“评了过”错误，应为“我以前评过这部电影”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95121, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他评地很准。", "corrected_sentence": "他评得很准。", "error_description": "补语错误：修饰动词的状态补语要用“得”连接，“评地很准”错误，应为“他评得很准”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
