INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95122, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "评论，评判好坏高低。", "primary_collocate": null, "pronunciation": "píng", "ipa": "pʰiŋ˧˥", "syllable_count": 1, "sentences": [{"text": "谁的作品最好，让专家来评一评。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛后，老师按分数评出了高低。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个学校哪个更好，很难评。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画好不好，要让时间来评。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们互相评作业，看谁做得最认真。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两位歌手谁唱得更好，我评不出来。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好坏高低，不能只靠一个人评。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你按这三个标准评一评这两家公司。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩好不好，让老师来评。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛由校长来评，大家都很放心。", "target_word": "评", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "评评", "label": "重叠"}, {"form": "评一评", "label": "重叠"}, {"form": "评了", "label": "体标"}, {"form": "评过", "label": "体标"}, {"form": "評", "label": "繁体"}], "register": "中性", "sense_fingerprint": "按标准判断好坏高低", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d21fd02-94af-431a-bf66-245fcefabcc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95122, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "评", "is_correct": true, "explanation": "正确。“评”表示按标准判断作品的好坏高低。"}, {"text": "烤", "is_correct": false, "explanation": "语义：烤是加热食物，与判断作品好坏无关。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是丢弃，不能用来判断作品高低。"}, {"text": "摸", "is_correct": false, "explanation": "语义：摸是用手接触，不能用来判断作品的好坏高低。"}], "explanations": {"评": "正确。“评”表示按标准判断作品的好坏高低。", "烤": "语义：烤是加热食物，与判断作品好坏无关。", "扔": "语义：扔是丢弃，不能用来判断作品高低。", "摸": "语义：摸是用手接触，不能用来判断作品的好坏高低。"}, "sentence_index": 0, "correct_answer": "评"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "专家评了这件文物的长度。", "explanation": "这里应该用〈量〉。评不表示量出长短，“评了长度”不能这样说。"}, {"text": "工人评了房间的面积。", "explanation": "这里应该用〈测量〉。评不表示量出数值。"}, {"text": "老师评了学生的人数。", "explanation": "这里应该用〈数〉。评不表示计算数目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "评", "is_correct": true, "explanation": "正确。“评”表示按标准判断好坏高低。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是进食，不能用来判断好坏高低。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是烹饪，与判断好坏高低无关。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不与“好坏高低”搭配。"}], "explanations": {"评": "正确。“评”表示按标准判断好坏高低。", "吃": "语义：吃是进食，不能用来判断好坏高低。", "煮": "语义：煮是烹饪，与判断好坏高低无关。", "唱": "搭配：“唱”不与“好坏高低”搭配。"}, "sentence_index": 6, "correct_answer": "评"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "售货员评了这些苹果的重量。", "explanation": "这里应该用〈称〉。评不表示用秤量出重量。"}, {"text": "医生评了我的身体。", "explanation": "这里应该用〈检查〉。评是判断好坏，不用于身体检查。"}, {"text": "会计评了公司的利润。", "explanation": "这里应该用〈计算〉。评不表示计算金额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师评地很公平。", "corrected_sentence": "老师评得很公平。", "error_description": "补语错误：状态补语要用“得”连接，“地”用于动词前修饰动词，“评地很公平”错误，应为“老师评得很公平”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们评了过这两家公司。", "corrected_sentence": "他们评过这两家公司。", "error_description": "体标错误：表示经历的“过”前面不能再加“了”，“评了过这两家公司”错误，应为“他们评过这两家公司”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
