INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95126, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "偷东西的人。", "primary_collocate": null, "pronunciation": "zéi", "ipa": "tsei˧˥", "syllable_count": 1, "sentences": [{"text": "昨天晚上家里进了贼。", "target_word": "贼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "贼从窗户爬进了房间。", "target_word": "贼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察昨天抓到了一个贼。", "target_word": "贼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个贼偷走了他的钱包。", "target_word": "贼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻居大喊：“抓贼！”", "target_word": "贼", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个贼很小心，没有留下东西。", "target_word": "贼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贼被人发现后马上跑了。", "target_word": "贼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门没关好，贼就进来了。", "target_word": "贼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子看见贼，吓得大哭。", "target_word": "贼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在地铁里遇到了一个贼。", "target_word": "贼", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小贼", "label": "复合"}, {"form": "盗贼", "label": "复合"}, {"form": "賊", "label": "繁体"}], "register": "口语", "sense_fingerprint": "偷东西的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755a2819-fc8e-4d21-b491-ab1430d215e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95126, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贼", "is_correct": true, "explanation": "贼指偷东西的人，夜里悄悄进屋，与句意相符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳白天出现，昨天晚上不会“进了家里”。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不会走进屋里，与“进了”的主语不合。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“进了”不与“饭菜”搭配，饭菜一般说“端上来”或“送来”。"}], "explanations": {"贼": "贼指偷东西的人，夜里悄悄进屋，与句意相符。", "太阳": "语义：太阳白天出现，昨天晚上不会“进了家里”。", "树": "语义：树不会走进屋里，与“进了”的主语不合。", "饭菜": "搭配：“进了”不与“饭菜”搭配，饭菜一般说“端上来”或“送来”。"}, "sentence_index": 0, "correct_answer": "贼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "贼每天在工厂里生产零件。", "explanation": "这里应该用〈工人〉。工人在工厂里生产零件；贼是偷东西的人，不做这样的工作。"}, {"text": "路口有一个贼，向路人讨钱。", "explanation": "这里应该用〈乞丐〉。乞丐向路人讨钱，不偷东西；贼是偷东西的人，不会向路人讨钱。"}, {"text": "我家请了一个贼，每天帮我们做饭打扫。", "explanation": "这里应该用〈保姆〉。保姆每天帮家里做饭、打扫；贼是偷东西的人，不会受雇做家务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4a3377f-3e32-4c57-9340-b9253ea5873e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95126, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贼", "is_correct": true, "explanation": "贼偷东西，被人发现后会马上逃跑，与句意相符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不会“被人发现”后跑掉。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会自己跑，与“马上跑了”不合。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“跑”的主语一般是人或动物，“窗户”不能用“跑了”。"}], "explanations": {"贼": "贼偷东西，被人发现后会马上逃跑，与句意相符。", "太阳": "语义：太阳不会“被人发现”后跑掉。", "石头": "语义：石头不会自己跑，与“马上跑了”不合。", "窗户": "搭配：“跑”的主语一般是人或动物，“窗户”不能用“跑了”。"}, "sentence_index": 6, "correct_answer": "贼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "贼每天早上八点准时去公司上班，月底领工资。", "explanation": "这里应该用〈职员〉。职员每天按时上班、月底领工资；贼是偷东西的人，不去公司上班领工资。"}, {"text": "贼每天在田里种庄稼，很早就起床。", "explanation": "这里应该用〈农民〉。农民在田里种庄稼；贼是偷东西的人，不种庄稼。"}, {"text": "贼为客人做了一件新衣服。", "explanation": "这里应该用〈裁缝〉。裁缝为客人量体裁衣、做衣服；贼是偷东西的人，不做衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4a3377f-3e32-4c57-9340-b9253ea5873e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天晚上我家进了一个贼们。", "corrected_sentence": "昨天晚上我家进了一个贼。", "error_description": "“贼”前有数量词“一个”，后面不能再加“们”，应说“一个贼”，错误在“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4a3377f-3e32-4c57-9340-b9253ea5873e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "前天他在地铁里遇到了一只贼。", "corrected_sentence": "前天他在地铁里遇到了一个贼。", "error_description": "“贼”指人，量词应用“个”，“只”多用于动物或某些物品，此处应说“一个贼”，错误在量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4a3377f-3e32-4c57-9340-b9253ea5873e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
