INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95127, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身份证是一张写着你是谁的卡片。", "primary_collocate": null, "pronunciation": "shēn fèn zhèng", "ipa": "ʂən˥ fən˥˩ ʈʂɤŋ˥˩", "syllable_count": 3, "sentences": [{"text": "他把身份证放在钱包里了。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身份证上写着我的名字。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟还小，没有身份证。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用身份证登记入住。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们带着身份证去考试。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是谁的身份证？掉在地上了。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身份证过期了，要换新的。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身份证照片看起来很年轻。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办手机卡要用身份证。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王拿着身份证排队进考场。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "身份證", "label": "繁体"}, {"form": "身份证号", "label": "复合"}], "register": "中性", "sense_fingerprint": "写着你是谁的一张卡片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f23e8f5-926c-4e66-9efb-f790437fb09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95127, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身份证", "is_correct": true, "explanation": "身份证：写着你是谁的卡片，与“他把……放在钱包里了”的句意相符。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海放不进钱包，与句意相矛盾。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光无法放进钱包，与句意不符。"}, {"text": "歌声", "is_correct": false, "explanation": "搭配：“放”不能与“歌声”搭配，句子读起来不通。"}], "explanations": {"身份证": "身份证：写着你是谁的卡片，与“他把……放在钱包里了”的句意相符。", "大海": "语义：大海放不进钱包，与句意相矛盾。", "阳光": "语义：阳光无法放进钱包，与句意不符。", "歌声": "搭配：“放”不能与“歌声”搭配，句子读起来不通。"}, "sentence_index": 0, "correct_answer": "身份证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在婚礼上把身份证当作请柬递给客人。", "explanation": "这里应该用〈请柬〉。婚礼上邀请客人用的是〈请柬〉，身份证不能当作请柬。"}, {"text": "聚会时大家互相赠送身份证。", "explanation": "这里应该用〈名片〉。聚会时交换的是〈名片〉，身份证是政府证件，不用于赠送。"}, {"text": "她的身份证是厨师。", "explanation": "这里应该用〈职业〉。身份证是证件，不能用来说明人的职业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95127, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身份证", "is_correct": true, "explanation": "身份证：写着你是谁的卡片，与“……过期了，要换新的”的句意相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不会“过期”，与句意不符。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“过期”不能与“友谊”搭配，句子读起来不通。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步不会“过期”，句意不通。"}], "explanations": {"身份证": "身份证：写着你是谁的卡片，与“……过期了，要换新的”的句意相符。", "天气": "语义：天气不会“过期”，与句意不符。", "友谊": "搭配：“过期”不能与“友谊”搭配，句子读起来不通。", "脚步": "语义：脚步不会“过期”，句意不通。"}, "sentence_index": 6, "correct_answer": "身份证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下雨了，他用身份证当雨伞。", "explanation": "这里应该用〈雨伞〉。身份证不能用来挡雨。"}, {"text": "他在超市用身份证结账。", "explanation": "这里应该用〈信用卡〉。身份证是证件，不能用来付款；结账可以用〈信用卡〉等。"}, {"text": "她的身份证是司机。", "explanation": "这里应该用〈工作〉。身份证是证件，不能用来说明人的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95127, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌上有一本身份证。", "corrected_sentence": "桌上有一张身份证。", "error_description": "错误：“一本身份证”；正确：“一张身份证”。身份证是卡片，量词用“张”，不用“本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95127, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天刚办好一本身份证。", "corrected_sentence": "我昨天刚办好一张身份证。", "error_description": "错误：“一本身份证”；正确：“一张身份证”。身份证是卡片，量词用“张”，不用“本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
