INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95128, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "证明持有人身份的证件，上面有姓名、出生日期等信息。", "primary_collocate": null, "pronunciation": "shēn fèn zhèng", "ipa": "ʂən˥ fən˥˩ ʈʂɤŋ˥˩", "syllable_count": 3, "sentences": [{"text": "请把你的身份证给我看一下。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的身份证丢了，要去补办。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买火车票要带身份证。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身份证上有你的姓名和照片。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘带身份证，不能进银行。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张身份证是去年办的。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住酒店的时候要给前台看身份证。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身份证上的出生日期写错了。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她十八岁那年拿到了第一张身份证。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说：“请出示您的身份证。”", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "身份證", "label": "繁体"}, {"form": "身份证号", "label": "复合"}], "register": "中性", "sense_fingerprint": "证明身份、写有姓名和出生日期的证件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f23e8f5-926c-4e66-9efb-f790437fb09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身份证", "is_correct": true, "explanation": "身份证：证明持有人身份的证件，与“请把你的……给我看一下”的句意相符。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日不能拿出来给人看，与句意不符。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“看”不能与“心情”搭配，句子读起来不通。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：脚印不是可以拿给别人看的物品，与句意不符。"}], "explanations": {"身份证": "身份证：证明持有人身份的证件，与“请把你的……给我看一下”的句意相符。", "生日": "语义：生日不能拿出来给人看，与句意不符。", "心情": "搭配：“看”不能与“心情”搭配，句子读起来不通。", "脚印": "语义：脚印不是可以拿给别人看的物品，与句意不符。"}, "sentence_index": 0, "correct_answer": "身份证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "去展览馆要买身份证。", "explanation": "这里应该用〈门票〉。去展览馆要买门票，身份证不能用来买票。"}, {"text": "开会时大家互相交换身份证。", "explanation": "这里应该用〈名片〉。交换介绍用的是〈名片〉，身份证是政府发放的证件，不用于交换。"}, {"text": "他的身份证是医生。", "explanation": "这里应该用〈身份〉。身份证是证件，说人的身份或职业要用〈身份〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身份证", "is_correct": true, "explanation": "身份证：证明持有人身份的证件，与“住酒店的时候要给前台看……”的句意相符。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”不能与“声音”搭配，句子读起来不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“看”不能与“味道”搭配，句子读起来不通。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：给前台看梦想不符合酒店登记的语境，句意不通。"}], "explanations": {"身份证": "身份证：证明持有人身份的证件，与“住酒店的时候要给前台看……”的句意相符。", "声音": "搭配：“看”不能与“声音”搭配，句子读起来不通。", "味道": "搭配：“看”不能与“味道”搭配，句子读起来不通。", "梦想": "语义：给前台看梦想不符合酒店登记的语境，句意不通。"}, "sentence_index": 6, "correct_answer": "身份证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用身份证给手机充电。", "explanation": "这里应该用〈充电宝〉。身份证不能给手机充电。"}, {"text": "点菜时要看身份证。", "explanation": "这里应该用〈菜单〉。点菜要看菜单，身份证不用于点菜。"}, {"text": "他的身份证是护士。", "explanation": "这里应该用〈职业〉。身份证是证件，不能用来说明人的职业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地上有一本身份证。", "corrected_sentence": "地上有一张身份证。", "error_description": "错误：“一本身份证”；正确：“一张身份证”。身份证是卡片，量词用“张”，不用“本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "抽屉里有一本身份证。", "corrected_sentence": "抽屉里有一张身份证。", "error_description": "错误：“一本身份证”；正确：“一张身份证”。身份证是卡片，量词用“张”，不用“本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95129, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保存", "is_correct": false, "explanation": "语义：“保存”指留存物品或数据，与位置远近无关，不是反义词。"}, {"text": "远离", "is_correct": true, "explanation": "远离：与“邻近”意思相反，指离得很远。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“出发”指动身前往，与两地的远近关系无关，不是反义词。"}, {"text": "等待", "is_correct": false, "explanation": "语义：“等待”指停留等候，与位置远近无关，不是反义词。"}], "correct_answer": "远离", "explanations": {"保存": "语义：“保存”指留存物品或数据，与位置远近无关，不是反义词。", "远离": "远离：与“邻近”意思相反，指离得很远。", "出发": "语义：“出发”指动身前往，与两地的远近关系无关，不是反义词。", "等待": "语义：“等待”指停留等候，与位置远近无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95129, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "讨论", "is_correct": false, "explanation": "语义：“讨论”指交换意见，与位置远近无关，不是反义词。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指使器物恢复正常，与位置远近无关，不是反义词。"}, {"text": "远离", "is_correct": true, "explanation": "远离：与“邻近”意思相反，指离得很远。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”指保存物品，与位置远近无关，不是反义词。"}], "correct_answer": "远离", "explanations": {"讨论": "语义：“讨论”指交换意见，与位置远近无关，不是反义词。", "修理": "语义：“修理”指使器物恢复正常，与位置远近无关，不是反义词。", "远离": "远离：与“邻近”意思相反，指离得很远。", "收藏": "语义：“收藏”指保存物品，与位置远近无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95129, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "邻近是离得很近。", "primary_collocate": null, "pronunciation": "lín jìn", "ipa": "lin³⁵ tɕin⁵¹", "syllable_count": 2, "sentences": [{"text": "他家邻近公司，走路五分钟。", "target_word": "邻近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们两个村子邻近，常来往。", "target_word": "邻近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻近的商店都关门了。", "target_word": "邻近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行邻近车站，取钱很方便。", "target_word": "邻近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两所学校邻近，学生常一起玩。", "target_word": "邻近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想租邻近地铁的房子。", "target_word": "邻近", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公园邻近我们小区，早上很多人去跑步。", "target_word": "邻近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬到邻近老家的城市工作了。", "target_word": "邻近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻近的几个国家都说这种语言。", "target_word": "邻近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市邻近我们学校，放学后常去买东西。", "target_word": "邻近", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "邻近：两处离得很近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54467bb6-6f7e-4da9-9fdd-38e961a14e4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95129, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远离", "is_correct": false, "explanation": "语义：“远离”指距离很远，与后面“走路五分钟”的说法矛盾。"}, {"text": "攀登", "is_correct": false, "explanation": "搭配：“攀登”的对象是山、高处等，不能说攀登公司。"}, {"text": "邻近", "is_correct": true, "explanation": "邻近：两处离得很近，与“走路五分钟”相符，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象须是食物，不能说吃公司。"}], "explanations": {"远离": "语义：“远离”指距离很远，与后面“走路五分钟”的说法矛盾。", "攀登": "搭配：“攀登”的对象是山、高处等，不能说攀登公司。", "邻近": "邻近：两处离得很近，与“走路五分钟”相符，符合句意。", "吃": "搭配：“吃”的对象须是食物，不能说吃公司。"}, "sentence_index": 0, "correct_answer": "邻近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考试马上就要邻近了。", "explanation": "这里应该用〈临近〉。邻近表示两处位置接近，时间将要到来要用临近。"}, {"text": "这两个孩子的性格很邻近。", "explanation": "这里应该用〈相似〉。邻近只说位置靠近，表示性质相同要用相似。"}, {"text": "他慢慢邻近我，然后坐了下来。", "explanation": "这里应该用〈走近〉。走近表示移动靠近的过程，邻近只描述位置接近的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95129, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放弃", "is_correct": false, "explanation": "搭配：“放弃”的对象是事情、机会等，不能说放弃公园。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”的对象须是人，不能说公园嘲笑我们小区。"}, {"text": "邻近", "is_correct": true, "explanation": "邻近：公园与小区离得很近，早上很多人去跑步，符合句意。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”的对象是乐曲或乐器，不能说演奏小区。"}], "explanations": {"放弃": "搭配：“放弃”的对象是事情、机会等，不能说放弃公园。", "嘲笑": "语义：“嘲笑”的对象须是人，不能说公园嘲笑我们小区。", "邻近": "邻近：公园与小区离得很近，早上很多人去跑步，符合句意。", "演奏": "搭配：“演奏”的对象是乐曲或乐器，不能说演奏小区。"}, "sentence_index": 6, "correct_answer": "邻近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩很邻近满分。", "explanation": "这里应该用〈接近〉。邻近只指位置接近，表示成绩、数量相近要用接近。"}, {"text": "他们俩的关系很邻近，像兄弟一样。", "explanation": "这里应该用〈亲密〉。邻近只说位置，表示感情关系好要用亲密。"}, {"text": "两城之间的邻近只有三公里。", "explanation": "这里应该用〈距离〉。邻近是表示位置接近的词，不能作名词表示两地间隔的长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95129, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家邻近在学校，走路就到。", "corrected_sentence": "我们家邻近学校，走路就到。", "error_description": "错误在“邻近”后多加了介词“在”。“邻近”后直接带宾语，应说“邻近学校”，不说“邻近在学校”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95129, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个超市邻近到地铁站，买东西很方便。", "corrected_sentence": "这个超市邻近地铁站，买东西很方便。", "error_description": "错误在“邻近”后多加了补语“到”。“邻近”后直接带宾语，应说“邻近地铁站”，不说“邻近到地铁站”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95130, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远离", "is_correct": true, "explanation": "远离：与“邻近”意思相反，指离得很远。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”指保存物品，与位置远近无关，不是反义词。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：“讨论”指交换意见，与位置远近无关，不是反义词。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指使器物恢复正常，与位置远近无关，不是反义词。"}], "correct_answer": "远离", "explanations": {"远离": "远离：与“邻近”意思相反，指离得很远。", "收藏": "语义：“收藏”指保存物品，与位置远近无关，不是反义词。", "讨论": "语义：“讨论”指交换意见，与位置远近无关，不是反义词。", "修理": "语义：“修理”指使器物恢复正常，与位置远近无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95130, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出发", "is_correct": false, "explanation": "语义：“出发”指动身前往，与两地的远近关系无关，不是反义词。"}, {"text": "远离", "is_correct": true, "explanation": "远离：与“邻近”意思相反，指离得很远。"}, {"text": "等待", "is_correct": false, "explanation": "语义：“等待”指停留等候，与位置远近无关，不是反义词。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清除脏物，与位置远近无关，不是反义词。"}], "correct_answer": "远离", "explanations": {"出发": "语义：“出发”指动身前往，与两地的远近关系无关，不是反义词。", "远离": "远离：与“邻近”意思相反，指离得很远。", "等待": "语义：“等待”指停留等候，与位置远近无关，不是反义词。", "打扫": "语义：“打扫”指清除脏物，与位置远近无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95130, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "位置接近，靠近。", "primary_collocate": null, "pronunciation": "lín jìn", "ipa": "lin³⁵ tɕin⁵¹", "syllable_count": 2, "sentences": [{"text": "我家邻近一所小学。", "target_word": "邻近", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家饭店邻近地铁站，很方便。", "target_word": "邻近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校邻近海边，空气非常好。", "target_word": "邻近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个公园邻近我们的小区。", "target_word": "邻近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻近的两个城市坐车只要一小时。", "target_word": "邻近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在邻近学校的地方租了一间房。", "target_word": "邻近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院邻近火车站，来看病的人很多。", "target_word": "邻近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们住的地方邻近一座山，周末常去爬山。", "target_word": "邻近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻近河边的那条路，晚上很安静。", "target_word": "邻近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小城邻近大海，所以常吃海鲜。", "target_word": "邻近", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "邻近：位置上挨得近，靠近某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54467bb6-6f7e-4da9-9fdd-38e961a14e4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95130, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象须是食物，不能说吃一所小学。"}, {"text": "邻近", "is_correct": true, "explanation": "邻近：位置接近，说明我家离小学很近，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与“我家”“一所小学”这样的宾语不相容。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、器皿等，不能说洗一所小学。"}], "explanations": {"吃": "搭配：“吃”的对象须是食物，不能说吃一所小学。", "邻近": "邻近：位置接近，说明我家离小学很近，符合句意。", "唱": "语义：“唱”指发出歌声，与“我家”“一所小学”这样的宾语不相容。", "洗": "搭配：“洗”的对象是衣物、器皿等，不能说洗一所小学。"}, "sentence_index": 0, "correct_answer": "邻近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春节快要邻近了。", "explanation": "这里应该用〈临近〉。邻近只表示空间上的接近，时间将要到来时用临近。"}, {"text": "他的成绩邻近满分。", "explanation": "这里应该用〈接近〉。邻近只指位置靠近，表示数量或程度相近要用接近。"}, {"text": "孩子很邻近妈妈。", "explanation": "这里应该用〈亲近〉。邻近只说位置，表示感情亲密要用亲近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆除，句子说的是医院与火车站的位置关系，不能说医院拆火车站。"}, {"text": "邻近", "is_correct": true, "explanation": "邻近：位置接近，说明医院离火车站近，来看病的人多，符合句意。"}, {"text": "陪伴", "is_correct": false, "explanation": "搭配：“陪伴”的对象是人，不能说陪伴火车站。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象是动物或幼儿，不能说喂火车站。"}], "explanations": {"拆": "语义：“拆”指拆除，句子说的是医院与火车站的位置关系，不能说医院拆火车站。", "邻近": "邻近：位置接近，说明医院离火车站近，来看病的人多，符合句意。", "陪伴": "搭配：“陪伴”的对象是人，不能说陪伴火车站。", "喂": "搭配：“喂”的对象是动物或幼儿，不能说喂火车站。"}, "sentence_index": 6, "correct_answer": "邻近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的邻近住在三楼。", "explanation": "这里应该用〈邻居〉。邻近表示位置接近，不能指人。"}, {"text": "他慢慢邻近了我的身边。", "explanation": "这里应该用〈走近〉。走近强调移动过来，邻近只描述位置接近的状态，不表示移动的过程。"}, {"text": "这位演员的表演很邻近真实。", "explanation": "这里应该用〈逼真〉。邻近只说位置，形容表演像真的要用逼真。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家邻近到学校，上学很方便。", "corrected_sentence": "我家邻近学校，上学很方便。", "error_description": "错误在“邻近”后多加了补语“到”。“邻近”后直接带宾语，应说“邻近学校”，不说“邻近到学校”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家邻近在学校，走路就能到。", "corrected_sentence": "我家邻近学校，走路就能到。", "error_description": "错误在“邻近”后多加了介词“在”。“邻近”后直接带宾语，应说“邻近学校”，不说“邻近在学校”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
