INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95131, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "医师是帮人看病的人。", "primary_collocate": null, "pronunciation": "yī shī", "ipa": "i˥ ʂʅ˥", "syllable_count": 2, "sentences": [{"text": "医师帮病人看病，很辛苦。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医师对每个病人都很好。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我生病了，要去找医师。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医师说我要多喝水，多休息。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想长大后当医师，帮助别人。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医师给孩子开了一些药。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院有二十位医师。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医师让我张开嘴，看看喉咙。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医师问我哪里不舒服。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位医师每天都站着给病人检查。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "醫師", "label": "繁体"}], "register": "中性", "sense_fingerprint": "帮人看病的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6217be5-e5ea-4a87-a628-c92f2ff422f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95131, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "医师", "is_correct": true, "explanation": "医师 yī shī，指帮人看病的人，是本题的正确答案。"}, {"text": "遗失", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，遗失的意思是丢失。"}, {"text": "衣饰", "is_correct": false, "explanation": "第二个音节 shì（第四声）与 shī（第一声）声调不同，衣饰指衣服等装饰品。"}, {"text": "一时", "is_correct": false, "explanation": "第二个音节 shí（第二声）与 shī（第一声）声调不同，一时指短时间。"}, {"text": "仪式", "is_correct": false, "explanation": "两个音节的声调都与医师不同，仪式指典礼。"}], "explanations": {"医师": "医师 yī shī，指帮人看病的人，是本题的正确答案。", "遗失": "yí（第二声）与 yī（第一声）声调不同，遗失的意思是丢失。", "衣饰": "第二个音节 shì（第四声）与 shī（第一声）声调不同，衣饰指衣服等装饰品。", "一时": "第二个音节 shí（第二声）与 shī（第一声）声调不同，一时指短时间。", "仪式": "两个音节的声调都与医师不同，仪式指典礼。"}, "sentence_index": null, "correct_answer": "医师"}, "level_3": {"options": [{"text": "医师", "is_correct": true, "explanation": "医师：帮人看病的专业人员，与“帮病人看病”相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：“厨师”负责做饭，与“帮病人看病”无关。"}, {"text": "律师", "is_correct": false, "explanation": "语义：“律师”负责法律事务，不给病人看病。"}, {"text": "清洁工", "is_correct": false, "explanation": "搭配：“看病”的主体是医务人员，清洁工与“看病”不搭配。"}], "explanations": {"医师": "医师：帮人看病的专业人员，与“帮病人看病”相符。", "厨师": "语义：“厨师”负责做饭，与“帮病人看病”无关。", "律师": "语义：“律师”负责法律事务，不给病人看病。", "清洁工": "搭配：“看病”的主体是医务人员，清洁工与“看病”不搭配。"}, "sentence_index": 0, "correct_answer": "医师"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家医院有一只医师，很有名。", "explanation": "这里的量词“只”用于动物，数人要用〈位〉，不能用“只”。"}, {"text": "我学了很多医师知识，希望将来做研究。", "explanation": "这里应该用〈医学〉。医师指人，学科和知识要用〈医学〉，不能说“医师知识”。"}, {"text": "他在医师工作了十年，很有经验。", "explanation": "这里应该用〈医院〉。医师是人，不是工作的地方，“在……工作”的地点要用〈医院〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95131, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "医师", "is_correct": true, "explanation": "医师 yī shī，指帮人看病的人，是本题的正确答案。"}, {"text": "移师", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，移师指转移军队。"}, {"text": "医事", "is_correct": false, "explanation": "第二个音节 shì（第四声）与 shī（第一声）声调不同，医事指医疗方面的事务。"}, {"text": "遗失", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，遗失的意思是丢失。"}, {"text": "议事", "is_correct": false, "explanation": "两个音节的声调都与医师不同，议事指商量事情。"}], "explanations": {"医师": "医师 yī shī，指帮人看病的人，是本题的正确答案。", "移师": "yí（第二声）与 yī（第一声）声调不同，移师指转移军队。", "医事": "第二个音节 shì（第四声）与 shī（第一声）声调不同，医事指医疗方面的事务。", "遗失": "yí（第二声）与 yī（第一声）声调不同，遗失的意思是丢失。", "议事": "两个音节的声调都与医师不同，议事指商量事情。"}, "sentence_index": null, "correct_answer": "医师"}, "level_3": {"options": [{"text": "医师", "is_correct": true, "explanation": "医师：医院里负责看病的专业人员，与“这家医院”相符。"}, {"text": "诗人", "is_correct": false, "explanation": "语义：“诗人”指写诗的人，不是医院里的医疗人员，句子读起来不通。"}, {"text": "演员", "is_correct": false, "explanation": "语义：“演员”指表演的人，与医院的人员配置无关。"}, {"text": "农民", "is_correct": false, "explanation": "搭配：“农民”与“医院的人员”不搭配，句子不通。"}], "explanations": {"医师": "医师：医院里负责看病的专业人员，与“这家医院”相符。", "诗人": "语义：“诗人”指写诗的人，不是医院里的医疗人员，句子读起来不通。", "演员": "语义：“演员”指表演的人，与医院的人员配置无关。", "农民": "搭配：“农民”与“医院的人员”不搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "医师"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位医师整天都在修理汽车。", "explanation": "这里应该用〈修车工〉。医师是治病的人，修汽车的人要用〈修车工〉。"}, {"text": "那位医师每天都在田里插秧。", "explanation": "这里应该用〈农民〉。医师是治病的人，在田里插秧的人要用〈农民〉。"}, {"text": "那位医师每天都在工地上搬砖。", "explanation": "这里应该用〈工人〉。医师是治病的人，在工地搬砖的人要用〈工人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95131, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从小就想当一只医师。", "corrected_sentence": "他从小就想当一位医师。", "error_description": "错误在量词。医师是人，应用“位”（或“名”），“只”用于动物，不能用来数医师。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95131, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们小区的诊所有三个位医师。", "corrected_sentence": "我们小区的诊所有三位医师。", "error_description": "错误在量词。“个”和“位”不能同时使用，数医师用“位”就够了，应说“三位医师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
