INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95132, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "经过考试取得资格、从事治病工作的专业人员。", "primary_collocate": null, "pronunciation": "yī shī", "ipa": "i˥ ʂʅ˥", "syllable_count": 2, "sentences": [{"text": "他考过了医师资格考试。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做医师要先通过国家考试。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位有十年经验的医师。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有资格的医师，不能给人看病。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医师在大医院工作了二十年。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学了五年，终于成了一名医师。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医师要经过考试，才能给病人治病。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一名医师，会用针灸治病。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥是医师，在市里的医院工作。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家会给考试合格的医师发证。", "target_word": "医师", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "醫師", "label": "繁体"}], "register": "书面", "sense_fingerprint": "经考试取得资格、从事治病的专业人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6217be5-e5ea-4a87-a628-c92f2ff422f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95132, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "医师", "is_correct": true, "explanation": "医师 yī shī，指经考试取得资格、从事治病工作的专业人员，是本题的正确答案。"}, {"text": "遗失", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，遗失的意思是丢失。"}, {"text": "衣饰", "is_correct": false, "explanation": "第二个音节 shì（第四声）与 shī（第一声）声调不同，衣饰指衣服等装饰品。"}, {"text": "一时", "is_correct": false, "explanation": "第二个音节 shí（第二声）与 shī（第一声）声调不同，一时指短时间。"}, {"text": "议事", "is_correct": false, "explanation": "两个音节的声调都与医师不同，议事指商量事情。"}], "explanations": {"医师": "医师 yī shī，指经考试取得资格、从事治病工作的专业人员，是本题的正确答案。", "遗失": "yí（第二声）与 yī（第一声）声调不同，遗失的意思是丢失。", "衣饰": "第二个音节 shì（第四声）与 shī（第一声）声调不同，衣饰指衣服等装饰品。", "一时": "第二个音节 shí（第二声）与 shī（第一声）声调不同，一时指短时间。", "议事": "两个音节的声调都与医师不同，议事指商量事情。"}, "sentence_index": null, "correct_answer": "医师"}, "level_3": {"options": [{"text": "医师", "is_correct": true, "explanation": "医师：经考试取得资格的治病专业人员，与“资格考试”相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：没有“桌子资格考试”，桌子不是一种职业，句子不通。"}, {"text": "茶叶", "is_correct": false, "explanation": "搭配：“茶叶”与“资格考试”不搭配，句子不通。"}, {"text": "水果", "is_correct": false, "explanation": "语义：没有“水果资格考试”，水果不是一种职业。"}], "explanations": {"医师": "医师：经考试取得资格的治病专业人员，与“资格考试”相符。", "桌子": "语义：没有“桌子资格考试”，桌子不是一种职业，句子不通。", "茶叶": "搭配：“茶叶”与“资格考试”不搭配，句子不通。", "水果": "语义：没有“水果资格考试”，水果不是一种职业。"}, "sentence_index": 0, "correct_answer": "医师"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一只医师，已经通过了资格考试。", "explanation": "这里应该用〈位〉或〈名〉。量词“只”用于动物，数医师要用“位”或“名”。"}, {"text": "他学了五年医师，终于成了一名医生。", "explanation": "这里应该用〈医学〉。医师是人，学了五年要说“学医学”，不能说“学医师”。"}, {"text": "他在大学里读医师专业。", "explanation": "这里应该用〈医学〉。医师指人，大学专业要说“医学专业”，不能说“医师专业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95132, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "医师", "is_correct": true, "explanation": "医师 yī shī，指经考试取得资格、从事治病工作的专业人员，是本题的正确答案。"}, {"text": "移师", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，移师指转移军队。"}, {"text": "医事", "is_correct": false, "explanation": "第二个音节 shì（第四声）与 shī（第一声）声调不同，医事指医疗方面的事务。"}, {"text": "以示", "is_correct": false, "explanation": "两个音节的声调都与医师不同，以示指用来表明。"}, {"text": "仪式", "is_correct": false, "explanation": "两个音节的声调都与医师不同，仪式指典礼。"}], "explanations": {"医师": "医师 yī shī，指经考试取得资格、从事治病工作的专业人员，是本题的正确答案。", "移师": "yí（第二声）与 yī（第一声）声调不同，移师指转移军队。", "医事": "第二个音节 shì（第四声）与 shī（第一声）声调不同，医事指医疗方面的事务。", "以示": "两个音节的声调都与医师不同，以示指用来表明。", "仪式": "两个音节的声调都与医师不同，仪式指典礼。"}, "sentence_index": null, "correct_answer": "医师"}, "level_3": {"options": [{"text": "医师", "is_correct": true, "explanation": "医师：经考试取得资格、能给病人治病的专业人员，与句中语境相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：“厨师”负责做饭，不给病人治病，句子不通。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”负责教学，与“给病人治病”无关。"}, {"text": "司机", "is_correct": false, "explanation": "搭配：“司机”与“给病人治病”不搭配，句子不通。"}], "explanations": {"医师": "医师：经考试取得资格、能给病人治病的专业人员，与句中语境相符。", "厨师": "语义：“厨师”负责做饭，不给病人治病，句子不通。", "老师": "语义：“老师”负责教学，与“给病人治病”无关。", "司机": "搭配：“司机”与“给病人治病”不搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "医师"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位医师每天在火车站卖票。", "explanation": "这里应该用〈售票员〉。医师指治病的专业人员，卖票的人要用〈售票员〉。"}, {"text": "这位医师每天在教室里教数学。", "explanation": "这里应该用〈教师〉。医师是治病的专业人员，教数学的人要用〈教师〉。"}, {"text": "那位医师每天在码头上扛货。", "explanation": "这里应该用〈搬运工〉。医师是治病的专业人员，扛货的人要用〈搬运工〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是了十年医师。", "corrected_sentence": "他当了十年医师。", "error_description": "错误在动词。“当”表示担任某种职业，“是”不能与“了”连用表示担任职业的经历，应说“当了十年医师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是一把优秀的医师。", "corrected_sentence": "她是一名优秀的医师。", "error_description": "错误在量词。医师是人，应用“名”或“位”，“把”用于有柄的器具，不能用来数医师。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
