INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95133, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "间谍是偷偷拿别国秘密的人。", "primary_collocate": null, "pronunciation": "jiàn dié", "ipa": "tɕjɛn˥˩ tjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "警察抓到了一个间谍。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是别国派来的间谍。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的间谍常常换名字。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个间谍偷走了国家的秘密。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学说他像个间谍，总是很神秘。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位间谍偷偷拍下了别国的军事文件。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是普通人，而是一名间谍。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都不知道他是间谍。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是一个间谍的故事。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场的警察正在找那个间谍。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "間諜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "偷偷获取别国秘密的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61745b1a-f27b-4aaf-b958-4b5b5e37ece2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95133, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花园", "is_correct": false, "explanation": "搭配：「抓到」的对象应是人或可以被抓的东西，花园不能被抓到。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是需要抓捕的对象，句意不通。"}, {"text": "间谍", "is_correct": true, "explanation": "「间谍」指偷偷刺探情报的人，是警察抓捕的对象，符合句意。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能被警察抓到，与句意不合。"}], "explanations": {"花园": "搭配：「抓到」的对象应是人或可以被抓的东西，花园不能被抓到。", "桌子": "语义：桌子不是需要抓捕的对象，句意不通。", "间谍": "「间谍」指偷偷刺探情报的人，是警察抓捕的对象，符合句意。", "月亮": "语义：月亮不能被警察抓到，与句意不合。"}, "sentence_index": 0, "correct_answer": "间谍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个间谍专门在公交车上偷乘客的钱包。", "explanation": "这里应该用〈小偷〉。间谍是替别国刺探秘密的人，专门偷别人财物的人应说小偷。"}, {"text": "这匹间谍偷走了国家的秘密。", "explanation": "这里不能用〈匹〉。〈匹〉用于马、布等，间谍指人，应用「个」或「名」。"}, {"text": "这个间谍是一座大楼，偷走了国家的秘密。", "explanation": "这里不能用〈间谍〉指一座建筑。〈间谍〉指偷偷刺探别国秘密的人，不指建筑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95133, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语法：「名」只用于人，「一名汽车」不成立，汽车也不能表示身份。"}, {"text": "间谍", "is_correct": true, "explanation": "「而是一名间谍」说明他的隐秘身份，符合句意。"}, {"text": "雨伞", "is_correct": false, "explanation": "语法：「名」只用于人，雨伞不能作人的身份。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是人，不能用「一名」计量，也不能作身份。"}], "explanations": {"汽车": "语法：「名」只用于人，「一名汽车」不成立，汽车也不能表示身份。", "间谍": "「而是一名间谍」说明他的隐秘身份，符合句意。", "雨伞": "语法：「名」只用于人，雨伞不能作人的身份。", "月亮": "语义：月亮不是人，不能用「一名」计量，也不能作身份。"}, "sentence_index": 6, "correct_answer": "间谍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个间谍在机场破了一个案子。", "explanation": "这里应该用〈侦探〉。间谍替他国或组织刺探秘密情报，破案调查应说侦探。"}, {"text": "那个间谍是一台电脑，专门负责传递消息。", "explanation": "这里不能用〈间谍〉指机器。〈间谍〉指人，不能说它是一台电脑或其他机器。"}, {"text": "机场的警察正在找那条间谍。", "explanation": "这里不能用〈条〉。〈条〉用于细长的东西或某些动物，间谍是人，应用「个」或「位」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95133, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个人假装成游客，其实是一只间谍。", "corrected_sentence": "那个人假装成游客，其实是一名间谍。", "error_description": "错误：「一只间谍」。正确：「间谍」指人，量词应用「名」或「个」，「只」用于动物或成对的物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95133, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个很聪明间谍，没人发现。", "corrected_sentence": "他是一个很聪明的间谍，没人发现。", "error_description": "错误：「很聪明间谍」漏掉了修饰语后面的「的」。正确：「很聪明的间谍」，形容词修饰名词时中间要加「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
