INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95134, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "为他国或某组织秘密刺探情报的人。", "primary_collocate": null, "pronunciation": "jiàn dié", "ipa": "tɕjɛn˥˩ tjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "他为另一个国家做间谍，收集情报。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司怀疑里面有竞争对手派来的间谍。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个间谍每天把情报发给组织。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个组织派了一名间谍进来。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当间谍很多年，没人知道。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "间谍的工作又危险又秘密。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在大使馆当间谍，拍下了很多文件。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理发现，新来的同事是对手公司的间谍。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得他会是间谍吗？", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个间谍用手机把消息传了出去。", "target_word": "间谍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "間諜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "替别的国家或组织秘密收集情报的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61745b1a-f27b-4aaf-b958-4b5b5e37ece2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95134, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饭", "is_correct": false, "explanation": "语义：做饭与收集情报无关，句意不通。"}, {"text": "间谍", "is_correct": true, "explanation": "「做间谍」指替别国收集情报，与句中的「收集情报」相符。"}, {"text": "手工", "is_correct": false, "explanation": "语义：做手工与收集情报无关，不能描述这件事。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：「做生日」不能用来指为国家做的事，且与「收集情报」不合。"}], "explanations": {"饭": "语义：做饭与收集情报无关，句意不通。", "间谍": "「做间谍」指替别国收集情报，与句中的「收集情报」相符。", "手工": "语义：做手工与收集情报无关，不能描述这件事。", "生日": "搭配：「做生日」不能用来指为国家做的事，且与「收集情报」不合。"}, "sentence_index": 0, "correct_answer": "间谍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个间谍每天跟着老板，保护他的安全。", "explanation": "这里应该用〈保镖〉。间谍是为他国或组织秘密刺探情报的人，贴身保护老板要用保镖。"}, {"text": "那个组织派了一头间谍进来。", "explanation": "这里不能用〈头〉。〈头〉用于牛、猪等动物，间谍指人，应用「名」或「个」。"}, {"text": "那个组织派了一名间谍进来，他公开在医院给病人治病。", "explanation": "这里应该用〈医生〉。间谍是秘密刺探情报的人，公开在医院行医应说「医生」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95134, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "搭配：「当」后接人的身份，不能说「当桌子」。"}, {"text": "苹果", "is_correct": false, "explanation": "搭配：「当」后接人的身份，苹果不是身份，句意不通。"}, {"text": "间谍", "is_correct": true, "explanation": "「当间谍」指替别国刺探情报，与「拍下了很多文件」相符。"}, {"text": "空调", "is_correct": false, "explanation": "搭配：「当」后接的是人的身份，不能说「当空调」。"}], "explanations": {"桌子": "搭配：「当」后接人的身份，不能说「当桌子」。", "苹果": "搭配：「当」后接人的身份，苹果不是身份，句意不通。", "间谍": "「当间谍」指替别国刺探情报，与「拍下了很多文件」相符。", "空调": "搭配：「当」后接的是人的身份，不能说「当空调」。"}, "sentence_index": 6, "correct_answer": "间谍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个间谍用手机骗了很多老人的钱。", "explanation": "这里应该用〈骗子〉。间谍是替别国或组织收集情报的人，骗钱的人应说骗子。"}, {"text": "那个间谍是一部手机，用来把消息传了出去。", "explanation": "这里不能用〈间谍〉指一件设备。〈间谍〉指人，不能当作机器。"}, {"text": "那台间谍用手机把消息传了出去。", "explanation": "这里不能用〈台〉。〈台〉用于机器、电器，间谍指人，应用「名」或「个」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我怀疑隔壁那个人是为别国工作的一只间谍。", "corrected_sentence": "我怀疑隔壁那个人是为别国工作的间谍。", "error_description": "错误：「一只间谍」。正确：「间谍」指人，前面不用「只」修饰，直接说「的间谍」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被人怀疑间谍，所以很快就被抓了。", "corrected_sentence": "他被人怀疑是间谍，所以很快就被抓了。", "error_description": "错误：「怀疑间谍」，漏掉了「是」。正确：「被人怀疑是间谍」，「怀疑」后接人的身份时，中间要用「是」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
