INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95135, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "双手是左手和右手两只手。", "primary_collocate": null, "pronunciation": "shuāng shǒu", "ipa": "ʂwaŋ˥ ʂoʊ˨˩", "syllable_count": 2, "sentences": [{"text": "他用双手拿着一杯热茶。", "target_word": "双手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭前要洗干净双手。", "target_word": "双手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子伸出双手，想让妈妈抱。", "target_word": "双手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的双手很冷，快给我一杯热水。", "target_word": "双手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她双手提着两个大袋子。", "target_word": "双手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把双手举起来。", "target_word": "双手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天出门要戴手套，别冻着双手。", "target_word": "双手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着向我伸出了双手。", "target_word": "双手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的双手又粗又大。", "target_word": "双手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她双手捧着一束花，走进教室。", "target_word": "双手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一双手", "label": "量词"}, {"form": "雙手", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体部位：左手和右手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d21fd02-94af-431a-bf66-245fcefabcc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95135, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "双手", "is_correct": true, "explanation": "正确：双手是左手和右手两只手。"}, {"text": "水手", "is_correct": false, "explanation": "第一音节 shuǐ（第三声）与 shuāng（第一声）声调不同，意思是水手。"}, {"text": "上手", "is_correct": false, "explanation": "第一音节 shàng（第四声）与 shuāng 韵母和声调都不同，意思是上手，指熟练。"}, {"text": "熟手", "is_correct": false, "explanation": "第一音节 shóu（第二声）与 shuāng 不同，意思是熟练的人。"}], "explanations": {"双手": "正确：双手是左手和右手两只手。", "水手": "第一音节 shuǐ（第三声）与 shuāng（第一声）声调不同，意思是水手。", "上手": "第一音节 shàng（第四声）与 shuāng 韵母和声调都不同，意思是上手，指熟练。", "熟手": "第一音节 shóu（第二声）与 shuāng 不同，意思是熟练的人。"}, "sentence_index": null, "correct_answer": "双手"}, "level_3": {"options": [{"text": "双手", "is_correct": true, "explanation": "正确：双手是身体部位，可以“用……拿着”东西，与句子相符。"}, {"text": "双脚", "is_correct": false, "explanation": "语义：脚不能用来拿东西，与“用……拿着一杯热茶”冲突。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛是用来看的，不能用来拿东西，与“拿着一杯热茶”冲突。"}, {"text": "嘴巴", "is_correct": false, "explanation": "搭配：“拿着”的工具一般是手，“嘴巴”不能与“用……拿着”搭配。"}], "explanations": {"双手": "正确：双手是身体部位，可以“用……拿着”东西，与句子相符。", "双脚": "语义：脚不能用来拿东西，与“用……拿着一杯热茶”冲突。", "眼睛": "语义：眼睛是用来看的，不能用来拿东西，与“拿着一杯热茶”冲突。", "嘴巴": "搭配：“拿着”的工具一般是手，“嘴巴”不能与“用……拿着”搭配。"}, "sentence_index": 0, "correct_answer": "双手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他双手闭上，静静地坐在床边。", "explanation": "这里应该用〈双眼〉。闭眼要用双眼，双手不能闭。"}, {"text": "冬天出门要戴上双手。", "explanation": "这里应该用〈手套〉。戴的是手套，双手是身体部位，不能用“戴”。"}, {"text": "他用双手踢球。", "explanation": "这里应该用〈脚〉。踢球要用脚，双手不能用来踢球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95135, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "双手", "is_correct": true, "explanation": "正确：双手是左手和右手两只手。"}, {"text": "双收", "is_correct": false, "explanation": "第二音节 shōu（第一声）与 shǒu（第三声）声调不同，意思是两方面都有收获。"}, {"text": "上首", "is_correct": false, "explanation": "第一音节 shàng（第四声）与 shuāng 读音不同，意思是位置较尊贵的一侧。"}, {"text": "双数", "is_correct": false, "explanation": "第二音节 shù 与 shǒu 韵母和声调不同，意思是偶数。"}], "explanations": {"双手": "正确：双手是左手和右手两只手。", "双收": "第二音节 shōu（第一声）与 shǒu（第三声）声调不同，意思是两方面都有收获。", "上首": "第一音节 shàng（第四声）与 shuāng 读音不同，意思是位置较尊贵的一侧。", "双数": "第二音节 shù 与 shǒu 韵母和声调不同，意思是偶数。"}, "sentence_index": null, "correct_answer": "双手"}, "level_3": {"options": [{"text": "双手", "is_correct": true, "explanation": "正确：双手是身体部位，可以被“冻着”，与“别冻着双手”相符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是身体部位，不会被“冻着”，与句意冲突。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不是身体部位，不会被“冻着”，与句意冲突。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不会被“冻着”，与句意冲突。"}], "explanations": {"双手": "正确：双手是身体部位，可以被“冻着”，与“别冻着双手”相符。", "书包": "语义：书包不是身体部位，不会被“冻着”，与句意冲突。", "椅子": "语义：椅子不是身体部位，不会被“冻着”，与句意冲突。", "作业": "语义：作业不会被“冻着”，与句意冲突。"}, "sentence_index": 6, "correct_answer": "双手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用双手听声音。", "explanation": "这里应该用〈耳朵〉。听声音用耳朵，双手不能用来听。"}, {"text": "她用双手闻花香。", "explanation": "这里应该用〈鼻子〉。闻花香用鼻子，双手不能用来闻。"}, {"text": "她用双手看远处的山。", "explanation": "这里应该用〈眼睛〉。看东西用眼睛，双手不能用来看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95135, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她伸出一只双手，接住了那个球。", "corrected_sentence": "她伸出一双手，接住了那个球。", "error_description": "量词错误：双手是一对，量词应用“双”，应说“一双手”，用“只”是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95135, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她双手的很稳，能捧住这束花。", "corrected_sentence": "她双手很稳，能捧住这束花。", "error_description": "结构错误：“双手很稳”中间不能加“的”，“的”多余，应说“她双手很稳”，不能说“她双手的很稳”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
