INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95137, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "发小是从小一起玩大的朋友。", "primary_collocate": null, "pronunciation": "fā xiǎo", "ipa": "fa⁵⁵ ɕiɑʊ̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "他是我的发小，我们一起长大。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和发小常常一起去河边玩。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我的发小结婚了，我去喝喜酒。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发小从国外回来，我去机场接他。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有三个发小，感情都很好。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和发小十年没见过面了。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到难事，我先给发小打电话。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的发小在北京工作。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发小送了我一本书。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩是发小，什么话都能说。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "發小", "label": "繁体"}], "register": "口语", "sense_fingerprint": "从小一起玩到大的朋友", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c21081-19c8-4e43-9122-d082b2713663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95137, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发小", "is_correct": true, "explanation": "发小（fā xiǎo）指从小一起玩大的朋友。"}, {"text": "发笑", "is_correct": false, "explanation": "第二个音节声调不同：xiào（第四声）与 xiǎo（第三声）不同，意思是引人发笑。"}, {"text": "发表", "is_correct": false, "explanation": "第二个音节声母不同：b 与 x 不同，意思是公开发表。"}, {"text": "发烧", "is_correct": false, "explanation": "第二个音节读音不同：shāo（声母 sh，第一声）与 xiǎo（声母 x，第三声）不同，意思是体温升高、生病。"}], "explanations": {"发小": "发小（fā xiǎo）指从小一起玩大的朋友。", "发笑": "第二个音节声调不同：xiào（第四声）与 xiǎo（第三声）不同，意思是引人发笑。", "发表": "第二个音节声母不同：b 与 x 不同，意思是公开发表。", "发烧": "第二个音节读音不同：shāo（声母 sh，第一声）与 xiǎo（声母 x，第三声）不同，意思是体温升高、生病。"}, "sentence_index": null, "correct_answer": "发小"}, "level_3": {"options": [{"text": "发小", "is_correct": true, "explanation": "发小指从小一起长大的朋友，与“一起长大”的语境相合。"}, {"text": "老板", "is_correct": false, "explanation": "语义：“老板”是工作关系，与“一起长大”的经历矛盾。"}, {"text": "客户", "is_correct": false, "explanation": "语义：“客户”是生意往来，与“一起长大”的经历矛盾。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：「雨伞」是物品，不能「和我们一起长大」，句意不通。"}], "explanations": {"发小": "发小指从小一起长大的朋友，与“一起长大”的语境相合。", "老板": "语义：“老板”是工作关系，与“一起长大”的经历矛盾。", "客户": "语义：“客户”是生意往来，与“一起长大”的经历矛盾。", "雨伞": "语义：「雨伞」是物品，不能「和我们一起长大」，句意不通。"}, "sentence_index": 0, "correct_answer": "发小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班转来一个新发小。", "explanation": "这里应该用〈同学〉。发小指从小一起长大的朋友，刚转到班里的同学不能叫发小。"}, {"text": "我和刚认识的发小很投缘。", "explanation": "这里应该用〈朋友〉。发小指从小一起长大的朋友，刚认识的人不能叫发小。"}, {"text": "一个发小是我昨天刚认识的新邻居。", "explanation": "这里应该用〈邻居〉。发小指从小一起长大的朋友，昨天刚认识的人不能叫发小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95137, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发小", "is_correct": true, "explanation": "发小指从小一起长大的朋友，与“遇到难事找他帮忙”的语境相合。"}, {"text": "仇人", "is_correct": false, "explanation": "语义：“仇人”与“遇到难事先找他”的情理相反，不合。"}, {"text": "电视", "is_correct": false, "explanation": "语义：「电视」是电器，不能被「打电话」求助，句意不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：「冰箱」是电器，不能被「打电话」求助，句意不通。"}], "explanations": {"发小": "发小指从小一起长大的朋友，与“遇到难事找他帮忙”的语境相合。", "仇人": "语义：“仇人”与“遇到难事先找他”的情理相反，不合。", "电视": "语义：「电视」是电器，不能被「打电话」求助，句意不通。", "冰箱": "语义：「冰箱」是电器，不能被「打电话」求助，句意不通。"}, "sentence_index": 6, "correct_answer": "发小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门口站着一只发小。", "explanation": "这里应该用〈个〉。“只”用于动物，指人应用“个”。"}, {"text": "屋里坐着一把发小。", "explanation": "这里应该用〈个〉。“把”用于有柄的器具，指人应用“个”。"}, {"text": "他书桌上放着一本发小。", "explanation": "这里应该用〈个〉。“本”用于书籍，指人应用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95137, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我地发小们都来了。", "corrected_sentence": "我的发小们都来了。", "error_description": "结构助词错误：表示领属的定语后应用“的”，应写作“我的发小们”；“我地发小们”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95137, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在北京有两只发小。", "corrected_sentence": "我在北京有两个发小。", "error_description": "量词错误：“只”用于动物，指人的发小应用“个”，写作“两个发小”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
