INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95138, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从小就在一起长大的朋友。", "primary_collocate": null, "pronunciation": "fā xiǎo", "ipa": "fa⁵⁵ ɕiɑʊ̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "我和发小在同一条街上长大。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发小比我小一岁，总叫我哥。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我约了发小去爬山。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的发小是个医生。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我和发小常常偷偷下河游泳。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发小生病了，我去看他。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我发小，我们认识二十年了。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发小借给我一辆车。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们几个发小每年见一次面。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老同学不如发小亲。", "target_word": "发小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "發小", "label": "繁体"}], "register": "口语", "sense_fingerprint": "从小一起长大的朋友", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c21081-19c8-4e43-9122-d082b2713663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发小", "is_correct": true, "explanation": "发小指从小一起长大的朋友，与“在同一条街上长大”的语境相合。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：“陌生人”与“一起长大”矛盾，不可能从小在同一条街上长大。"}, {"text": "债主", "is_correct": false, "explanation": "语义：“债主”是借贷关系，与“一起长大”的经历矛盾。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：「汽车」是交通工具，不能与「我」一起在街上长大，句意不通。"}], "explanations": {"发小": "发小指从小一起长大的朋友，与“在同一条街上长大”的语境相合。", "陌生人": "语义：“陌生人”与“一起长大”矛盾，不可能从小在同一条街上长大。", "债主": "语义：“债主”是借贷关系，与“一起长大”的经历矛盾。", "汽车": "语义：「汽车」是交通工具，不能与「我」一起在街上长大，句意不通。"}, "sentence_index": 0, "correct_answer": "发小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门口停着一辆发小。", "explanation": "这里应该用〈个〉。“辆”用于车辆，指人应用“个”。"}, {"text": "他家门前站着一台发小。", "explanation": "这里应该用〈个〉。“台”用于机器，指人应用“个”。"}, {"text": "桌边坐着一张发小。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，指人应用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95138, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "发小", "is_correct": true, "explanation": "发小（fā xiǎo）指从小一起长大的朋友。"}, {"text": "发笑", "is_correct": false, "explanation": "第二个音节声调不同：xiào（第四声）与 xiǎo（第三声）不同，意思是引人发笑。"}, {"text": "发表", "is_correct": false, "explanation": "第二个音节声母不同：b 与 x 不同，意思是公开发表。"}, {"text": "发烧", "is_correct": false, "explanation": "第二个音节读音不同：shāo（声母 sh，第一声）与 xiǎo（声母 x，第三声）不同，意思是体温升高、生病。"}], "explanations": {"发小": "发小（fā xiǎo）指从小一起长大的朋友。", "发笑": "第二个音节声调不同：xiào（第四声）与 xiǎo（第三声）不同，意思是引人发笑。", "发表": "第二个音节声母不同：b 与 x 不同，意思是公开发表。", "发烧": "第二个音节读音不同：shāo（声母 sh，第一声）与 xiǎo（声母 x，第三声）不同，意思是体温升高、生病。"}, "sentence_index": null, "correct_answer": "发小"}, "level_3": {"options": [{"text": "发小", "is_correct": true, "explanation": "发小指从小一起长大的朋友，与“认识二十年”的语境相合。"}, {"text": "新人", "is_correct": false, "explanation": "语义：“新人”指刚认识的人，与“认识二十年了”矛盾。"}, {"text": "新手", "is_correct": false, "explanation": "语义：“新手”指刚入门的人，与“认识二十年了”矛盾。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：「椅子」是家具，不能是「我」认识二十年的人，句意不通。"}], "explanations": {"发小": "发小指从小一起长大的朋友，与“认识二十年”的语境相合。", "新人": "语义：“新人”指刚认识的人，与“认识二十年了”矛盾。", "新手": "语义：“新手”指刚入门的人，与“认识二十年了”矛盾。", "椅子": "语义：「椅子」是家具，不能是「我」认识二十年的人，句意不通。"}, "sentence_index": 6, "correct_answer": "发小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我大学时的发小一直很照顾我。", "explanation": "这里应该用〈同学〉。发小指从小一起长大的朋友，大学认识的人不能叫发小。"}, {"text": "我的发小是一台旧电脑。", "explanation": "这里应该用〈朋友〉指人。「电脑」是物件，不能是从小一起长大的人。"}, {"text": "车站里来了一位发小，他是我刚认识的同事。", "explanation": "这里应该用〈同事〉。发小指从小一起长大的朋友，刚认识的人不能叫发小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在老家有两本发小。", "corrected_sentence": "我在老家有两个发小。", "error_description": "量词用错。“发小”指人，量词应用“个”，“本”只用于书籍。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我地发小们都来参加婚礼了。", "corrected_sentence": "我的发小们都来参加婚礼了。", "error_description": "结构助词错误：表示领属的定语后应用“的”，应写作“我的发小们”；“我地发小们”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
