INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95141, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一线是最前面做事的地方。", "primary_collocate": null, "pronunciation": "yí xiàn", "ipa": "i³⁵ ɕi̯ɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "她愿意去农村一线工作。", "target_word": "一线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "护士在一线照顾病人，很不容易。", "target_word": "一线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "消防员冲到火灾一线。", "target_word": "一线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从一线退了下来，在家休息。", "target_word": "一线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一线的同事比办公室里的人更忙。", "target_word": "一线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厂长常到一线看工人干活。", "target_word": "一线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要听听一线老师的想法。", "target_word": "一线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "疫情期间，很多人守在一线。", "target_word": "一线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的医生被派到了一线。", "target_word": "一线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在一线学到了很多东西。", "target_word": "一线", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "第一线", "label": "复合"}], "register": "中性", "sense_fingerprint": "一线：最前面、直接做事的工作现场", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54467bb6-6f7e-4da9-9fdd-38e961a14e4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95141, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一线", "is_correct": true, "explanation": "一线：yí xiàn，指直接做事的工作现场，是正确答案。"}, {"text": "一项", "is_correct": false, "explanation": "一项：yí xiàng，与“一线”韵母不同（ang / an），意思是一个项目，不是一线。"}, {"text": "一下", "is_correct": false, "explanation": "一下：yí xià，比“一线”少了鼻音 n，意思是一次、短时间，不是一线。"}, {"text": "一遍", "is_correct": false, "explanation": "一遍：yí biàn，与“一线”声母不同（b / x），意思是一次从头到尾。"}], "explanations": {"一线": "一线：yí xiàn，指直接做事的工作现场，是正确答案。", "一项": "一项：yí xiàng，与“一线”韵母不同（ang / an），意思是一个项目，不是一线。", "一下": "一下：yí xià，比“一线”少了鼻音 n，意思是一次、短时间，不是一线。", "一遍": "一遍：yí biàn，与“一线”声母不同（b / x），意思是一次从头到尾。"}, "sentence_index": null, "correct_answer": "一线"}, "level_3": {"options": [{"text": "宇宙", "is_correct": false, "explanation": "语义：“宇宙”与“农村”不相关，不能说去农村宇宙工作。"}, {"text": "一线", "is_correct": true, "explanation": "一线：直接做事的工作现场，她愿意去农村一线工作，符合句意。"}, {"text": "海底", "is_correct": false, "explanation": "语义：“海底”与“农村”的地理环境相悖，不能说去农村海底工作。"}, {"text": "疆场", "is_correct": false, "explanation": "语域：“疆场”是文言色彩很浓的词，与这句话的日常语境不搭。"}], "explanations": {"宇宙": "语义：“宇宙”与“农村”不相关，不能说去农村宇宙工作。", "一线": "一线：直接做事的工作现场，她愿意去农村一线工作，符合句意。", "海底": "语义：“海底”与“农村”的地理环境相悖，不能说去农村海底工作。", "疆场": "语域：“疆场”是文言色彩很浓的词，与这句话的日常语境不搭。"}, "sentence_index": 0, "correct_answer": "一线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天在一线理发。", "explanation": "这里不能用〈一线〉。“一线”指工作现场，理发应去〈理发店〉。"}, {"text": "孩子们在一线画画，很开心。", "explanation": "这里不能用〈一线〉。“一线”指直接做事的工作现场，画画的地方应说〈画室〉。"}, {"text": "我在一线买菜。", "explanation": "这里不能用〈一线〉。买菜应去〈菜市场〉，“一线”不指购物场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95141, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一线", "is_correct": true, "explanation": "一线：yí xiàn，指直接做事的工作现场，是正确答案。"}, {"text": "一箱", "is_correct": false, "explanation": "一箱：yì xiāng，与“一线”声调和韵母都不同（yì / yí，iang / ian），意思是一个箱子的量，不是一线。"}, {"text": "一笑", "is_correct": false, "explanation": "一笑：yí xiào，与“一线”韵母不同（iao / ian），意思是笑一下，不是一线。"}, {"text": "一件", "is_correct": false, "explanation": "一件：yí jiàn，与“一线”声母不同（j / x），是数量词，如一件衣服，不是一线。"}], "explanations": {"一线": "一线：yí xiàn，指直接做事的工作现场，是正确答案。", "一箱": "一箱：yì xiāng，与“一线”声调和韵母都不同（yì / yí，iang / ian），意思是一个箱子的量，不是一线。", "一笑": "一笑：yí xiào，与“一线”韵母不同（iao / ian），意思是笑一下，不是一线。", "一件": "一件：yí jiàn，与“一线”声母不同（j / x），是数量词，如一件衣服，不是一线。"}, "sentence_index": null, "correct_answer": "一线"}, "level_3": {"options": [{"text": "太空", "is_correct": false, "explanation": "语义：“太空”与老师的工作场所不相关，不能说太空老师。"}, {"text": "一线", "is_correct": true, "explanation": "一线：直接参与工作的地方，修饰“老师”，表示一线老师，符合句意。"}, {"text": "神话", "is_correct": false, "explanation": "语义：“神话”指虚构的故事，与“老师的想法”不相关，不能说神话老师。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱”是家电，不能修饰“老师”，不能说冰箱老师。"}], "explanations": {"太空": "语义：“太空”与老师的工作场所不相关，不能说太空老师。", "一线": "一线：直接参与工作的地方，修饰“老师”，表示一线老师，符合句意。", "神话": "语义：“神话”指虚构的故事，与“老师的想法”不相关，不能说神话老师。", "冰箱": "搭配：“冰箱”是家电，不能修饰“老师”，不能说冰箱老师。"}, "sentence_index": 6, "correct_answer": "一线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在一线出生了。", "explanation": "这里不能用〈一线〉。“一线”指工作现场，出生的地点应说〈医院〉。"}, {"text": "他们在一线结婚了。", "explanation": "这里不能用〈一线〉。“一线”指工作现场，结婚的场所应说〈礼堂〉。"}, {"text": "我在一线考了驾照。", "explanation": "这里不能用〈一线〉。“一线”指工作现场，考驾照应去〈驾校〉或〈考场〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95141, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防员一直一线奋战。", "corrected_sentence": "消防员一直在一线奋战。", "error_description": "错误在“一线”前缺少介词“在”。表示动作发生的地点时要说“在一线奋战”，不能直接说“一线奋战”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95141, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们在一线里忙碌，很辛苦。", "corrected_sentence": "工人们在一线忙碌，很辛苦。", "error_description": "错误在“一线”后多加了方位词“里”。“在一线”已经表示地点，不需要再加“里”，应说“在一线忙碌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
