INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95142, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "最前方，直接参与工作的地方。", "primary_collocate": null, "pronunciation": "yí xiàn", "ipa": "i³⁵ ɕi̯ɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "他一直在教学一线工作。", "target_word": "一线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生们战斗在一线，非常辛苦。", "target_word": "一线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师回到一线教书了。", "target_word": "一线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一线的工人每天工作很长时间。", "target_word": "一线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者去了地震一线，拍下很多照片。", "target_word": "一线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在一线干了二十年，经验很多。", "target_word": "一线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司让经理多去一线看看。", "target_word": "一线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "护士长每天都在一线查房。", "target_word": "一线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次任务由一线指挥员直接负责。", "target_word": "一线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察在抗洪一线守了三天三夜。", "target_word": "一线", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "第一线", "label": "复合"}], "register": "中性", "sense_fingerprint": "一线：最前方直接做事的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54467bb6-6f7e-4da9-9fdd-38e961a14e4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95142, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一线", "is_correct": true, "explanation": "一线：yí xiàn，指直接参与工作的地方，是正确答案。"}, {"text": "一向", "is_correct": false, "explanation": "一向：yí xiàng，与“一线”韵母不同（ang / an），意思是一直，不是一线。"}, {"text": "一下", "is_correct": false, "explanation": "一下：yí xià，比“一线”少了鼻音 n，意思是一次、短时间，不是一线。"}, {"text": "一遍", "is_correct": false, "explanation": "一遍：yí biàn，与“一线”声母不同（b / x），意思是一次从头到尾。"}], "explanations": {"一线": "一线：yí xiàn，指直接参与工作的地方，是正确答案。", "一向": "一向：yí xiàng，与“一线”韵母不同（ang / an），意思是一直，不是一线。", "一下": "一下：yí xià，比“一线”少了鼻音 n，意思是一次、短时间，不是一线。", "一遍": "一遍：yí biàn，与“一线”声母不同（b / x），意思是一次从头到尾。"}, "sentence_index": null, "correct_answer": "一线"}, "level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”与“教学”的内容无关，不能说在教学厨房工作。"}, {"text": "一线", "is_correct": true, "explanation": "一线：直接参与工作的地方，与“教学”搭配，表示在教学第一线工作。"}, {"text": "战壕", "is_correct": false, "explanation": "语域：“战壕”属军事语域，与“教学”这种日常工作不搭。"}, {"text": "仓库", "is_correct": false, "explanation": "语义：“仓库”是存放货物的地方，与“教学”无关，不能说在教学仓库工作。"}], "explanations": {"厨房": "语义：“厨房”与“教学”的内容无关，不能说在教学厨房工作。", "一线": "一线：直接参与工作的地方，与“教学”搭配，表示在教学第一线工作。", "战壕": "语域：“战壕”属军事语域，与“教学”这种日常工作不搭。", "仓库": "语义：“仓库”是存放货物的地方，与“教学”无关，不能说在教学仓库工作。"}, "sentence_index": 0, "correct_answer": "一线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们在一线上课，很认真。", "explanation": "这里不能用〈一线〉。“一线”指直接做事的工作现场，学生上课的地点应说〈教室〉。"}, {"text": "他每天在一线玩游戏。", "explanation": "这里应该用〈家里〉。“一线”指工作现场，不用来表示休闲的地方。"}, {"text": "他下班后在一线唱歌。", "explanation": "这里不能用〈一线〉。“一线”指工作现场，唱歌应去〈KTV〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95142, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一线", "is_correct": true, "explanation": "一线：yí xiàn，指直接参与工作的地方，是正确答案。"}, {"text": "一箱", "is_correct": false, "explanation": "一箱：yì xiāng，与“一线”声调和韵母都不同（yì / yí，iang / ian），意思是一个箱子的量，不是一线。"}, {"text": "一笑", "is_correct": false, "explanation": "一笑：yí xiào，与“一线”韵母不同（iao / ian），意思是笑一下，不是一线。"}, {"text": "一件", "is_correct": false, "explanation": "一件：yí jiàn，与“一线”声母不同（j / x），是数量词，如一件衣服，不是一线。"}], "explanations": {"一线": "一线：yí xiàn，指直接参与工作的地方，是正确答案。", "一箱": "一箱：yì xiāng，与“一线”声调和韵母都不同（yì / yí，iang / ian），意思是一个箱子的量，不是一线。", "一笑": "一笑：yí xiào，与“一线”韵母不同（iao / ian），意思是笑一下，不是一线。", "一件": "一件：yí jiàn，与“一线”声母不同（j / x），是数量词，如一件衣服，不是一线。"}, "sentence_index": null, "correct_answer": "一线"}, "level_3": {"options": [{"text": "太空", "is_correct": false, "explanation": "语义：“太空”与“去看看”的工作场景不符，公司不会让经理去太空看看。"}, {"text": "一线", "is_correct": true, "explanation": "一线：直接参与工作的地方，公司让经理去一线看看，符合句意。"}, {"text": "沙场", "is_correct": false, "explanation": "语域：“沙场”是文言色彩很浓的词，与公司管理的日常语境不搭。"}, {"text": "月球", "is_correct": false, "explanation": "语义：“月球”与公司经理的工作无关，不能说去月球看看。"}], "explanations": {"太空": "语义：“太空”与“去看看”的工作场景不符，公司不会让经理去太空看看。", "一线": "一线：直接参与工作的地方，公司让经理去一线看看，符合句意。", "沙场": "语域：“沙场”是文言色彩很浓的词，与公司管理的日常语境不搭。", "月球": "语义：“月球”与公司经理的工作无关，不能说去月球看看。"}, "sentence_index": 6, "correct_answer": "一线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在一线买了一张票。", "explanation": "这里不能用〈一线〉。“一线”指工作现场，买票应在〈售票处〉。"}, {"text": "这个孩子在一线出生了。", "explanation": "这里不能用〈一线〉。“一线”指工作现场，出生的地点应说〈医院〉。"}, {"text": "他在一线结婚了。", "explanation": "这里不能用〈一线〉。“一线”指工作现场，结婚的场所应说〈礼堂〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一线工作了十年，很辛苦。", "corrected_sentence": "她在一线工作了十年，很辛苦。", "error_description": "错误在“一线”前缺少介词“在”。表示工作地点时要说“在一线工作”，不能直接说“一线工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "护士们在一线里照顾病人。", "corrected_sentence": "护士们在一线照顾病人。", "error_description": "错误在“一线”后多加了方位词“里”。“在一线”已经表示地点，不需要再加“里”，应说“在一线照顾病人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df46dac-71a2-40c4-adf6-a8154a8c6086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
