INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95144, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "修改订正文字、规章等。", "primary_collocate": null, "pronunciation": "xiū dìng", "ipa": "ɕioʊ˥ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "公司去年修订了安全规章。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校正在修订考试制度。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府修订了这部法律。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂修订了上班时间的规定。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起修订了班级的规定。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个规则用了十年，该修订了。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协会修订过几次会员章程。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的交通规则已经修订好了。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要把这份合同的文字修订一下。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理让我们修订员工手册里的旧规定。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "修订了", "label": "体标"}, {"form": "修订过", "label": "体标"}, {"form": "修订本", "label": "复合"}, {"form": "修訂", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "修订：对文字、规章、制度等修改订正", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '629e9c88-00bf-45eb-822b-29c0b905eb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95144, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修订", "is_correct": true, "explanation": "“修订”指修改文字、规章，与“公司去年……了安全规章”相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能说“喝规章”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不用于规章。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洗，与对安全规章的修改毫无关系。"}], "explanations": {"修订": "“修订”指修改文字、规章，与“公司去年……了安全规章”相符。", "喝": "搭配：“喝”的对象是饮品，不能说“喝规章”。", "吃": "搭配：“吃”的对象是食物，不用于规章。", "洗": "语义：“洗”指清洗，与对安全规章的修改毫无关系。"}, "sentence_index": 0, "correct_answer": "修订"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府修订了一座新桥。", "explanation": "这里应该用〈修建〉。修订用于文字、规章，桥梁、房屋等建造要用〈修建〉。"}, {"text": "他把坏了的电脑修订好了。", "explanation": "这里应该用〈修理〉。修订只用于文字和规章，电脑等器物的修理要用〈修理〉。"}, {"text": "园丁修订了花枝。", "explanation": "这里应该用〈修剪〉。修订指修改文字或规章，修剪花木要用〈修剪〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修订", "is_correct": true, "explanation": "“修订”指修改会章等文字，与“协会……过几次会员章程”相符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”用于食物，不能用于章程。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”指切开，与“几次会员章程”的修改语境不符。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”用于食物，不能说“烤章程”。"}], "explanations": {"修订": "“修订”指修改会章等文字，与“协会……过几次会员章程”相符。", "煮": "搭配：“煮”用于食物，不能用于章程。", "切": "语义：“切”指切开，与“几次会员章程”的修改语境不符。", "烤": "搭配：“烤”用于食物，不能说“烤章程”。"}, "sentence_index": 6, "correct_answer": "修订"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村里修订了古老的祠堂。", "explanation": "这里应该用〈修缮〉。修订用于文字、规章，祠堂等古建筑的修补要用〈修缮〉。"}, {"text": "电梯修订得很及时。", "explanation": "这里应该用〈维修〉。修订只用于文字和规章，机器设备的检修要用〈维修〉。"}, {"text": "博物馆修订了一件瓷器。", "explanation": "这里应该用〈修复〉。修订指修改文字或规章，瓷器等文物恢复原样要用〈修复〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份规章已经修订了过。", "corrected_sentence": "这份规章已经修订过。", "error_description": "“修订了过”错误，“了”和“过”不能同时用在同一动词后，表示曾经修订过应说“修订过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
