INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95145, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "俺是有些地方的人说的“我”。", "primary_collocate": null, "pronunciation": "ǎn", "ipa": "an²¹⁴", "syllable_count": 1, "sentences": [{"text": "俺是山东人，来北京三年了。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个苹果是俺自己种的。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俺饿了，咱们快去吃饭吧。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俺没听懂，你再说一遍。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大娘拉着俺的手，说了很多话。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俺想回家看看老人。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着对我说：“俺请你喝酒。”", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俺哥比俺高一个头。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这活儿太累，俺干不了。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俺从小就爱听戏。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "俺们", "label": "复合"}], "register": "口语", "sense_fingerprint": "有些地方的人用来称自己的“我”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c21081-19c8-4e43-9122-d082b2713663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95145, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "俺", "is_correct": true, "explanation": "俺（ǎn）是有些地方方言中的“我”，即目标词本身。"}, {"text": "安", "is_correct": false, "explanation": "安（ān，第一声）与 ǎn（第三声）声调不同，意思是平安。"}, {"text": "暗", "is_correct": false, "explanation": "暗（àn，第四声）与 ǎn（第三声）声调不同，意思是昏暗。"}, {"text": "感", "is_correct": false, "explanation": "感（gǎn）比 ǎn 多一个声母 g，声调相同，意思是感觉。"}, {"text": "懒", "is_correct": false, "explanation": "懒（lǎn）比 ǎn 多一个声母 l，声调相同，意思是懒惰。"}], "explanations": {"俺": "俺（ǎn）是有些地方方言中的“我”，即目标词本身。", "安": "安（ān，第一声）与 ǎn（第三声）声调不同，意思是平安。", "暗": "暗（àn，第四声）与 ǎn（第三声）声调不同，意思是昏暗。", "感": "感（gǎn）比 ǎn 多一个声母 g，声调相同，意思是感觉。", "懒": "懒（lǎn）比 ǎn 多一个声母 l，声调相同，意思是懒惰。"}, "sentence_index": null, "correct_answer": "俺"}, "level_3": {"options": [{"text": "俺", "is_correct": true, "explanation": "俺是有些地方方言中的“我”，属口语，与介绍自己的口吻相合。"}, {"text": "很", "is_correct": false, "explanation": "语法：「很」是副词，不能作主语，「很是山东人」不成句。"}, {"text": "被", "is_correct": false, "explanation": "语法：「被」是介词，不能作主语，句子不通。"}, {"text": "的", "is_correct": false, "explanation": "语法：「的」是助词，不能放在句首作主语。"}], "explanations": {"俺": "俺是有些地方方言中的“我”，属口语，与介绍自己的口吻相合。", "很": "语法：「很」是副词，不能作主语，「很是山东人」不成句。", "被": "语法：「被」是介词，不能作主语，句子不通。", "的": "语法：「的」是助词，不能放在句首作主语。"}, "sentence_index": 0, "correct_answer": "俺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈问我：“俺今天吃饭了吗？”", "explanation": "这里应该用〈你〉。妈妈问的是对方，「俺」只指说话人自己。"}, {"text": "我问小王：“俺几点下班？”", "explanation": "这里应该用〈你〉。问的是小王的下班时间，「俺」只指说话人自己。"}, {"text": "我问爷爷：“俺身体好吗？”", "explanation": "这里应该用〈您〉。问的是爷爷的身体，「俺」只指说话人自己。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95145, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "俺", "is_correct": true, "explanation": "俺（ǎn）是有些地方方言中的“我”，即目标词本身。"}, {"text": "按", "is_correct": false, "explanation": "按（àn，第四声）与 ǎn（第三声）声调不同，意思是按照。"}, {"text": "晚", "is_correct": false, "explanation": "晚（wǎn）比 ǎn 多一个声母 w，声调相同，意思是晚上。"}, {"text": "满", "is_correct": false, "explanation": "满（mǎn）比 ǎn 多一个声母 m，声调相同，意思是充满。"}], "explanations": {"俺": "俺（ǎn）是有些地方方言中的“我”，即目标词本身。", "按": "按（àn，第四声）与 ǎn（第三声）声调不同，意思是按照。", "晚": "晚（wǎn）比 ǎn 多一个声母 w，声调相同，意思是晚上。", "满": "满（mǎn）比 ǎn 多一个声母 m，声调相同，意思是充满。"}, "sentence_index": null, "correct_answer": "俺"}, "level_3": {"options": [{"text": "俺", "is_correct": true, "explanation": "俺是有些地方方言中的“我”，属口语，与朋友间请客的口吻相合。"}, {"text": "您", "is_correct": false, "explanation": "语义：“您”指对方，与后文“请你”的“你”指同一人，形成矛盾。"}, {"text": "你", "is_correct": false, "explanation": "人称：「你请你喝酒」主宾指同一人，句意矛盾。"}, {"text": "很", "is_correct": false, "explanation": "语法：「很」是副词，不能作主语，句子不通。"}], "explanations": {"俺": "俺是有些地方方言中的“我”，属口语，与朋友间请客的口吻相合。", "您": "语义：“您”指对方，与后文“请你”的“你”指同一人，形成矛盾。", "你": "人称：「你请你喝酒」主宾指同一人，句意矛盾。", "很": "语法：「很」是副词，不能作主语，句子不通。"}, "sentence_index": 6, "correct_answer": "俺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师问学生：“俺作业写完了吗？”", "explanation": "这里应该用〈你〉。老师问的是学生的作业，「俺」只指说话人自己。"}, {"text": "我对客人说：“俺请坐，俺喝茶。”", "explanation": "这里应该用〈您〉。请对方坐下喝茶，「俺」只指说话人自己。"}, {"text": "他指着弟弟说：“俺今年五岁了。”", "explanation": "这里应该用〈他〉。说的是弟弟的年龄，「俺」只指说话人自己。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
