INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95146, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "北方方言中的“我”或“我们”。", "primary_collocate": null, "pronunciation": "ǎn", "ipa": "an²¹⁴", "syllable_count": 1, "sentences": [{"text": "俺今天下午要去地里干活。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俺娘做的饺子最好吃。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别担心，这事俺来办。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俺家就在河边，你来玩吧。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俺不会写字，你帮帮俺。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张笑着说：“俺没钱，请不起客。”", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俺昨天去过北京，那儿真大。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俺爹在村里种了一辈子地。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他问俺想吃什么，俺说想吃面。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俺那儿冬天很冷，雪下得很大。", "target_word": "俺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "俺们", "label": "复合"}], "register": "口语", "sense_fingerprint": "北方方言里自称，指我或我们", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c21081-19c8-4e43-9122-d082b2713663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95146, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "俺", "is_correct": true, "explanation": "俺（ǎn）是北方方言中的“我”，即目标词本身。"}, {"text": "安", "is_correct": false, "explanation": "安（ān，第一声）与 ǎn（第三声）声调不同，意思是平安。"}, {"text": "按", "is_correct": false, "explanation": "按（àn，第四声）与 ǎn（第三声）声调不同，意思是按照、按下。"}, {"text": "感", "is_correct": false, "explanation": "感（gǎn）比 ǎn 多一个声母 g，声调相同，意思是感觉。"}, {"text": "眼", "is_correct": false, "explanation": "眼（yǎn）比 ǎn 多一个声母 y，声调相同，意思是眼睛。"}, {"text": "懒", "is_correct": false, "explanation": "懒（lǎn）比 ǎn 多一个声母 l，声调相同，意思是懒惰。"}], "explanations": {"俺": "俺（ǎn）是北方方言中的“我”，即目标词本身。", "安": "安（ān，第一声）与 ǎn（第三声）声调不同，意思是平安。", "按": "按（àn，第四声）与 ǎn（第三声）声调不同，意思是按照、按下。", "感": "感（gǎn）比 ǎn 多一个声母 g，声调相同，意思是感觉。", "眼": "眼（yǎn）比 ǎn 多一个声母 y，声调相同，意思是眼睛。", "懒": "懒（lǎn）比 ǎn 多一个声母 l，声调相同，意思是懒惰。"}, "sentence_index": null, "correct_answer": "俺"}, "level_3": {"options": [{"text": "俺", "is_correct": true, "explanation": "俺是北方方言中的“我”，属口语，与“去地里干活”的农村语境相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不会自己去地里干活，不能作这里的主语。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”与句中的“今天下午”时间冲突，句子不通。"}, {"text": "锄头", "is_correct": false, "explanation": "语义：“锄头”是工具，不能自己“要去”干活。"}], "explanations": {"俺": "俺是北方方言中的“我”，属口语，与“去地里干活”的农村语境相合。", "石头": "语义：“石头”不会自己去地里干活，不能作这里的主语。", "明天": "语义：“明天”与句中的“今天下午”时间冲突，句子不通。", "锄头": "语义：“锄头”是工具，不能自己“要去”干活。"}, "sentence_index": 0, "correct_answer": "俺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "尊敬的各位来宾，俺代表公司欢迎大家的到来。", "explanation": "这里应该用〈我〉。“俺”是北方口语方言，正式致辞要用“我”。"}, {"text": "本论文中，俺将讨论三个问题。", "explanation": "这里应该用〈笔者〉。学术论文是书面正式语体，不能用方言口语的“俺”。"}, {"text": "新闻主播说：“俺台记者从现场发回报道。”", "explanation": "这里应该用〈本〉。新闻播报是正式语体，应说“本台”，不能用方言“俺”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95146, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "俺", "is_correct": true, "explanation": "俺（ǎn）是北方方言中的“我”，即目标词本身。"}, {"text": "岸", "is_correct": false, "explanation": "岸（àn，第四声）与 ǎn（第三声）声调不同，意思是岸边。"}, {"text": "掩", "is_correct": false, "explanation": "掩（yǎn）比 ǎn 多一个声母 y，声调相同，意思是遮掩。"}, {"text": "晚", "is_correct": false, "explanation": "晚（wǎn）比 ǎn 多一个声母 w，声调相同，意思是晚上。"}, {"text": "满", "is_correct": false, "explanation": "满（mǎn）比 ǎn 多一个声母 m，声调相同，意思是充满。"}], "explanations": {"俺": "俺（ǎn）是北方方言中的“我”，即目标词本身。", "岸": "岸（àn，第四声）与 ǎn（第三声）声调不同，意思是岸边。", "掩": "掩（yǎn）比 ǎn 多一个声母 y，声调相同，意思是遮掩。", "晚": "晚（wǎn）比 ǎn 多一个声母 w，声调相同，意思是晚上。", "满": "满（mǎn）比 ǎn 多一个声母 m，声调相同，意思是充满。"}, "sentence_index": null, "correct_answer": "俺"}, "level_3": {"options": [{"text": "俺", "is_correct": true, "explanation": "俺是北方方言中的“我”，属口语，与前一句的叙述语气相合。"}, {"text": "米饭", "is_correct": false, "explanation": "语义：“米饭”是食物，不能“去过北京”。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年”与“昨天去过”时间冲突，句子不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是物，不能“去过北京”。"}], "explanations": {"俺": "俺是北方方言中的“我”，属口语，与前一句的叙述语气相合。", "米饭": "语义：“米饭”是食物，不能“去过北京”。", "明年": "语义：“明年”与“昨天去过”时间冲突，句子不通。", "桌子": "语义：“桌子”是物，不能“去过北京”。"}, "sentence_index": 6, "correct_answer": "俺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "总理在大会上发言：“俺国经济正在稳步发展。”", "explanation": "这里应该用〈我〉。正式讲话应说“我国”，“俺”是方言口语。"}, {"text": "公司公告：俺公司将于下周一放假一天。", "explanation": "这里应该用〈本〉。正式公告应说“本公司”，不能用方言“俺”。"}, {"text": "法官宣布：“俺庭判决如下。”", "explanation": "这里应该用〈本〉。法庭用语极正式，应说“本庭”，不能用方言“俺”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95146, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "俺的想给娘买件新衣服。", "corrected_sentence": "俺想给娘买件新衣服。", "error_description": "“俺”后面不能加“的”再接动词，“俺的想”是错误的，应为“俺想”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95146, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家俺的院子很大。", "corrected_sentence": "俺家的院子很大。", "error_description": "语序错误。“俺家”是“我家”的方言说法，“家”必须在“俺”之后，应为“俺家的院子很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
