INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95147, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "两国是两个国家。", "primary_collocate": null, "pronunciation": "liǎng guó", "ipa": "ljɑŋ˨˩ kwɔ˧˥", "syllable_count": 2, "sentences": [{"text": "两国是邻居，关系一直很好。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两国的人都喜欢喝茶。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的老师明天要见面。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国之间有一条很长的河。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两国他都去过，觉得都很漂亮。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的孩子一起学习了汉语。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的足球队今天晚上比赛。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们希望两国永远是朋友。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的天气不一样，一个冷一个热。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的总统昨天在北京见面了。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "两國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两个国家的合称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65ce783-209c-496d-8375-67116e6f7c33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95147, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书桌", "is_correct": false, "explanation": "语义：“邻居”指住户或人，书桌不能是邻居。"}, {"text": "两国", "is_correct": true, "explanation": "两国：两个国家。“两国是邻居，关系一直很好”指两个国家相邻、关系友好，符合语境。"}, {"text": "牙膏", "is_correct": false, "explanation": "搭配：“是邻居”的主语要是人或住户，“牙膏”不能与之搭配。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是房间，不能说是“邻居”。"}], "explanations": {"书桌": "语义：“邻居”指住户或人，书桌不能是邻居。", "两国": "两国：两个国家。“两国是邻居，关系一直很好”指两个国家相邻、关系友好，符合语境。", "牙膏": "搭配：“是邻居”的主语要是人或住户，“牙膏”不能与之搭配。", "教室": "语义：教室是房间，不能说是“邻居”。"}, "sentence_index": 0, "correct_answer": "两国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和妹妹是两国。", "explanation": "这里应该用〈两人〉。“两国”只指两个国家，不能用来说两个人。"}, {"text": "北京和上海是两国。", "explanation": "这里应该用〈两座城市〉。“两国”指两个国家，北京和上海是两座城市，不是国家。"}, {"text": "中国、日本和韩国是两国。", "explanation": "这里应该用〈三个国家〉。“两国”只指两个国家，中国、日本、韩国共三个，要说“三个国家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95147, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是可以组队比赛的主体，不能有足球队。"}, {"text": "两国", "is_correct": true, "explanation": "两国：两个国家。“两国的足球队今天晚上比赛”指两个国家的球队对阵，符合语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱”与“足球队”不搭配，不能说冰箱的球队。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能组队参加比赛。"}], "explanations": {"汽车": "语义：汽车不是可以组队比赛的主体，不能有足球队。", "两国": "两国：两个国家。“两国的足球队今天晚上比赛”指两个国家的球队对阵，符合语境。", "冰箱": "搭配：“冰箱”与“足球队”不搭配，不能说冰箱的球队。", "窗户": "语义：窗户是建筑部件，不能组队参加比赛。"}, "sentence_index": 6, "correct_answer": "两国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座楼有两国。", "explanation": "这里应该用〈两层〉。“两国”指两个国家，不能用来数楼的层数，说楼的层要用“层”。"}, {"text": "这枚硬币的两国都很清楚。", "explanation": "这里应该用〈两面〉。“国”不表示“面”，硬币有两面，应说“两面”，“两国”指两个国家。"}, {"text": "这两国都是我们班的同学。", "explanation": "这里应该用〈两名同学〉。“两国”指国家，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95147, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个两国的人都很友好。", "corrected_sentence": "这两国的人都很友好。", "error_description": "错误在量词“个”。“两”是数词，“两国”前面直接用指示代词“这”即可，应说“这两国”，不说“这个两国”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95147, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国们的球员在比赛中很努力。", "corrected_sentence": "两国的球员在比赛中很努力。", "error_description": "错误在“们”。“两国”是指国家的名词，后面不能加表示复数的“们”，应说“两国的球员”，不说“两国们的球员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
