INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95148, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "两个国家。", "primary_collocate": null, "pronunciation": "liǎng guó", "ipa": "ljɑŋ˨˩ kwɔ˧˥", "syllable_count": 2, "sentences": [{"text": "中国和日本，这两国我都想去。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的电影在这里很受欢迎。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的饭菜有的像，有的不像。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两国中间只隔着一座山。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国人民常常来往，关系很近。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的商人做了很多生意。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在两国都住过，会说两种语言。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国开通了一条新的铁路。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了两国的历史。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的学生在网上交了朋友。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "两國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "指两个国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65ce783-209c-496d-8375-67116e6f7c33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95148, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书店", "is_correct": false, "explanation": "语义：前文是“中国和日本”两个国家，“书店”不能与之并列作为想去的对象。"}, {"text": "两国", "is_correct": true, "explanation": "两国：两个国家。这里指中国和日本，“这两国我都想去”语义通顺，符合语境。"}, {"text": "牙膏", "is_correct": false, "explanation": "搭配：“想去”的对象要是地方，“牙膏”不能与“想去”搭配。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是小地方，不能与“中国和日本”并列作为想去的国家。"}], "explanations": {"书店": "语义：前文是“中国和日本”两个国家，“书店”不能与之并列作为想去的对象。", "两国": "两国：两个国家。这里指中国和日本，“这两国我都想去”语义通顺，符合语境。", "牙膏": "搭配：“想去”的对象要是地方，“牙膏”不能与“想去”搭配。", "花园": "语义：花园是小地方，不能与“中国和日本”并列作为想去的国家。"}, "sentence_index": 0, "correct_answer": "两国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两国都是我们班的同学。", "explanation": "这里应该用〈两个同学〉。“两国”指两个国家，不能用来指人。"}, {"text": "这座楼有两国。", "explanation": "这里应该用〈两层〉。“两国”指两个国家，不能用来数楼的层数，说楼的层要用“层”。"}, {"text": "北京和上海是两国。", "explanation": "这里应该用〈两座城市〉。北京和上海都是城市，不是国家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95148, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：“住过”的地方要能住人，汽车不是住的地方，与语境不符。"}, {"text": "两国", "is_correct": true, "explanation": "两国：两个国家。“她在两国都住过，会说两种语言”指她在两个国家生活过，符合语境。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能住人，“住过”的地点不能是窗户。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“在……住过”的地点与“课本”不搭配。"}], "explanations": {"汽车": "语义：“住过”的地方要能住人，汽车不是住的地方，与语境不符。", "两国": "两国：两个国家。“她在两国都住过，会说两种语言”指她在两个国家生活过，符合语境。", "窗户": "语义：窗户不能住人，“住过”的地点不能是窗户。", "课本": "搭配：“在……住过”的地点与“课本”不搭配。"}, "sentence_index": 6, "correct_answer": "两国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两国在操场上跑步。", "explanation": "这里应该用〈两个学生〉。“两国”指国家，国家不能在操场上跑步。"}, {"text": "我爸爸是两国。", "explanation": "这里不能用“两国”指人。“两国”只指两个国家，不能用来描述一个人。"}, {"text": "我把这两国放进了冰箱。", "explanation": "这里应该用〈两瓶〉。国家不能放进冰箱，“两国”只指两个国家，不能指两件东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个两国的音乐很好听。", "corrected_sentence": "这两国的音乐很好听。", "error_description": "错误在量词“个”。“两”是数词，“两国”前面直接用“这”即可，应说“这两国”，不说“这个两国”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两国们的人民很友好。", "corrected_sentence": "这两国的人民很友好。", "error_description": "错误在“们”。“两国”是指国家的名词，后面不能加表示复数的“们”，应说“这两国的人民”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
