INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95149, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "冷静是遇到事不乱，心里很稳。", "primary_collocate": null, "pronunciation": "lěng jìng", "ipa": "lɤŋ˨˩ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "着火了，他一点也不慌，很冷静。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遇到问题，我们要先冷静想一想。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出了事故，司机还是很冷静。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不哭也不叫，样子很冷静。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试时越紧张越要保持冷静。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很冷静，没有跟着大家一起乱跑。", "target_word": "冷静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震时，老师冷静地带学生出去。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别急，先冷静一下，再慢慢说。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面对坏消息，她的头脑还很冷静。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大火来了，冷静的人先想办法。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷静下来", "label": "复合"}, {"form": "冷靜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "遇到事情不慌不乱、心里稳的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0a3031-66ae-43d8-9fb5-fe85694236c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95149, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "慌张", "is_correct": false, "explanation": "语义：「慌张」表示慌乱失措，与前半句「一点也不慌」直接矛盾，句子不通。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：「漂亮」形容外表好看，不能用来描述面对火灾时的镇定状态。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：「热情」多用于形容待人的态度，不能用来形容面对险情时的心理状态。"}, {"text": "冷静", "is_correct": true, "explanation": "「冷静」指遇事不慌不乱，与「一点也不慌」相呼应，符合语境。"}], "explanations": {"慌张": "语义：「慌张」表示慌乱失措，与前半句「一点也不慌」直接矛盾，句子不通。", "漂亮": "体貌：「漂亮」形容外表好看，不能用来描述面对火灾时的镇定状态。", "热情": "搭配：「热情」多用于形容待人的态度，不能用来形容面对险情时的心理状态。", "冷静": "「冷静」指遇事不慌不乱，与「一点也不慌」相呼应，符合语境。"}, "sentence_index": 0, "correct_answer": "冷静"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个菜很冷静，一点也不辣。", "explanation": "这里应该用〈清淡〉。「冷静」形容人遇事不慌乱，不能形容饭菜的味道。"}, {"text": "我的手很冷静，快冻僵了。", "explanation": "这里应该用〈冷〉。「冷静」形容遇事的心理状态，不表示温度，手温度低要说「冷」。"}, {"text": "收到录取通知后，他很冷静地跳起来欢呼。", "explanation": "「冷静」指沉着理智、不慌不乱，与「跳起来欢呼」的激动情绪矛盾。这里应该用〈激动〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95149, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "害羞", "is_correct": false, "explanation": "语义：「害羞」表示不好意思，与地震时老师带学生撤离的紧急情境不合。"}, {"text": "懒洋洋", "is_correct": false, "explanation": "语义：「懒洋洋」形容没精神、不着急的样子，与地震时的紧急情况矛盾。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：「瘦弱」描述身体状况，不能用来说明人的行事方式。"}, {"text": "冷静", "is_correct": true, "explanation": "「冷静地」修饰动作「带学生出去」，表示老师在地震中沉着应对，符合语境。"}], "explanations": {"害羞": "语义：「害羞」表示不好意思，与地震时老师带学生撤离的紧急情境不合。", "懒洋洋": "语义：「懒洋洋」形容没精神、不着急的样子，与地震时的紧急情况矛盾。", "瘦弱": "体貌：「瘦弱」描述身体状况，不能用来说明人的行事方式。", "冷静": "「冷静地」修饰动作「带学生出去」，表示老师在地震中沉着应对，符合语境。"}, "sentence_index": 6, "correct_answer": "冷静"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他长得很冷静，一看就是个好人。", "explanation": "「冷静」只形容遇事的心理状态，不能用来形容外貌。这里应该用〈和善〉。"}, {"text": "听到大家的掌声，他冷静得脸都红了。", "explanation": "「冷静」指不慌不乱，与「脸都红了」所表示的窘迫情绪矛盾。这里应该用〈害羞〉。"}, {"text": "他很冷静地大哭了一场。", "explanation": "这里应该用〈伤心〉。「冷静」指遇事不慌不乱，与「大哭」所表示的悲伤情绪矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95149, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他听到消息以后，慢慢冷静来了。", "corrected_sentence": "他听到消息以后，慢慢冷静下来了。", "error_description": "「冷静」后的趋向补语应为「下来」，不能只用「来」；「冷静来了」不成立，应改为「冷静下来」，表示由激动转为平静。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95149, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很冷静得处理了这件事。", "corrected_sentence": "他很冷静地处理了这件事。", "error_description": "修饰动词「处理」的状语应用「地」，不能用「得」。「得」用于动词或形容词之后，连接补语，这里「冷静」只修饰后面的动作，应改为「冷静地」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95150, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冲动", "is_correct": true, "explanation": "「冲动」与「冷静」是反义词，指不考虑后果、凭一时情绪行事，与「沉着镇定、不冲动」相对。"}, {"text": "便宜", "is_correct": false, "explanation": "「便宜」形容价格低，与「冷静」没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "「明亮」形容光线或颜色，与「冷静」没有反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "「轻松」形容心情或状态不紧张，与「冷静」指的沉着不是反义关系。"}], "correct_answer": "冲动", "explanations": {"冲动": "「冲动」与「冷静」是反义词，指不考虑后果、凭一时情绪行事，与「沉着镇定、不冲动」相对。", "便宜": "「便宜」形容价格低，与「冷静」没有反义关系。", "明亮": "「明亮」形容光线或颜色，与「冷静」没有反义关系。", "轻松": "「轻松」形容心情或状态不紧张，与「冷静」指的沉着不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95150, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冲动", "is_correct": true, "explanation": "「冲动」与「冷静」是反义词，指不考虑后果、凭一时情绪行事，与「头脑要冷静」相对。"}, {"text": "缓慢", "is_correct": false, "explanation": "「缓慢」形容速度慢，与「冷静」没有反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "「温暖」形容温度或态度，与「冷静」没有反义关系。"}, {"text": "沉重", "is_correct": false, "explanation": "「沉重」形容分量大或心情压抑，与「冷静」没有反义关系。"}], "correct_answer": "冲动", "explanations": {"冲动": "「冲动」与「冷静」是反义词，指不考虑后果、凭一时情绪行事，与「头脑要冷静」相对。", "缓慢": "「缓慢」形容速度慢，与「冷静」没有反义关系。", "温暖": "「温暖」形容温度或态度，与「冷静」没有反义关系。", "沉重": "「沉重」形容分量大或心情压抑，与「冷静」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95150, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "沉着镇定，不冲动。", "primary_collocate": null, "pronunciation": "lěng jìng", "ipa": "lɤŋ˨˩ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他很生气，但还是冷静地说话。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先冷静想想，不要马上做决定。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吵架的时候，要冷静，不要乱发火。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买东西前冷静一下，就不会乱花钱。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他比朋友冷静，没有冲上去打人。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到别人骂他，他还是很冷静。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我生气的时候，会先冷静十分钟。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你冷静点儿，别一激动就大喊大叫。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理很冷静，没有当场骂那个人。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做重要的决定时，头脑要冷静。", "target_word": "冷静", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷静下来", "label": "复合"}, {"form": "冷靜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "沉着镇定、不被情绪推着冲动行事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0a3031-66ae-43d8-9fb5-fe85694236c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95150, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "慌张", "is_correct": false, "explanation": "语义：「慌张」表示惊惶失措，与「但还是」所表达的镇定态度相反。"}, {"text": "迟钝", "is_correct": false, "explanation": "语义：「迟钝」形容反应慢，与「说话」时保持镇定的语境不符。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：「矮小」描述身材，不能用来形容说话的方式。"}, {"text": "冷静", "is_correct": true, "explanation": "「冷静地说话」表示即使生气也能沉着说话，与「但还是」相呼应，符合语境。"}], "explanations": {"慌张": "语义：「慌张」表示惊惶失措，与「但还是」所表达的镇定态度相反。", "迟钝": "语义：「迟钝」形容反应慢，与「说话」时保持镇定的语境不符。", "矮小": "体貌：「矮小」描述身材，不能用来形容说话的方式。", "冷静": "「冷静地说话」表示即使生气也能沉着说话，与「但还是」相呼应，符合语境。"}, "sentence_index": 0, "correct_answer": "冷静"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块蛋糕很冷静，我很喜欢吃。", "explanation": "这里应该用〈好吃〉。「冷静」形容人沉着、不冲动，不能形容食物的味道。"}, {"text": "我的脚很冷静，快冻僵了。", "explanation": "这里应该用〈冷〉。「冷静」形容心理状态，不表示温度，脚冷要说「冷」。"}, {"text": "他一听到消息就很冷静地跳起来大骂。", "explanation": "「冷静」指不冲动，与「跳起来大骂」的冲动行为矛盾。这里描述的是冲动行为，应该用〈冲动〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95150, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冲动", "is_correct": false, "explanation": "搭配：「冲动」描述轻率行动的状态，不能与「先……十分钟」的平复过程搭配。"}, {"text": "激动", "is_correct": false, "explanation": "语义：「激动」是情绪高涨，与生气之后先平复下来的语境相反。"}, {"text": "慌张", "is_correct": false, "explanation": "语义：「慌张」表示惊慌失措，与先让自己平静下来的语境不符。"}, {"text": "冷静", "is_correct": true, "explanation": "「冷静」作动词时表示让自己平静下来，与「生气的时候先……十分钟」的语境相符。"}], "explanations": {"冲动": "搭配：「冲动」描述轻率行动的状态，不能与「先……十分钟」的平复过程搭配。", "激动": "语义：「激动」是情绪高涨，与生气之后先平复下来的语境相反。", "慌张": "语义：「慌张」表示惊慌失措，与先让自己平静下来的语境不符。", "冷静": "「冷静」作动词时表示让自己平静下来，与「生气的时候先……十分钟」的语境相符。"}, "sentence_index": 6, "correct_answer": "冷静"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的耳朵很冷静，冻得发红。", "explanation": "这里应该用〈冷〉。「冷静」形容心理状态，不表示温度，耳朵冷要说「冷」。"}, {"text": "听到好消息，他冷静地哭得说不出话。", "explanation": "这里应该用〈激动〉。「冷静」指沉着、不冲动，与「哭得说不出话」所表示的激动情绪矛盾。"}, {"text": "他很冷静地抢过别人的手机，还大声骂人。", "explanation": "「冷静」指不冲动，与「抢手机、大声骂人」的冲动行为矛盾。这里应该用〈冲动〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他遇到问题没有冲动，而是冷静得解决了问题。", "corrected_sentence": "他遇到问题没有冲动，而是冷静地解决了问题。", "error_description": "修饰动词「解决」的状语应该用「地」，表示方式。「得」用在动词或形容词之后，连接补语，这里误用了「得」，应改为「冷静地」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "做决定时，他总是冷静得想清楚。", "corrected_sentence": "做决定时，他总是冷静地想清楚。", "error_description": "「冷静」修饰动词「想清楚」，作状语，应用「地」表示方式。「得」用于动词或形容词之后引出补语，这里误用，应改为「冷静地」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95151, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复合", "is_correct": true, "explanation": "复合：恋人分手后重新和好、恢复关系，与“结束恋爱关系”相反。"}, {"text": "结婚", "is_correct": false, "explanation": "结婚：指正式成为夫妻，是关系的发展，与分手不构成反义。"}, {"text": "相识", "is_correct": false, "explanation": "相识：指彼此认识，与分手不构成反义。"}, {"text": "约会", "is_correct": false, "explanation": "约会：指事先约好见面，与分手不构成反义。"}], "correct_answer": "复合", "explanations": {"复合": "复合：恋人分手后重新和好、恢复关系，与“结束恋爱关系”相反。", "结婚": "结婚：指正式成为夫妻，是关系的发展，与分手不构成反义。", "相识": "相识：指彼此认识，与分手不构成反义。", "约会": "约会：指事先约好见面，与分手不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95151, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "和好", "is_correct": true, "explanation": "和好：恋人闹别扭后重新和好，与“结束恋爱关系”相对。"}, {"text": "照顾", "is_correct": false, "explanation": "照顾：指关心、料理他人，与分手不构成反义。"}, {"text": "同居", "is_correct": false, "explanation": "同居：指生活在一起，与分手不构成反义。"}, {"text": "求婚", "is_correct": false, "explanation": "求婚：指向对方提出结婚的请求，与分手不构成反义。"}], "correct_answer": "和好", "explanations": {"和好": "和好：恋人闹别扭后重新和好，与“结束恋爱关系”相对。", "照顾": "照顾：指关心、料理他人，与分手不构成反义。", "同居": "同居：指生活在一起，与分手不构成反义。", "求婚": "求婚：指向对方提出结婚的请求，与分手不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95151, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分手是两个人不再在一起了。", "primary_collocate": null, "pronunciation": "fēn shǒu", "ipa": "fən˥ ʂou˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们昨天分手了。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和女朋友分手三个月了。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他们因为工作分手了。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想分手，可是他很坚决。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分手以后，他们还是好朋友。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们为什么要分手？", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱了三年的两个人，最后还是分手了。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她提出分手，他一句话也没说。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谈了五年恋爱，他们决定分手。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是常吵架，两个人就容易分手。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分手了", "label": "体标"}, {"form": "分过手", "label": "体标"}], "register": "口语", "sense_fingerprint": "恋人结束恋爱关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce87e407-f827-4d11-8490-1be803ed23ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95151, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分手", "is_correct": true, "explanation": "分手（fēn shǒu）：两个人不再在一起，结束恋爱关系。"}, {"text": "分数", "is_correct": false, "explanation": "分数（fēn shù）：第二个音节 shǒu 与 shù 的韵母和声调都不同，意思是分数。"}, {"text": "分食", "is_correct": false, "explanation": "分食（fēn shí）：shǒu（第三声）与 shí（第二声）的韵母和声调都不同，意思是分着吃。"}, {"text": "分售", "is_correct": false, "explanation": "分售（fēn shòu）：shǒu（第三声）与 shòu（第四声）声调不同，意思是分开出售。"}], "explanations": {"分手": "分手（fēn shǒu）：两个人不再在一起，结束恋爱关系。", "分数": "分数（fēn shù）：第二个音节 shǒu 与 shù 的韵母和声调都不同，意思是分数。", "分食": "分食（fēn shí）：shǒu（第三声）与 shí（第二声）的韵母和声调都不同，意思是分着吃。", "分售": "分售（fēn shòu）：shǒu（第三声）与 shòu（第四声）声调不同，意思是分开出售。"}, "sentence_index": null, "correct_answer": "分手"}, "level_3": {"options": [{"text": "分手", "is_correct": true, "explanation": "正确：分手指两人结束恋爱关系，与“他们昨天……了”相符。"}, {"text": "怀孕", "is_correct": false, "explanation": "语义：怀孕只能指女性，不能用“他们”作主语。"}, {"text": "出嫁", "is_correct": false, "explanation": "搭配：出嫁指女子结婚后离开娘家，不能用于“他们”。"}, {"text": "登基", "is_correct": false, "explanation": "语域：登基指帝王即位，用在日常叙述里很不协调。"}], "explanations": {"分手": "正确：分手指两人结束恋爱关系，与“他们昨天……了”相符。", "怀孕": "语义：怀孕只能指女性，不能用“他们”作主语。", "出嫁": "搭配：出嫁指女子结婚后离开娘家，不能用于“他们”。", "登基": "语域：登基指帝王即位，用在日常叙述里很不协调。"}, "sentence_index": 0, "correct_answer": "分手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两块磁铁分手了。", "explanation": "这里的“分手”用于恋人等有感情关系的人，不能用于磁铁。这里应该用〈分离〉。"}, {"text": "人群在广场上分手了。", "explanation": "分手的主语是两个人（恋人），人群散开应该用〈散开〉，不用〈分手〉。"}, {"text": "两队在中场分手了，比分还是平的。", "explanation": "这里应该用〈休息〉。分手只用于两个人（恋人）结束关系，两队在中场休息时不能说分手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95151, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分手", "is_correct": true, "explanation": "分手（fēn shǒu）：两个人不再在一起，结束恋爱关系。"}, {"text": "分期", "is_correct": false, "explanation": "分期（fēn qī）：第二个音节的声母、韵母和声调都不同，意思是分期付款。"}, {"text": "分时", "is_correct": false, "explanation": "分时（fēn shí）：shǒu（第三声）与 shí（第二声）的韵母和声调不同，意思是按时间分段。"}, {"text": "分身", "is_correct": false, "explanation": "分身（fēn shēn）：韵母和声调都不同，意思是分身、化身。"}], "explanations": {"分手": "分手（fēn shǒu）：两个人不再在一起，结束恋爱关系。", "分期": "分期（fēn qī）：第二个音节的声母、韵母和声调都不同，意思是分期付款。", "分时": "分时（fēn shí）：shǒu（第三声）与 shí（第二声）的韵母和声调不同，意思是按时间分段。", "分身": "分身（fēn shēn）：韵母和声调都不同，意思是分身、化身。"}, "sentence_index": null, "correct_answer": "分手"}, "level_3": {"options": [{"text": "分手", "is_correct": true, "explanation": "正确：分手指两人结束恋爱关系，与“爱了三年的两个人，最后还是……了”相符。"}, {"text": "分娩", "is_correct": false, "explanation": "语义：分娩只能指女性生孩子，不能用于“两个人”。"}, {"text": "嫁", "is_correct": false, "explanation": "搭配：嫁只用于女性出嫁，不能说“两个人嫁了”。"}, {"text": "退位", "is_correct": false, "explanation": "语域：退位指帝王让出君位，用在恋爱叙述里很不协调。"}], "explanations": {"分手": "正确：分手指两人结束恋爱关系，与“爱了三年的两个人，最后还是……了”相符。", "分娩": "语义：分娩只能指女性生孩子，不能用于“两个人”。", "嫁": "搭配：嫁只用于女性出嫁，不能说“两个人嫁了”。", "退位": "语域：退位指帝王让出君位，用在恋爱叙述里很不协调。"}, "sentence_index": 6, "correct_answer": "分手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个好朋友因为一件小事分手了，之后再也不说话。", "explanation": "分手专指恋人结束恋爱关系，朋友之间闹翻应该用〈绝交〉，不用〈分手〉。"}, {"text": "小王一个人分手了，觉得很轻松。", "explanation": "分手需要两个人共同结束关系，主语只有一个人时不能用，这里应该用〈离开〉。"}, {"text": "这两只小狗分手了，各自去玩。", "explanation": "分手只用于恋爱中的人，小狗不能用，这里应该用〈分开〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95151, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把男朋友分手了，很伤心。", "corrected_sentence": "她跟男朋友分手了，很伤心。", "error_description": "错误：“把男朋友分手了”；正确：“跟男朋友分手了”。分手是不及物动词，后面不能带宾语，也不能用把字句；表示与某人分手，要用介词“跟”引出对象。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95151, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她上个月和男朋友分手着。", "corrected_sentence": "她上个月和男朋友分手了。", "error_description": "错误：“分手着”；正确：“分手了”。“分手”表示已经完成的结束关系，要用完成标记“了”，不能用表示持续状态的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
