INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95153, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "前线是战争中离敌人最近的地方。", "primary_collocate": null, "pronunciation": "qián xiàn", "ipa": "tɕʰjɛn˧˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "战士们在前线打了很多天仗。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸年轻时去过前线当兵。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前线的战士很需要食物和药。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们坐车把药送到了前线。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前线离敌人很近，晚上常有枪声。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前线的战士给家里写了一封信。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争开始了，他决定上前线。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天都在想前线的儿子。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前线传来了好消息，我们赢了。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们在前线守着这座山。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前線", "label": "繁体"}, {"form": "前线指挥部", "label": "复合"}], "register": "中性", "sense_fingerprint": "战争中离敌人最近的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f23e8f5-926c-4e66-9efb-f790437fb09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95153, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前线", "is_correct": true, "explanation": "前线：指战争中离敌人最近的地方，与所听到的读音一致。"}, {"text": "前向", "is_correct": false, "explanation": "xiàng 与 xiàn 韵母不同（ang／an），前向意思是“朝前”，不指战争中的地方。"}, {"text": "全线", "is_correct": false, "explanation": "quán 与 qián 的介音不同（u／i），全线意思是“整条战线”，不是“前线”。"}, {"text": "前嫌", "is_correct": false, "explanation": "xián 与 xiàn 只差声调（阳平／去声），前嫌意思是“以前的怨恨”，与战争中的地方无关。"}], "explanations": {"前线": "前线：指战争中离敌人最近的地方，与所听到的读音一致。", "前向": "xiàng 与 xiàn 韵母不同（ang／an），前向意思是“朝前”，不指战争中的地方。", "全线": "quán 与 qián 的介音不同（u／i），全线意思是“整条战线”，不是“前线”。", "前嫌": "xián 与 xiàn 只差声调（阳平／去声），前嫌意思是“以前的怨恨”，与战争中的地方无关。"}, "sentence_index": null, "correct_answer": "前线"}, "level_3": {"options": [{"text": "前线", "is_correct": true, "explanation": "前线：指战争中离敌人最近的地方，与“战士们在……打仗”的句意相符。"}, {"text": "课堂", "is_correct": false, "explanation": "语义：课堂是教学的地方，与“打了很多天仗”的句意不符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是作战的地方，与“打了很多天仗”的句意相矛盾。"}, {"text": "图书馆", "is_correct": false, "explanation": "搭配：“打仗”不能在图书馆进行，与句中的动作搭配不当。"}], "explanations": {"前线": "前线：指战争中离敌人最近的地方，与“战士们在……打仗”的句意相符。", "课堂": "语义：课堂是教学的地方，与“打了很多天仗”的句意不符。", "厨房": "语义：厨房不是作战的地方，与“打了很多天仗”的句意相矛盾。", "图书馆": "搭配：“打仗”不能在图书馆进行，与句中的动作搭配不当。"}, "sentence_index": 0, "correct_answer": "前线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车站的前线有一个红绿灯。", "explanation": "这里应该用〈前方〉。前线只指战争中离敌人最近的地方，车站的位置要用〈前方〉。"}, {"text": "这栋楼的前线很宽，适合停车。", "explanation": "这里应该用〈前面〉。前线只指战争中离敌人最近的地方，建筑物的正面要用〈前面〉。"}, {"text": "剧场的前线坐满了观众。", "explanation": "这里应该用〈前排〉。前线指战争中的第一线，剧场座位的前排要用〈前排〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95153, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前线", "is_correct": true, "explanation": "前线：指战争中离敌人最近的地方，与“战争开始了，他决定去……”的句意相符。"}, {"text": "讲台", "is_correct": false, "explanation": "语义：战争开始后决定“上讲台”，与句意不相容。"}, {"text": "田野", "is_correct": false, "explanation": "搭配：“上”与“田野”搭配别扭，且与战争开始的语境不符。"}, {"text": "考场", "is_correct": false, "explanation": "语义：战争开始后决定去考场，与句中的战争语境不符。"}], "explanations": {"前线": "前线：指战争中离敌人最近的地方，与“战争开始了，他决定去……”的句意相符。", "讲台": "语义：战争开始后决定“上讲台”，与句意不相容。", "田野": "搭配：“上”与“田野”搭配别扭，且与战争开始的语境不符。", "考场": "语义：战争开始后决定去考场，与句中的战争语境不符。"}, "sentence_index": 6, "correct_answer": "前线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "楼梯的前线很陡，老人走得很慢。", "explanation": "这里应该用〈前部〉。前线只指战争中的第一线，楼梯的前面部分要用〈前部〉。"}, {"text": "这件衣服的前线有一道裂缝。", "explanation": "这里应该用〈前襟〉。前线只指战争中的第一线，衣服的前面部分要用〈前襟〉。"}, {"text": "我们在学校的前线踢足球。", "explanation": "这里应该用〈操场〉。前线指战争中的第一线，不指场地，踢足球要在〈操场〉上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95153, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在前线回来了。", "corrected_sentence": "他从前线回来了。", "error_description": "错误：“在前线”；正确：“从前线”。回来的起点要用介词“从”引出，“在”表示处所，不能用来表示起点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95153, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们被派前线去了。", "corrected_sentence": "他们被派到前线去了。", "error_description": "错误：“被派前线去”；正确：“被派到前线去”。表示派往的地点要用介词引出（如“派到”“派往”），缺少介词，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
