INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95154, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "作战时靠近敌方的第一线。", "primary_collocate": null, "pronunciation": "qián xiàn", "ipa": "tɕʰjɛn˧˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他们的部队已经到了前线，正准备进攻。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前线的炮声一夜没有停。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军亲自来到前线看士兵。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前线和后方只隔着一条河。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前线的路很难走，车开不过去。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院就在离前线不远的地方。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把受伤的战士从前线带回了后方。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说前线很危险，奶奶一直担心。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前线的士兵吃不上热饭。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，他再也没回过前线。", "target_word": "前线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前線", "label": "繁体"}, {"form": "前线指挥部", "label": "复合"}], "register": "中性", "sense_fingerprint": "作战时靠近敌方的第一线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f23e8f5-926c-4e66-9efb-f790437fb09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95154, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前线", "is_correct": true, "explanation": "前线：作战时靠近敌方的第一线，与所听到的读音一致。"}, {"text": "前向", "is_correct": false, "explanation": "xiàng 与 xiàn 韵母不同（ang／an），前向意思是“朝前”，不指第一线。"}, {"text": "全线", "is_correct": false, "explanation": "quán 与 qián 的介音不同（u／i），全线意思是“整条线”，不是“前线”。"}, {"text": "前嫌", "is_correct": false, "explanation": "xián 与 xiàn 只差声调，前嫌意思是“以前的怨恨”，不指第一线。"}], "explanations": {"前线": "前线：作战时靠近敌方的第一线，与所听到的读音一致。", "前向": "xiàng 与 xiàn 韵母不同（ang／an），前向意思是“朝前”，不指第一线。", "全线": "quán 与 qián 的介音不同（u／i），全线意思是“整条线”，不是“前线”。", "前嫌": "xián 与 xiàn 只差声调，前嫌意思是“以前的怨恨”，不指第一线。"}, "sentence_index": null, "correct_answer": "前线"}, "level_3": {"options": [{"text": "前线", "is_correct": true, "explanation": "前线：作战时靠近敌方的第一线，与“部队已经到了……”的句意相符。"}, {"text": "银行", "is_correct": false, "explanation": "语义：部队不会“到了”银行，这与作战的语境不符。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市不是作战的地方，与“部队已经到了”的句意相矛盾。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“部队”与“教室”搭配别扭，句子读起来不自然。"}], "explanations": {"前线": "前线：作战时靠近敌方的第一线，与“部队已经到了……”的句意相符。", "银行": "语义：部队不会“到了”银行，这与作战的语境不符。", "超市": "语义：超市不是作战的地方，与“部队已经到了”的句意相矛盾。", "教室": "搭配：“部队”与“教室”搭配别扭，句子读起来不自然。"}, "sentence_index": 0, "correct_answer": "前线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子的前线停着一辆车。", "explanation": "这里应该用〈前方〉。停车的位置要用〈前方〉，前线只指作战时靠近敌方的第一线。"}, {"text": "我们班的前线坐着一位同学。", "explanation": "这里应该用〈前排〉。教室里排在前面的座位要用〈前排〉，前线只指作战时靠近敌方的第一线。"}, {"text": "这个盒子的前线印着一只猫。", "explanation": "这里应该用〈正面〉。盒子的表面要用〈正面〉，前线只指作战时靠近敌方的第一线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前线", "is_correct": true, "explanation": "前线：作战时靠近敌方的第一线，与“医生把战士从……带回了后方”的句意相符。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：受伤的战士不会从幼儿园带回后方，与句中的战争语境不符。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场与受伤战士、后方的语境完全不相容。"}, {"text": "书店", "is_correct": false, "explanation": "搭配：“带回后方”与“书店”搭配不当，句子读起来不通。"}], "explanations": {"前线": "前线：作战时靠近敌方的第一线，与“医生把战士从……带回了后方”的句意相符。", "幼儿园": "语义：受伤的战士不会从幼儿园带回后方，与句中的战争语境不符。", "菜市场": "语义：菜市场与受伤战士、后方的语境完全不相容。", "书店": "搭配：“带回后方”与“书店”搭配不当，句子读起来不通。"}, "sentence_index": 6, "correct_answer": "前线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的前线坏了。", "explanation": "这里应该用〈前腿〉。椅子前面的两条腿要用〈前腿〉，前线只指作战时靠近敌方的第一线。"}, {"text": "桌子的前线摆满了书。", "explanation": "这里应该用〈前边〉。桌子前面的位置要用〈前边〉，前线只指作战时靠近敌方的第一线。"}, {"text": "讲台的前线放着一杯水。", "explanation": "这里应该用〈前部〉。讲台的前面部分要用〈前部〉，前线只指作战时靠近敌方的第一线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "部队昨天到了在前线。", "corrected_sentence": "部队昨天到了前线。", "error_description": "错误：“到了在前线”；正确：“到了前线”。“到”后面直接接地点，不能再加“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "连长把伤员前线送到了后方。", "corrected_sentence": "连长把伤员从前线送到了后方。", "error_description": "错误：“前线送到”；正确：“从前线送到”。表示起点要用介词“从”引出，缺少“从”，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
