INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95155, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "汇率是一个国家的钱换另一个国家的钱的比例。", "primary_collocate": null, "pronunciation": "huì lǜ", "ipa": "xweɪ˥˩ ly˥˩", "syllable_count": 2, "sentences": [{"text": "今天的汇率是一美元换七块钱。", "target_word": "汇率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汇率每天都在变化。", "target_word": "汇率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国前我先看了看汇率。", "target_word": "汇率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行门口写着今天的汇率。", "target_word": "汇率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民币的汇率上升了，出国旅游更便宜了。", "target_word": "汇率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想按今天的汇率换一千块钱。", "target_word": "汇率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道美元的汇率是多少吗？", "target_word": "汇率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汇率不同，换到的钱也不同。", "target_word": "汇率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行的时候，我用手机查汇率。", "target_word": "汇率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家的汇率每天都不一样。", "target_word": "汇率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外汇汇率", "label": "复合"}], "register": "中性", "sense_fingerprint": "两国的钱互相兑换的比例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f23e8f5-926c-4e66-9efb-f790437fb09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95155, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "汇率", "is_correct": true, "explanation": "正确答案：汇率 huìlǜ，指两国货币互相兑换的比率。"}, {"text": "贿赂", "is_correct": false, "explanation": "lù（第四声）与 lǜ（第四声）韵母不同（u 与 ü），意思是贿赂。"}, {"text": "税率", "is_correct": false, "explanation": "shuì 与 huì 声母不同（sh 与 h），意思是税率。"}, {"text": "翠绿", "is_correct": false, "explanation": "cuì 与 huì 声母不同（c 与 h），意思是翠绿色。"}, {"text": "灰绿", "is_correct": false, "explanation": "huī（第一声）与 huì（第四声）声调不同，意思是灰绿色。"}], "explanations": {"汇率": "正确答案：汇率 huìlǜ，指两国货币互相兑换的比率。", "贿赂": "lù（第四声）与 lǜ（第四声）韵母不同（u 与 ü），意思是贿赂。", "税率": "shuì 与 huì 声母不同（sh 与 h），意思是税率。", "翠绿": "cuì 与 huì 声母不同（c 与 h），意思是翠绿色。", "灰绿": "huī（第一声）与 huì（第四声）声调不同，意思是灰绿色。"}, "sentence_index": null, "correct_answer": "汇率"}, "level_3": {"options": [{"text": "汇率", "is_correct": true, "explanation": "正确：汇率指一美元换七块钱这类两种货币的兑换比率，与句中的“换”相符。"}, {"text": "利率", "is_correct": false, "explanation": "语义：利率指存款或借款的利息比例，不表示货币之间的兑换比率。"}, {"text": "物价", "is_correct": false, "explanation": "搭配：“换”要搭配货币或兑换比率，“物价”说的是商品价格水平，不能这样用。"}, {"text": "人民币", "is_correct": false, "explanation": "语义：人民币是货币本身，不是比率，不能作“今天的……是一美元换七块钱”的主语。"}], "explanations": {"汇率": "正确：汇率指一美元换七块钱这类两种货币的兑换比率，与句中的“换”相符。", "利率": "语义：利率指存款或借款的利息比例，不表示货币之间的兑换比率。", "物价": "搭配：“换”要搭配货币或兑换比率，“物价”说的是商品价格水平，不能这样用。", "人民币": "语义：人民币是货币本身，不是比率，不能作“今天的……是一美元换七块钱”的主语。"}, "sentence_index": 0, "correct_answer": "汇率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "银行把定期存款的汇率提高了。", "explanation": "这里应该用〈利率〉。汇率指货币兑换的比例，存款的收益比例要用利率。"}, {"text": "男生和女生的汇率是三比二。", "explanation": "这里应该用〈比率〉。汇率只用于不同货币之间的兑换，人数之间的比例要用比率。"}, {"text": "这件衣服的汇率是两百块。", "explanation": "这里应该用〈价格〉。汇率是货币之间的兑换比例，不能用来说商品的售价，售价要用价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95155, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汇率", "is_correct": true, "explanation": "正确：汇率指美元兑换其他货币的比率，问“是多少”正合适。"}, {"text": "股价", "is_correct": false, "explanation": "语义：股价是股票的价格，美元不是股票，不能说“美元的股价”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不是可以用“是多少”来问的数值，不能说“美元的天气”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是数量，美元没有可以问“是多少”的颜色。"}], "explanations": {"汇率": "正确：汇率指美元兑换其他货币的比率，问“是多少”正合适。", "股价": "语义：股价是股票的价格，美元不是股票，不能说“美元的股价”。", "天气": "搭配：“天气”不是可以用“是多少”来问的数值，不能说“美元的天气”。", "颜色": "语义：颜色不是数量，美元没有可以问“是多少”的颜色。"}, "sentence_index": 6, "correct_answer": "汇率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的汇率是百分之二十五。", "explanation": "这里应该用〈税率〉。汇率是货币兑换的比例，公司应缴税款的比例要用税率，不能说“汇率”。"}, {"text": "我在银行买了一些汇率。", "explanation": "这里应该用〈外汇〉。外汇是外国货币本身，可以买卖；汇率只是比例，不能买。"}, {"text": "这笔存款每年给我带来一些汇率。", "explanation": "这里应该用〈利息〉。汇率是两种货币的兑换比例，不是存款带来的收益。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95155, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月的汇率比上个月很高。", "corrected_sentence": "这个月的汇率比上个月高。", "error_description": "错误：“比上个月很高”；正确：“比上个月高”。用“比”比较汇率时，形容词前不能加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95155, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把汇率换了一些钱。", "corrected_sentence": "我按汇率换了一些钱。", "error_description": "“汇率”不能作“把”的宾语被“换”，此处应用“按”引出依据，正确说法是“按汇率换了一些钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
