INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95157, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "去路是要走过去的路。", "primary_collocate": null, "pronunciation": "qù lù", "ipa": "tɕʰy˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "我们不知道去路在哪里，只好停下来看地图。", "target_word": "去路", "complexity_tier": "T3", "furigana": "wǒ men bù zhī dào qù lù zài nǎ lǐ, zhǐ hǎo tíng xià lái kàn dì tú", "sentence_source": "generated"}, {"text": "地图上画着来路和去路。", "target_word": "去路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来路已经看不见了，去路还很远。", "target_word": "去路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们回头看了看来路，又望向前面的去路。", "target_word": "去路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里有两条小路，哪一条才是去路呢？", "target_word": "去路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人指着前面说：“那就是你们的去路。”", "target_word": "去路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪太大，来路和去路都分不清了。", "target_word": "去路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小路是去路，那条是回来的路。", "target_word": "去路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在路口，看着前面的去路发呆。", "target_word": "去路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿着去路走，有一座小桥，过桥就到村子了。", "target_word": "去路", "complexity_tier": "T3", "furigana": "yán zhe qù lù zǒu, yǒu yí zuò xiǎo qiáo, guò qiáo jiù dào cūn zi le", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "要去的方向上的路，与来路相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcd4018f-a1c8-4a3f-b92d-7f066eb0ba12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95157, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "去路", "is_correct": true, "explanation": "去路：要走过去的路，句中说不知道它在哪里，句意通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的属性，不是能找到位置的东西。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法是语言的规则，不是能找到位置的东西。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是内心的感受，不是能找到位置的东西。"}], "explanations": {"去路": "去路：要走过去的路，句中说不知道它在哪里，句意通顺。", "颜色": "语义：颜色是事物的属性，不是能找到位置的东西。", "语法": "语义：语法是语言的规则，不是能找到位置的东西。", "心情": "语义：心情是内心的感受，不是能找到位置的东西。"}, "sentence_index": 0, "correct_answer": "去路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们沿着去路回去，就能找到营地。", "explanation": "这里应该用〈来路〉。回去要沿来路走；去路指要前往的路，与来路相对。"}, {"text": "我们在雪地里走过一片去路。", "explanation": "这里应该用〈条〉。去路用“条”量，“片”用于雪地、树叶等平面的东西，不用于道路。"}, {"text": "这篇论文的去路很清楚，作者一步步论证了结论。", "explanation": "这里应该用〈思路〉。思路指思考问题的条理，去路指要走过去的路，不能用来说论文的论证条理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95157, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "去路", "is_correct": true, "explanation": "去路：与来路相对的前行之路，句中“来路和去路都分不清”，句意通顺。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄与路的走向无关，不能和来路并列说分不清。"}, {"text": "路灯", "is_correct": false, "explanation": "语义：路灯是路边的设施，不是可以分辨的路径，与“来路”不相称。"}, {"text": "答案", "is_correct": false, "explanation": "搭配：“分不清”不接“答案”，应说“不知道答案”。"}], "explanations": {"去路": "去路：与来路相对的前行之路，句中“来路和去路都分不清”，句意通顺。", "年龄": "语义：年龄与路的走向无关，不能和来路并列说分不清。", "路灯": "语义：路灯是路边的设施，不是可以分辨的路径，与“来路”不相称。", "答案": "搭配：“分不清”不接“答案”，应说“不知道答案”。"}, "sentence_index": 6, "correct_answer": "去路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈说，他的去路很有条理，做事总是一步一步来。", "explanation": "这里应该用〈思路〉。思路指思考问题的条理，去路指要前往的道路，不能用来说人的条理。"}, {"text": "这张去路很长，我们走了一下午。", "explanation": "这里应该用〈条〉。去路用“条”量，“张”用于纸、桌子等平面的东西，不用于道路。"}, {"text": "这座楼的去路在东边，从那里可以出去。", "explanation": "这里应该用〈出口〉。出口指建筑的出入处，去路指要走过去的路，不能用来说楼的出口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95157, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在岔路口辨认了一下，选了一座去路。", "corrected_sentence": "我们在岔路口辨认了一下，选了一条去路。", "error_description": "“去路”的量词应为“条”，“座”用于桥、山等大型物体，不用于道路。错误形式是“一座去路”，正确形式是“一条去路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95157, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪太大，我们终于找到了一片去路，慢慢走出了山林。", "corrected_sentence": "雪太大，我们终于找到了一条去路，慢慢走出了山林。", "error_description": "“去路”的量词应为“条”，“片”多用于平面的东西，不用于道路。错误形式是“一片去路”，正确形式是“一条去路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
