INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95159, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "吧女是酒吧里做事的女人。", "primary_collocate": null, "pronunciation": "bā nǚ", "ipa": "pa⁵⁵ ny²¹⁴", "syllable_count": 2, "sentences": [{"text": "她十八岁就去酒吧当吧女了。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吧女每天晚上七点上班。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位吧女的歌唱得很好听。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的吧女活得很不容易。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吧女把酒放在桌子上。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的姐姐做过吧女，吃了不少苦。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒吧里有一个新来的吧女。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人想点酒，就叫吧女过来。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒吧有五位吧女。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当吧女挣钱养家。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "口语", "sense_fingerprint": "酒吧里做事的女人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c21081-19c8-4e43-9122-d082b2713663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95159, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吧女", "is_correct": true, "explanation": "正确：吧女指酒吧里做事的女人，与“去酒吧当”相符。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生在医院工作，不会去酒吧当医生，与“酒吧”冲突。"}, {"text": "教师", "is_correct": false, "explanation": "语义：教师在学校工作，与“去酒吧”冲突。"}, {"text": "柜台", "is_correct": false, "explanation": "搭配：“当”后接的是人的身份或职业，“柜台”是物，不能说“当柜台”。"}], "explanations": {"吧女": "正确：吧女指酒吧里做事的女人，与“去酒吧当”相符。", "医生": "语义：医生在医院工作，不会去酒吧当医生，与“酒吧”冲突。", "教师": "语义：教师在学校工作，与“去酒吧”冲突。", "柜台": "搭配：“当”后接的是人的身份或职业，“柜台”是物，不能说“当柜台”。"}, "sentence_index": 0, "correct_answer": "吧女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "餐厅的吧女手脚麻利，上菜很快。", "explanation": "这里应该用〈女服务员〉。“吧女”限于酒吧，餐厅里服务客人的女性要用〈女服务员〉。"}, {"text": "航班上的吧女递来了一条热毛巾。", "explanation": "这里应该用〈空姐〉。“吧女”限于酒吧，飞机上服务乘客的女性要用〈空姐〉。"}, {"text": "奶奶家的吧女每天负责打扫卫生。", "explanation": "这里应该用〈保姆〉。“吧女”不做家务，负责家里打扫卫生的人要用〈保姆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95159, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吧女", "is_correct": true, "explanation": "正确：吧女指酒吧里做事的女人，与“酒吧里有”相符。"}, {"text": "护士", "is_correct": false, "explanation": "语义：护士在医院工作，不会在酒吧里任职，与“酒吧里”冲突。"}, {"text": "法官", "is_correct": false, "explanation": "语义：法官在法院工作，与“酒吧里”冲突。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“新来的”只能说人，“歌曲”是物，不能“新来”，句意不通。"}], "explanations": {"吧女": "正确：吧女指酒吧里做事的女人，与“酒吧里有”相符。", "护士": "语义：护士在医院工作，不会在酒吧里任职，与“酒吧里”冲突。", "法官": "语义：法官在法院工作，与“酒吧里”冲突。", "歌曲": "语义：“新来的”只能说人，“歌曲”是物，不能“新来”，句意不通。"}, "sentence_index": 6, "correct_answer": "吧女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家医院的吧女负责给病人换药。", "explanation": "这里应该用〈护士〉。“吧女”限于酒吧里陪客人的女性，给病人换药的人要用〈护士〉。"}, {"text": "这家公司的吧女负责替老板写报告。", "explanation": "这里应该用〈秘书〉。“吧女”限于酒吧，替老板处理文件、写报告的人要用〈秘书〉。"}, {"text": "这所学校的吧女每天给学生上数学课。", "explanation": "这里应该用〈老师〉。“吧女”限于酒吧，给学生上课的人要用〈老师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95159, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几个吧女们都很年轻。", "corrected_sentence": "这几个吧女都很年轻。", "error_description": "词缀错误：“们”表示复数，与数量词“几个”同用是重复，应去掉“们”，写作“这几个吧女”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95159, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是一头吧女，每天很努力。", "corrected_sentence": "她是一位吧女，每天很努力。", "error_description": "量词错误：“头”用于大牲畜，指人的吧女应该用“位”，写作“一位吧女”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
