INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95160, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在酒吧里陪客人或服务的女性。", "primary_collocate": null, "pronunciation": "bā nǚ", "ipa": "pa⁵⁵ ny²¹⁴", "syllable_count": 2, "sentences": [{"text": "她以前在酒吧当吧女。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家酒吧的吧女很年轻。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吧女给客人倒了一杯酒。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影里有一个吧女，人很善良。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做过两年吧女，后来开了小店。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上吧女很忙，要到很晚才下班。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在酒吧认识了一位吧女。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吧女笑着问我们想喝什么。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板请了三个吧女。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想一直当吧女，想学做饭。", "target_word": "吧女", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "口语", "sense_fingerprint": "在酒吧里陪客人或服务的女性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c21081-19c8-4e43-9122-d082b2713663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95160, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吧女", "is_correct": true, "explanation": "正确：吧女指在酒吧里陪客人的女性，与“酒吧”和“当”相符。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师在学校教书，不在酒吧工作，与“酒吧”冲突。"}, {"text": "护士", "is_correct": false, "explanation": "语义：护士在医院工作，不会在酒吧当护士，与“酒吧”冲突。"}, {"text": "柜台", "is_correct": false, "explanation": "搭配：“当”后接的是人的身份或职业，“柜台”是物，不能说“当柜台”。"}], "explanations": {"吧女": "正确：吧女指在酒吧里陪客人的女性，与“酒吧”和“当”相符。", "老师": "语义：老师在学校教书，不在酒吧工作，与“酒吧”冲突。", "护士": "语义：护士在医院工作，不会在酒吧当护士，与“酒吧”冲突。", "柜台": "搭配：“当”后接的是人的身份或职业，“柜台”是物，不能说“当柜台”。"}, "sentence_index": 0, "correct_answer": "吧女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "饭店里的吧女手脚麻利，帮我们点菜很快。", "explanation": "这里应该用〈女服务员〉。“吧女”限于酒吧里陪客人的女性，饭店里招待客人的女性要用〈女服务员〉。"}, {"text": "火车上的吧女端来了一杯热茶。", "explanation": "这里应该用〈女招待〉。“吧女”限于酒吧，火车上服务乘客的女性要用〈女招待〉。"}, {"text": "我家的吧女每天做饭打扫。", "explanation": "这里应该用〈保姆〉。“吧女”指酒吧里陪客人的女性，不负责家务，料理家里的事要用〈保姆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吧女", "is_correct": true, "explanation": "正确：吧女指在酒吧里陪客人的女性，与“在酒吧认识”相符。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：小学生年龄小，不去酒吧，与“在酒吧”冲突。"}, {"text": "和尚", "is_correct": false, "explanation": "语义：和尚出家修行，与“酒吧”的场景冲突，句子不合。"}, {"text": "啤酒", "is_correct": false, "explanation": "语义：“啤酒”是饮料，不能被“认识”，也不能用量词“位”。"}], "explanations": {"吧女": "正确：吧女指在酒吧里陪客人的女性，与“在酒吧认识”相符。", "小学生": "语义：小学生年龄小，不去酒吧，与“在酒吧”冲突。", "和尚": "语义：和尚出家修行，与“酒吧”的场景冲突，句子不合。", "啤酒": "语义：“啤酒”是饮料，不能被“认识”，也不能用量词“位”。"}, "sentence_index": 6, "correct_answer": "吧女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医院里的吧女正在给病人打针。", "explanation": "这里应该用〈护士〉。“吧女”限于酒吧里陪客人的女性，在医院给病人打针的人要用〈护士〉。"}, {"text": "工厂车间里的吧女正在修理机器。", "explanation": "这里应该用〈工人〉。“吧女”限于酒吧，在车间修理机器的人要用〈工人〉。"}, {"text": "出租车上的吧女开车把我们送到了机场。", "explanation": "这里应该用〈司机〉。“吧女”限于酒吧，开出租车载客的人要用〈司机〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她每天晚上当过吧女。", "corrected_sentence": "她每天晚上当吧女。", "error_description": "体标错误：“过”表示曾经有过的经历，不能与表示经常性的“每天晚上”同用，应去掉“过”，写作“她每天晚上当吧女”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我朋友曾经是一把吧女。", "corrected_sentence": "我朋友曾经是一位吧女。", "error_description": "量词错误：“把”用于有柄的器具，指人的吧女应该用“位”，写作“一位吧女”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b83f946-df0e-467f-a33a-2a1595f530b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
