INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95162, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向法院控告某人，提起诉讼。", "primary_collocate": null, "pronunciation": "gào", "ipa": "kau˥˩", "syllable_count": 1, "sentences": [{"text": "他去法院告了那家公司。", "target_word": "告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居把我们家告到了法院。", "target_word": "告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她请律师告那个骗子。", "target_word": "告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他欠了钱不还，我只好去告他。", "target_word": "告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们一起告了老板，因为他不给工资。", "target_word": "告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家商店卖假货，客人把它告了。", "target_word": "告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没有告过别人。", "target_word": "告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们告我偷了东西，可是我没有偷。", "target_word": "告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事太小了，你不用去法院告他。", "target_word": "告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想告医院，但是律师说证据不够。", "target_word": "告", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "告了", "label": "体标"}, {"form": "告过", "label": "体标"}], "register": "中性", "sense_fingerprint": "向法院控告某人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '432c6f3e-dab6-42df-a5ff-3707d97e69dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95162, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "告", "is_correct": true, "explanation": "告（gào）：向法院控告某人，是本词的意思。"}, {"text": "高", "is_correct": false, "explanation": "gāo（第一声）与 gào（第四声）声调不同，意思是高。"}, {"text": "搞", "is_correct": false, "explanation": "gǎo（第三声）与 gào（第四声）声调不同，意思是做、弄。"}, {"text": "靠", "is_correct": false, "explanation": "kào 与 gào 声母不同（k 与 g），意思是靠近、依靠。"}, {"text": "到", "is_correct": false, "explanation": "dào 与 gào 声母不同（d 与 g），意思是到达。"}, {"text": "号", "is_correct": false, "explanation": "hào 与 gào 声母不同（h 与 g），意思是号码、名号。"}], "explanations": {"告": "告（gào）：向法院控告某人，是本词的意思。", "高": "gāo（第一声）与 gào（第四声）声调不同，意思是高。", "搞": "gǎo（第三声）与 gào（第四声）声调不同，意思是做、弄。", "靠": "kào 与 gào 声母不同（k 与 g），意思是靠近、依靠。", "到": "dào 与 gào 声母不同（d 与 g），意思是到达。", "号": "hào 与 gào 声母不同（h 与 g），意思是号码、名号。"}, "sentence_index": null, "correct_answer": "告"}, "level_3": {"options": [{"text": "告", "is_correct": true, "explanation": "告：此处表示向法院控告，“去法院告了那家公司”即起诉该公司。"}, {"text": "赔", "is_correct": false, "explanation": "配价：“赔”要带所赔的内容或对象（赔钱、赔给某人），不能直接以“那家公司”作宾语。"}, {"text": "谢", "is_correct": false, "explanation": "语义：“谢”是感谢，与“去法院”的诉讼语境不符，不能说去法院感谢那家公司。"}, {"text": "拜", "is_correct": false, "explanation": "语义：“拜”是拜访、行礼，与“去法院”的诉讼语境不符，不能说去法院拜那家公司。"}], "explanations": {"告": "告：此处表示向法院控告，“去法院告了那家公司”即起诉该公司。", "赔": "配价：“赔”要带所赔的内容或对象（赔钱、赔给某人），不能直接以“那家公司”作宾语。", "谢": "语义：“谢”是感谢，与“去法院”的诉讼语境不符，不能说去法院感谢那家公司。", "拜": "语义：“拜”是拜访、行礼，与“去法院”的诉讼语境不符，不能说去法院拜那家公司。"}, "sentence_index": 0, "correct_answer": "告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一进门就告了我一身泥。", "explanation": "这里应该用〈弄〉。“告”没有弄脏的意思，弄脏身上要用“弄”。"}, {"text": "老师看到他迟到，就把他告了一顿。", "explanation": "这里应该用〈训〉。“告”没有责备、训斥的意思，骂人要说“训了一顿”。"}, {"text": "他收到礼物后，向每位老师告了歉。", "explanation": "这里应该用〈道歉〉。“告”不能和“歉”搭配，表示道歉要说“道歉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95162, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "告", "is_correct": true, "explanation": "告（gào）：向法院控告某人，是本词的意思。"}, {"text": "稿", "is_correct": false, "explanation": "gǎo（第三声）与 gào（第四声）声调不同，意思是稿件。"}, {"text": "膏", "is_correct": false, "explanation": "gāo（第一声）与 gào（第四声）声调不同，意思是膏状物，如牙膏。"}, {"text": "道", "is_correct": false, "explanation": "dào 与 gào 声母不同（d 与 g），意思是道路。"}, {"text": "盖", "is_correct": false, "explanation": "gài 与 gào 韵母不同（ai 与 ao），意思是覆盖、盖子。"}], "explanations": {"告": "告（gào）：向法院控告某人，是本词的意思。", "稿": "gǎo（第三声）与 gào（第四声）声调不同，意思是稿件。", "膏": "gāo（第一声）与 gào（第四声）声调不同，意思是膏状物，如牙膏。", "道": "dào 与 gào 声母不同（d 与 g），意思是道路。", "盖": "gài 与 gào 韵母不同（ai 与 ao），意思是覆盖、盖子。"}, "sentence_index": null, "correct_answer": "告"}, "level_3": {"options": [{"text": "告", "is_correct": true, "explanation": "告：此处表示向法院控告，“从来没有告过别人”指从未起诉过别人。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的宾语应是食物，不能说吃别人，与句意不符。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，后面不能直接带“别人”作宾语。"}, {"text": "飞", "is_correct": false, "explanation": "配价：“飞”是不及物动词，不能带人作宾语，“飞过别人”说不通。"}], "explanations": {"告": "告：此处表示向法院控告，“从来没有告过别人”指从未起诉过别人。", "吃": "语义：“吃”的宾语应是食物，不能说吃别人，与句意不符。", "哭": "配价：“哭”是不及物动词，后面不能直接带“别人”作宾语。", "飞": "配价：“飞”是不及物动词，不能带人作宾语，“飞过别人”说不通。"}, "sentence_index": 6, "correct_answer": "告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他觉得那份合同有问题，就去告它。", "explanation": "搭配：“告”控告的对象应是人或单位，不能用来控告一份合同。"}, {"text": "这家饭店的菜太难吃了，我想去告这些菜。", "explanation": "搭配：“告”控告的对象必须是人或单位，不能用来控告食物。"}, {"text": "我的手机坏了，我要去告它。", "explanation": "搭配：手机是物品，不能作为“告”的对象，“告”只能用于控告人或单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那家商店告了上法院。", "corrected_sentence": "他把那家商店告上了法院。", "error_description": "补语位置错误：“告上法院”中的“上”是结果补语，“了”应放在“告上”之后，应说“告上了法院”，不能说“告了上法院”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们从来没有告了那家银行。", "corrected_sentence": "我们从来没有告过那家银行。", "error_description": "体标错误：表示从未有过的经历时，“没有”后应接“过”，不能用“了”，应说“从来没有告过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
