INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95163, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "哎是惊讶或叫人时发出的声音。", "primary_collocate": null, "pronunciation": "āi", "ipa": "ai˥", "syllable_count": 1, "sentences": [{"text": "哎，你等一下，我有话对你说。", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，老王，你要去哪儿？", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，这不是小李吗？好久不见！", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，你看，天上有一只大鸟。", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，我的手机呢？刚才还在这儿。", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，你怎么在这儿？我以为你回家了。", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，那个穿红衣服的同学，请过来一下。", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，这个字我好像见过。", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，下雪了！今年的雪来得真早。", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，服务员，请给我们一杯水。", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "哎呀", "label": "复合"}, {"form": "哎哟", "label": "复合"}], "register": "口语", "sense_fingerprint": "叫人或表示惊讶的叹词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '432c6f3e-dab6-42df-a5ff-3707d97e69dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95163, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "哎", "is_correct": true, "explanation": "哎（āi）：表示惊讶或叫人时发出的叹词，是本词的意思。"}, {"text": "矮", "is_correct": false, "explanation": "ǎi（第三声）与 āi（第一声）声调不同，意思是个子低。"}, {"text": "爱", "is_correct": false, "explanation": "ài（第四声）与 āi（第一声）声调不同，意思是喜爱。"}, {"text": "癌", "is_correct": false, "explanation": "ái（第二声）与 āi（第一声）声调不同，意思是癌症。"}], "explanations": {"哎": "哎（āi）：表示惊讶或叫人时发出的叹词，是本词的意思。", "矮": "ǎi（第三声）与 āi（第一声）声调不同，意思是个子低。", "爱": "ài（第四声）与 āi（第一声）声调不同，意思是喜爱。", "癌": "ái（第二声）与 āi（第一声）声调不同，意思是癌症。"}, "sentence_index": null, "correct_answer": "哎"}, "level_3": {"options": [{"text": "哎", "is_correct": true, "explanation": "哎：表示叫人，此处用于招呼对方等候，是本词的意思。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示惊叹，不用来招呼人等一下，与句意不符。"}, {"text": "啧啧", "is_correct": false, "explanation": "语义：“啧啧”表示赞叹或惋惜，不用来招呼人等一下。"}, {"text": "呸", "is_correct": false, "explanation": "语域：“呸”表示唾弃、轻蔑，语气粗鲁，不适合客气地请人等一下。"}], "explanations": {"哎": "哎：表示叫人，此处用于招呼对方等候，是本词的意思。", "哇": "语义：“哇”表示惊叹，不用来招呼人等一下，与句意不符。", "啧啧": "语义：“啧啧”表示赞叹或惋惜，不用来招呼人等一下。", "呸": "语域：“呸”表示唾弃、轻蔑，语气粗鲁，不适合客气地请人等一下。"}, "sentence_index": 0, "correct_answer": "哎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "哎，这道题我又算错了。", "explanation": "这里的“哎”表示懊恼，是另一种用法，不表示惊讶或招呼人。"}, {"text": "哎，真可惜，他没有考上大学。", "explanation": "这里的“哎”表示惋惜、叹息，是另一种用法，不表示惊讶或叫人。"}, {"text": "哎，你怎么又把钥匙忘在家里了？", "explanation": "这里的“哎”表示责备、不满，是另一种用法，不表示惊讶或招呼人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95163, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "哎", "is_correct": true, "explanation": "哎（āi）：表示惊讶或叫人时发出的叹词，是本词的意思。"}, {"text": "艾", "is_correct": false, "explanation": "ài（第四声）与 āi（第一声）声调不同，意思是艾草。"}, {"text": "安", "is_correct": false, "explanation": "ān 与 āi 韵母不同（an 与 ai），意思是平安。"}, {"text": "该", "is_correct": false, "explanation": "声母不同：gāi（该）比 āi 多一个声母 g，声调相同，意思是应该。"}], "explanations": {"哎": "哎（āi）：表示惊讶或叫人时发出的叹词，是本词的意思。", "艾": "ài（第四声）与 āi（第一声）声调不同，意思是艾草。", "安": "ān 与 āi 韵母不同（an 与 ai），意思是平安。", "该": "声母不同：gāi（该）比 āi 多一个声母 g，声调相同，意思是应该。"}, "sentence_index": null, "correct_answer": "哎"}, "level_3": {"options": [{"text": "哎", "is_correct": true, "explanation": "哎：表示叫人，此处用于客气地请人过来，是本词的意思。"}, {"text": "咦", "is_correct": false, "explanation": "语义：“咦”表示疑惑或惊奇，不用来招呼人过来。"}, {"text": "哼", "is_correct": false, "explanation": "语义：“哼”表示不屑或不满，与请人过来的客气语气不合。"}, {"text": "呃", "is_correct": false, "explanation": "语域：“呃”是迟疑时的语气词，口语中不用于招呼他人。"}], "explanations": {"哎": "哎：表示叫人，此处用于客气地请人过来，是本词的意思。", "咦": "语义：“咦”表示疑惑或惊奇，不用来招呼人过来。", "哼": "语义：“哼”表示不屑或不满，与请人过来的客气语气不合。", "呃": "语域：“呃”是迟疑时的语气词，口语中不用于招呼他人。"}, "sentence_index": 6, "correct_answer": "哎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "哎，这次又没考好，真让人失望。", "explanation": "这里的“哎”表示惋惜、失望，是另一种用法，不表示惊讶或叫人。"}, {"text": "哎，我早就说过这事不行，你偏不听。", "explanation": "这里的“哎”表示责备、不满，是另一种用法，不表示惊讶或叫人。"}, {"text": "哎，这个月的工资又花光了。", "explanation": "这里的“哎”表示懊恼、无奈，是另一种用法，不表示惊讶或叫人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95163, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "哎的，小王，你等一下。", "corrected_sentence": "哎，小王，你等一下。", "error_description": "叹词错误：“哎”是叹词，后面不能加“的”，应说“哎，小王”，不能说“哎的，小王”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95163, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的哎很响，抬起头来。", "corrected_sentence": "她哎了一声，抬起头来。", "error_description": "叹词错误：「哎」是叹词，不能像名词一样带「的」，「她的哎」不成立，应说「她哎了一声」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
