INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95164, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "表示不满或提醒的叹词。", "primary_collocate": null, "pronunciation": "āi", "ipa": "ai˥", "syllable_count": 1, "sentences": [{"text": "哎，你别碰那个杯子，很贵的。", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，说好七点见面，你怎么八点才来？", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，我不是说过了吗？不要再问了。", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，别走错了，是左边那条路。", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，你小声点，孩子在睡觉。", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，你怎么又把书放在地上了？", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，这样做不太好吧？", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，小心点，地上有水。", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，你又忘了带钥匙？", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎，我的话还没说完呢，你别走。", "target_word": "哎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "哎呀", "label": "复合"}, {"form": "哎哟", "label": "复合"}], "register": "口语", "sense_fingerprint": "表示不满或提醒的叹词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '432c6f3e-dab6-42df-a5ff-3707d97e69dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95164, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "哎", "is_correct": true, "explanation": "哎（āi）：表示不满或提醒的叹词，是本词的意思。"}, {"text": "矮", "is_correct": false, "explanation": "ǎi（第三声）与 āi（第一声）声调不同，意思是个子低。"}, {"text": "艾", "is_correct": false, "explanation": "ài（第四声）与 āi（第一声）声调不同，意思是艾草。"}, {"text": "癌", "is_correct": false, "explanation": "ái（第二声）与 āi（第一声）声调不同，意思是癌症。"}], "explanations": {"哎": "哎（āi）：表示不满或提醒的叹词，是本词的意思。", "矮": "ǎi（第三声）与 āi（第一声）声调不同，意思是个子低。", "艾": "ài（第四声）与 āi（第一声）声调不同，意思是艾草。", "癌": "ái（第二声）与 āi（第一声）声调不同，意思是癌症。"}, "sentence_index": null, "correct_answer": "哎"}, "level_3": {"options": [{"text": "哎", "is_correct": true, "explanation": "哎：表示提醒或制止，此处用于提醒对方别碰杯子，是本词的意思。"}, {"text": "咦", "is_correct": false, "explanation": "语义：“咦”表示疑惑或惊奇，不表示提醒对方别碰东西。"}, {"text": "呸", "is_correct": false, "explanation": "语域：“呸”表示唾弃，语气粗鲁，不适合温和地提醒他人。"}, {"text": "哦", "is_correct": false, "explanation": "语义：“哦”表示恍然或应答，不带提醒或制止的语气。"}], "explanations": {"哎": "哎：表示提醒或制止，此处用于提醒对方别碰杯子，是本词的意思。", "咦": "语义：“咦”表示疑惑或惊奇，不表示提醒对方别碰东西。", "呸": "语域：“呸”表示唾弃，语气粗鲁，不适合温和地提醒他人。", "哦": "语义：“哦”表示恍然或应答，不带提醒或制止的语气。"}, "sentence_index": 0, "correct_answer": "哎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "哎，来了，您稍等一下。", "explanation": "这里的“哎”是应声，表示答应，不表示惊讶、不满或提醒。"}, {"text": "哎，李阿姨，您要去买菜吗？", "explanation": "这里的“哎”用来招呼人，是叫人的用法，不表示提醒或不满。"}, {"text": "“小王！”“哎，我在这儿呢。”", "explanation": "这里的“哎”是应答，表示答应，不表示不满或提醒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95164, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "哎", "is_correct": true, "explanation": "哎（āi）：表示不满或提醒的叹词，是本词的意思。"}, {"text": "爱", "is_correct": false, "explanation": "ài（第四声）与 āi（第一声）声调不同，意思是喜爱。"}, {"text": "安", "is_correct": false, "explanation": "ān 与 āi 韵母不同（an 与 ai），意思是平安。"}, {"text": "癌", "is_correct": false, "explanation": "ái（第二声）与 āi（第一声）声调不同，意思是癌症。"}], "explanations": {"哎": "哎（āi）：表示不满或提醒的叹词，是本词的意思。", "爱": "ài（第四声）与 āi（第一声）声调不同，意思是喜爱。", "安": "ān 与 āi 韵母不同（an 与 ai），意思是平安。", "癌": "ái（第二声）与 āi（第一声）声调不同，意思是癌症。"}, "sentence_index": null, "correct_answer": "哎"}, "level_3": {"options": [{"text": "哎", "is_correct": true, "explanation": "哎：表示委婉的不满或劝阻，此处用于说这样做不太好，是本词的意思。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示惊叹，不表示委婉劝阻。"}, {"text": "嘻嘻", "is_correct": false, "explanation": "语义：“嘻嘻”是笑声，不用来委婉地表示不满或劝阻。"}, {"text": "呃", "is_correct": false, "explanation": "语域：“呃”是迟疑的语气词，不用作直接表达劝阻的开头。"}], "explanations": {"哎": "哎：表示委婉的不满或劝阻，此处用于说这样做不太好，是本词的意思。", "哇": "语义：“哇”表示惊叹，不表示委婉劝阻。", "嘻嘻": "语义：“嘻嘻”是笑声，不用来委婉地表示不满或劝阻。", "呃": "语域：“呃”是迟疑的语气词，不用作直接表达劝阻的开头。"}, "sentence_index": 6, "correct_answer": "哎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "尊敬的各位嘉宾，哎，感谢大家今天的到场。", "explanation": "语域：“哎”是随意的口语叹词，在正式致辞中用它很不得体。"}, {"text": "“老陈，吃饭了！”“哎，马上来。”", "explanation": "这里的“哎”是应声，表示答应，不表示不满或提醒。"}, {"text": "敬爱的老师：哎，我最近身体很好，谢谢您。", "explanation": "语域：“哎”是口语叹词，书信开头一般不用，不符合书面语的写法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
