INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哎的，老刘，你怎么又忘带钥匙了？", "corrected_sentence": "哎，老刘，你怎么又忘带钥匙了？", "error_description": "叹词错误：“哎”后面不能加“的”，应说“哎，老刘”，不能说“哎的，老刘”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
