INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95166, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95166, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "饮用含酒精的饮料。", "primary_collocate": null, "pronunciation": "hē jiǔ", "ipa": "xɤ˥ tɕjou˨˩", "syllable_count": 2, "sentences": [{"text": "开车的人不能喝酒。", "target_word": "喝酒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说他的胃不好，不要喝酒。", "target_word": "喝酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喝酒喝得脸很红。", "target_word": "喝酒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天晚上都喝酒，喝完就睡觉。", "target_word": "喝酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春节时，爸爸和朋友一起喝酒。", "target_word": "喝酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他吃了药，今天不能喝酒。", "target_word": "喝酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酒吧里的人都在喝酒、唱歌。", "target_word": "喝酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌上有啤酒和花生，他们正在喝酒。", "target_word": "喝酒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喝酒以后很容易生气。", "target_word": "喝酒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请不要在上班时间喝酒。", "target_word": "喝酒", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "喝了酒", "label": "体标"}, {"form": "喝过酒", "label": "体标"}], "register": "中性", "sense_fingerprint": "饮用含酒精的饮料，如啤酒、白酒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0a3031-66ae-43d8-9fb5-fe85694236c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95166, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喝酒", "is_correct": true, "explanation": "「喝酒」与「开车的人不能……」相呼应，表示开车时不能饮酒，符合语境。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：「结婚」与开车的限制毫无关系，句子不合逻辑。"}, {"text": "散步", "is_correct": false, "explanation": "语义：「散步」与「开车」的限制不相关，句子意思不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：「游泳」与开车毫无关系，句子不合逻辑。"}], "explanations": {"喝酒": "「喝酒」与「开车的人不能……」相呼应，表示开车时不能饮酒，符合语境。", "结婚": "语义：「结婚」与开车的限制毫无关系，句子不合逻辑。", "散步": "语义：「散步」与「开车」的限制不相关，句子意思不通。", "游泳": "语义：「游泳」与开车毫无关系，句子不合逻辑。"}, "sentence_index": 0, "correct_answer": "喝酒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察大声喝酒，让他停下来。", "explanation": "这里应该用〈喝止〉。「喝酒」指饮用含酒精的饮料，大声制止要用「喝止」，这里的「喝」是大声呵斥的意思，不能说「喝酒」。"}, {"text": "我渴了，想去厨房喝酒。", "explanation": "「喝酒」只用于饮用含酒精的饮料，口渴想喝水应该说「喝水」。"}, {"text": "这瓶饮料没有酒精，可以放心地喝酒。", "explanation": "「喝酒」指饮用含酒精的饮料，这瓶饮料没有酒精，应该说「喝饮料」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝酒", "is_correct": true, "explanation": "「喝酒」与「酒吧里的人都在……、唱歌」相呼应，符合酒吧的场景。"}, {"text": "上课", "is_correct": false, "explanation": "语义：「上课」与酒吧的场景不符，句子不合逻辑。"}, {"text": "写作业", "is_correct": false, "explanation": "语义：「写作业」与酒吧里的场景不相符，句子不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：「睡觉」不能和「唱歌」同时进行，也不符合酒吧的场景。"}], "explanations": {"喝酒": "「喝酒」与「酒吧里的人都在……、唱歌」相呼应，符合酒吧的场景。", "上课": "语义：「上课」与酒吧的场景不符，句子不合逻辑。", "写作业": "语义：「写作业」与酒吧里的场景不相符，句子不通。", "睡觉": "语义：「睡觉」不能和「唱歌」同时进行，也不符合酒吧的场景。"}, "sentence_index": 6, "correct_answer": "喝酒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤很香，我想先喝酒。", "explanation": "「喝酒」只指饮用含酒精的饮料，喝汤要说「喝汤」，不能用「喝酒」。"}, {"text": "这块蛋糕很甜，我慢慢地喝酒。", "explanation": "「喝酒」只用于饮用含酒精的饮料，吃蛋糕要说「吃」，不能用「喝酒」。"}, {"text": "这碗粥很烫，我一小口一小口地喝酒。", "explanation": "「喝酒」只指饮用含酒精的饮料，喝粥要说「喝粥」，不能用「喝酒」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他喝酒喝了多，就回家了。", "corrected_sentence": "他喝酒喝多了，就回家了。", "error_description": "动补结构中，补语「多」应紧接动词「喝」之后，说「喝酒喝多了」，「喝了多」的语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来不喝酒了，只喝果汁。", "corrected_sentence": "他从来不喝酒，只喝果汁。", "error_description": "「从来不」表示一贯如此，句末「了」表示变化，两者矛盾，应去掉「了」，说「他从来不喝酒」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
