INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95167, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地带是有一定大小的一片地方。", "primary_collocate": null, "pronunciation": "dì dài", "ipa": "ti˥˩ tai˥˩", "syllable_count": 2, "sentences": [{"text": "这片地带很平，可以盖很多房子。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边有一片地带，孩子们常去那里玩。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那片地带都是石头，不能种菜。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在这个地带找了半天，没有看到水。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有一片安静的地带，老人喜欢在那儿下棋。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一地带很平，适合搭帐篷。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把车停在这片地带，然后走路上山。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子后面的这片地带，现在是一个小公园。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片地带有两公里宽。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把帐篷搭在河边那片地带，离水很近。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片地带", "label": "量词"}, {"form": "危险地带", "label": "复合"}, {"form": "安全地带", "label": "复合"}, {"form": "缓冲地带", "label": "复合"}], "register": "中性", "sense_fingerprint": "有一定范围的一片地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d21fd02-94af-431a-bf66-245fcefabcc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95167, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地带", "is_correct": true, "explanation": "正确：地带指有一定大小的一片地方。"}, {"text": "提袋", "is_correct": false, "explanation": "tí dài：第一音节声母送气、声调不同，意思是手提的袋子。"}, {"text": "地台", "is_correct": false, "explanation": "第二音节 tái（第二声）与 dài（第四声）送气和声调不同，意思是高出地面的平台。"}, {"text": "地毯", "is_correct": false, "explanation": "第二音节 tǎn（第三声）与 dài 不同，意思是地毯。"}, {"text": "替代", "is_correct": false, "explanation": "第一音节 tì 与 dì 只有声母不同，意思是替代，指用一个东西代替另一个。"}], "explanations": {"地带": "正确：地带指有一定大小的一片地方。", "提袋": "tí dài：第一音节声母送气、声调不同，意思是手提的袋子。", "地台": "第二音节 tái（第二声）与 dài（第四声）送气和声调不同，意思是高出地面的平台。", "地毯": "第二音节 tǎn（第三声）与 dài 不同，意思是地毯。", "替代": "第一音节 tì 与 dì 只有声母不同，意思是替代，指用一个东西代替另一个。"}, "sentence_index": null, "correct_answer": "地带"}, "level_3": {"options": [{"text": "地带", "is_correct": true, "explanation": "正确：地带指一片有范围的地方，与“很平，可以盖很多房子”相符。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是室内空间，不能在里面再盖三间房子，与“盖房子”需要的场地语义冲突。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：脸是人的面部，不能作为可以盖房子的场地，与“只能盖三间房子”冲突。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“盖房子”需要有场地，“声音”不能作盖房子的场所，二者无法搭配。"}], "explanations": {"地带": "正确：地带指一片有范围的地方，与“很平，可以盖很多房子”相符。", "房间": "语义：房间是室内空间，不能在里面再盖三间房子，与“盖房子”需要的场地语义冲突。", "脸": "体貌：脸是人的面部，不能作为可以盖房子的场地，与“只能盖三间房子”冲突。", "声音": "搭配：“盖房子”需要有场地，“声音”不能作盖房子的场所，二者无法搭配。"}, "sentence_index": 0, "correct_answer": "地带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把地带推开，走进了房间。", "explanation": "这里应该用〈门〉。推开的是门，地带不能推开。"}, {"text": "我们约定的地带是下午三点。", "explanation": "这里应该用〈时间〉。约定的是时间，地带指一片有范围的区域，不能表示时间。"}, {"text": "地带绕着太阳转。", "explanation": "这里应该用〈地球〉。绕着太阳转的是地球，地带指一片有范围的地方，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95167, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "地带", "is_correct": true, "explanation": "正确：地带指有一定大小的一片地方。"}, {"text": "地道", "is_correct": false, "explanation": "第二音节 dào 与 dài 韵母不同，意思是地下通道。"}, {"text": "低档", "is_correct": false, "explanation": "dī dàng：第一音节声调不同，第二音节韵母不同，意思是质量较低。"}, {"text": "抵达", "is_correct": false, "explanation": "dǐ dá：两个音节的声调都不同，第二音节韵母也不同，意思是到达。"}], "explanations": {"地带": "正确：地带指有一定大小的一片地方。", "地道": "第二音节 dào 与 dài 韵母不同，意思是地下通道。", "低档": "dī dàng：第一音节声调不同，第二音节韵母不同，意思是质量较低。", "抵达": "dǐ dá：两个音节的声调都不同，第二音节韵母也不同，意思是到达。"}, "sentence_index": null, "correct_answer": "地带"}, "level_3": {"options": [{"text": "地带", "is_correct": true, "explanation": "正确：地带指一片有范围的地方，与“把车停在这片地带，然后走路上山”相符。"}, {"text": "海", "is_correct": false, "explanation": "语义：车不能停在海上，“停在这片海”与语义冲突。"}, {"text": "天空", "is_correct": false, "explanation": "语义：车不能停在天空中，“停在这片天空”与语义冲突。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“停在”需要可以停车的地面，“树叶”不能作停车的位置。"}], "explanations": {"地带": "正确：地带指一片有范围的地方，与“把车停在这片地带，然后走路上山”相符。", "海": "语义：车不能停在海上，“停在这片海”与语义冲突。", "天空": "语义：车不能停在天空中，“停在这片天空”与语义冲突。", "树叶": "搭配：“停在”需要可以停车的地面，“树叶”不能作停车的位置。"}, "sentence_index": 6, "correct_answer": "地带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他写信时忘了写地带。", "explanation": "这里应该用〈地址〉。信上写的是地址，地带指一片有范围的区域，不能写在信上。"}, {"text": "他洗完脸，用地带擦了擦。", "explanation": "这里应该用〈毛巾〉。擦脸用毛巾，地带是一片地方，不能用来擦。"}, {"text": "房间里铺着一片地带。", "explanation": "这里应该用〈地毯〉。“铺”的对象是地毯这类可以铺的东西，地带是区域，不能铺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95167, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只地带靠近河边，很适合种树。", "corrected_sentence": "那片地带靠近河边，很适合种树。", "error_description": "量词错误：“地带”是一片有范围的区域，应说“那片地带”，用“只”是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95167, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们找到一张很平的地带，就在那儿搭帐篷。", "corrected_sentence": "我们找到一片很平的地带，就在那儿搭帐篷。", "error_description": "量词错误：地带是一片地方，应说“一片地带”，用“张”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
