INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95168, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "具有某种特点的一片区域。", "primary_collocate": null, "pronunciation": "dì dài", "ipa": "ti˥˩ tai˥˩", "syllable_count": 2, "sentences": [{"text": "这里是沙漠地带，白天特别热。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面是危险地带，请不要进去。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的寒冷地带，冬天常常下大雪。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿海地带的夏天很热，雨也多。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里是无人地带，走很久也看不到人。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地带地下有很多水，所以树长得很好。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国中间有一个缓冲地带。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平原地带的人，大多种小麦。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在地震多的地带，房子都盖得很结实。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的绿化地带，每天都有人浇水。", "target_word": "地带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片地带", "label": "量词"}, {"form": "危险地带", "label": "复合"}, {"form": "沿海地带", "label": "复合"}, {"form": "缓冲地带", "label": "复合"}], "register": "中性", "sense_fingerprint": "有某种特点的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d21fd02-94af-431a-bf66-245fcefabcc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95168, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地带", "is_correct": true, "explanation": "正确：地带指具有某种特点的一片区域。"}, {"text": "提袋", "is_correct": false, "explanation": "tí dài：第一音节声母送气、声调不同，意思是手提的袋子。"}, {"text": "替代", "is_correct": false, "explanation": "第一音节 tì 与 dì 只有声母不同，意思是替代。"}, {"text": "地台", "is_correct": false, "explanation": "第二音节 tái（第二声）与 dài（第四声）送气和声调不同，意思是高出地面的平台。"}, {"text": "地毯", "is_correct": false, "explanation": "第二音节 tǎn（第三声）与 dài 不同，意思是地毯。"}], "explanations": {"地带": "正确：地带指具有某种特点的一片区域。", "提袋": "tí dài：第一音节声母送气、声调不同，意思是手提的袋子。", "替代": "第一音节 tì 与 dì 只有声母不同，意思是替代。", "地台": "第二音节 tái（第二声）与 dài（第四声）送气和声调不同，意思是高出地面的平台。", "地毯": "第二音节 tǎn（第三声）与 dài 不同，意思是地毯。"}, "sentence_index": null, "correct_answer": "地带"}, "level_3": {"options": [{"text": "地带", "is_correct": true, "explanation": "正确：地带指具有某种特点的一片区域，与“这里是沙漠，白天特别热”相符。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，不能作为地区，“这里是沙漠小说”与语义冲突。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是电子设备，不是有气候特点的区域，与“白天特别热”冲突。"}, {"text": "窗口", "is_correct": false, "explanation": "搭配：“沙漠”修饰区域，不能修饰“窗口”，二者无法搭配。"}], "explanations": {"地带": "正确：地带指具有某种特点的一片区域，与“这里是沙漠，白天特别热”相符。", "小说": "语义：小说是文学作品，不能作为地区，“这里是沙漠小说”与语义冲突。", "手机": "语义：手机是电子设备，不是有气候特点的区域，与“白天特别热”冲突。", "窗口": "搭配：“沙漠”修饰区域，不能修饰“窗口”，二者无法搭配。"}, "sentence_index": 0, "correct_answer": "地带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地带开着，风吹进来。", "explanation": "这里应该用〈窗户〉。窗户能开，地带指一片区域，不能说“地带开着”。"}, {"text": "他把地带锁上，然后回家了。", "explanation": "这里应该用〈门〉。锁的是门，地带不能锁。"}, {"text": "这封信的地带写错了。", "explanation": "这里应该用〈地址〉。信上写错的是地址，地带指一片有范围的区域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95168, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "地带", "is_correct": true, "explanation": "正确：地带指具有某种特点的一片区域。"}, {"text": "地道", "is_correct": false, "explanation": "第二音节 dào 与 dài 韵母不同，意思是地下通道。"}, {"text": "低档", "is_correct": false, "explanation": "dī dàng：第一音节声调不同，第二音节韵母不同，意思是质量较低。"}, {"text": "抵达", "is_correct": false, "explanation": "dǐ dá：两个音节的声调都不同，第二音节韵母也不同，意思是到达。"}], "explanations": {"地带": "正确：地带指具有某种特点的一片区域。", "地道": "第二音节 dào 与 dài 韵母不同，意思是地下通道。", "低档": "dī dàng：第一音节声调不同，第二音节韵母不同，意思是质量较低。", "抵达": "dǐ dá：两个音节的声调都不同，第二音节韵母也不同，意思是到达。"}, "sentence_index": null, "correct_answer": "地带"}, "level_3": {"options": [{"text": "地带", "is_correct": true, "explanation": "正确：地带指一片有范围的区域，与“两国中间有一个缓冲地带”相符。"}, {"text": "缓冲器", "is_correct": false, "explanation": "语义：缓冲器是一种装置，不是两国中间的区域，与“两国中间”的语义冲突。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能放在两国中间作缓冲。"}, {"text": "皮肤", "is_correct": false, "explanation": "搭配：“缓冲”后接区域名词，“皮肤”是身体器官，不能作两国之间的缓冲。"}], "explanations": {"地带": "正确：地带指一片有范围的区域，与“两国中间有一个缓冲地带”相符。", "缓冲器": "语义：缓冲器是一种装置，不是两国中间的区域，与“两国中间”的语义冲突。", "桌子": "语义：桌子是家具，不能放在两国中间作缓冲。", "皮肤": "搭配：“缓冲”后接区域名词，“皮肤”是身体器官，不能作两国之间的缓冲。"}, "sentence_index": 6, "correct_answer": "地带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "房间的墙上贴着地带。", "explanation": "这里应该用〈墙纸〉。墙上贴的是墙纸这类薄片，地带是一片区域，不能贴。"}, {"text": "他洗完脸，用地带擦了擦。", "explanation": "这里应该用〈毛巾〉。擦脸用毛巾，地带是一片区域，不能用来擦。"}, {"text": "床上铺着干净的地带。", "explanation": "这里应该用〈床单〉。“铺”的对象是床单这类东西，地带是区域，不能铺在床上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.vali