INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95169, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "外用是涂在身上，不能吃。", "primary_collocate": null, "pronunciation": "wài yòng", "ipa": "wai˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这瓶药水只能外用，不能吃。", "target_word": "外用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个药要外用，涂在手上就行。", "target_word": "外用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说这种药膏是外用的。", "target_word": "外用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种药是外用的，不能放进嘴里。", "target_word": "外用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心，这瓶水是外用的，不是喝的。", "target_word": "外用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "药盒上写着“外用”，所以不能吃。", "target_word": "外用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手破了，医生给了他一管外用的药。", "target_word": "外用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种药酒是外用的，别喝下去。", "target_word": "外用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶红花油只能外用，涂在腿上。", "target_word": "外用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个药是外用的，吃了会不舒服。", "target_word": "外用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "外用药", "label": "复合"}], "register": "中性", "sense_fingerprint": "药物涂在身体表面使用，不能吃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0a3031-66ae-43d8-9fb5-fe85694236c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95169, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "外用", "is_correct": true, "explanation": "正确。wài yòng 指涂在身体表面使用，不能内服。"}, {"text": "外运", "is_correct": false, "explanation": "yùn（第四声）与 yòng 韵母不同（un 与 ong），意思是对外运输，与药品用法无关。"}, {"text": "爱用", "is_correct": false, "explanation": "ài 没有 w 声母，与 wài 声母不同，意思是喜爱使用。"}, {"text": "未用", "is_correct": false, "explanation": "wèi 与 wài 韵母不同（ei 与 ai），意思是尚未使用。"}], "explanations": {"外用": "正确。wài yòng 指涂在身体表面使用，不能内服。", "外运": "yùn（第四声）与 yòng 韵母不同（un 与 ong），意思是对外运输，与药品用法无关。", "爱用": "ài 没有 w 声母，与 wài 声母不同，意思是喜爱使用。", "未用": "wèi 与 wài 韵母不同（ei 与 ai），意思是尚未使用。"}, "sentence_index": null, "correct_answer": "外用"}, "level_3": {"options": [{"text": "内服", "is_correct": false, "explanation": "语义：内服即口服，与“不能吃”矛盾。"}, {"text": "外用", "is_correct": true, "explanation": "正确。外用指涂在身上使用，与“不能吃”一致。"}, {"text": "灌溉", "is_correct": false, "explanation": "搭配：“灌溉”说的是田地、庄稼，药水不能用来灌溉。"}, {"text": "服用", "is_correct": false, "explanation": "语义：服用是吃下去，与“不能吃”矛盾。"}], "explanations": {"内服": "语义：内服即口服，与“不能吃”矛盾。", "外用": "正确。外用指涂在身上使用，与“不能吃”一致。", "灌溉": "搭配：“灌溉”说的是田地、庄稼，药水不能用来灌溉。", "服用": "语义：服用是吃下去，与“不能吃”矛盾。"}, "sentence_index": 0, "correct_answer": "外用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药要饭后外用。", "explanation": "这里应该用〈服用〉。外用是涂在身上，不能吃；饭后吃药要说服用。"}, {"text": "他每天外用一杯牛奶。", "explanation": "这里应该用〈喝〉。外用只用于涂在身体表面的药物，牛奶不能外用。"}, {"text": "他把两粒药丸外用了。", "explanation": "这里应该用〈吞下〉。药丸要口服，外用只限涂在身体表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95169, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "外用", "is_correct": true, "explanation": "正确。wài yòng 指涂在身体表面使用，不能内服。"}, {"text": "耐用", "is_correct": false, "explanation": "nài 与 wài 声母不同（n 与 w），意思是经久耐用。"}, {"text": "万用", "is_correct": false, "explanation": "wàn 与 wài 韵母不同（an 与 ai），意思是多种用途。"}, {"text": "待用", "is_correct": false, "explanation": "dài 与 wài 声母不同（d 与 w），意思是等待使用。"}], "explanations": {"外用": "正确。wài yòng 指涂在身体表面使用，不能内服。", "耐用": "nài 与 wài 声母不同（n 与 w），意思是经久耐用。", "万用": "wàn 与 wài 韵母不同（an 与 ai），意思是多种用途。", "待用": "dài 与 wài 声母不同（d 与 w），意思是等待使用。"}, "sentence_index": null, "correct_answer": "外用"}, "level_3": {"options": [{"text": "口服", "is_correct": false, "explanation": "语义：口服即内服，与手上的伤不相符。"}, {"text": "外用", "is_correct": true, "explanation": "正确。外用的药指涂在身上使用，与手破了的情况相符。"}, {"text": "吞服", "is_correct": false, "explanation": "语义：吞服是咽下去，手上的伤不能靠吞服药来处理。"}, {"text": "擦洗", "is_correct": false, "explanation": "搭配：“擦洗”针对身体或物件，药不能被擦洗。"}], "explanations": {"口服": "语义：口服即内服，与手上的伤不相符。", "外用": "正确。外用的药指涂在身上使用，与手破了的情况相符。", "吞服": "语义：吞服是咽下去，手上的伤不能靠吞服药来处理。", "擦洗": "搭配：“擦洗”针对身体或物件，药不能被擦洗。"}, "sentence_index": 6, "correct_answer": "外用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生给他外用了一针。", "explanation": "这里应该用〈注射〉。注射要进入体内，外用只限涂在身体表面。"}, {"text": "这种药要嚼碎了外用。", "explanation": "这里应该用〈嚼碎了吃〉。药要吞下去，外用只用于涂抹在身体表面。"}, {"text": "这片药要外用在舌下慢慢化开。", "explanation": "这里应该用〈含〉。舌下属于口腔内部，外用只限身体表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95169, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这管药膏是外用地，要涂在伤口上。", "corrected_sentence": "这管药膏是外用的，要涂在伤口上。", "error_description": "结构助词用错：作谓语时应用“的”，说“是外用的”；“地”只用于修饰其后的动词或形容词，不能用在“是……”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95169, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了一盒外用得药，涂在腿上。", "corrected_sentence": "他买了一盒外用的药，涂在腿上。", "error_description": "结构助词用错：修饰语「外用」与中心语「药」之间应用「的」，说「外用的药」；「外用得药」中的「得」是误用，应改为「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
