INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95171, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大拿是某件事特别厉害的人。", "primary_collocate": null, "pronunciation": "dà ná", "ipa": "ta˥˩ na˧˥", "syllable_count": 2, "sentences": [{"text": "他是电脑方面的大拿，什么问题都能解决。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司的修车大拿今天休息。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张是做菜的大拿，他做的鱼特别好吃。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想学下棋，就去请教那位大拿吧。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我们班的英语大拿，每次考试都是第一。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器坏了，得找个修理大拿来看看。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他十岁就成了画画大拿，大家都很佩服他。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跟着这位种地大拿学了一年，我也会种菜了。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别看他年轻，其实是个游戏大拿。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想拍好照片，你应该问问摄影大拿。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "口语", "sense_fingerprint": "在某件事上特别厉害的行家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcd4018f-a1c8-4a3f-b92d-7f066eb0ba12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95171, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大拿", "is_correct": true, "explanation": "正确。“大拿”指在某件事上特别厉害的人，与“什么问题都能解决”相符。"}, {"text": "外行", "is_correct": false, "explanation": "语义：“外行”指不懂行的人，与“什么问题都能解决”的意思正好相反。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：“小偷”指偷东西的人，与“电脑方面”的本领毫无关系。"}, {"text": "老板", "is_correct": false, "explanation": "搭配：“老板”指管理公司或店铺的人，不说“某方面的老板”，也与句中的本领无关。"}], "explanations": {"大拿": "正确。“大拿”指在某件事上特别厉害的人，与“什么问题都能解决”相符。", "外行": "语义：“外行”指不懂行的人，与“什么问题都能解决”的意思正好相反。", "小偷": "语义：“小偷”指偷东西的人，与“电脑方面”的本领毫无关系。", "老板": "搭配：“老板”指管理公司或店铺的人，不说“某方面的老板”，也与句中的本领无关。"}, "sentence_index": 0, "correct_answer": "大拿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间厨房是做菜的大拿，什么菜都能做。", "explanation": "这里把“大拿”用于厨房，指的不是人。“大拿”只用于人，指在某件事上特别厉害的人，不能用来称呼场所。"}, {"text": "在公司里，他是拍板说了算的大拿，谁也不敢违抗。", "explanation": "这里的“大拿”指有权势、能拍板的人，是另一义项；本句谈的是权力，而不是某人在某件事上特别厉害。"}, {"text": "这首歌是唱歌的大拿，大家都爱听。", "explanation": "这里把“大拿”用于歌曲，指的不是人。“大拿”指在某件事上特别厉害的人，不能用来称呼作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95171, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大拿", "is_correct": true, "explanation": "正确。“大拿”指特别厉害的人，与“十岁就成了”和“大家都很佩服他”相符。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：“乞丐”指靠讨饭为生的人，与“画画”的本领和“大家佩服”的语境相矛盾。"}, {"text": "观众", "is_correct": false, "explanation": "语义：“观众”只是看的人，不会画画，与“成了画画……”的意思矛盾。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”指生病的人，与“画画”的本领毫无关系。"}], "explanations": {"大拿": "正确。“大拿”指特别厉害的人，与“十岁就成了”和“大家都很佩服他”相符。", "乞丐": "语义：“乞丐”指靠讨饭为生的人，与“画画”的本领和“大家佩服”的语境相矛盾。", "观众": "语义：“观众”只是看的人，不会画画，与“成了画画……”的意思矛盾。", "病人": "语义：“病人”指生病的人，与“画画”的本领毫无关系。"}, "sentence_index": 6, "correct_answer": "大拿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把锤子是修理大拿，用起来特别顺手。", "explanation": "“大拿”只指人，不能用来指工具。这里说的是锤子好用，不能称锤子为大拿。"}, {"text": "这辆自行车是骑车大拿，跑得又快又稳。", "explanation": "“大拿”只指人，不能用来指交通工具。自行车的性能应直接描述，不能用“大拿”来形容。"}, {"text": "这本词典是查词大拿，收的词特别多。", "explanation": "“大拿”只指人，不能用来指书。词典的内容应直接描述，不能称词典为大拿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95171, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是我们学校一台唱歌大拿。", "corrected_sentence": "她是我们学校一位唱歌大拿。", "error_description": "“大拿”指人，量词应用“位”或“个”，不能用“台”（用于机器）。正确的说法是“一位唱歌大拿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95171, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几位大拿们都很厉害。", "corrected_sentence": "这几位大拿都很厉害。", "error_description": "有“几位”修饰时，名词后不能再加“们”。应去掉“们”，说“这几位大拿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
