INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95172, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "某方面很有本事、有权势的人。", "primary_collocate": null, "pronunciation": "dà ná", "ipa": "ta˥˩ na˧˥", "syllable_count": 2, "sentences": [{"text": "他在这个行业里是个大拿，谁都得给他面子。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说新来的经理是上面的大拿，大家都很小心。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的生意，都由几位大拿说了算。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认识很多大拿，办什么事都很方便。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在村里，他是说话最有分量的大拿。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大拿一开口，下面的人都不敢出声。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要办成这件事，得先找到能做主的大拿。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小穷苦，后来成了地方上的大拿。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会上来了好几位大拿，气氛很紧张。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不想得罪那位在行里有权势的大拿。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "口语", "sense_fingerprint": "在某方面有本事、有权势、说话有分量的人物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcd4018f-a1c8-4a3f-b92d-7f066eb0ba12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95172, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大拿", "is_correct": true, "explanation": "正确。“大拿”指有本事、有权势的人，与“谁都得给他面子”相符。"}, {"text": "学徒", "is_correct": false, "explanation": "语义：“学徒”指还在学艺、没有权势的人，与“谁都得给他面子”矛盾。"}, {"text": "游客", "is_correct": false, "explanation": "搭配：“游客”指旅游的人，不能说“在这个行业里是个游客”。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”只是搭车的人，没有权势，与“谁都得给他面子”矛盾。"}], "explanations": {"大拿": "正确。“大拿”指有本事、有权势的人，与“谁都得给他面子”相符。", "学徒": "语义：“学徒”指还在学艺、没有权势的人，与“谁都得给他面子”矛盾。", "游客": "搭配：“游客”指旅游的人，不能说“在这个行业里是个游客”。", "乘客": "语义：“乘客”只是搭车的人，没有权势，与“谁都得给他面子”矛盾。"}, "sentence_index": 0, "correct_answer": "大拿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子是家里的大拿，谁都得给它让座。", "explanation": "这里把“大拿”用于椅子，指的不是人。“大拿”指某方面有权势、说了算的人，不能用来称呼家具。"}, {"text": "这台电脑是公司里的大拿，大家都得听它的。", "explanation": "这里把“大拿”用于电脑，指的不是人。“大拿”指有本事、有权势的人，不能用来称呼机器。"}, {"text": "这辆摩托车是村里的大拿，谁都得听它的。", "explanation": "这里把“大拿”用于摩托车，指的不是人。“大拿”指有权势的人，不能用来称呼交通工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大拿", "is_correct": true, "explanation": "正确。“大拿”指有本事、有权势的人，与“能做主”相符。"}, {"text": "旁观者", "is_correct": false, "explanation": "语义：“旁观者”只看不管，不能做主，与“能做主的”矛盾。"}, {"text": "路人", "is_correct": false, "explanation": "语义：“路人”与这件事无关，没有决定权，与句意矛盾。"}, {"text": "病号", "is_correct": false, "explanation": "搭配：“病号”指生病的人，不能用于“能做主的……”这类身份说法。"}], "explanations": {"大拿": "正确。“大拿”指有本事、有权势的人，与“能做主”相符。", "旁观者": "语义：“旁观者”只看不管，不能做主，与“能做主的”矛盾。", "路人": "语义：“路人”与这件事无关，没有决定权，与句意矛盾。", "病号": "搭配：“病号”指生病的人，不能用于“能做主的……”这类身份说法。"}, "sentence_index": 6, "correct_answer": "大拿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子是家具大拿，用了十年还很结实。", "explanation": "“大拿”只指人，不能用来指家具。桌子结实应直接描述，不能称桌子为大拿。"}, {"text": "那辆卡车是运输大拿，跑得又稳又快。", "explanation": "“大拿”只指人，不能用来指车辆。卡车的性能应直接描述，不能用“大拿”来形容。"}, {"text": "这座房子是建筑大拿，住着很舒服。", "explanation": "“大拿”只指人，不能用来指建筑物。房子舒服与否应直接描述，不能称房子为大拿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里这几位大拿们都很有分量。", "corrected_sentence": "村里这几位大拿都很有分量。", "error_description": "有“几位”修饰时，名词后不能再加“们”。应去掉“们”，说“这几位大拿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是村里一只有名的大拿。", "corrected_sentence": "他是村里一位有名的大拿。", "error_description": "“大拿”指人，量词应用“位”，不能用“只”（“只”多用于动物或成对的东西）。正确的说法是“他是村里一位有名的大拿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
