INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95173, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "大致是差不多，不太细。", "primary_collocate": null, "pronunciation": "dà zhì", "ipa": "ta˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "时间不多，我只大致看了一下这本书。", "target_word": "大致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师只大致讲了一下考试的内容。", "target_word": "大致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理没有细说，只大致介绍了计划。", "target_word": "大致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先大致说说这件事，细节以后再谈。", "target_word": "大致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事我只大致记得，细节都忘了。", "target_word": "大致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生大致看了看，说问题不大。", "target_word": "大致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把房间大致收拾了一下，客人就到了。", "target_word": "大致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们大致看过这份材料，还要再仔细读一遍。", "target_word": "大致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游先大致说明路线，然后带我们出发。", "target_word": "大致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你大致画一下教室的样子，不用画得太细。", "target_word": "大致", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "大致：不求细致，只做粗略、概括的处理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95568041-1756-4a69-ab1f-8a712d7a8619') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95173, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大致", "is_correct": true, "explanation": "正确答案：大致（dà zhì）。"}, {"text": "大事", "is_correct": false, "explanation": "dà shì（第四声）与 dà zhì 声母不同（sh 与 zh），意思是重大的事情。"}, {"text": "大旨", "is_correct": false, "explanation": "dà zhǐ（第三声）与 dà zhì 声调不同，意思是主要意思。"}, {"text": "打制", "is_correct": false, "explanation": "dǎ zhì（第三声）与 dà zhì 第一个音节声调不同，意思是敲打制作。"}], "explanations": {"大致": "正确答案：大致（dà zhì）。", "大事": "dà shì（第四声）与 dà zhì 声母不同（sh 与 zh），意思是重大的事情。", "大旨": "dà zhǐ（第三声）与 dà zhì 声调不同，意思是主要意思。", "打制": "dǎ zhì（第三声）与 dà zhì 第一个音节声调不同，意思是敲打制作。"}, "sentence_index": null, "correct_answer": "大致"}, "level_3": {"options": [{"text": "大致", "is_correct": true, "explanation": "正确：“大致”表示不求细致，与“只”和“看了一下”相合。"}, {"text": "完全", "is_correct": false, "explanation": "语义：“完全”表示彻底、毫无遗漏，与“只……看了一下”的略看之意相矛盾。"}, {"text": "彻底", "is_correct": false, "explanation": "搭配：“彻底”多与“解决”“改变”搭配，不能与“看了一下”搭配。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”强调总括所有，与“只”和“一下”的略读之意相矛盾。"}], "explanations": {"大致": "正确：“大致”表示不求细致，与“只”和“看了一下”相合。", "完全": "语义：“完全”表示彻底、毫无遗漏，与“只……看了一下”的略看之意相矛盾。", "彻底": "搭配：“彻底”多与“解决”“改变”搭配，不能与“看了一下”搭配。", "全部": "语义：“全部”强调总括所有，与“只”和“一下”的略读之意相矛盾。"}, "sentence_index": 0, "correct_answer": "大致"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大致登记了每一张发票，一张也不能漏。", "explanation": "这里应该用〈逐一〉。“一张也不能漏”要求逐张登记，“大致”的粗略处理与之冲突。"}, {"text": "这份护照上的数字不能有一点差错，他大致核对了一遍。", "explanation": "这里应该用〈仔细〉。“不能有一点差错”要求仔细核对，“大致”的粗略处理与之冲突。"}, {"text": "我们大致计算了每个人应付的金额，一分钱都不能错。", "explanation": "这里应该用〈精确〉。金额要一分不差，“大致”的粗略处理与“一分钱都不能错”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95173, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大致", "is_correct": true, "explanation": "正确：“大致”修饰“收拾”，表示粗略做一下，与“一下”和“客人就到了”的仓促相合。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，不能直接修饰“收拾了一下”这样的动作。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续不断，不能与“收拾了一下”这种一次性动作搭配。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示经常或习惯，与“客人就到了”这一次性情境不符。"}], "explanations": {"大致": "正确：“大致”修饰“收拾”，表示粗略做一下，与“一下”和“客人就到了”的仓促相合。", "非常": "语法：“非常”是程度副词，不能直接修饰“收拾了一下”这样的动作。", "一直": "搭配：“一直”表示持续不断，不能与“收拾了一下”这种一次性动作搭配。", "总是": "语义：“总是”表示经常或习惯，与“客人就到了”这一次性情境不符。"}, "sentence_index": 6, "correct_answer": "大致"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "考试前，老师要我们大致检查每一道题，一个字都不能错。", "explanation": "这里应该用〈仔细〉。“一个字都不能错”要求仔细检查，“大致”的粗略之意与之矛盾。"}, {"text": "工程师大致测量了零件的尺寸，误差不能超过0.1毫米。", "explanation": "这里应该用〈精准〉。“误差不能超过0.1毫米”要求精准测量，“大致”不能与之搭配。"}, {"text": "医生说药的分量一点都不能错，护士却大致称了一下。", "explanation": "这里应该用〈准确〉。药量一点都不能错，“大致”的粗略处理与之冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95173, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很大致看了一下这份报告。", "corrected_sentence": "他大致看了一下这份报告。", "error_description": "错误：副词“大致”前面不能加程度副词“很”。“大致”本身已是副词，应说“大致看了一下”，不说“很大致看了一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95173, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些资料我们大致的整理了一下，明天再仔细看。", "corrected_sentence": "这些资料我们大致整理了一下，明天再仔细看。", "error_description": "错误：副词“大致”后面不能加“的”。“大致”在这里作状语修饰动词，应说“大致整理”，不说“大致的整理”（“大致的”只修饰名词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
