INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95174, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "大概，大体上。", "primary_collocate": null, "pronunciation": "dà zhì", "ipa": "ta˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "从这里到学校，大致要走二十分钟。", "target_word": "大致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个班的人数大致相同。", "target_word": "大致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的看法大致一样，只有一点不同。", "target_word": "大致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事的情况大致是这样的。", "target_word": "大致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个班大致有五十个学生。", "target_word": "大致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年夏天的天气和去年大致相似，都很热。", "target_word": "大致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议大致在下午三点结束。", "target_word": "大致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从地图上看，路线大致是从东到西。", "target_word": "大致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的汉语水平大致能看懂新闻。", "target_word": "大致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作业大致写完了，只剩最后一题。", "target_word": "大致", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "大致：大概、大体上，对数量、情况作概略估计", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95568041-1756-4a69-ab1f-8a712d7a8619') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95174, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大致", "is_correct": true, "explanation": "正确答案：大致（dà zhì）。"}, {"text": "大事", "is_correct": false, "explanation": "dà shì（第四声）与 dà zhì 声母不同（sh 与 zh），意思是重大的事情。"}, {"text": "大旨", "is_correct": false, "explanation": "dà zhǐ（第三声）与 dà zhì 声调不同，意思是主要意思。"}, {"text": "打制", "is_correct": false, "explanation": "dǎ zhì（第三声）与 dà zhì 第一个音节声调不同，意思是敲打制作。"}], "explanations": {"大致": "正确答案：大致（dà zhì）。", "大事": "dà shì（第四声）与 dà zhì 声母不同（sh 与 zh），意思是重大的事情。", "大旨": "dà zhǐ（第三声）与 dà zhì 声调不同，意思是主要意思。", "打制": "dǎ zhì（第三声）与 dà zhì 第一个音节声调不同，意思是敲打制作。"}, "sentence_index": null, "correct_answer": "大致"}, "level_3": {"options": [{"text": "大致", "is_correct": true, "explanation": "正确：“大致”修饰时长的估计，与“二十分钟”的概数相合。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与路程所需的固定时长不符。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，不能修饰“要走二十分钟”。"}, {"text": "完全", "is_correct": false, "explanation": "语义：“完全”表示精确无误，与“大致”所表达的概略估计相矛盾。"}], "explanations": {"大致": "正确：“大致”修饰时长的估计，与“二十分钟”的概数相合。", "偶尔": "语义：“偶尔”表示不常发生，与路程所需的固定时长不符。", "非常": "语法：“非常”是程度副词，不能修饰“要走二十分钟”。", "完全": "语义：“完全”表示精确无误，与“大致”所表达的概略估计相矛盾。"}, "sentence_index": 0, "correct_answer": "大致"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的护照号码大致是一串九位数，一位都不能错。", "explanation": "这里应该用〈确切〉。护照号码必须准确无误，“大致”的概略之意与之矛盾。"}, {"text": "我的生日大致是五月三号。", "explanation": "这里应该用〈就〉或不用副词。自己的生日是确切的日子，不需要概略估计。"}, {"text": "我家的电话号码大致是8765 4321。", "explanation": "这里不应该用“大致”。电话号码必须准确，不能概略估计。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95174, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大致", "is_correct": true, "explanation": "正确：“大致”修饰结束时间的估计，与“下午三点”的概数相合。"}, {"text": "慢慢", "is_correct": false, "explanation": "语义：“慢慢”描述动作的速度，与“在下午三点结束”这一时间点的表达不符。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能修饰“在下午三点结束”。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，不能修饰时间状语和动词。"}], "explanations": {"大致": "正确：“大致”修饰结束时间的估计，与“下午三点”的概数相合。", "慢慢": "语义：“慢慢”描述动作的速度，与“在下午三点结束”这一时间点的表达不符。", "很": "语法：“很”是程度副词，不能修饰“在下午三点结束”。", "非常": "语法：“非常”是程度副词，不能修饰时间状语和动词。"}, "sentence_index": 6, "correct_answer": "大致"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一年大致有十二个月。", "explanation": "这里不应该用“大致”。一年正好十二个月，是确定的事实，不是估计。"}, {"text": "一个星期大致有七天。", "explanation": "这里不应该用“大致”。一个星期正好七天，不需要估计。"}, {"text": "我大致有两个眼睛。", "explanation": "这里不应该用“大致”。人有两个眼睛是确定的事实，不能概略估计。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这趟旅行很大致要三天。", "corrected_sentence": "这趟旅行大致要三天。", "error_description": "错误：“大致”前面不能加程度副词“很”。“大致”本身已表示概略，应说“大致要三天”，不说“很大致”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个方案的成本大致的相同，可以都考虑。", "corrected_sentence": "两个方案的成本大致相同，可以都考虑。", "error_description": "错误：“大致”后面不能加“的”。“大致”在这里修饰形容词“相同”，应说“大致相同”，“大致的”只修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
