INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95175, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天地是天和地，也是很大的地方。", "primary_collocate": null, "pronunciation": "tiān dì", "ipa": "tʰiɛn⁵⁵ ti⁵¹", "syllable_count": 2, "sentences": [{"text": "大雪过后，天地一片白色。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳升起来，天地都亮了。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片草原的天地很大，孩子们可以随便跑。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里很安静，天地都睡着了。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在山顶，他望见远处天地相接的地方。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，天地充满了生机。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上刮着大风，天地一片黑。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在草原上，对着天地大声喊。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人相信，天地是有生命的。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雾散了以后，天地又变得清楚了。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "新天地", "label": "复合"}, {"form": "一片天地", "label": "量词"}], "register": "中性", "sense_fingerprint": "天地：天和地，眼前的自然空间；也指广大的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0a3031-66ae-43d8-9fb5-fe85694236c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95175, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天地", "is_correct": true, "explanation": "正确。tiān dì 指天和地，即眼前的自然空间。"}, {"text": "田地", "is_correct": false, "explanation": "tián（第二声）与 tiān（第一声）声调不同，意思是田地、土地。"}, {"text": "天敌", "is_correct": false, "explanation": "dí（第二声）与 dì（第四声）声调不同，意思是天然的敌对生物。"}, {"text": "天气", "is_correct": false, "explanation": "qì 与 dì 声母不同（q 与 d），意思是大气的状况。"}, {"text": "天际", "is_correct": false, "explanation": "jì 与 dì 声母不同（j 与 d），意思是天边。"}], "explanations": {"天地": "正确。tiān dì 指天和地，即眼前的自然空间。", "田地": "tián（第二声）与 tiān（第一声）声调不同，意思是田地、土地。", "天敌": "dí（第二声）与 dì（第四声）声调不同，意思是天然的敌对生物。", "天气": "qì 与 dì 声母不同（q 与 d），意思是大气的状况。", "天际": "jì 与 dì 声母不同（j 与 d），意思是天边。"}, "sentence_index": null, "correct_answer": "天地"}, "level_3": {"options": [{"text": "道理", "is_correct": false, "explanation": "语义：“道理”不是景象，不能呈现“一片白色”。"}, {"text": "天地", "is_correct": true, "explanation": "正确。大雪过后，天地呈现一片白色。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“一片白色”形容景物，“考试”不能呈现颜色。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不能呈现“一片白色”的景象。"}], "explanations": {"道理": "语义：“道理”不是景象，不能呈现“一片白色”。", "天地": "正确。大雪过后，天地呈现一片白色。", "考试": "搭配：“一片白色”形容景物，“考试”不能呈现颜色。", "数学": "语义：数学是学科，不能呈现“一片白色”的景象。"}, "sentence_index": 0, "correct_answer": "天地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个天地只有五分钟。", "explanation": "这里应该用〈时间〉。天地指很大的地方，不能用来计算时长。"}, {"text": "这个天地很重，我搬不动。", "explanation": "这里应该用〈箱子〉。天地是很大的地方，没有重量，不能说“重”。"}, {"text": "他把天地装进了背包里。", "explanation": "这里应该用〈东西〉。天地是很大的地方，不能装进背包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95175, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "语义：“一片黑”形容空间或景象，时间不能呈现这种状态。"}, {"text": "天地", "is_correct": true, "explanation": "正确。海上刮着大风，天地一片黑。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“一片黑”形容天空、大地等景物，不说价格一片黑。"}, {"text": "薪水", "is_correct": false, "explanation": "语义：薪水是钱数，不是可以呈现颜色的景象。"}], "explanations": {"时间": "语义：“一片黑”形容空间或景象，时间不能呈现这种状态。", "天地": "正确。海上刮着大风，天地一片黑。", "价格": "搭配：“一片黑”形容天空、大地等景物，不说价格一片黑。", "薪水": "语义：薪水是钱数，不是可以呈现颜色的景象。"}, "sentence_index": 6, "correct_answer": "天地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雾散了以后，天地很香。", "explanation": "这里应该用〈花〉。天地是景象，没有气味，“香”只能形容有气味的东西。"}, {"text": "雾散了以后，天地很甜。", "explanation": "这里应该用〈西瓜〉。天地没有味道，“甜”只能形容食物或味道。"}, {"text": "雾散了以后，天地很重。", "explanation": "这里应该用〈箱子〉。天地是景象，没有重量，不能用“重”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95175, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片草原的天地的很宽，牛羊可以自由地跑。", "corrected_sentence": "这片草原的天地很宽，牛羊可以自由地跑。", "error_description": "多余的“的”：“天地”后不应加“的”，“的很宽”是错误形式，应为“这片草原的天地很宽”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95175, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "站在草原上，眼前是一只广阔的天地。", "corrected_sentence": "站在草原上，眼前是一片广阔的天地。", "error_description": "量词错误：“天地”指很大的地方时，量词应用“片”；“只”用于动物等，不能说“一只天地”。应为“一片广阔的天地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
