INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95176, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻人活动、发展的领域或境地。", "primary_collocate": null, "pronunciation": "tiān dì", "ipa": "tʰiɛn⁵⁵ ti⁵¹", "syllable_count": 2, "sentences": [{"text": "他离开家乡，想去外面闯一片新天地。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大了，应该有自己的天地。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村是一个广阔的天地，年轻人可以大有作为。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把小小的厨房当成自己的天地。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休以后，爷爷在花园里找到了自己的小天地。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了汉语，我看到了一个新的天地。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给了年轻人一个施展才华的天地。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在音乐的天地里过得很快乐。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书房是爸爸一个人的小天地，我们不能随便进去。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业后，他决定到大城市开创自己的天地。", "target_word": "天地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "新天地", "label": "复合"}, {"form": "一片天地", "label": "量词"}], "register": "中性", "sense_fingerprint": "天地：人活动、发展的领域或境地（新天地、小天地）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0a3031-66ae-43d8-9fb5-fe85694236c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95176, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天地", "is_correct": true, "explanation": "正确。tiān dì 指天和地，也指活动的领域或境地。"}, {"text": "田地", "is_correct": false, "explanation": "tián（第二声）与 tiān（第一声）声调不同，意思是田地、土地。"}, {"text": "天敌", "is_correct": false, "explanation": "dí（第二声）与 dì（第四声）声调不同，意思是天然的敌对生物。"}, {"text": "天气", "is_correct": false, "explanation": "qì 与 dì 声母不同（q 与 d），意思是大气的状况。"}, {"text": "天际", "is_correct": false, "explanation": "jì 与 dì 声母不同（j 与 d），意思是天边。"}], "explanations": {"天地": "正确。tiān dì 指天和地，也指活动的领域或境地。", "田地": "tián（第二声）与 tiān（第一声）声调不同，意思是田地、土地。", "天敌": "dí（第二声）与 dì（第四声）声调不同，意思是天然的敌对生物。", "天气": "qì 与 dì 声母不同（q 与 d），意思是大气的状况。", "天际": "jì 与 dì 声母不同（j 与 d），意思是天边。"}, "sentence_index": null, "correct_answer": "天地"}, "level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "语义：“闯”的对象是领域或境地，心情不能被“闯”。"}, {"text": "天地", "is_correct": true, "explanation": "正确。“闯一片新天地”指在新的领域中开拓。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：“闯”的对象是领域或境地，饭菜不能被“闯”，句意不通。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“一片”和“闯”一般不用于工厂，搭配不成立。"}], "explanations": {"心情": "语义：“闯”的对象是领域或境地，心情不能被“闯”。", "天地": "正确。“闯一片新天地”指在新的领域中开拓。", "饭菜": "语义：“闯”的对象是领域或境地，饭菜不能被“闯”，句意不通。", "工厂": "搭配：“一片”和“闯”一般不用于工厂，搭配不成立。"}, "sentence_index": 0, "correct_answer": "天地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位天地很能干。", "explanation": "这里应该用〈人〉。天地指天和地或活动的领域，不指人，不能用“位”计数，也不能说“能干”。"}, {"text": "他终于在公司吃到了一片属于自己的天地。", "explanation": "这里应该用〈得到〉。天地指活动的领域，是抽象的，不能吃。"}, {"text": "这片天地很香，让他想起了小时候。", "explanation": "这里应该用〈花园〉。天地是抽象的领域，没有气味，不能用“香”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河流", "is_correct": false, "explanation": "语义：“施展才华”的对象不能是河流，句意不通。"}, {"text": "天地", "is_correct": true, "explanation": "正确。“施展才华的天地”指可以发挥才能的领域。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“施展”搭配的是才华、本领，不说施展工资。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐不是可以施展才华的地方，句意不通。"}], "explanations": {"河流": "语义：“施展才华”的对象不能是河流，句意不通。", "天地": "正确。“施展才华的天地”指可以发挥才能的领域。", "工资": "搭配：“施展”搭配的是才华、本领，不说施展工资。", "早餐": "语义：早餐不是可以施展才华的地方，句意不通。"}, "sentence_index": 6, "correct_answer": "天地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他决定到大城市开挖自己的天地。", "explanation": "这里应该用〈开创〉。天地是抽象的领域，不能被开挖。"}, {"text": "他决定到大城市给自己的天地打个电话。", "explanation": "这里应该用〈人〉。电话只能打给人，天地是抽象的领域，不能给它打电话。"}, {"text": "他把这个天地装进了行李箱。", "explanation": "这里应该用〈东西〉。天地是抽象的领域，不是能装进行李箱的实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毕业以后，她想到大城市开创一只新天地。", "corrected_sentence": "毕业以后，她想到大城市开创一片新天地。", "error_description": "量词错误：“天地”指活动的领域时，量词应用“片”，“只”用于动物或成对的东西。应为“一片新天地”，“一只新天地”是错误形式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毕业以后，他终于找到了一片属于自己天地。", "corrected_sentence": "毕业以后，他终于找到了一片属于自己的天地。", "error_description": "“的”遗漏：定语“属于自己”后应加“的”，应为“属于自己的天地”。“自己天地”是错误形式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
