INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95178, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95178, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由广大人民群众广泛参与，依靠群众力量进行的战争。", "primary_collocate": null, "pronunciation": "rén mín zhàn zhēng", "ipa": "ɻən min ʈʂan ʈʂəŋ", "syllable_count": 4, "sentences": [{"text": "这场人民战争得到了全国人民的支持。", "target_word": "人民战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书上讲过人民战争的故事。", "target_word": "人民战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民战争依靠的是广大群众的力量。", "target_word": "人民战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，人民战争不只是军人的事。", "target_word": "人民战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读了一本讲人民战争的书。", "target_word": "人民战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有依靠群众，才能打好人民战争。", "target_word": "人民战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民战争让敌人没有地方躲。", "target_word": "人民战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的人民战争打了很多年。", "target_word": "人民战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常给我讲人民战争的故事。", "target_word": "人民战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民战争的胜利靠的是千千万万的人。", "target_word": "人民战争", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "广大群众参与、依靠群众力量的战争", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3fe24b8-ed9b-4c4c-b194-80ca274be0f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95178, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人民战争", "is_correct": true, "explanation": "正确。人民战争指广大群众广泛参与的战争，与“得到全国人民的支持”相符。"}, {"text": "暴雨", "is_correct": false, "explanation": "语义：暴雨是自然现象，不能“得到全国人民的支持”。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不是可以获得支持的活动。"}, {"text": "火灾", "is_correct": false, "explanation": "搭配：“得到支持”一般接在人或事业上，不接火灾。"}], "explanations": {"人民战争": "正确。人民战争指广大群众广泛参与的战争，与“得到全国人民的支持”相符。", "暴雨": "语义：暴雨是自然现象，不能“得到全国人民的支持”。", "感冒": "语义：感冒是疾病，不是可以获得支持的活动。", "火灾": "搭配：“得到支持”一般接在人或事业上，不接火灾。"}, "sentence_index": 0, "correct_answer": "人民战争"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场人民战争只靠一支精锐小部队就打赢了。", "explanation": "这里应该用〈战役〉。人民战争依靠广大群众，不是只靠一支小部队作战，与其含义相矛盾。"}, {"text": "这场人民战争让两派军队在城外互相厮杀，村民们都躲在家里。", "explanation": "这里应该用〈内战〉。人民战争是广大群众共同抗敌，不是两派军队互相厮杀，村民也不会躲在家里。"}, {"text": "这场人民战争只有两个人参加。", "explanation": "这里应该用〈战斗〉。人民战争要靠广大群众广泛参与，只有两个人参加不符合其含义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人民战争", "is_correct": true, "explanation": "正确。人民战争能使敌人没有地方躲，与句中的语境相符。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：夏天是季节，不能让敌人没有地方躲。"}, {"text": "地图", "is_correct": false, "explanation": "配价：“让”的主语要能使人行动，地图不能使敌人没有地方躲。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：友谊是感情，不能对敌人造成这种结果。"}], "explanations": {"人民战争": "正确。人民战争能使敌人没有地方躲，与句中的语境相符。", "夏天": "语义：夏天是季节，不能让敌人没有地方躲。", "地图": "配价：“让”的主语要能使人行动，地图不能使敌人没有地方躲。", "友谊": "语义：友谊是感情，不能对敌人造成这种结果。"}, "sentence_index": 6, "correct_answer": "人民战争"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场人民战争是侵略者发动的，与当地百姓无关。", "explanation": "这里应该用〈侵略战争〉。人民战争由广大群众参与，不是侵略者发动的，也不与百姓无关。"}, {"text": "这场人民战争依靠的是坚固的堡垒和大量火炮，普通百姓不参与。", "explanation": "这里应该用〈阵地战〉。人民战争依靠广大群众，不是依靠堡垒和火炮，普通百姓也不参与，与定义相矛盾。"}, {"text": "这场人民战争是少数分子煽动的，普通百姓都不知情。", "explanation": "这里应该用〈暴乱〉。人民战争要求广大群众广泛参与，少数分子煽动、百姓不知情的情形不符合其含义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个人民战争动员了全村的人。", "corrected_sentence": "一场人民战争动员了全村的人。", "error_description": "量词错误：战争应用量词“场”，不用“个”。应改为“一场人民战争”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场人民战争打败着侵略者。", "corrected_sentence": "这场人民战争打败了侵略者。", "error_description": "时态错误：“打败”表示已完成的结果，应用“了”，用“着”表示持续状态，与已经发生的战争不符。应改为“打败了侵略者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
