INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95179, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一些人被选出来，一起去别的地方做事，他们就是一个队。", "primary_collocate": null, "pronunciation": "dài biǎo tuán", "ipa": "tai˥˩ piɑu˨˩˦ tʰuan˧˥", "syllable_count": 3, "sentences": [{"text": "学校派了一个代表团去参加比赛。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有三个人加入了代表团。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代表团坐火车去了上海。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个代表团要去外地学习。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们组成代表团，一起去别的城市。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里选出一个代表团，去城里说明情况。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代表团的人都穿着白衬衫。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代表团今天早上坐船出发了。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸是工人代表团里的一个人。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代表团回来后，给大家讲了路上的事。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "支", "label": "量词"}, {"form": "代表團", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "代表团：选出来一起去外地办事的一队人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '629e9c88-00bf-45eb-822b-29c0b905eb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95179, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：作业是练习题，不能被派去参加比赛。"}, {"text": "奖杯", "is_correct": false, "explanation": "搭配：“派”一般接人或团体，不能说派出奖杯。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不能去参加比赛。"}, {"text": "代表团", "is_correct": true, "explanation": "正确：代表团是为办事派出的一队人，可以“派去参加比赛”。"}], "explanations": {"作业": "语义：作业是练习题，不能被派去参加比赛。", "奖杯": "搭配：“派”一般接人或团体，不能说派出奖杯。", "书包": "语义：书包是装东西的袋子，不能去参加比赛。", "代表团": "正确：代表团是为办事派出的一队人，可以“派去参加比赛”。"}, "sentence_index": 0, "correct_answer": "代表团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们全家组成一个代表团，去海边玩。", "explanation": "这里应该用〈旅游团〉。代表团是为会议或办事派出的团体，全家出游不用此词。"}, {"text": "我们班派了一个代表团去教室后面打扫卫生。", "explanation": "这里应该用〈小组〉。代表团是被选派到别处办事的团体，在教室后面打扫卫生应说〈小组〉。"}, {"text": "我们班派了一个代表团在教室里唱歌。", "explanation": "这里应该用〈合唱团〉。代表团是被选派到别处办事的团体，在教室里唱歌应说〈合唱团〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95179, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：“桌子的人”说不通，桌子不是人或团体。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是墙上的开口，不能指一群穿衣服的人。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是写字的文具，不是由人组成的团体，“铅笔的人”说不通。"}, {"text": "代表团", "is_correct": true, "explanation": "正确：代表团是由一群人组成的团体，“代表团的人”通顺。"}], "explanations": {"桌子": "语义：“桌子的人”说不通，桌子不是人或团体。", "窗户": "语义：窗户是墙上的开口，不能指一群穿衣服的人。", "铅笔": "语义：铅笔是写字的文具，不是由人组成的团体，“铅笔的人”说不通。", "代表团": "正确：代表团是由一群人组成的团体，“代表团的人”通顺。"}, "sentence_index": 6, "correct_answer": "代表团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我是一个代表团。", "explanation": "这里应该用〈代表〉。代表团是由几个人组成的团体，只有一个人时应说〈代表〉。"}, {"text": "我们班的代表团每周五在教室里活动。", "explanation": "这里应该用〈社团〉。代表团是为会议或访问临时派出的，不是长期活动的组织。"}, {"text": "这个代表团是我们几个朋友自发组织的，平时一起打牌。", "explanation": "这里应该用〈小圈子〉。代表团是被选出来去办事的团体，几个朋友自发组织、平时打牌的聚会不属于这一义项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95179, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校派了一双代表团去外地。", "corrected_sentence": "学校派了一个代表团去外地。", "error_description": "错误：一双代表团。正确：一个代表团。〈双〉用于成对的东西，代表团是一群人组成的团体，应用〈个〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95179, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "代表团们昨天下午坐车回来了。", "corrected_sentence": "代表团昨天下午坐车回来了。", "error_description": "错误：代表团们。正确：代表团。〈代表团〉是集体名词，不能再加〈们〉表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
