INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95180, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由若干代表组成、受派前往某地参加会议或访问的团体。", "primary_collocate": null, "pronunciation": "dài biǎo tuán", "ipa": "tai˥˩ piɑu˨˩˦ tʰuan˧˥", "syllable_count": 3, "sentences": [{"text": "中国代表团明天到北京。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代表团团长在会上发了言。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的代表团参加了这次国际会议。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个代表团有二十多个人。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代表团到机场时，很多人来欢迎。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理带着代表团参观了工厂。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青年代表团下个星期去日本访问。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代表团昨天和市长见了面。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是代表团的一员，要去开会。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代表团的一位成员在欢迎晚会上唱了一首歌。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "支", "label": "量词"}, {"form": "代表團", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "代表团：受派出席会议或进行访问的官方、正式团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '629e9c88-00bf-45eb-822b-29c0b905eb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "首都", "is_correct": false, "explanation": "语义：首都本身就是北京，句中却说“明天到北京”，二者矛盾。"}, {"text": "代表团", "is_correct": true, "explanation": "正确：代表团是受派前往某地参加会议或访问的团体，可以“明天到北京”。"}, {"text": "制度", "is_correct": false, "explanation": "搭配：“到”的主语须是人或交通工具，制度不能“到北京”。"}, {"text": "大会", "is_correct": false, "explanation": "语义：大会是会议本身，不是会“明天到北京”的一方。"}], "explanations": {"首都": "语义：首都本身就是北京，句中却说“明天到北京”，二者矛盾。", "代表团": "正确：代表团是受派前往某地参加会议或访问的团体，可以“明天到北京”。", "制度": "搭配：“到”的主语须是人或交通工具，制度不能“到北京”。", "大会": "语义：大会是会议本身，不是会“明天到北京”的一方。"}, "sentence_index": 0, "correct_answer": "代表团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我是这次会议的代表团。", "explanation": "这里应该用〈代表〉。代表团指由若干人组成的团体，一个人只能说〈代表〉。"}, {"text": "妈妈每天早上带代表团去幼儿园。", "explanation": "这里应该用〈孩子〉。代表团是为会议或访问派出的正式团体，不是每天送去幼儿园的小孩。"}, {"text": "这个代表团负责整理档案，每天在办公室工作。", "explanation": "这里应该用〈工作组〉。代表团是为会议或访问派出的团体，不负责日常办公的事务，这类工作应说〈工作组〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课程", "is_correct": false, "explanation": "语义：课程是教学内容，不能去日本访问。"}, {"text": "代表团", "is_correct": true, "explanation": "正确：代表团是派出访问的团体，能够“下个星期去日本访问”。"}, {"text": "方案", "is_correct": false, "explanation": "语义：方案是计划或设计，本身不能前往日本访问。"}, {"text": "歌曲", "is_correct": false, "explanation": "配价：“访问”要求有生命的人或团体作主语，歌曲不能充当。"}], "explanations": {"课程": "语义：课程是教学内容，不能去日本访问。", "代表团": "正确：代表团是派出访问的团体，能够“下个星期去日本访问”。", "方案": "语义：方案是计划或设计，本身不能前往日本访问。", "歌曲": "配价：“访问”要求有生命的人或团体作主语，歌曲不能充当。"}, "sentence_index": 6, "correct_answer": "代表团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们家是一个代表团。", "explanation": "这里应该用〈家庭〉。代表团是为会议或访问派出的团体，一家人不是这种团体，应说〈家庭〉。"}, {"text": "她每周都去学校的代表团练习书法。", "explanation": "这里应该用〈社团〉。代表团是为会议或访问临时派出的团体，不是长期的兴趣组织。"}, {"text": "我们的代表团下周去云南旅游。", "explanation": "这里应该用〈旅行团〉。代表团是为公务派出的团体，外出旅游的团体应说〈旅行团〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的代表团们昨天参观了一家工厂。", "corrected_sentence": "我们的代表团昨天参观了一家工厂。", "error_description": "错误：代表团们。正确：代表团。代表团是集体名词，不能再加〈们〉表示复数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一张代表团昨天坐飞机出发了。", "corrected_sentence": "一个代表团昨天坐飞机出发了。", "error_description": "错误：一张代表团。正确：一个代表团。〈张〉用于桌子、纸等平面的东西，代表团是一群人，应用〈个〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95181, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "工作", "is_correct": true, "explanation": "工作：指做事或职业活动，与“工作做完后轻松玩乐”的休闲相反。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫：指清理卫生，与休闲没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考：指动脑筋想问题，与休闲没有反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "购买：指花钱买东西，与休闲没有反义关系。"}], "correct_answer": "工作", "explanations": {"工作": "工作：指做事或职业活动，与“工作做完后轻松玩乐”的休闲相反。", "打扫": "打扫：指清理卫生，与休闲没有反义关系。", "思考": "思考：指动脑筋想问题，与休闲没有反义关系。", "购买": "购买：指花钱买东西，与休闲没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95181, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "劳动", "is_correct": true, "explanation": "劳动：指付出体力或脑力从事工作，与休闲的轻松玩乐相对。"}, {"text": "研究", "is_correct": false, "explanation": "研究：指探讨问题，与休闲没有反义关系。"}, {"text": "写作", "is_correct": false, "explanation": "写作：指创作文章，与休闲没有反义关系。"}, {"text": "训练", "is_correct": false, "explanation": "训练：指有计划地练习，与休闲没有反义关系。"}], "correct_answer": "劳动", "explanations": {"劳动": "劳动：指付出体力或脑力从事工作，与休闲的轻松玩乐相对。", "研究": "研究：指探讨问题，与休闲没有反义关系。", "写作": "写作：指创作文章，与休闲没有反义关系。", "训练": "训练：指有计划地练习，与休闲没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95181, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "工作做完了，不用忙，轻轻松松地玩一玩。", "primary_collocate": null, "pronunciation": "xiū xián", "ipa": "ɕiou˥ ɕiɛn˧˥", "syllable_count": 2, "sentences": [{"text": "工作做完了，下午可以休闲一下。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我喜欢去公园休闲。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "忙了一周，他想在家休闲两天。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们坐在树下休闲聊天。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考完试，我们去海边休闲几天。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班以后，他常常在茶馆休闲。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别总是加班，也要找时间休闲。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情都做完了，我们休闲一会儿吧。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他退休后，每天在湖边休闲，钓钓鱼。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期里他不想学习，只想好好休闲。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "休闲了", "label": "体标"}, {"form": "休闲娱乐", "label": "复合"}], "register": "中性", "sense_fingerprint": "忙完之后轻松地玩一玩、放松", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce87e407-f827-4d11-8490-1be803ed23ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95181, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "休闲", "is_correct": true, "explanation": "正确：休闲指工作做完后轻松玩一玩，与“工作做完了，下午可以……一下”相符。"}, {"text": "加班", "is_correct": false, "explanation": "语义：工作已经做完，下午再去加班，与句意矛盾。"}, {"text": "上班", "is_correct": false, "explanation": "语义：工作做完了，下午又去上班，与句意矛盾。"}, {"text": "出征", "is_correct": false, "explanation": "语域：出征指出兵打仗，用于此处语域不协调，且与句意矛盾。"}], "explanations": {"休闲": "正确：休闲指工作做完后轻松玩一玩，与“工作做完了，下午可以……一下”相符。", "加班": "语义：工作已经做完，下午再去加班，与句意矛盾。", "上班": "语义：工作做完了，下午又去上班，与句意矛盾。", "出征": "语域：出征指出兵打仗，用于此处语域不协调，且与句意矛盾。"}, "sentence_index": 0, "correct_answer": "休闲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "感冒以后，他要在床上休闲三天。", "explanation": "这里应该用〈休养〉。休闲指工作之余轻松玩乐，不用于养病。"}, {"text": "这台机器坏了，一直在仓库里休闲。", "explanation": "这里应该用〈闲置〉。休闲指人忙完后轻松玩乐，不能用于机器。"}, {"text": "我每天都去公司休闲。", "explanation": "这里应该用〈上班〉。休闲指不忙时轻松玩乐，去公司工作不能说休闲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95181, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "休闲", "is_correct": true, "explanation": "正确：休闲指忙里偷闲地放松玩乐，与“别总是加班，也要找时间……”的劝告相符。"}, {"text": "工作", "is_correct": false, "explanation": "语义：前一句劝人不要总加班，后面又说“找时间工作”，自相矛盾。"}, {"text": "熬夜", "is_correct": false, "explanation": "语义：熬夜同样是过度劳累，与“也要找时间”放松身心的语境矛盾。"}, {"text": "生病", "is_correct": false, "explanation": "搭配：“找时间”后面不能接“生病”这类不由自主的状态。"}], "explanations": {"休闲": "正确：休闲指忙里偷闲地放松玩乐，与“别总是加班，也要找时间……”的劝告相符。", "工作": "语义：前一句劝人不要总加班，后面又说“找时间工作”，自相矛盾。", "熬夜": "语义：熬夜同样是过度劳累，与“也要找时间”放松身心的语境矛盾。", "生病": "搭配：“找时间”后面不能接“生病”这类不由自主的状态。"}, "sentence_index": 6, "correct_answer": "休闲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地震过后，废墟上的景象很休闲。", "explanation": "这里应该用〈凄凉〉。休闲表示工作之余轻松从容，不能用来形容灾后的废墟。"}, {"text": "妈妈把旧衣服休闲在柜子里。", "explanation": "这里应该用〈放〉。休闲是人轻松玩乐，不能带宾语表示放置东西。"}, {"text": "运动员正在赛场上休闲。", "explanation": "这里应该用〈比赛〉。赛场上的运动员是在竞赛，不是轻松玩乐，不能说休闲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95181, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我们可以公园休闲一下。", "corrected_sentence": "周末我们可以在公园休闲一下。", "error_description": "错误：“可以公园休闲”；正确：“可以在公园休闲”。休闲的地点要用介词“在”引出，放在动词前面，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95181, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们周末在家里休闲的很舒服。", "corrected_sentence": "他们周末在家里休闲得很舒服。", "error_description": "错误：“休闲的很舒服”；正确：“休闲得很舒服”。表示动作的状态或程度时，动词后要用“得”引出补语，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95182, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "紧张", "is_correct": true, "explanation": "紧张：指不放松、有压力的状态，与休闲的放松从容相反。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：形容光线充足或颜色鲜明，与休闲没有反义关系。"}, {"text": "精致", "is_correct": false, "explanation": "精致：形容做工细致，与休闲没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：形容明白、不模糊，与休闲没有反义关系。"}], "correct_answer": "紧张", "explanations": {"紧张": "紧张：指不放松、有压力的状态，与休闲的放松从容相反。", "明亮": "明亮：形容光线充足或颜色鲜明，与休闲没有反义关系。", "精致": "精致：形容做工细致，与休闲没有反义关系。", "清楚": "清楚：形容明白、不模糊，与休闲没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95182, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忙碌", "is_correct": true, "explanation": "忙碌：指事情多、没有空闲，与休闲的放松从容相反。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速：形容速度快，与休闲没有反义关系。"}, {"text": "干燥", "is_correct": false, "explanation": "干燥：形容缺少水分，与休闲没有反义关系。"}, {"text": "清脆", "is_correct": false, "explanation": "清脆：形容声音响亮爽朗，与休闲没有反义关系。"}], "correct_answer": "忙碌", "explanations": {"忙碌": "忙碌：指事情多、没有空闲，与休闲的放松从容相反。", "迅速": "迅速：形容速度快，与休闲没有反义关系。", "干燥": "干燥：形容缺少水分，与休闲没有反义关系。", "清脆": "清脆：形容声音响亮爽朗，与休闲没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95182, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "工作之余放松身心、从容消遣的状态。", "primary_collocate": null, "pronunciation": "xiū xián", "ipa": "ɕiou˥ ɕiɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他喜欢休闲的生活。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家咖啡馆的环境很休闲。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末是我的休闲时间。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钓鱼是一种很好的休闲方式。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他这几天过得很休闲，每天看看书、喝喝茶。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有很多休闲的人。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休后，他过着休闲的日子。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里有吃有玩，是个休闲的好地方。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的生活节奏慢，过得很休闲。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在休闲的气氛里聊了很久。", "target_word": "休闲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "休闲装", "label": "复合"}, {"form": "休闲鞋", "label": "复合"}], "register": "中性", "sense_fingerprint": "放松从容、不紧张的生活或消遣状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce87e407-f827-4d11-8490-1be803ed23ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "休闲", "is_correct": true, "explanation": "正确：休闲形容生活轻松从容，与“他喜欢……的生活”搭配。"}, {"text": "痛苦", "is_correct": false, "explanation": "语义：没有人喜欢痛苦的生活，“喜欢痛苦”与句意矛盾。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：没有人喜欢饥饿的生活，与句意矛盾。"}, {"text": "愤怒", "is_correct": false, "explanation": "搭配：愤怒是情绪，不能用来修饰“生活”。"}], "explanations": {"休闲": "正确：休闲形容生活轻松从容，与“他喜欢……的生活”搭配。", "痛苦": "语义：没有人喜欢痛苦的生活，“喜欢痛苦”与句意矛盾。", "饥饿": "语义：没有人喜欢饥饿的生活，与句意矛盾。", "愤怒": "搭配：愤怒是情绪，不能用来修饰“生活”。"}, "sentence_index": 0, "correct_answer": "休闲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试很休闲。", "explanation": "这里应该用〈轻松〉。休闲形容生活或环境从容，不用于考试这类有压力的事。"}, {"text": "手术室里很休闲。", "explanation": "这里应该用〈严肃〉。手术室需要严肃紧张的环境，休闲不能用来形容这种场所。"}, {"text": "紧急会议上他很休闲。", "explanation": "这里应该用〈冷静〉。休闲指从容放松，紧急场合不能用休闲来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "休闲", "is_correct": true, "explanation": "正确：退休后过轻松从容的日子，与“过着……的日子”搭配。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：退休的人已不年轻，“过着年轻的日子”与句意矛盾。"}, {"text": "青春", "is_correct": false, "explanation": "语义：青春指年轻的时期，与退休后的情境不符。"}, {"text": "幼稚", "is_correct": false, "explanation": "搭配：幼稚形容行为或想法，不能用来修饰“日子”。"}], "explanations": {"休闲": "正确：退休后过轻松从容的日子，与“过着……的日子”搭配。", "年轻": "语义：退休的人已不年轻，“过着年轻的日子”与句意矛盾。", "青春": "语义：青春指年轻的时期，与退休后的情境不符。", "幼稚": "搭配：幼稚形容行为或想法，不能用来修饰“日子”。"}, "sentence_index": 6, "correct_answer": "休闲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器运行得很休闲。", "explanation": "这里应该用〈平稳〉。休闲形容人的生活或从容的状态，不能形容机器运行。"}, {"text": "这把椅子的腿很休闲。", "explanation": "这里应该用〈牢固〉。休闲形容人的生活或从容状态，不能用来形容椅子的结构。"}, {"text": "这家公司的纪律很休闲。", "explanation": "这里应该用〈严明〉。纪律需要严格，休闲不能用来形容纪律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在家里过很休闲，像在度假。", "corrected_sentence": "妈妈在家里过得很休闲，像在度假。", "error_description": "错误：“过很休闲”；正确：“过得很休闲”。动词后接表示状态或程度的补语，要用“得”引出，漏掉“得”则不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他退休以后，每天钓钓鱼，休闲的很。", "corrected_sentence": "他退休以后，每天钓钓鱼，休闲得很。", "error_description": "错误：“休闲的很”；正确：“休闲得很”。形容词作程度补语要用“得”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a05b7c-f2b6-4f9e-9778-b4e1b1536d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
