INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95183, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一张小卡片，可以先拿它买东西，以后再给钱。", "primary_collocate": null, "pronunciation": "xìn yòng kǎ", "ipa": "ɕin⁵¹ jʊŋ⁵¹ kʰa²¹⁴", "syllable_count": 3, "sentences": [{"text": "我没带现金，用信用卡买了这件衣服。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店可以用信用卡，也可以用现金。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的钱包里有两张信用卡。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先用信用卡买，下个月再给钱。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把信用卡放在家里了。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张信用卡可以在网上买东西。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点儿，别丢了你的信用卡。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹第一次用信用卡买了一双鞋。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有没有带信用卡？我忘了带钱。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "付钱的时候，她拿出了一张信用卡。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张信用卡", "label": "量词搭配"}, {"form": "信用卡账单", "label": "复合词"}, {"form": "信用卡号", "label": "复合词"}], "register": "中性", "sense_fingerprint": "可以先买东西、以后再给钱的小卡片，日常购物用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db3644ad-b860-49ef-adcd-01357c77d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95183, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信用卡", "is_correct": true, "explanation": "正确：信用卡是银行发的卡，可以先买东西、以后再还钱，符合“没带现金”的语境。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包是装钱和证件的东西，不能用来付钱买衣服。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是用来开门的，不是付款的工具，不能说“用钥匙买了这件衣服”。"}, {"text": "借书证", "is_correct": false, "explanation": "搭配：借书证只用于借书，不能和“用……买了这件衣服”搭配。"}], "explanations": {"信用卡": "正确：信用卡是银行发的卡，可以先买东西、以后再还钱，符合“没带现金”的语境。", "钱包": "语义：钱包是装钱和证件的东西，不能用来付钱买衣服。", "钥匙": "语义：钥匙是用来开门的，不是付款的工具，不能说“用钥匙买了这件衣服”。", "借书证": "搭配：借书证只用于借书，不能和“用……买了这件衣服”搭配。"}, "sentence_index": 0, "correct_answer": "信用卡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸每天都用信用卡给花浇水。", "explanation": "这里应该用〈水壶〉。浇花要用水壶；信用卡是先消费后还款的卡，不能用来浇水。"}, {"text": "妈妈给信用卡充了五十块钱的话费。", "explanation": "这里应该用〈充值卡〉。话费要充到手机或充值卡上；信用卡是先消费后还款的卡，不能充话费。"}, {"text": "奶奶每天用信用卡喂小鸡。", "explanation": "这里应该用〈饲料〉。喂小鸡要用饲料；信用卡不能用来喂食。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95183, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信用卡", "is_correct": true, "explanation": "正确：“丢了”的是可以拿在手里的卡片，信用卡符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是东西，不能被丢掉，“别丢了你的天气”不成立。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不会被丢失，这句话没有意义。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“丢”不跟体重搭配，体重减少要说“减”。"}], "explanations": {"信用卡": "正确：“丢了”的是可以拿在手里的卡片，信用卡符合句意。", "天气": "语义：天气不是东西，不能被丢掉，“别丢了你的天气”不成立。", "年龄": "语义：年龄不会被丢失，这句话没有意义。", "体重": "搭配：“丢”不跟体重搭配，体重减少要说“减”。"}, "sentence_index": 6, "correct_answer": "信用卡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用信用卡在墙上写了几个字。", "explanation": "这里应该用〈粉笔〉。在墙上写字要用粉笔或笔；信用卡是先消费后还款的卡，不能用来写字。"}, {"text": "我们拿出五十四张信用卡，开始打牌。", "explanation": "这里应该用〈扑克牌〉。打牌用的是扑克牌；信用卡是银行发的卡，不能用来打牌。"}, {"text": "这张信用卡要去银行兑现。", "explanation": "这里应该用〈支票〉。支票可以到银行兑现；信用卡不能兑现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95183, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想换一只信用卡。", "corrected_sentence": "我想换一张信用卡。", "error_description": "量词错误：“信用卡”是卡片，应说“一张信用卡”，不能说“一只信用卡”（“只”用于动物或成对物品中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95183, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈昨天给我办了一张的信用卡。", "corrected_sentence": "妈妈昨天给我办了一张信用卡。", "error_description": "“的”不能插在量词和名词之间。量词后直接接名词，应说“一张信用卡”，不说“一张的信用卡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
