INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95184, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "银行发给持卡人的卡片，可先消费后还款。", "primary_collocate": null, "pronunciation": "xìn yòng kǎ", "ipa": "ɕin⁵¹ jʊŋ⁵¹ kʰa²¹⁴", "syllable_count": 3, "sentences": [{"text": "他去银行办了一张信用卡。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我用信用卡花了不少钱，下个月要还。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信用卡每个月都要按时还款。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行给我寄来了一张新的信用卡。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想申请一张信用卡，要带什么？", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张信用卡的额度是五千块。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的信用卡晚还了几天，银行打来电话。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办信用卡的时候，要带身份证。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用信用卡买东西，先花钱，后还钱。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的信用卡丢了，得马上给银行打电话。", "target_word": "信用卡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张信用卡", "label": "量词搭配"}, {"form": "信用卡账单", "label": "复合词"}, {"form": "信用卡号", "label": "复合词"}], "register": "中性", "sense_fingerprint": "银行发给持卡人、可先消费后按时还款的金融卡片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db3644ad-b860-49ef-adcd-01357c77d0ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95184, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信用卡", "is_correct": true, "explanation": "正确：信用卡是银行发的卡，在银行办理，符合句意。"}, {"text": "火车票", "is_correct": false, "explanation": "语义：火车票是乘车用的，不是在银行办理的东西。"}, {"text": "健身卡", "is_correct": false, "explanation": "搭配：健身卡要去健身房办，不能说“去银行办了一张健身卡”。"}, {"text": "借书证", "is_correct": false, "explanation": "语义：借书证由图书馆发放，不会在银行办理。"}], "explanations": {"信用卡": "正确：信用卡是银行发的卡，在银行办理，符合句意。", "火车票": "语义：火车票是乘车用的，不是在银行办理的东西。", "健身卡": "搭配：健身卡要去健身房办，不能说“去银行办了一张健身卡”。", "借书证": "语义：借书证由图书馆发放，不会在银行办理。"}, "sentence_index": 0, "correct_answer": "信用卡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去图书馆借书，却忘了带信用卡，没法借书。", "explanation": "这里应该用〈借书证〉。借书要出示借书证；信用卡是银行发的卡，不能代替借书证。"}, {"text": "办公室的信用卡坏了，没法打印文件。", "explanation": "这里应该用〈打印机〉。打印文件要用打印机；信用卡是卡片，不能用来打印。"}, {"text": "这张信用卡太旧了，刷不开办公楼的门。", "explanation": "这里应该用〈门禁卡〉。刷门要用门禁卡；信用卡是银行发的卡，不能用来开门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95184, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信用卡", "is_correct": true, "explanation": "正确：可以晚还款的是信用卡，句中的“还”与“银行打来电话”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能“还”，这句话没有意义。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不能“还”，这句话没有意义。"}, {"text": "电费", "is_correct": false, "explanation": "搭配：电费一般说“交”，不说“晚还电费”，且不会因此让银行打电话。"}], "explanations": {"信用卡": "正确：可以晚还款的是信用卡，句中的“还”与“银行打来电话”相符。", "天气": "语义：天气不能“还”，这句话没有意义。", "体重": "语义：体重不能“还”，这句话没有意义。", "电费": "搭配：电费一般说“交”，不说“晚还电费”，且不会因此让银行打电话。"}, "sentence_index": 6, "correct_answer": "信用卡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用信用卡给小猫洗澡。", "explanation": "这里应该用〈香皂〉。给小猫洗澡要用香皂之类的东西；信用卡是银行发的卡，不能用来洗澡。"}, {"text": "我每天都用信用卡擦桌子。", "explanation": "这里应该用〈抹布〉。擦桌子要用抹布；信用卡是先消费后还款的卡，不能用来擦东西。"}, {"text": "他把一张信用卡当作一副牌，发给了每个人。", "explanation": "这里应该用〈扑克牌〉。发牌、打牌用的是扑克牌；信用卡是银行发的卡，不能当牌用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只信用卡的年费是多少？", "corrected_sentence": "这张信用卡的年费是多少？", "error_description": "量词错误：“信用卡”是卡片，应说“这张信用卡”，不能说“这只信用卡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把两条信用卡忘在超市了，得马上打电话。", "corrected_sentence": "我把两张信用卡忘在超市了，得马上打电话。", "error_description": "量词错误：“信用卡”是卡片，应说“两张信用卡”，不能说“两条信用卡”（“条”用于长条形的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0951cffc-c221-4855-94ff-5e8df6e4b522') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
