INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95185, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个东西里面藏着的深层意思。", "primary_collocate": null, "pronunciation": "nèi hán", "ipa": "nei˥˩ xan˧˥", "syllable_count": 2, "sentences": [{"text": "这首诗的内涵很深。", "target_word": "内涵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲了这个成语的内涵。", "target_word": "内涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能看懂这幅画的内涵吗？", "target_word": "内涵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这句话有很深的内涵，要慢慢想。", "target_word": "内涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影看起来简单，内涵却不少。", "target_word": "内涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有理解这个故事的内涵。", "target_word": "内涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个节日都有自己的内涵。", "target_word": "内涵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌的内涵，需要多听几遍才明白。", "target_word": "内涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名字的内涵是希望孩子平安。", "target_word": "内涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词的内涵比字面意思更丰富。", "target_word": "内涵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "內涵", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "诗、画、词语、作品等里面藏着的深层意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbe411f-991a-416c-a28b-6dca83adf8ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95185, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内涵", "is_correct": true, "explanation": "内涵：指诗的深层意思，与“很深”搭配，符合句意。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数是数量，没有深浅，与句中的“很深”不符。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“很深”修饰抽象的意思或颜色，不能修饰价格。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“很深”不能用来修饰体重，体重只能说重或轻。"}], "explanations": {"内涵": "内涵：指诗的深层意思，与“很深”搭配，符合句意。", "字数": "语义：字数是数量，没有深浅，与句中的“很深”不符。", "价格": "搭配：“很深”修饰抽象的意思或颜色，不能修饰价格。", "体重": "搭配：“很深”不能用来修饰体重，体重只能说重或轻。"}, "sentence_index": 0, "correct_answer": "内涵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影的内涵很甜，大家都爱吃。", "explanation": "“内涵”指抽象的含义，不能说成“甜”；这里误把它当作可以吃的东西。"}, {"text": "这张桌子的内涵很长，搬不动。", "explanation": "“内涵”指抽象的意义，不指桌子等具体物体的长度；这里误用于具体物体的尺寸。"}, {"text": "这首诗的内涵吃了三碗饭。", "explanation": "“内涵”是抽象的意义，不会吃饭；这里把它当作有生命的人来写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95185, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内涵", "is_correct": true, "explanation": "内涵：指节日里包含的意义，与“自己的”搭配，符合句意。"}, {"text": "地址", "is_correct": false, "explanation": "语义：节日不是地点，没有地址，与句意不符。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”指人或动物的高度，节日不能说身高。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：节日的年份不叫年龄，“年龄”只用于人或动物。"}], "explanations": {"内涵": "内涵：指节日里包含的意义，与“自己的”搭配，符合句意。", "地址": "语义：节日不是地点，没有地址，与句意不符。", "身高": "搭配：“身高”指人或动物的高度，节日不能说身高。", "年龄": "语义：节日的年份不叫年龄，“年龄”只用于人或动物。"}, "sentence_index": 6, "correct_answer": "内涵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的内涵很热，挂在墙上会发烫。", "explanation": "“内涵”指抽象的意义，没有温度，不能用“热”和“发烫”形容。"}, {"text": "这首诗的内涵有三公斤重。", "explanation": "“内涵”是抽象的意义，没有重量，不能用公斤来计量。"}, {"text": "这首歌的内涵很大声，我很喜欢。", "explanation": "“内涵”是抽象的意义，不能用“大声”形容；“大声”说的是声音的响度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95185, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我读懂了这首诗内涵。", "corrected_sentence": "我读懂了这首诗的内涵。", "error_description": "错误：修饰名词“内涵”的“这首诗”后漏了“的”，应为“这首诗的内涵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95185, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇小说是丰富的内涵，值得细读。", "corrected_sentence": "这篇小说有丰富的内涵，值得细读。", "error_description": "错误：“是”表示判断或等同，不能说小说“是”某种内涵；表示拥有应当用“有”，应为“有丰富的内涵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
