INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95186, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人内在的学识、修养和气质。", "primary_collocate": null, "pronunciation": "nèi hán", "ipa": "nei˥˩ xan˧˥", "syllable_count": 2, "sentences": [{"text": "他很有内涵，说话不多但很有道理。", "target_word": "内涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书可以让人更有内涵。", "target_word": "内涵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不只是漂亮，还很有内涵。", "target_word": "内涵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有内涵的人，不用说很多话。", "target_word": "内涵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多读书、多旅行，会让你更有内涵。", "target_word": "内涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师很有内涵，学生都喜欢他。", "target_word": "内涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得外表不重要，内涵更重要。", "target_word": "内涵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年纪不大，但是很有内涵。", "target_word": "内涵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想找一个有内涵的朋友。", "target_word": "内涵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有内涵的人不会随便生气。", "target_word": "内涵", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "內涵", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "人内在的学识、修养和气质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbe411f-991a-416c-a28b-6dca83adf8ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95186, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "内涵", "is_correct": true, "explanation": "内涵 nèi hán，指人内在的学识、修养和气质。"}, {"text": "耐寒", "is_correct": false, "explanation": "耐寒 nài hán 与 nèi hán 只差第一个音节的韵母（ai 与 ei），声调相同，意思是能忍受寒冷。"}, {"text": "内行", "is_correct": false, "explanation": "内行 nèi háng 与 nèi hán 只差第二个音节的韵尾（ng 与 n），意思是对某事很熟悉的人。"}, {"text": "内环", "is_correct": false, "explanation": "内环 nèi huán 比 nèi hán 多了介音 u，意思是内侧的环线。"}], "explanations": {"内涵": "内涵 nèi hán，指人内在的学识、修养和气质。", "耐寒": "耐寒 nài hán 与 nèi hán 只差第一个音节的韵母（ai 与 ei），声调相同，意思是能忍受寒冷。", "内行": "内行 nèi háng 与 nèi hán 只差第二个音节的韵尾（ng 与 n），意思是对某事很熟悉的人。", "内环": "内环 nèi huán 比 nèi hán 多了介音 u，意思是内侧的环线。"}, "sentence_index": null, "correct_answer": "内涵"}, "level_3": {"options": [{"text": "内涵", "is_correct": true, "explanation": "内涵：指人的修养和学识，与“很有”搭配，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“很有身高”不能这样说，“身高”不能与“有”搭配表示修养。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话与人的修养无关，与“说话不多但很有道理”不符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不能用来说人的修养，与句意不符。"}], "explanations": {"内涵": "内涵：指人的修养和学识，与“很有”搭配，符合句意。", "身高": "搭配：“很有身高”不能这样说，“身高”不能与“有”搭配表示修养。", "电话": "语义：电话与人的修养无关，与“说话不多但很有道理”不符。", "书包": "语义：书包是物品，不能用来说人的修养，与句意不符。"}, "sentence_index": 0, "correct_answer": "内涵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个杯子的内涵装满了一升水。", "explanation": "“内涵”指抽象的含义或修养，不是液体，不能说成“装满一升水”。"}, {"text": "他的内涵比我高一米。", "explanation": "“内涵”指人的修养和学识，没有高矮，不能用身高的“高”和“一米”来比较。"}, {"text": "这两张桌子的内涵不一样，一张很长。", "explanation": "“内涵”指抽象的含义或修养，桌子的长短不属于内涵的范畴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95186, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内涵", "is_correct": true, "explanation": "内涵：指人的修养，与前句“外表不重要”形成对比，符合句意。"}, {"text": "身材", "is_correct": false, "explanation": "语义：身材也属于外表，说它“更重要”与前句“外表不重要”矛盾。"}, {"text": "脸蛋", "is_correct": false, "explanation": "体貌：“脸蛋”指脸的样子，是外表的一部分，与前句矛盾。"}, {"text": "颜值", "is_correct": false, "explanation": "语义：颜值指外貌好看的程度，同样属于外表，与前句矛盾。"}], "explanations": {"内涵": "内涵：指人的修养，与前句“外表不重要”形成对比，符合句意。", "身材": "语义：身材也属于外表，说它“更重要”与前句“外表不重要”矛盾。", "脸蛋": "体貌：“脸蛋”指脸的样子，是外表的一部分，与前句矛盾。", "颜值": "语义：颜值指外貌好看的程度，同样属于外表，与前句矛盾。"}, "sentence_index": 6, "correct_answer": "内涵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的内涵是红色的，很显眼。", "explanation": "“内涵”指人的修养，没有颜色，不能用“红色”来形容。"}, {"text": "他的内涵很热，一碰就烫手。", "explanation": "“内涵”指抽象的含义或修养，没有温度，不能用“热”和“烫手”形容。"}, {"text": "他的内涵很咸，我不喜欢吃。", "explanation": "“内涵”指抽象的含义或修养，没有咸淡之分，不能用“咸”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一个很有内涵人，说话很得体。", "corrected_sentence": "她是一个很有内涵的人，说话很得体。", "error_description": "错误：“很有内涵”修饰名词“人”时漏了“的”，应为“很有内涵的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我喜欢有内涵老师。", "corrected_sentence": "我喜欢有内涵的老师。", "error_description": "错误：“有内涵”修饰名词时漏了“的”，应为“有内涵的老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
