INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95188, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "竭尽所能地去做某件事，多指帮助、支持或完成任务。", "primary_collocate": null, "pronunciation": "quán lì", "ipa": "tɕʰɥɛn˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "我们会全力帮助你。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司全力支持这个计划。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生正在全力抢救病人。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了考试，她全力准备了三个月。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师全力教我们学汉语。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家全力工作，希望按时完成。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察全力寻找丢失的孩子。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说会全力照顾好父母。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队全力争取这场比赛的胜利。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放心，我一定全力去做。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全力以赴", "label": "复合"}, {"form": "尽全力", "label": "复合"}], "register": "中性", "sense_fingerprint": "竭尽所能地去帮助、支持或完成某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcd4018f-a1c8-4a3f-b92d-7f066eb0ba12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95188, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全力", "is_correct": true, "explanation": "正确。“全力”指竭尽所能，与“我们会……帮助你”的承诺相符。"}, {"text": "力气", "is_correct": false, "explanation": "语法：“力气”是名词，不能直接放在动词“帮助”前面作状语。"}, {"text": "力量", "is_correct": false, "explanation": "语法：“力量”是名词，不能直接修饰动词“帮助”。"}, {"text": "尽情", "is_correct": false, "explanation": "搭配：“尽情”多修饰玩乐、表演等，不能修饰“帮助”。"}], "explanations": {"全力": "正确。“全力”指竭尽所能，与“我们会……帮助你”的承诺相符。", "力气": "语法：“力气”是名词，不能直接放在动词“帮助”前面作状语。", "力量": "语法：“力量”是名词，不能直接修饰动词“帮助”。", "尽情": "搭配：“尽情”多修饰玩乐、表演等，不能修饰“帮助”。"}, "sentence_index": 0, "correct_answer": "全力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他全力跳起来，摸到了天花板。", "explanation": "这里的“全力”表示用尽身体的力气，属于另一义项；本词此处指竭尽所能地去做某事。"}, {"text": "我全力抬起了那块石头。", "explanation": "这里的“全力”表示用尽身体的力气，属于另一义项；本词此处指竭尽所能地去做某事。"}, {"text": "她全力打了个哈欠，大家都笑了。", "explanation": "“全力”表示有意竭尽所能，打哈欠是不由自主的动作，不能用“全力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全力", "is_correct": true, "explanation": "正确。“全力”指竭尽所能，与“警察……寻找丢失的孩子”的紧迫语境相符。"}, {"text": "力气", "is_correct": false, "explanation": "语法：“力气”是名词，不能直接修饰动词“寻找”。"}, {"text": "随手", "is_correct": false, "explanation": "搭配：“随手”多修饰顺手拿、写之类的动作，不能修饰“寻找”。"}, {"text": "全身", "is_correct": false, "explanation": "语法：“全身”指整个身体，是名词，不能作“寻找”的状语。"}], "explanations": {"全力": "正确。“全力”指竭尽所能，与“警察……寻找丢失的孩子”的紧迫语境相符。", "力气": "语法：“力气”是名词，不能直接修饰动词“寻找”。", "随手": "搭配：“随手”多修饰顺手拿、写之类的动作，不能修饰“寻找”。", "全身": "语法：“全身”指整个身体，是名词，不能作“寻找”的状语。"}, "sentence_index": 6, "correct_answer": "全力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他全力晕倒在了路边。", "explanation": "“全力”表示有意竭尽所能去做，晕倒是不由自主的状态，不能用“全力”。"}, {"text": "她全力发烧了一整夜。", "explanation": "“全力”表示有意竭尽所能去做，发烧是身体的状态，不能用“全力”。"}, {"text": "他全力打了个寒战。", "explanation": "“全力”表示有意竭尽所能去做，打寒战是身体不由自主的反应，不能用“全力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们会全力了配合你的工作。", "corrected_sentence": "我们会全力配合你的工作。", "error_description": "助词“了”不能直接加在副词“全力”后面，应去掉“了”。错误形式是“全力了配合”，正确形式是“全力配合”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很全力准备了很多天。", "corrected_sentence": "他全力准备了很多天。", "error_description": "副词“全力”前面不能加程度副词“很”。应去掉“很”，说“他全力准备了很多天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95189, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "专职", "is_correct": true, "explanation": "反义：“专职”指专门担任一项职务、不兼其他工作，与“兼职”相对。"}, {"text": "假期", "is_correct": false, "explanation": "无关：“假期”指休息的时间，与“兼职”没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：“窗户”是建筑部件，与“兼职”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”是地理事物，与“兼职”没有反义关系。"}], "correct_answer": "专职", "explanations": {"专职": "反义：“专职”指专门担任一项职务、不兼其他工作，与“兼职”相对。", "假期": "无关：“假期”指休息的时间，与“兼职”没有反义关系。", "窗户": "无关：“窗户”是建筑部件，与“兼职”没有反义关系。", "河流": "无关：“河流”是地理事物，与“兼职”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95189, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "专职", "is_correct": true, "explanation": "反义：“专职”指专门担任一项职务、不兼其他工作，与“兼职”相对。"}, {"text": "海洋", "is_correct": false, "explanation": "无关：“海洋”是地理事物，与“兼职”没有反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：“桌子”是家具，与“兼职”没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "无关：“天气”指大气状况，与“兼职”没有反义关系。"}], "correct_answer": "专职", "explanations": {"专职": "反义：“专职”指专门担任一项职务、不兼其他工作，与“兼职”相对。", "海洋": "无关：“海洋”是地理事物，与“兼职”没有反义关系。", "桌子": "无关：“桌子”是家具，与“兼职”没有反义关系。", "天气": "无关：“天气”指大气状况，与“兼职”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95189, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "除了自己主要的工作，还去做另一份小工作。", "primary_collocate": null, "pronunciation": "jiān zhí", "ipa": "tɕjɛn˥ ʈʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "大学生周末常常找兼职赚零花钱。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我白天上班，晚上还做一份兼职。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在咖啡店做兼职，每小时二十块。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份兼职不累，时间也比较自由。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工资不高，下班后去找了一份兼职。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生可以先在网上看看有什么兼职。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈有一份兼职，每周去商店工作三天。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兼职的钱不多，但是可以学到很多东西。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了存钱，同时做着两份兼职。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找一份晚上的兼职，不影响白天上课。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兼职工作", "label": "复合"}, {"form": "兼职人员", "label": "复合"}], "register": "口语", "sense_fingerprint": "主业或学业之外另找的一份小工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce6f043-36d5-4f98-a980-2e9de3c98ca2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95189, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "兼职", "is_correct": true, "explanation": "兼职 jiān zhí：本职之外另做的工作，正确答案。"}, {"text": "坚持", "is_correct": false, "explanation": "声母不同：chí 与 zhí 只在声母 ch/zh 上不同，意思是坚持。"}, {"text": "简直", "is_correct": false, "explanation": "声调不同：jiǎn（第三声）与 jiān（第一声）声调不同，意思是简直。"}, {"text": "监制", "is_correct": false, "explanation": "声调不同：zhì（第四声）与 zhí（第二声）声调不同，意思是监制。"}, {"text": "剪纸", "is_correct": false, "explanation": "声调不同：jiǎn 与 zhǐ 分别与 jiān、zhí 声调不同，意思是剪纸。"}], "explanations": {"兼职": "兼职 jiān zhí：本职之外另做的工作，正确答案。", "坚持": "声母不同：chí 与 zhí 只在声母 ch/zh 上不同，意思是坚持。", "简直": "声调不同：jiǎn（第三声）与 jiān（第一声）声调不同，意思是简直。", "监制": "声调不同：zhì（第四声）与 zhí（第二声）声调不同，意思是监制。", "剪纸": "声调不同：jiǎn 与 zhǐ 分别与 jiān、zhí 声调不同，意思是剪纸。"}, "sentence_index": null, "correct_answer": "兼职"}, "level_3": {"options": [{"text": "兼职", "is_correct": true, "explanation": "正确：“找兼职赚零花钱”符合周末打工的语境。"}, {"text": "全职", "is_correct": false, "explanation": "语义：“全职”指全日制的固定工作，与“周末”打小工、赚零花钱的语境矛盾。"}, {"text": "正职", "is_correct": false, "explanation": "语义：“正职”是主要工作，不是周末赚零花钱的小工作。"}, {"text": "学位", "is_correct": false, "explanation": "搭配：“找”后面接工作、职位，不接学位，学位也与赚钱无关。"}], "explanations": {"兼职": "正确：“找兼职赚零花钱”符合周末打工的语境。", "全职": "语义：“全职”指全日制的固定工作，与“周末”打小工、赚零花钱的语境矛盾。", "正职": "语义：“正职”是主要工作，不是周末赚零花钱的小工作。", "学位": "搭配：“找”后面接工作、职位，不接学位，学位也与赚钱无关。"}, "sentence_index": 0, "correct_answer": "兼职"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他周末去学画画，这是他的兼职。", "explanation": "这里应该用〈业余爱好〉。兼职指有报酬的工作，画画作为爱好不能说兼职。"}, {"text": "他周末在养老院做兼职，不拿报酬。", "explanation": "这里应该用〈志愿者〉。兼职指有报酬的工作，无偿的志愿服务不能说兼职。"}, {"text": "他在这家公司干了二十年，这份兼职一直做得很好。", "explanation": "这里应该用〈正式工作〉。兼职指本职之外另做的工作，干了二十年的主要职业不能说兼职。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95189, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "兼职", "is_correct": true, "explanation": "兼职 jiān zhí：本职之外另做的工作，正确答案。"}, {"text": "减值", "is_correct": false, "explanation": "声调不同：jiǎn（第三声）与 jiān（第一声）声调不同，意思是资产价值下降。"}, {"text": "剪枝", "is_correct": false, "explanation": "声调不同：剪 jiǎn、枝 zhī 与 jiān、zhí 的声调都不同，意思是修剪树枝。"}, {"text": "建置", "is_correct": false, "explanation": "声调不同：jiàn 与 zhì 分别与 jiān、zhí 声调不同，意思是设置。"}], "explanations": {"兼职": "兼职 jiān zhí：本职之外另做的工作，正确答案。", "减值": "声调不同：jiǎn（第三声）与 jiān（第一声）声调不同，意思是资产价值下降。", "剪枝": "声调不同：剪 jiǎn、枝 zhī 与 jiān、zhí 的声调都不同，意思是修剪树枝。", "建置": "声调不同：jiàn 与 zhì 分别与 jiān、zhí 声调不同，意思是设置。"}, "sentence_index": null, "correct_answer": "兼职"}, "level_3": {"options": [{"text": "兼职", "is_correct": true, "explanation": "正确：“妈妈有一份兼职，每周去商店工作三天”符合语境。"}, {"text": "专业", "is_correct": false, "explanation": "语义：“专业”指学科或职业领域，不能说“有一份专业”去商店工作。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“学历”不能说“一份学历”，也与去商店工作的语境不符。"}, {"text": "名片", "is_correct": false, "explanation": "语义：“名片”是交际用的小卡片，与每周去商店工作的语境不相关。"}], "explanations": {"兼职": "正确：“妈妈有一份兼职，每周去商店工作三天”符合语境。", "专业": "语义：“专业”指学科或职业领域，不能说“有一份专业”去商店工作。", "学历": "搭配：“学历”不能说“一份学历”，也与去商店工作的语境不符。", "名片": "语义：“名片”是交际用的小卡片，与每周去商店工作的语境不相关。"}, "sentence_index": 6, "correct_answer": "兼职"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在医院做了十年医生，这份兼职一直是他的主要收入来源。", "explanation": "这里应该用〈全职〉。兼职是主要工作之外的小工作，主要收入来源不能说兼职。"}, {"text": "他的兼职是每天早上跑步，已经跑了三年。", "explanation": "这里应该用〈爱好〉。兼职指主业之外另做的、有报酬的工作，每天跑步是个人爱好，不能说兼职。"}, {"text": "他的兼职是厨师，每天在饭店上班，已经干了十年。", "explanation": "这里应该用〈正式工作〉。兼职是本职之外另做的工作，每天上班干了十年的主职不能说兼职。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95189, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有两张兼职，周末都很忙。", "corrected_sentence": "他有两份兼职，周末都很忙。", "error_description": "量词错误：“兼职”应搭配“份”，应说“两份兼职”；“张”用于纸张、桌子等平面物件，不能用来数工作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95189, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她找到了一本兼职，每周去书店三次。", "corrected_sentence": "她找到了一份兼职，每周去书店三次。", "error_description": "量词错误：“兼职”应搭配“份”，应说“一份兼职”；“本”用于书册，不能用来数工作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
