INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95190, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在本职工作之外兼任的另一项工作。", "primary_collocate": null, "pronunciation": "jiān zhí", "ipa": "tɕjɛn˥ ʈʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "他的正式工作是医生，兼职是大学老师。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李教授在大学教书，还有一个公司顾问的兼职。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长的本职工作很忙，没时间再做别的兼职。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在报社上班，同时在电台有一份兼职。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不同意员工在外面做兼职。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生的兼职是给电视台讲健康知识。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的本职是工程师，周末有一份教书的兼职。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当了公司经理，还有一个大学的兼职。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兼职做多了，会影响本职工作。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在银行工作，兼职是一家杂志的编辑。", "target_word": "兼职", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兼职工作", "label": "复合"}, {"form": "兼职人员", "label": "复合"}], "register": "口语", "sense_fingerprint": "本职之外同时担任的另一个职务或工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce6f043-36d5-4f98-a980-2e9de3c98ca2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95190, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "兼职", "is_correct": true, "explanation": "兼职 jiān zhí：本职之外兼任的另一项工作，正确答案。"}, {"text": "坚持", "is_correct": false, "explanation": "声母不同：chí 与 zhí 只在声母 ch/zh 上不同，意思是坚持。"}, {"text": "简直", "is_correct": false, "explanation": "声调不同：jiǎn（第三声）与 jiān（第一声）声调不同，意思是简直。"}, {"text": "剪枝", "is_correct": false, "explanation": "声调不同：剪 jiǎn、枝 zhī 与 jiān、zhí 的声调都不同，意思是修剪树枝。"}, {"text": "建置", "is_correct": false, "explanation": "声调不同：jiàn 与 zhì 分别与 jiān、zhí 声调不同，意思是设置。"}], "explanations": {"兼职": "兼职 jiān zhí：本职之外兼任的另一项工作，正确答案。", "坚持": "声母不同：chí 与 zhí 只在声母 ch/zh 上不同，意思是坚持。", "简直": "声调不同：jiǎn（第三声）与 jiān（第一声）声调不同，意思是简直。", "剪枝": "声调不同：剪 jiǎn、枝 zhī 与 jiān、zhí 的声调都不同，意思是修剪树枝。", "建置": "声调不同：jiàn 与 zhì 分别与 jiān、zhí 声调不同，意思是设置。"}, "sentence_index": null, "correct_answer": "兼职"}, "level_3": {"options": [{"text": "兼职", "is_correct": true, "explanation": "正确：“兼职是大学老师”指本职之外的另一份工作，符合语境。"}, {"text": "全职", "is_correct": false, "explanation": "语义：“全职”与“正式工作”重复，且与前半句“工作是医生”矛盾。"}, {"text": "本职", "is_correct": false, "explanation": "语义：“本职”指主要工作，与前句“正式工作是医生”重复，也与后半句矛盾。"}, {"text": "学位", "is_correct": false, "explanation": "搭配：“是大学老师”是职业身份，“学位”不能与之搭配。"}], "explanations": {"兼职": "正确：“兼职是大学老师”指本职之外的另一份工作，符合语境。", "全职": "语义：“全职”与“正式工作”重复，且与前半句“工作是医生”矛盾。", "本职": "语义：“本职”指主要工作，与前句“正式工作是医生”重复，也与后半句矛盾。", "学位": "搭配：“是大学老师”是职业身份，“学位”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "兼职"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的兼职是老师，已经在学校教了二十年书。", "explanation": "这里应该用〈正式工作〉。兼职指本职之外另做的工作，教了二十年的主要职业不能说兼职。"}, {"text": "他暑假去海边兼职，玩了两个星期。", "explanation": "这里应该用〈度假〉。兼职指本职之外兼任的工作，外出玩乐休假要说度假，不能说兼职。"}, {"text": "他每天在家做饭、洗衣，这是他的兼职。", "explanation": "这里应该用〈家务〉。兼职指本职之外兼任的工作，在家做饭洗衣属于家务，不能说兼职。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95190, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "兼职", "is_correct": true, "explanation": "兼职 jiān zhí：本职之外兼任的另一项工作，正确答案。"}, {"text": "减值", "is_correct": false, "explanation": "声调不同：jiǎn（第三声）与 jiān（第一声）声调不同，意思是资产价值下降。"}, {"text": "监制", "is_correct": false, "explanation": "声调不同：zhì（第四声）与 zhí（第二声）声调不同，意思是监制。"}, {"text": "剪纸", "is_correct": false, "explanation": "声调不同：jiǎn 与 zhǐ 分别与 jiān、zhí 声调不同，意思是剪纸。"}], "explanations": {"兼职": "兼职 jiān zhí：本职之外兼任的另一项工作，正确答案。", "减值": "声调不同：jiǎn（第三声）与 jiān（第一声）声调不同，意思是资产价值下降。", "监制": "声调不同：zhì（第四声）与 zhí（第二声）声调不同，意思是监制。", "剪纸": "声调不同：jiǎn 与 zhǐ 分别与 jiān、zhí 声调不同，意思是剪纸。"}, "sentence_index": null, "correct_answer": "兼职"}, "level_3": {"options": [{"text": "兼职", "is_correct": true, "explanation": "正确：“周末有一份教书的兼职”指本职之外的另一份工作，符合语境。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“一份教书的学历”不成立，“学历”不能作为教书的工作。"}, {"text": "名片", "is_correct": false, "explanation": "语义：“名片”是交际用的小卡片，不是可以周末去教书的工作。"}, {"text": "专业", "is_correct": false, "explanation": "语义：“专业”指学科方向，不能指周末教书的工作。"}], "explanations": {"兼职": "正确：“周末有一份教书的兼职”指本职之外的另一份工作，符合语境。", "学历": "搭配：“一份教书的学历”不成立，“学历”不能作为教书的工作。", "名片": "语义：“名片”是交际用的小卡片，不是可以周末去教书的工作。", "专业": "语义：“专业”指学科方向，不能指周末教书的工作。"}, "sentence_index": 6, "correct_answer": "兼职"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在银行做了二十年经理，这份兼职一直是他的主要工作。", "explanation": "这里应该用〈本职〉。兼职指本职之外另做的工作，二十年的主要职业不能说兼职。"}, {"text": "他的兼职是周末看电影，从来不拿钱。", "explanation": "这里应该用〈爱好〉。兼职指本职之外兼任的工作，周末看电影是爱好，不能说兼职。"}, {"text": "他的兼职是在大学读英语专业。", "explanation": "这里应该用〈学业〉。兼职指本职之外兼任的工作，在大学读书是学业，不能说兼职。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503170ae-c285-467c-84c1-fba5608e9ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
