INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95192, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95192, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一定时期内利息与本金的比率。", "primary_collocate": null, "pronunciation": "lì lǜ", "ipa": "li˥˩ ly˥˩", "syllable_count": 2, "sentences": [{"text": "银行下调了房贷的利率。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "利率上升，买房的人就少了。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家提高利率，是为了控制物价。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "利率越低，贷款的人越多。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔贷款的利率是百分之五。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "利率下降后，很多人买了房子。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理在会上说明了新的利率。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "利率等于利息除以本金。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家银行的利率差得不多。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，明年利率会继续下降。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "贷款利率", "label": "复合"}, {"form": "年利率", "label": "复合"}], "register": "中性", "sense_fingerprint": "金融上利息与本金之比，随政策和贷款变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcd4018f-a1c8-4a3f-b92d-7f066eb0ba12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "语义：工资是发给员工的报酬，与房贷无关。"}, {"text": "利率", "is_correct": true, "explanation": "正确。房贷利率可以下调，银行下调房贷的利率是常见做法。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：时间说“长”或“短”，不说“下调”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人的重量，与银行的房贷无关。"}], "explanations": {"工资": "语义：工资是发给员工的报酬，与房贷无关。", "利率": "正确。房贷利率可以下调，银行下调房贷的利率是常见做法。", "时间": "搭配：时间说“长”或“短”，不说“下调”。", "体重": "语义：体重是人的重量，与银行的房贷无关。"}, "sentence_index": 0, "correct_answer": "利率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔贷款的利率是三千元。", "explanation": "这里应该用〈利息〉。利率是比例，要说百分之几；说三千元要用利息。"}, {"text": "这两个数的利率是二比三。", "explanation": "这里应该用〈比率〉。利率专指利息与本金之比，两个数之间的比要用比率。"}, {"text": "去年我们的人口利率是百分之一。", "explanation": "这里应该用〈增长率〉。利率只用于存贷款的利息，人口的增长比例要用增长率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脸色", "is_correct": false, "explanation": "语义：脸色是人脸的状态，不是会议上要说明的内容。"}, {"text": "利率", "is_correct": true, "explanation": "正确。经理在会上说明的是新的利率，即存贷款利息的比例。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是人体的温度，不是会议上要说明的内容。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步是走路的动作，与会议说明无关。"}], "explanations": {"脸色": "语义：脸色是人脸的状态，不是会议上要说明的内容。", "利率": "正确。经理在会上说明的是新的利率，即存贷款利息的比例。", "体温": "语义：体温是人体的温度，不是会议上要说明的内容。", "脚步": "语义：脚步是走路的动作，与会议说明无关。"}, "sentence_index": 6, "correct_answer": "利率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次手术的利率很高。", "explanation": "这里应该用〈成功率〉。利率指利息与本金之比，手术的成功比例要用成功率。"}, {"text": "这种病的利率很低。", "explanation": "这里应该用〈发病率〉。利率只用于存贷款，疾病的发生比例要用发病率。"}, {"text": "全国网络的利率已经很高。", "explanation": "这里应该用〈普及率〉。利率不能描述网络的覆盖情况，应该用普及率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只利率比去年低。", "corrected_sentence": "这个利率比去年低。", "error_description": "错误：“利率”的量词应用“个”，“只”主要用于动物等，不能修饰“利率”；应说“这个利率”。正确：这个利率比去年低。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上个月银行降低着利率。", "corrected_sentence": "上个月银行降低了利率。", "error_description": "错误：“着”表示动作正在进行，与“上个月”这种已完成的时间不搭配；应说“降低了”。正确：上个月银行降低了利率。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f607f4-3adb-4b83-8dd1-5e16a2915b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
