INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95195, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "性别一样的人，比如都是男孩，或者都是女孩。", "primary_collocate": null, "pronunciation": "tóng xìng", "ipa": "tʰʊŋ˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "她喜欢和同性一起逛街。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男生常常和同性一起踢球。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同性之间也可以成为好朋友。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常跟同性一起去爬山。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在同性面前比较放松。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的好朋友大多是同性。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对同性和异性一样友好。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我更喜欢和同性玩。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在学校里，同性之间更容易成为朋友。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女孩子有时会跟同性分享小秘密。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "与自己性别一样的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f23e8f5-926c-4e66-9efb-f790437fb09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95195, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同性", "is_correct": true, "explanation": "同性（tóng xìng）指与自己性别一样的人，是正确答案。"}, {"text": "同心", "is_correct": false, "explanation": "xīn（第一声）与 xìng（第四声）声调不同，韵母 in 与 ing 也不同，意思是一条心。"}, {"text": "童星", "is_correct": false, "explanation": "xīng（第一声）与 xìng（第四声）声调不同，意思是童年时就成名的演员或歌手。"}, {"text": "同情", "is_correct": false, "explanation": "qíng 与 xìng 声母 q 与 x 不同，声调也不同，意思是对别人的不幸感到难过。"}, {"text": "通行", "is_correct": false, "explanation": "tōng（第一声）与 tóng（第二声）、xíng（第二声）与 xìng（第四声）声调都不同，意思是通过、可以通行。"}], "explanations": {"同性": "同性（tóng xìng）指与自己性别一样的人，是正确答案。", "同心": "xīn（第一声）与 xìng（第四声）声调不同，韵母 in 与 ing 也不同，意思是一条心。", "童星": "xīng（第一声）与 xìng（第四声）声调不同，意思是童年时就成名的演员或歌手。", "同情": "qíng 与 xìng 声母 q 与 x 不同，声调也不同，意思是对别人的不幸感到难过。", "通行": "tōng（第一声）与 tóng（第二声）、xíng（第二声）与 xìng（第四声）声调都不同，意思是通过、可以通行。"}, "sentence_index": null, "correct_answer": "同性"}, "level_3": {"options": [{"text": "同性", "is_correct": true, "explanation": "这里要填“同性”，指与她性别相同的朋友，可以一起逛街。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物不能和她一起逛街，与句意矛盾。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不能一起逛街，句意不通。"}, {"text": "物品", "is_correct": false, "explanation": "语义：“一起逛街”的对象只能是人，物品不能和她一起逛街。"}], "explanations": {"同性": "这里要填“同性”，指与她性别相同的朋友，可以一起逛街。", "动物": "语义：动物不能和她一起逛街，与句意矛盾。", "植物": "语义：植物不能一起逛街，句意不通。", "物品": "语义：“一起逛街”的对象只能是人，物品不能和她一起逛街。"}, "sentence_index": 0, "correct_answer": "同性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我常跟同性的背包一起去爬山。", "explanation": "这里应该用〈同款〉。“同性”只指性别相同的人，不能修饰背包；说两个背包样式相同要用“同款”。"}, {"text": "周末我常跟同性的装备一起去爬山。", "explanation": "这里应该用〈同类〉。“同性”只指人或动物的性别相同，不能用来修饰装备。"}, {"text": "我是女生，周末常跟同性一起去爬山，他们都是男生。", "explanation": "这里应该用〈异性〉。“同性”指和自己性别一样的人，男生对女生来说是异性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95195, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同性", "is_correct": true, "explanation": "这里要填“同性”，与后面的“异性”相对，表示两类人同样友好。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“友好”用于人或动物，不能用于椅子。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有感情，不能对它友好，句意矛盾。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不是有感情的对象，“对书友好”与句意不符。"}], "explanations": {"同性": "这里要填“同性”，与后面的“异性”相对，表示两类人同样友好。", "椅子": "搭配：“友好”用于人或动物，不能用于椅子。", "石头": "语义：石头没有感情，不能对它友好，句意矛盾。", "书": "语义：书不是有感情的对象，“对书友好”与句意不符。"}, "sentence_index": 6, "correct_answer": "同性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "女孩子有时会跟同性的哥哥分享小秘密。", "explanation": "这里应该用〈异性〉。“同性”指性别相同，哥哥与女孩子性别不同，应说“异性”。"}, {"text": "女孩子有时会把同性的日记借给朋友看。", "explanation": "这里应该用〈私人的〉。“同性”只指人或动物的性别相同，不能用来修饰日记。"}, {"text": "女孩子有时会跟同性分享小秘密，比如她家的小狗。", "explanation": "这里应该用〈宠物〉。“同性”指性别相同的人，不能指家里的小狗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95195, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她们很同性朋友。", "corrected_sentence": "她们是同性朋友。", "error_description": "错误：“很”修饰“同性”；正确：“是同性朋友”。“同性”表示性别相同，属于名词性成分，不能被程度副词“很”修饰；说明两人是同性时要用“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95195, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上课时她和同性地同学坐在一起。", "corrected_sentence": "上课时她和同性的同学坐在一起。", "error_description": "错误：“同性地同学”；正确：“同性的同学”。“同性”修饰名词“同学”时要用“的”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95196, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "异性", "is_correct": true, "explanation": "“异性”与“同性”相对，指性别不同，是这一义项的反义词。"}, {"text": "男性", "is_correct": false, "explanation": "“男性”指男子，与“同性”没有反义关系。"}, {"text": "老师", "is_correct": false, "explanation": "“老师”指职业身份，与“同性”没有反义关系。"}, {"text": "朋友", "is_correct": false, "explanation": "“朋友”指人际关系，与“同性”没有反义关系。"}], "correct_answer": "异性", "explanations": {"异性": "“异性”与“同性”相对，指性别不同，是这一义项的反义词。", "男性": "“男性”指男子，与“同性”没有反义关系。", "老师": "“老师”指职业身份，与“同性”没有反义关系。", "朋友": "“朋友”指人际关系，与“同性”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95196, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "异性", "is_correct": true, "explanation": "“异性”与“同性”相对，指性别不同，是这一义项的反义词。"}, {"text": "室友", "is_correct": false, "explanation": "“室友”指同住的人，与“同性”没有反义关系。"}, {"text": "邻居", "is_correct": false, "explanation": "“邻居”指住得近的人，与“同性”没有反义关系。"}, {"text": "老板", "is_correct": false, "explanation": "“老板”指职位身份，与“同性”没有反义关系。"}], "correct_answer": "异性", "explanations": {"异性": "“异性”与“同性”相对，指性别不同，是这一义项的反义词。", "室友": "“室友”指同住的人，与“同性”没有反义关系。", "邻居": "“邻居”指住得近的人，与“同性”没有反义关系。", "老板": "“老板”指职位身份，与“同性”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95196, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "性别相同。", "primary_collocate": null, "pronunciation": "tóng xìng", "ipa": "tʰʊŋ˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这两个孩子是同性，都是男孩。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和我的室友是同性，都是女生。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班的同性同学经常一起吃饭。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间宿舍只让同性的学生住在一起。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛分组时，同性的选手在一组。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做检查时，医生和病人最好是同性。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同性的朋友更容易聊起这些话题。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不是同性，一个是男的，一个是女的。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间只租给同性的学生。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个是同性，所以可以住一间房。", "target_word": "同性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "性别相同的状态；多作定语或宾语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f23e8f5-926c-4e66-9efb-f790437fb09d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95196, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同性", "is_correct": true, "explanation": "同性（tóng xìng）指性别相同，是正确答案。"}, {"text": "同心", "is_correct": false, "explanation": "xīn（第一声）与 xìng（第四声）声调不同，韵母 in 与 ing 也不同，意思是一条心。"}, {"text": "童星", "is_correct": false, "explanation": "xīng（第一声）与 xìng（第四声）声调不同，意思是童年时就成名的演员或歌手。"}, {"text": "同情", "is_correct": false, "explanation": "qíng 与 xìng 声母 q 与 x 不同，声调也不同，意思是对别人的不幸感到难过。"}, {"text": "通行", "is_correct": false, "explanation": "tōng（第一声）与 tóng（第二声）、xíng（第二声）与 xìng（第四声）声调都不同，意思是通过、可以通行。"}], "explanations": {"同性": "同性（tóng xìng）指性别相同，是正确答案。", "同心": "xīn（第一声）与 xìng（第四声）声调不同，韵母 in 与 ing 也不同，意思是一条心。", "童星": "xīng（第一声）与 xìng（第四声）声调不同，意思是童年时就成名的演员或歌手。", "同情": "qíng 与 xìng 声母 q 与 x 不同，声调也不同，意思是对别人的不幸感到难过。", "通行": "tōng（第一声）与 tóng（第二声）、xíng（第二声）与 xìng（第四声）声调都不同，意思是通过、可以通行。"}, "sentence_index": null, "correct_answer": "同性"}, "level_3": {"options": [{"text": "同性", "is_correct": true, "explanation": "这里要填“同性”，指性别相同，与后半句“都是男孩”一致。"}, {"text": "异性", "is_correct": false, "explanation": "语义：“异性”指性别不同，与“都是男孩”矛盾。"}, {"text": "姐妹", "is_correct": false, "explanation": "语义：“姐妹”指女性之间的亲属关系，与“都是男孩”矛盾。"}, {"text": "女性", "is_correct": false, "explanation": "语义：“女性”与“都是男孩”矛盾，句子说不通。"}], "explanations": {"同性": "这里要填“同性”，指性别相同，与后半句“都是男孩”一致。", "异性": "语义：“异性”指性别不同，与“都是男孩”矛盾。", "姐妹": "语义：“姐妹”指女性之间的亲属关系，与“都是男孩”矛盾。", "女性": "语义：“女性”与“都是男孩”矛盾，句子说不通。"}, "sentence_index": 0, "correct_answer": "同性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两件衣服是同性的，颜色和款式都一样。", "explanation": "这里应该用〈同类〉。“同性”只指人或动物的性别相同，不能用来说衣服的款式或颜色相同。"}, {"text": "这两家公司是同性的，业务范围也相同。", "explanation": "这里应该用〈同行〉。“同性”只指性别相同，不指公司的业务相同。"}, {"text": "这两种点心是同性，口味差不多。", "explanation": "这里应该用〈同类〉。“同性”只指人或动物的性别相同，不能用来说食品的种类相同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同性", "is_correct": true, "explanation": "这里要填“同性”，指性别相同的朋友，与句意相符。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物不能像朋友一样聊天，与“聊起这些话题”矛盾。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物无法聊起话题，句意不通。"}, {"text": "机器", "is_correct": false, "explanation": "搭配：“朋友”一般指人，“机器的朋友”不能与“聊起这些话题”搭配。"}], "explanations": {"同性": "这里要填“同性”，指性别相同的朋友，与句意相符。", "动物": "语义：动物不能像朋友一样聊天，与“聊起这些话题”矛盾。", "植物": "语义：植物无法聊起话题，句意不通。", "机器": "搭配：“朋友”一般指人，“机器的朋友”不能与“聊起这些话题”搭配。"}, "sentence_index": 6, "correct_answer": "同性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们两个是同性，一男一女。", "explanation": "这里应该用〈异性〉。“同性”指性别相同，一男一女性别不同，应说“异性”。"}, {"text": "这两个房间是同性，都朝南。", "explanation": "这里应该用〈相同〉。“同性”只指人或动物的性别相同，不能用来说房间的朝向相同。"}, {"text": "这两个城市是同性，所以天气也一样。", "explanation": "这里应该用〈相同〉。“同性”只指人或动物的性别相同，不能用来说城市或天气相同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们俩很同性，所以一起住在宿舍里。", "corrected_sentence": "他们俩是同性，所以一起住在宿舍里。", "error_description": "错误：“很同性”；正确：“是同性”。“同性”是名词，不能用“很”修饰，要用“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们俩是不同性，一个是男生，一个是女生。", "corrected_sentence": "他们俩不是同性，一个是男生，一个是女生。", "error_description": "错误：“是不同性”；正确：“不是同性”。否定要说“不是同性”，“不”放在“是”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3db3ce7c-ebfa-4f40-bda8-3a18cec9dbd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
