INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95199, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "代表一个国家的旗子。", "primary_collocate": null, "pronunciation": "guó qí", "ipa": "kuo˧˥ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "学校门口有一面国旗。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，国旗飘得很高。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个星期一，我们都要升国旗。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员举着国旗走进了体育场。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的国旗是红色的，上面有五颗星。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一面小国旗送给外国朋友。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国旗挂在大楼的最上面。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈教我怎样把国旗叠整齐。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，她披着国旗跑了一圈。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把国旗拿到教室外面去。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一面国旗", "label": "量词"}], "register": "中性", "sense_fingerprint": "代表国家的旗子，可以挂、升、举的实物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1665dc3-7706-4348-9cee-b52c002cdca1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95199, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国旗", "is_correct": true, "explanation": "正确。国旗 guó qí 指代表一个国家的旗子。"}, {"text": "过期", "is_correct": false, "explanation": "guòqī 与 guóqí 两个音节声调都不同（guò 第四声、qī 第一声），意思是超过期限。"}, {"text": "国企", "is_correct": false, "explanation": "guóqǐ 与 guóqí 第二个音节声调不同（qǐ 第三声，qí 第二声），意思是国有企业。"}, {"text": "国籍", "is_correct": false, "explanation": "guójí 与 guóqí 第二个音节声母不同（j 与 q），声调相同，意思是国籍。"}, {"text": "锅气", "is_correct": false, "explanation": "guōqì 与 guóqí 两个音节声调都不同（guō 第一声、qì 第四声），意思是锅里烹饪时产生的香气。"}], "explanations": {"国旗": "正确。国旗 guó qí 指代表一个国家的旗子。", "过期": "guòqī 与 guóqí 两个音节声调都不同（guò 第四声、qī 第一声），意思是超过期限。", "国企": "guóqǐ 与 guóqí 第二个音节声调不同（qǐ 第三声，qí 第二声），意思是国有企业。", "国籍": "guójí 与 guóqí 第二个音节声母不同（j 与 q），声调相同，意思是国籍。", "锅气": "guōqì 与 guóqí 两个音节声调都不同（guō 第一声、qì 第四声），意思是锅里烹饪时产生的香气。"}, "sentence_index": null, "correct_answer": "国旗"}, "level_3": {"options": [{"text": "国旗", "is_correct": true, "explanation": "正确。“国旗”是代表国家的旗子，量词用“面”。"}, {"text": "大门", "is_correct": false, "explanation": "搭配：量词“面”用于平面的东西，门要用“扇”，不说“一面大门”。"}, {"text": "国家", "is_correct": false, "explanation": "语义：“国家”是抽象概念，不是可以放在门口的物件。"}, {"text": "校长", "is_correct": false, "explanation": "搭配：量词“面”不用于人，“一面校长”不成立，且人也不能被当作一件物品放在门口。"}], "explanations": {"国旗": "正确。“国旗”是代表国家的旗子，量词用“面”。", "大门": "搭配：量词“面”用于平面的东西，门要用“扇”，不说“一面大门”。", "国家": "语义：“国家”是抽象概念，不是可以放在门口的物件。", "校长": "搭配：量词“面”不用于人，“一面校长”不成立，且人也不能被当作一件物品放在门口。"}, "sentence_index": 0, "correct_answer": "国旗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "乐队在仪式上奏起了国旗。", "explanation": "这里应该用〈国歌〉。奏的是国歌，国旗是用来挂、升、举的旗子，不能用“奏”。"}, {"text": "他是这一派的国旗，大家都很听他的。", "explanation": "这里应该用〈旗帜〉。“旗帜”可以比喻某一派的代表，“国旗”只指国家的旗子，不能用来比喻人。"}, {"text": "孩子们在国旗里游泳。", "explanation": "这里应该用〈游泳池〉。国旗是挂、升、举的旗子，不能在里面游泳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95199, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "国旗", "is_correct": true, "explanation": "正确。国旗 guó qí 指代表一个国家的旗子。"}, {"text": "过气", "is_correct": false, "explanation": "guòqì 与 guóqí 两个音节声调都不同（guò 第四声、qì 第四声），意思是过时、不再流行。"}, {"text": "过期", "is_correct": false, "explanation": "guòqī 与 guóqí 两个音节声调都不同，意思是超过期限。"}, {"text": "国际", "is_correct": false, "explanation": "guójì 与 guóqí 第二个音节声母与声调都不同（j 与 q，第四声与第二声），意思是国际。"}, {"text": "国企", "is_correct": false, "explanation": "guóqǐ 与 guóqí 第二个音节声调不同（qǐ 第三声，qí 第二声），意思是国有企业。"}], "explanations": {"国旗": "正确。国旗 guó qí 指代表一个国家的旗子。", "过气": "guòqì 与 guóqí 两个音节声调都不同（guò 第四声、qì 第四声），意思是过时、不再流行。", "过期": "guòqī 与 guóqí 两个音节声调都不同，意思是超过期限。", "国际": "guójì 与 guóqí 第二个音节声母与声调都不同（j 与 q，第四声与第二声），意思是国际。", "国企": "guóqǐ 与 guóqí 第二个音节声调不同（qǐ 第三声，qí 第二声），意思是国有企业。"}, "sentence_index": null, "correct_answer": "国旗"}, "level_3": {"options": [{"text": "国旗", "is_correct": true, "explanation": "正确。“国旗挂在大楼的最上面”是自然的说法。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“挂”一般不用于行李，行李通常是放或提的。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见、摸不着，不能挂在大楼的最上面。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”是人，不能被挂在大楼上。"}], "explanations": {"国旗": "正确。“国旗挂在大楼的最上面”是自然的说法。", "行李": "搭配：“挂”一般不用于行李，行李通常是放或提的。", "空气": "语义：空气看不见、摸不着，不能挂在大楼的最上面。", "老师": "语义：“老师”是人，不能被挂在大楼上。"}, "sentence_index": 6, "correct_answer": "国旗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次在比赛中担任了代表团的国旗。", "explanation": "这里应该用〈旗手〉。担任职务的是人，“国旗”是物，不能担任。"}, {"text": "他每天早上用国旗刷牙。", "explanation": "这里应该用〈牙刷〉。国旗是代表国家的旗子，不能用来刷牙。"}, {"text": "我渴了，想喝一杯国旗。", "explanation": "这里应该用〈水〉。国旗是旗子，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95199, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把国旗挂教室里。", "corrected_sentence": "老师把国旗挂在教室里。", "error_description": "错误形式是“挂教室里”，正确形式是“挂在教室里”。把字句中，表示处所的补语要用介词“在”引出，学习者常漏掉“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95199, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国旗慢慢升起去了。", "corrected_sentence": "国旗慢慢升起来了。", "error_description": "错误形式是“升起去”，正确形式是“升起来”。“升起来”表示由低处向上、朝向说话人所在的方向；“去”表示离开，与“升起”的语义不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
