INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95200, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "象征一个国家的旗帜。", "primary_collocate": null, "pronunciation": "guó qí", "ipa": "kuo˧˥ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "国旗是一个国家的象征。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到国旗，他心里很激动。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国旗的颜色有特别的意义。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了国旗的故事。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们保护国旗，就像保护自己的国家。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国旗上的星星代表什么？", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱国歌的时候，大家看着国旗。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在国外看见国旗，我觉得很亲切。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个国家都有自己的国旗。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为国旗的设计想了很久。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一面国旗", "label": "量词"}], "register": "中性", "sense_fingerprint": "象征国家的旗帜，带有尊严与情感意义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1665dc3-7706-4348-9cee-b52c002cdca1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95200, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国旗", "is_correct": true, "explanation": "正确。国旗 guó qí 指象征国家的旗帜。"}, {"text": "国籍", "is_correct": false, "explanation": "guójí 与 guóqí 第二个音节声母不同（j 与 q），声调相同，意思是国籍。"}, {"text": "过期", "is_correct": false, "explanation": "guòqī 与 guóqí 两个音节声调都不同，意思是超过期限。"}, {"text": "过气", "is_correct": false, "explanation": "guòqì 与 guóqí 两个音节声调都不同，意思是过时、不再流行。"}, {"text": "锅气", "is_correct": false, "explanation": "guōqì 与 guóqí 两个音节声调都不同，意思是锅里烹饪时产生的香气。"}], "explanations": {"国旗": "正确。国旗 guó qí 指象征国家的旗帜。", "国籍": "guójí 与 guóqí 第二个音节声母不同（j 与 q），声调相同，意思是国籍。", "过期": "guòqī 与 guóqí 两个音节声调都不同，意思是超过期限。", "过气": "guòqì 与 guóqí 两个音节声调都不同，意思是过时、不再流行。", "锅气": "guōqì 与 guóqí 两个音节声调都不同，意思是锅里烹饪时产生的香气。"}, "sentence_index": null, "correct_answer": "国旗"}, "level_3": {"options": [{"text": "国旗", "is_correct": true, "explanation": "正确。国旗是国家的象征，是一个国家的旗帜。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用的书，与“一个国家的象征”不相符。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日常用品，不能象征一个国家。"}, {"text": "老铁", "is_correct": false, "explanation": "语域：“老铁”是口语网络用语，不适合用在这样的书面定义句中。"}], "explanations": {"国旗": "正确。国旗是国家的象征，是一个国家的旗帜。", "课本": "语义：课本是学习用的书，与“一个国家的象征”不相符。", "雨伞": "语义：雨伞是日常用品，不能象征一个国家。", "老铁": "语域：“老铁”是口语网络用语，不适合用在这样的书面定义句中。"}, "sentence_index": 0, "correct_answer": "国旗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "升旗时，大家一起唱起了国旗。", "explanation": "这里应该用〈国歌〉。唱的是国歌，国旗是用来升、挂、举的旗子，不能用“唱”。"}, {"text": "这个图案是我们学校的国旗，象征着校风。", "explanation": "这里应该用〈标志〉。“国旗”只指国家的旗子，学校的图案应该称为“标志”。"}, {"text": "我渴了，想喝一杯国旗。", "explanation": "这里应该用〈水〉。国旗是旗帜，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95200, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "国旗", "is_correct": true, "explanation": "正确。国旗 guó qí 指象征国家的旗帜。"}, {"text": "过期", "is_correct": false, "explanation": "guòqī 与 guóqí 两个音节声调都不同，意思是超过期限。"}, {"text": "国际", "is_correct": false, "explanation": "guójì 与 guóqí 第二个音节声母与声调都不同（j 与 q，第四声与第二声），意思是国际。"}, {"text": "过气", "is_correct": false, "explanation": "guòqì 与 guóqí 两个音节声调都不同，意思是过时、不再流行。"}, {"text": "国企", "is_correct": false, "explanation": "guóqǐ 与 guóqí 第二个音节声调不同（qǐ 第三声，qí 第二声），意思是国有企业。"}], "explanations": {"国旗": "正确。国旗 guó qí 指象征国家的旗帜。", "过期": "guòqī 与 guóqí 两个音节声调都不同，意思是超过期限。", "国际": "guójì 与 guóqí 第二个音节声母与声调都不同（j 与 q，第四声与第二声），意思是国际。", "过气": "guòqì 与 guóqí 两个音节声调都不同，意思是过时、不再流行。", "国企": "guóqǐ 与 guóqí 第二个音节声调不同（qǐ 第三声，qí 第二声），意思是国有企业。"}, "sentence_index": null, "correct_answer": "国旗"}, "level_3": {"options": [{"text": "国旗", "is_correct": true, "explanation": "正确。唱国歌时，大家通常看着国旗。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”不能用于“声音”，声音是看不见的。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：味道是闻或尝的，不能“看着”。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：音乐是听的，不能“看着”。"}], "explanations": {"国旗": "正确。唱国歌时，大家通常看着国旗。", "声音": "搭配：“看”不能用于“声音”，声音是看不见的。", "味道": "搭配：味道是闻或尝的，不能“看着”。", "音乐": "搭配：音乐是听的，不能“看着”。"}, "sentence_index": 6, "correct_answer": "国旗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直是我们班的国旗，大家都很敬佩他。", "explanation": "这里应该用〈旗帜〉。“旗帜”可以比喻某个群体的代表，“国旗”只指国家的旗子，不能用来比喻人。"}, {"text": "他每次升旗都负责担任国旗。", "explanation": "这里应该用〈旗手〉。担任职务的是人，“国旗”是物，不能担任。"}, {"text": "他把国旗放进锅里煮了。", "explanation": "这里应该用〈面条〉。国旗是象征国家的旗帜，不能用来煮着吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把国旗好叠了。", "corrected_sentence": "他把国旗叠好了。", "error_description": "错误形式是“好叠”，正确形式是“叠好”。结果补语“好”要紧跟在动词之后，不能放在动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把国旗挂的很高。", "corrected_sentence": "妈妈把国旗挂得很高。", "error_description": "错误形式是“挂的很高”，正确形式是“挂得很高”。表示程度的补语要用助词“得”连接在动词之后，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95202, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "方", "is_correct": true, "explanation": "方与圆是形状上的反义词：圆没有棱角，方有四个角。"}, {"text": "黑", "is_correct": false, "explanation": "黑是颜色，与圆没有反义关系。"}, {"text": "粗", "is_correct": false, "explanation": "粗描写的是粗细，与圆的形状不构成反义关系。"}, {"text": "长", "is_correct": false, "explanation": "长描写的是长度，与圆的形状不构成反义关系。"}], "correct_answer": "方", "explanations": {"方": "方与圆是形状上的反义词：圆没有棱角，方有四个角。", "黑": "黑是颜色，与圆没有反义关系。", "粗": "粗描写的是粗细，与圆的形状不构成反义关系。", "长": "长描写的是长度，与圆的形状不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95202, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "方", "is_correct": true, "explanation": "方与圆是形状上的反义词：圆没有棱角，方有四个角。"}, {"text": "热", "is_correct": false, "explanation": "热描写温度，与圆的形状没有反义关系。"}, {"text": "细", "is_correct": false, "explanation": "细描写的是粗细，与圆的形状不构成反义关系。"}, {"text": "矮", "is_correct": false, "explanation": "矮描写的是高度，与圆不构成反义关系。"}], "correct_answer": "方", "explanations": {"方": "方与圆是形状上的反义词：圆没有棱角，方有四个角。", "热": "热描写温度，与圆的形状没有反义关系。", "细": "细描写的是粗细，与圆的形状不构成反义关系。", "矮": "矮描写的是高度，与圆不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95202, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形状像圆圈或球，周围没有棱角。", "primary_collocate": null, "pronunciation": "yuán", "ipa": "yɥɛn˧˥", "syllable_count": 1, "sentences": [{"text": "他在黑板上画了一个很圆的圈。", "target_word": "圆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张桌子是圆的。", "target_word": "圆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这面镜子是圆的，不是方的。", "target_word": "圆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她戴着一副圆圆的眼镜。", "target_word": "圆圆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盘子不够圆。", "target_word": "圆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "窗户做成圆的，看起来很特别。", "target_word": "圆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块饼干又薄又圆。", "target_word": "圆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请把这个洞挖得再圆一点。", "target_word": "圆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种面包是圆的，里面有奶油。", "target_word": "圆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小花的帽子是圆的，上面有一朵花。", "target_word": "圆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "圆圆", "label": "重叠"}, {"form": "圆形", "label": "复合"}, {"form": "圓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容物体的形状像圆圈，周围没有棱角", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbe411f-991a-416c-a28b-6dca83adf8ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95202, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "圆", "is_correct": true, "explanation": "圆 yuán（第二声），形容形状像圆圈，周围没有棱角。"}, {"text": "远", "is_correct": false, "explanation": "远 yuǎn（第三声）与 yuán（第二声）声调不同，意思是距离大，不是圆。"}, {"text": "院", "is_correct": false, "explanation": "院 yuàn（第四声）与 yuán（第二声）声调不同，意思是院子。"}, {"text": "盐", "is_correct": false, "explanation": "盐 yán（第二声）比 yuán 少了介音 u，声调相同，意思是盐。"}], "explanations": {"圆": "圆 yuán（第二声），形容形状像圆圈，周围没有棱角。", "远": "远 yuǎn（第三声）与 yuán（第二声）声调不同，意思是距离大，不是圆。", "院": "院 yuàn（第四声）与 yuán（第二声）声调不同，意思是院子。", "盐": "盐 yán（第二声）比 yuán 少了介音 u，声调相同，意思是盐。"}, "sentence_index": null, "correct_answer": "圆"}, "level_3": {"options": [{"text": "圆", "is_correct": true, "explanation": "圆：形容画出的圈是没有棱角的，符合句意。"}, {"text": "尖", "is_correct": false, "explanation": "语义：圈没有棱角，画成“尖”的就不是圈了。"}, {"text": "直", "is_correct": false, "explanation": "语义：圈是弯的，画成“直”的就不再是圈。"}, {"text": "脆", "is_correct": false, "explanation": "搭配：“脆”形容易碎的东西，不能用来形容画出的圈。"}], "explanations": {"圆": "圆：形容画出的圈是没有棱角的，符合句意。", "尖": "语义：圈没有棱角，画成“尖”的就不是圈了。", "直": "语义：圈是弯的，画成“直”的就不再是圈。", "脆": "搭配：“脆”形容易碎的东西，不能用来形容画出的圈。"}, "sentence_index": 0, "correct_answer": "圆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块长木板的形状很圆。", "explanation": "“圆”指弯曲、没有棱角的形状；长木板是平直的，不能用“圆”形容。"}, {"text": "这个方形的盒子很圆，四个角都很直。", "explanation": "“圆”指没有棱角的弯曲形状；方形盒子四个角是直角，与“圆”的形状义矛盾。"}, {"text": "这个三角形的纸片很圆。", "explanation": "“圆”指没有棱角的形状；三角形有三个角，不能用“圆”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95202, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "圆", "is_correct": true, "explanation": "圆 yuán（第二声），形容形状像圆圈，周围没有棱角。"}, {"text": "愿", "is_correct": false, "explanation": "愿 yuàn（第四声）与 yuán（第二声）声调不同，意思是愿意。"}, {"text": "严", "is_correct": false, "explanation": "严 yán（第二声）比 yuán 少了介音 u，声调相同，意思是严格。"}, {"text": "云", "is_correct": false, "explanation": "云 yún（第二声）比 yuán 少了元音 a，声调相同，意思是云彩。"}], "explanations": {"圆": "圆 yuán（第二声），形容形状像圆圈，周围没有棱角。", "愿": "愿 yuàn（第四声）与 yuán（第二声）声调不同，意思是愿意。", "严": "严 yán（第二声）比 yuán 少了介音 u，声调相同，意思是严格。", "云": "云 yún（第二声）比 yuán 少了元音 a，声调相同，意思是云彩。"}, "sentence_index": null, "correct_answer": "圆"}, "level_3": {"options": [{"text": "圆", "is_correct": true, "explanation": "圆：形容饼干的形状没有棱角，符合句意。"}, {"text": "胖", "is_correct": false, "explanation": "搭配：“胖”形容人或动物的身材，不能用来形容饼干的形状。"}, {"text": "急", "is_correct": false, "explanation": "语义：“急”形容节奏或情绪，不能用来形容饼干的形状。"}, {"text": "哑", "is_correct": false, "explanation": "语义：“哑”形容声音不清亮，饼干没有声音，与句意不符。"}], "explanations": {"圆": "圆：形容饼干的形状没有棱角，符合句意。", "胖": "搭配：“胖”形容人或动物的身材，不能用来形容饼干的形状。", "急": "语义：“急”形容节奏或情绪，不能用来形容饼干的形状。", "哑": "语义：“哑”形容声音不清亮，饼干没有声音，与句意不符。"}, "sentence_index": 6, "correct_answer": "圆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条马路很直，形状却很圆。", "explanation": "“圆”指弯弯的、没有棱角的形状；笔直的马路不能用“圆”形容。"}, {"text": "这个四方的水池很圆。", "explanation": "“圆”指没有棱角的形状；四方的水池有四个直角，不能用“圆”形容。"}, {"text": "这个正方形的窗户很圆。", "explanation": "“圆”指没有棱角的形状；正方形四角分明，不能用“圆”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95202, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个垫子是圆，颜色很漂亮。", "corrected_sentence": "这个垫子是圆的，颜色很漂亮。", "error_description": "错误：“是圆”后漏了“的”。形容词作谓语时常在后面加“的”，应为“是圆的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95202, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个碗的口是圆地，很大。", "corrected_sentence": "这个碗的口是圆的，很大。", "error_description": "错误：“是圆地”把“的”写成了“地”。形容词作谓语应用“的”，“地”用于修饰动词，应为“是圆的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
