INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95203, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "比地面高一点的平平的台子。", "primary_collocate": null, "pronunciation": "dì tái", "ipa": "ti˥˩ tʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "我家客厅有一个地台，孩子喜欢坐在上面玩。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卧室里的地台比地面高一点，上面放着床垫。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间茶室做了一个地台，大家脱鞋坐在上面喝茶。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在窗边搭了一个木头地台，当书桌用。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小地台上摆着一盆花。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子从地台上跳下来，高兴地笑了。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地台只有一步高，老人也能走上去。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把地台擦干净，再铺上一块毯子。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日式房间里常有一个矮矮的地台，可以睡觉。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地台下面有抽屉，可以放被子和衣服。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "地台床", "label": "复合"}], "register": "中性", "sense_fingerprint": "室内比地面略高的平台子，可坐可睡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '629e9c88-00bf-45eb-822b-29c0b905eb32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95203, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：窗户是墙上的开口，孩子不能坐在上面玩。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是冷藏食物的电器，不能让孩子坐着玩。"}, {"text": "地台", "is_correct": true, "explanation": "正确：地台是比地面高的平台，孩子可以坐在上面玩。"}, {"text": "水池", "is_correct": false, "explanation": "搭配：“坐在……上面”要求可以承重的平台或家具，水池不能这样用。"}], "explanations": {"窗户": "语义：窗户是墙上的开口，孩子不能坐在上面玩。", "冰箱": "语义：冰箱是冷藏食物的电器，不能让孩子坐着玩。", "地台": "正确：地台是比地面高的平台，孩子可以坐在上面玩。", "水池": "搭配：“坐在……上面”要求可以承重的平台或家具，水池不能这样用。"}, "sentence_index": 0, "correct_answer": "地台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位新来的地台很能干，大家都很喜欢他。", "explanation": "这里应该用〈同事〉。地台是比地面高一点的平台，不能指人，也不能用来称呼一个人。"}, {"text": "我每天用这个地台刷牙。", "explanation": "这里应该用〈洗漱台〉。地台是比地面高一点的平台，不能用来刷牙，刷牙应在〈洗漱台〉前。"}, {"text": "他用地台把门撑开了。", "explanation": "这里应该用〈门挡〉。地台是平台，不能用来撑门，撑门要用〈门挡〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab70b32-5cd7-4ce1-9368-e9b36247ac3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
